if (left.val != null and right.val != null) {
    const folded = if (op == '*') left.val.? *% right.val.? else @divTrunc(left.val.?, right.val.?);
    const dst = next_vreg.*;
    next_vreg.* += 1;
    try block.instrs.append(.{ .mov = .{ .dst = .{ .vreg = dst }, .src = .{ .imm = folded } } });
    left = .{ .vreg = dst, .val = folded };
