    const two = expr[pos.*..pos.*+2];
    if (std.mem.eql(u8, two, ">=") or std.mem.eql(u8, two, "<=") or std.mem.eql(u8, two, "==") or std.mem.eql(u8, two, "!=")) {
        op = two;
        pos.* += 2;
    } else if (expr[pos.*] == '>' or expr[pos.*] == '<') {
        op = expr[pos.*..pos.*+1];
        pos.* += 1;
    } else break;
