pub fn hasDst(inst: MInst) bool {
    return switch (inst) {
        .mov, .add, .sub, .imul, .idiv,
        .@"and", .@"or", .xor,
        .shl, .shr, .sar,
        .not_op, .neg_op,
        .alloca, .load, .lea,

        .call => |c| !c.is_void,
        else => false,
    };
}

pub fn dstVReg(inst: MInst) ?u32 {
    return switch (inst) {
        .mov => |m| vregOf(m.dst),
        .add => |m| vregOf(m.dst),
        .sub => |m| vregOf(m.dst),

        .guard_eval => |m| vregOf(m.result),
        else => null,
    };
}

fn vregOf(op: @import("operand.zig").MOperand) ?u32 {
    return switch (op) {
        .vreg => |v| v.id,
        else => null,
    };

