pub fn deinit(self: *MFunction) void {
    self.allocator.free(self.name);

self.allocator.free(self.params);
for (self.blocks.items) |*b| {
    self.allocator.free(b.label);
    for (b.instrs.items) |*inst| {
        switch (inst.*) {
