fn dstVreg(inst: mir.MInst) ?u32 {
    return switch (inst) {

        .setcc => |s| if (s.dst == .vreg) s.dst.vreg else null,
        .event_dispatch => |m| if (m.dst == .vreg) m.dst.vreg else null,
        .transition_check => |m| if (m.result == .vreg) m.result.vreg else null,
        .guard_eval => |m| if (m.result == .vreg) m.result.vreg else null,
        .state_init, .state_enter, .state_exit, .cmp_flags, .cmp, .test_flags, .jmp, .jcc, .store, .ret, .trap => null,
        .string_const => |s| if (s.dst == .vreg) s.dst.vreg else null,
    };
}

fn isSideEffecting(inst: mir.MInst) bool {

    };
}

fn srcVregs(inst: mir.MInst, buf: *[8]u32) usize {
    var n: usize = 0;
    switch (inst) {
        .mov => |m| {
            if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
        },
        .add => |m| {

    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.sub => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.imul => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.idiv => |m| {
    if (m.dividend == .vreg) { buf[n] = m.dividend.vreg; n += 1; }

    if (m.divisor == .vreg) { buf[n] = m.divisor.vreg; n += 1; }
},
.@"and" => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.@"or" => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.xor => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }

},
.shl, .shr, .sar => |m| {
    if (m.dst == .vreg) { buf[n] = m.dst.vreg; n += 1; }
    if (m.amount == .vreg) { buf[n] = m.amount.vreg; n += 1; }
},
.not_op, .neg_op => |m| {
    if (m.dst == .vreg) { buf[n] = m.dst.vreg; n += 1; }
},
.cmp => |m| {
    if (m.a == .vreg) { buf[n] = m.a.vreg; n += 1; }

    if (m.b == .vreg) { buf[n] = m.b.vreg; n += 1; }
},
.cmp_flags => |m| {
    if (m.a == .vreg) { buf[n] = m.a.vreg; n += 1; }
    if (m.b == .vreg) { buf[n] = m.b.vreg; n += 1; }
},
.test_flags => |m| {
    if (m.a == .vreg) { buf[n] = m.a.vreg; n += 1; }
    if (m.b == .vreg) { buf[n] = m.b.vreg; n += 1; }
},

.call => |m| {
    for (0..m.arg_count) |j| {
        if (m.args[j] == .vreg) { buf[n] = m.args[j].vreg; n += 1; }
    }
},
.load => |m| {
    if (m.ptr == .vreg) { buf[n] = m.ptr.vreg; n += 1; }
},
.store => |m| {
    if (m.ptr == .vreg) { buf[n] = m.ptr.vreg; n += 1; }

    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.ret => |m| {
    switch (m) {
        .void_ret => {},
        .value => |v| {
            if (v == .vreg) { buf[n] = v.vreg; n += 1; }
        },
    }
},

.phi => |p| {
    for (p.incoming) |inc| {
        if (inc.src == .vreg) { buf[n] = inc.src.vreg; n += 1; }
    }
},
.jmp, .jcc, .alloca, .trap => {},
.lea => |m| {
    if (m.base == .vreg) { buf[n] = m.base.vreg; n += 1; }
    if (m.index == .vreg) { buf[n] = m.index.vreg; n += 1; }
},

.fadd, .fsub, .fmul, .fdiv => |m| {
    if (m.a == .vreg) { buf[n] = m.a.vreg; n += 1; }
    if (m.b == .vreg) { buf[n] = m.b.vreg; n += 1; }
},
.fneg_op, .fsqrt_op => |m| {
    if (m.dst == .vreg) { buf[n] = m.dst.vreg; n += 1; }
},
.fcmp => |m| {
    if (m.a == .vreg) { buf[n] = m.a.vreg; n += 1; }
    if (m.b == .vreg) { buf[n] = m.b.vreg; n += 1; }

},
.sitofp, .fptosi, .fpext, .fptrunc, .sext_op, .zext_op, .trunc_op => |m| {
    if (m.src == .vreg) { buf[n] = m.src.vreg; n += 1; }
},
.select => |s| {
    if (s.dst == .vreg) { buf[n] = s.dst.vreg; n += 1; }
    if (s.src == .vreg) { buf[n] = s.src.vreg; n += 1; }
},
.setcc => {},
.state_init => |m| {

    if (m.initial_state == .vreg) { buf[n] = m.initial_state.vreg; n += 1; }
},
.state_enter => |m| {
    if (m.state_id == .vreg) { buf[n] = m.state_id.vreg; n += 1; }
},
.state_exit => |m| {
    if (m.state_id == .vreg) { buf[n] = m.state_id.vreg; n += 1; }
},
.event_dispatch => |m| {
    if (m.dst == .vreg) { buf[n] = m.dst.vreg; n += 1; }

    if (m.buf == .vreg) { buf[n] = m.buf.vreg; n += 1; }
    if (m.size == .vreg) { buf[n] = m.size.vreg; n += 1; }
},
.transition_check => |m| {
    if (m.result == .vreg) { buf[n] = m.result.vreg; n += 1; }
    if (m.event == .vreg) { buf[n] = m.event.vreg; n += 1; }
},
.guard_eval => |m| {
    if (m.result == .vreg) { buf[n] = m.result.vreg; n += 1; }
    if (m.lhs == .vreg) { buf[n] = m.lhs.vreg; n += 1; }

            if (m.rhs == .vreg) { buf[n] = m.rhs.vreg; n += 1; }
        },
        .string_const => {},
    }
    return n;
}

pub fn dce(mf: *mir.MFunction) !void {
    const allocator = mf.allocator;

var all_defs = std.AutoHashMap(u32, std.ArrayList(Ref)).init(allocator);
defer {
    var it = all_defs.iterator();
    while (it.next()) |entry| entry.value_ptr.deinit();
    all_defs.deinit();
}

for (mf.blocks.items, 0..) |block, bi| {
    for (block.instrs.items, 0..) |inst, ii| {
        if (dstVreg(inst)) |vr| {

            const gop = try all_defs.getOrPut(vr);
            if (!gop.found_existing) gop.value_ptr.* = std.ArrayList(Ref).init(allocator);
            try gop.value_ptr.append(.{ .block = @intCast(bi), .instr = @intCast(ii) });
        }
    }
}

var marked = std.AutoHashMap(Ref, void).init(allocator);
defer marked.deinit();

var worklist = std.ArrayList(Ref).init(allocator);
defer worklist.deinit();

for (mf.blocks.items, 0..) |block, bi| {
    for (block.instrs.items, 0..) |inst, ii| {
        if (isSideEffecting(inst)) {
            const ref = Ref{ .block = @intCast(bi), .instr = @intCast(ii) };
            try marked.put(ref, {});
            try worklist.append(ref);
        }

    }
}

var src_buf: [8]u32 = undefined;
while (worklist.items.len > 0) {
    const ref = worklist.pop() orelse unreachable;
    const inst = mf.blocks.items[ref.block].instrs.items[ref.instr];
    const n = srcVregs(inst, &src_buf);
    for (0..n) |j| {
        const vr = src_buf[j];

        const def_list = all_defs.get(vr) orelse continue;
        for (def_list.items) |dref| {
            if (!marked.contains(dref)) {
                try marked.put(dref, {});
                try worklist.append(dref);
            }
        }
    }
}

for (mf.blocks.items, 0..) |*block, bi| {
    var i: isize = @intCast(block.instrs.items.len);
    while (i > 0) {
        i -= 1;
        const ii = @as(usize, @intCast(i));
        if (!marked.contains(.{ .block = @intCast(bi), .instr = @intCast(ii) })) {
            _ = block.instrs.orderedRemove(ii);
        }
    }
}

const std = @import("std");
const mir = @import("../../mir.zig");

const VRegVal = union(enum) {
    copy: u32,
    constant: i64,
};

pub fn optimize(mfunc: *mir.MFunction) !void {
    var map = std.AutoHashMap(u32, VRegVal).init(mfunc.allocator);

defer map.deinit();

for (mfunc.blocks.items) |*block| {
    map.clearRetainingCapacity();

    var i: usize = 0;
    while (i < block.instrs.items.len) {
        const inst = block.instrs.items[i];
        switch (inst) {
            .mov => try handleMov(&map, block, &i),

.jmp, .jcc, .alloca, .phi, .trap => i += 1,
.lea => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.@"and", .@"or", .xor, .shl, .shr, .sar, .not_op, .neg_op, .test_flags => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.fadd, .fsub, .fmul, .fdiv => {

    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.fneg_op, .fsqrt_op => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.fcmp => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;

},
.sitofp, .fptosi, .fpext, .fptrunc, .sext_op, .zext_op, .trunc_op => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.select => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.setcc => {

    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.state_init, .state_enter, .state_exit => i += 1,
.event_dispatch => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.transition_check => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);

    i += 1;
},
.guard_eval => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},
.string_const => {
    if (dstOf(block.instrs.items[i])) |dv| redefineVReg(&map, dv);
    i += 1;
},

            }
        }
    }
}

fn resolveCopy(map: *std.AutoHashMap(u32, VRegVal), v: u32) u32 {
    var cur = v;
    for (0..16) |_| {
        switch (map.get(cur) orelse break) {
            .copy => |next| {

                if (next == cur) break;
                cur = next;
            },
            else => break,
        }
    }
    return cur;
}

fn resolveConst(map: *std.AutoHashMap(u32, VRegVal), v: u32) ?i64 {

var cur = v;
for (0..16) |_| {
    switch (map.get(cur) orelse return null) {
        .copy => |next| {
            if (next == cur) return null;
            cur = next;
        },
        .constant => |c| return c,
    }
}

    return null;
}

fn resolveCopyOp(map: *std.AutoHashMap(u32, VRegVal), op: mir.MOperand) mir.MOperand {
    return switch (op) {
        .vreg => |v| blk: {
            const rv = resolveCopy(map, v);
            if (rv != v) break :blk .{ .vreg = rv };
            break :blk op;
        },

        else => op,
    };
}

fn resolveConstOp(map: *std.AutoHashMap(u32, VRegVal), op: mir.MOperand) mir.MOperand {
    return switch (op) {
        .vreg => |v| blk: {
            if (resolveConst(map, v)) |c| break :blk .{ .imm = c };
            const rv = resolveCopy(map, v);
            if (rv != v) break :blk .{ .vreg = rv };

            break :blk op;
        },
        else => op,
    };
}

fn redefineVReg(map: *std.AutoHashMap(u32, VRegVal), v: u32) void {
    invalidateEntriesPointingTo(map, v);
    _ = map.remove(v);
}

fn invalidateEntriesPointingTo(map: *std.AutoHashMap(u32, VRegVal), target: u32) void {
    var keys_to_remove: [64]u32 = undefined;
    var count: usize = 0;
    var it = map.iterator();
    while (it.next()) |entry| {
        switch (entry.value_ptr.*) {
            .copy => |v| if (v == target) {
                keys_to_remove[count] = entry.key_ptr.*;
                count += 1;

            },
            else => {},
        }
    }
    for (0..count) |i| _ = map.remove(keys_to_remove[i]);
}

fn putVal(map: *std.AutoHashMap(u32, VRegVal), dv: u32, val: VRegVal) !void {
    invalidateEntriesPointingTo(map, dv);
    _ = map.remove(dv);

    try map.put(dv, val);
}

fn handleMov(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].mov;
    const dv = vreg(m.dst) orelse { ip.* += 1; return; };

    const new_src = resolveConstOp(map, m.src);

    if (vreg(new_src)) |rsv| {

    if (dv == rsv) {
        _ = block.instrs.orderedRemove(ip.*);
        return;
    }
    try putVal(map, dv, .{ .copy = rsv });
} else if (new_src == .imm) {
    try putVal(map, dv, .{ .constant = new_src.imm });
} else {
    redefineVReg(map, dv);
}

    if (!operandEq(new_src, m.src)) {
        block.instrs.items[ip.*] = .{ .mov = .{ .dst = m.dst, .src = new_src } };
    }
    ip.* += 1;
}

fn handleAddSub(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const inst = block.instrs.items[ip.*];
    const tag: u1 = if (@as(std.meta.Tag(mir.MInst), inst) == .add) @as(u1, 0) else @as(u1, 1);

const dst = if (tag == 0) inst.add.dst else inst.sub.dst;
const src = if (tag == 0) inst.add.src else inst.sub.src;
const dv = vreg(dst) orelse { ip.* += 1; return; };

const new_src = resolveConstOp(map, src);

if (new_src == .imm and new_src.imm == 0) {
    _ = block.instrs.orderedRemove(ip.*);
    return;

}

redefineVReg(map, dv);

if (!operandEq(new_src, src)) {
    block.instrs.items[ip.*] = if (tag == 0)
        .{ .add = .{ .dst = dst, .src = new_src } }
    else
        .{ .sub = .{ .dst = dst, .src = new_src } };
}

    ip.* += 1;
}

fn handleIMul(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].imul;
    const dv = vreg(m.dst) orelse { ip.* += 1; return; };

    const new_src = resolveConstOp(map, m.src);

    if (new_src == .imm) {

if (new_src.imm == 0) {
    block.instrs.items[ip.*] = .{ .mov = .{ .dst = m.dst, .src = .{ .imm = 0 } } };
    try putVal(map, dv, .{ .constant = 0 });
    ip.* += 1;
    return;
}
if (new_src.imm == 1) {
    _ = block.instrs.orderedRemove(ip.*);
    return;
}

    }

    redefineVReg(map, dv);

    if (!operandEq(new_src, m.src)) {
        block.instrs.items[ip.*] = .{ .imul = .{ .dst = m.dst, .src = new_src } };
    }
    ip.* += 1;
}

fn handleIDiv(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].idiv;

    const new_divisor = resolveConstOp(map, m.divisor);

    if (new_divisor == .imm and new_divisor.imm == 1) {
        _ = block.instrs.orderedRemove(ip.*);
        return;
    }

    redefineVReg(map, vreg(m.quotient) orelse return);

    if (!operandEq(new_divisor, m.divisor)) {
        block.instrs.items[ip.*] = .{ .idiv = .{ .dividend = m.dividend, .divisor = new_divisor, .quotient = m.quotient, .remainder = m.remainder } };
    }
    ip.* += 1;
}

fn handleCmp(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].cmp;

    const new_a = resolveCopyOp(map, m.a);
    const new_b = resolveCopyOp(map, m.b);

    if (!operandEq(new_a, m.a) or !operandEq(new_b, m.b)) {
        block.instrs.items[ip.*] = .{ .cmp = .{ .cc = m.cc, .a = new_a, .b = new_b } };
    }
    ip.* += 1;
}

fn handleCmpFlags(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].cmp_flags;
    const new_a = resolveCopyOp(map, m.a);
    const new_b = resolveConstOp(map, m.b);

    if (isZero(new_b)) {
        const av = if (vreg(new_a)) |v| v else {
            ip.* += 1;
            return;
        };

        block.instrs.items[ip.*] = .{ .test_flags = .{ .a = .{ .vreg = av }, .b = .{ .vreg = av } } };
        ip.* += 1;
        return;
    }

    if (!operandEq(new_a, m.a) or !operandEq(new_b, m.b)) {
        block.instrs.items[ip.*] = .{ .cmp_flags = .{ .a = new_a, .b = new_b } };
    }
    ip.* += 1;
}

fn isZero(op: mir.MOperand) bool {
    return switch (op) {
        .imm => |v| v == 0,
        else => false,
    };
}

fn handleLoad(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].load;

    const dv = vreg(m.dst) orelse { ip.* += 1; return; };
    const new_ptr = resolveCopyOp(map, m.ptr);
    redefineVReg(map, dv);
    if (!operandEq(new_ptr, m.ptr)) {
        block.instrs.items[ip.*] = .{ .load = .{ .dst = m.dst, .ptr = new_ptr, .size = m.size } };
    }
    ip.* += 1;
}

fn handleStore(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {

    const m = block.instrs.items[ip.*].store;
    const new_ptr = resolveCopyOp(map, m.ptr);
    const new_src = resolveCopyOp(map, m.src);
    if (!operandEq(new_ptr, m.ptr) or !operandEq(new_src, m.src)) {
        block.instrs.items[ip.*] = .{ .store = .{ .ptr = new_ptr, .src = new_src, .size = m.size } };
    }
    ip.* += 1;
}

fn handleRet(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {

const m = block.instrs.items[ip.*].ret;
switch (m) {
    .void_ret => {},
    .value => |val| {
        const new_val = resolveConstOp(map, val);
        if (!operandEq(new_val, val)) {
            block.instrs.items[ip.*] = .{ .ret = .{ .value = new_val } };
        }
    },
}

    ip.* += 1;
}

fn handleCall(map: *std.AutoHashMap(u32, VRegVal), block: *mir.MBlock, ip: *usize) !void {
    const m = block.instrs.items[ip.*].call;
    var changed = false;
    var new_args = m.args;
    for (0..m.arg_count) |j| {
        const ua = resolveCopyOp(map, m.args[j]);
        if (!operandEq(ua, m.args[j])) {

        new_args[j] = ua;
        changed = true;
    }
}
if (changed) {
    block.instrs.items[ip.*] = .{ .call = .{ .name = m.name, .args = new_args, .arg_count = m.arg_count, .dst = m.dst, .is_void = m.is_void } };
}
if (!m.is_void) {
    if (vreg(m.dst)) |dv| redefineVReg(map, dv);
}

    ip.* += 1;
}

fn operandEq(a: mir.MOperand, b: mir.MOperand) bool {
    if (@as(std.meta.Tag(mir.MOperand), a) != @as(std.meta.Tag(mir.MOperand), b)) return false;
    return switch (a) {
        .vreg => |av| b.vreg == av,
        .phys => |ap| b.phys == ap,
        .imm => |ai| b.imm == ai,
        .mem => |am| b.mem.base == am.base and b.mem.offset == am.offset and b.mem.size == am.size,

    };
}

fn vreg(op: mir.MOperand) ?u32 {
    return switch (op) {
        .vreg => |v| v,
        else => null,
    };
}

        .select => |s| vreg(s.dst),
        else => null,
    };
}

const std = @import("std");
const mir = @import("../mir.zig");
const mir_dce = @import("cleanup/dce.zig");
const mir_peephole = @import("cleanup/peephole.zig");
const mir_ssa_destroy = @import("ssa/ssa_destroy.zig");
const mir_copy_prop = @import("cleanup/copy_prop.zig");
const mir_verify = @import("verify.zig");
const mir_addr_fold = @import("memory/addr_fold.zig");

fn hasBackedge(mfunc: *const mir.MFunction) bool {

for (mfunc.blocks.items, 0..) |*block, bi| {
    if (block.instrs.items.len == 0) continue;
    const last = block.instrs.items[block.instrs.items.len - 1];
    switch (last) {
        .jcc => |j| { if (j.target <= bi) return true; },
        .jmp => |j| { if (j.target <= bi) return true; },
        else => {},
    }
}
return false;

}

fn dumpMIR(mfunc: *const mir.MFunction, label: []const u8) void {
    std.debug.print("\n  [DUMP] {s} - function '{s}':\n", .{ label, mfunc.name });
    for (mfunc.blocks.items, 0..) |block, bi| {
        std.debug.print("    b{d} '{s}':\n", .{ bi, block.label });
        for (block.instrs.items, 0..) |inst, ii| {
            std.debug.print("      {d}: ", .{ii});
            dumpInst(inst);
            std.debug.print("\n", .{});

        }
    }
}

fn dumpInst(inst: mir.MInst) void {
    switch (inst) {
        .mov => |m| { std.debug.print("mov ", .{}); dumpOp(m.dst); std.debug.print(", ", .{}); dumpOp(m.src); },
        .add => |m| { std.debug.print("add ", .{}); dumpOp(m.dst); std.debug.print(", ", .{}); dumpOp(m.src); },
        .sub => |m| { std.debug.print("sub ", .{}); dumpOp(m.dst); std.debug.print(", ", .{}); dumpOp(m.src); },
        .imul => |m| { std.debug.print("imul ", .{}); dumpOp(m.dst); std.debug.print(", ", .{}); dumpOp(m.src); },

    std.debug.print(", [", .{}); dumpOp(l.base);
    if (l.index != .imm) { std.debug.print(" + ", .{}); dumpOp(l.index); }
    std.debug.print(" * {d} + {d}]", .{ l.scale, l.disp });
},
.ret => |r| {
    switch (r) {
        .void_ret => std.debug.print("ret void", .{}),
        .value => |v| { std.debug.print("ret ", .{}); dumpOp(v); },
    }
},

        .state_exit => |m| { std.debug.print("state_exit ", .{}); dumpOp(m.state_id); },
        .event_dispatch => |m| { std.debug.print("event_dispatch ", .{}); dumpOp(m.dst); std.debug.print(", ", .{}); dumpOp(m.buf); std.debug.print(", ", .{}); dumpOp(m.size); },
        .transition_check => |m| { std.debug.print("transition_check ", .{}); dumpOp(m.event); std.debug.print(" ev={d}", .{m.event_id}); },
        .guard_eval => |m| { std.debug.print("guard_eval ", .{}); dumpOp(m.lhs); std.debug.print(", ", .{}); dumpOp(m.rhs); std.debug.print(" cc={s}", .{@tagName(m.cc)}); },
        .string_const => |s| { std.debug.print("string_const ", .{}); dumpOp(s.dst); std.debug.print(", \"{s}\"", .{s.data}); },
    }
}

fn dumpOp(op: mir.MOperand) void {
    switch (op) {

.vreg => |v| std.debug.print("v{d}", .{v}),
.imm => |v| std.debug.print("#{d}", .{v}),
.phys => |r| {
    const names = [_][]const u8{ "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15" };
    const idx: usize = @intCast(r);
    if (idx < names.len) std.debug.print("{s}", .{names[idx]}) else std.debug.print("phys({d})", .{idx});
},
.mem => |m| {
    std.debug.print("[", .{});
    const names = [_][]const u8{ "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15" };

            const idx: usize = @intCast(m.base);
            if (idx < names.len) std.debug.print("{s}", .{names[idx]}) else std.debug.print("phys({d})", .{idx});
            std.debug.print("+{d}]", .{m.offset});
        },
    }
}

pub fn optimize(mfunc: *mir.MFunction) !void {
    const debug = blk: {
        const val = std.process.getEnvVarOwned(mfunc.allocator, "BPC_DEBUG") catch { break :blk false; };

    defer mfunc.allocator.free(val);
    break :blk hasBackedge(mfunc) and val.len > 0;
};

try mir_ssa_destroy.destroySSA(mfunc);
try mir_verify.verifyNoPhis(mfunc);
mir_verify.verifyMir(mfunc) catch |err| {
    if (err == error.UnreachableBlock) dumpMIR(mfunc, "AFTER destroySSA UNREACHABLE");
    return err;
};

if (debug) dumpMIR(mfunc, "after SSA destroy");

try mir_addr_fold.AddrFoldPass.run(mfunc);
try mir_verify.verifyMir(mfunc);
if (debug) dumpMIR(mfunc, "after addr_fold");

try mir_copy_prop.propagateCopies(mfunc);
if (debug) dumpMIR(mfunc, "after copy_prop #1");

for (0..3) |_| {

        try mir_dce.dce(mfunc);
        try mir_peephole.optimize(mfunc);
        try mir_copy_prop.propagateCopies(mfunc);
    }
    try mir_dce.dce(mfunc);
    if (debug) dumpMIR(mfunc, "FINAL");
}

const std = @import("std");
const mir = @import("../../mir.zig");
const MInst = mir.MInst;
const MOperand = mir.MOperand;

/// Address Folding Pass
///
/// Recognizes address arithmetic patterns from BIR→MIR lowering and
/// synthesizes LEA instructions with [base+index*scale+disp] addressing.
///

/// Tracks value origins through mov/shl/add. Also propagates known
/// immediates so that shift amounts and displacement values are recognized.
///
/// Pattern (base + index*scale + disp):
///   mov v1, #3           ; index constant → known_imm(3)
///   mov v5, v2           ; v5 = index (copy(v2))
///   shl v5, v_shift      ; v5 = index * 4 (scaled(v2, 4))
///   mov v6, v_base       ; v6 = base (copy(v1))
///   add v6, v5           ; v6 = base + index*4 (addr(v1, v2, 4, 0))
///   mov v7, v6           ; v7 = addr (inherited addr)

///   add v7, v_disp       ; v7 = base + index*4 + disp → lea

const Origin = union(enum) {
    /// vreg holds a known immediate value (from mov v_r, #imm)
    known_imm: i64,
    /// vreg holds a copy of another operand (from mov v_r, v_s)
    copy: MOperand,
    /// vreg holds source * scale
    scaled: struct {
        source: MOperand,

        scale: u8,
    },
    /// vreg holds an address: base + index*scale + disp
    addr: struct {
        base: MOperand,
        index: MOperand = .{ .imm = 0 },
        scale: u8 = 1,
        disp: i32 = 0,
    },
};

pub const AddrFoldPass = struct {
    pub const name = "addr-fold";
    pub const pass_type = .transform;

    pub fn run(mfunc: *mir.MFunction) !void {
        for (mfunc.blocks.items) |*block| {
            try foldBlock(block, mfunc.allocator);
        }
    }

};

fn foldBlock(block: *mir.MBlock, allocator: std.mem.Allocator) !void {
    var origin = std.AutoHashMap(u32, Origin).init(allocator);
    defer origin.deinit();

    // Pass 1: Track value origins
    var i: usize = 0;
    while (i < block.instrs.items.len) {
        const inst = block.instrs.items[i];

switch (inst) {
    .mov => |m| {
        if (vregOf(m.dst)) |dv| {
            switch (m.src) {
                .vreg => |sv| {
                    // mov v_r, v_s: inherit scaled/addr, otherwise track as copy
                    if (origin.get(sv)) |o| {
                        switch (o) {
                            .scaled, .addr => try origin.put(dv, o),

            else => try origin.put(dv, .{ .copy = m.src }),
        }
    } else {
        try origin.put(dv, .{ .copy = m.src });
    }
},
.imm => |imm_val| {
    try origin.put(dv, .{ .known_imm = @intCast(imm_val) });
},
else => _ = origin.remove(dv),

        }
    }
    i += 1;
},

.shl => |s| {
    if (vregOf(s.dst)) |dv| {
        const shift_amt = resolveShiftAmount(s.amount, &origin) orelse {
            i += 1;
            continue;

};
if (shift_amt >= 1 and shift_amt <= 3) {
    const prev = origin.get(dv);
    const source: MOperand = if (prev) |p| switch (p) {
        .copy => |cp| cp,
        .scaled => |sc| sc.source,
        .addr => .{ .vreg = dv },
        .known_imm => .{ .vreg = dv },
    } else .{ .vreg = dv };
    try origin.put(dv, .{ .scaled = .{

                .source = source,
                .scale = @as(u8, 1) << @intCast(shift_amt),
            } });
        }
    }
    i += 1;
},

.add => |m| {
    const dst_v = vregOf(m.dst) orelse {

    i += 1;
    continue;
};

// Resolve the source to either an immediate value or a vreg
const src_imm: ?i32 = blk: {
    if (m.src == .imm) {
        break :blk @intCast(m.src.imm);
    }
    if (vregOf(m.src)) |sv| {

        if (origin.get(sv)) |o| {
            if (o == .known_imm) {
                break :blk @intCast(o.known_imm);
            }
        }
    }
    break :blk null;
};

if (src_imm) |imm_val| {

// add v_r, known_imm → displacement
const prev = origin.get(dst_v);
if (prev) |p| {
    switch (p) {
        .scaled => {},
        .addr => |a| {
            try origin.put(dst_v, .{ .addr = .{
                .base = a.base,
                .index = a.index,
                .scale = a.scale,

        .disp = a.disp +% imm_val,
    } });
    i += 1;
    continue;
},
.copy => |cp| {
    if (vregOf(cp)) |base_vreg| {
        if (origin.get(base_vreg)) |base_origin| {
            if (base_origin == .known_imm) {
                try origin.put(dst_v, .{ .known_imm = @intCast(@as(i64, @intCast(base_origin.known_imm)) +% @as(i64, @intCast(imm_val))) });

            i += 1;
            continue;
        }
    }
}
try origin.put(dst_v, .{ .addr = .{
    .base = cp,
    .disp = imm_val,
} });
i += 1;

            continue;
        },
        .known_imm => {
            // constant + constant = constant
            try origin.put(dst_v, .{ .known_imm = @intCast(@as(i64, @intCast(p.known_imm)) +% @as(i64, @intCast(imm_val))) });
            i += 1;
            continue;
        },
    }
}

    _ = origin.remove(dst_v);
    i += 1;
    continue;
}

// add v_r, v_s (both vregs, not resolved to immediate)
if (vregOf(m.src)) |sv| {
    const prev_dst = origin.get(dst_v);
    const prev_src = origin.get(sv);

if (prev_src) |ps| {
    switch (ps) {
        .scaled => |sc| {
            const base: MOperand = if (prev_dst) |pd| switch (pd) {
                .copy => |cp| cp,
                .addr => |a| a.base,
                else => m.dst,
            } else m.dst;
            try origin.put(dst_v, .{ .addr = .{
                .base = base,

        .index = sc.source,
        .scale = sc.scale,
        .disp = 0,
    } });
    i += 1;
    continue;
},
.copy => {},
.addr => {},
.known_imm => unreachable,

            }
        }

        _ = origin.remove(dst_v);
    }
    i += 1;
},

// LEA + ADD disp folding
.lea => {

if (i + 1 < block.instrs.items.len) {
    const next = block.instrs.items[i + 1];
    if (next == .add and next.add.src == .imm) {
        const lea_dst = vregOf(block.instrs.items[i].lea.dst);
        const add_dst = vregOf(next.add.dst);
        if (lea_dst != null and lea_dst == add_dst) {
            block.instrs.items[i].lea.disp +%= @intCast(next.add.src.imm);
            _ = block.instrs.orderedRemove(i + 1);
            continue;
        }

                }
            }
            i += 1;
        },

        else => i += 1,
    }
}

// Pass 2: Replace add v_r, #imm with lea when v_r has tracked address

i = 0;
while (i < block.instrs.items.len) {
    const inst = block.instrs.items[i];
    if (inst == .add) {
        const a = inst.add;
        // Only replace when source is an immediate (direct or known_imm vreg)
        const is_imm_src = if (a.src == .imm) true else blk: {
            if (vregOf(a.src)) |sv| {
                if (origin.get(sv)) |o| {
                    if (o == .known_imm) break :blk true;

        }
    }
    break :blk false;
};
if (is_imm_src) {
    if (vregOf(a.dst)) |dv| {
        if (origin.get(dv)) |o| {
            if (o == .addr) {
                const addr = o.addr;
                block.instrs.items[i] = .{ .lea = .{

                    .dst = a.dst,
                    .base = addr.base,
                    .index = addr.index,
                    .scale = addr.scale,
                    .disp = addr.disp,
                } };
            }
        }
    }
}

    }
    i += 1;
}

// Pass 3: Replace add v_r, v_s with lea when v_s has tracked scaled origin
i = 0;
while (i < block.instrs.items.len) {
    const inst = block.instrs.items[i];
    if (inst == .add) {
        const a = inst.add;

if (vregOf(a.src)) |sv| {
    if (vregOf(a.dst)) |dv| {
        if (origin.get(sv)) |o| {
            if (o == .scaled) {
                const sc = o.scaled;
                const prev_dst = origin.get(dv);
                const base: MOperand = if (prev_dst) |pd| switch (pd) {
                    .copy => |cp| cp,
                    .addr => |a2| a2.base,
                    else => a.dst,

        } else a.dst;
        block.instrs.items[i] = .{ .lea = .{
            .dst = a.dst,
            .base = base,
            .index = sc.source,
            .scale = sc.scale,
            .disp = 0,
        } };
    }
}

                }
            }
        }
        i += 1;
    }
}

fn vregOf(op: MOperand) ?u32 {
    return switch (op) {
        .vreg => |v| v,

        else => null,
    };
}

fn resolveShiftAmount(amount: MOperand, origin: *const std.AutoHashMap(u32, Origin)) ?u8 {
    if (amount == .imm) {
        const v = amount.imm;
        if (v >= 0 and v <= 31) return @intCast(v);
        return null;
    }

    if (amount == .vreg) {
        if (origin.get(amount.vreg)) |o| {
            if (o == .known_imm) {
                const v: i64 = o.known_imm;
                if (v >= 0 and v <= 31) return @intCast(v);
            }
        }
    }
    return null;
}

const std = @import("std");
const mir = @import("../../mir.zig");

pub fn destroySSA(mfunc: *mir.MFunction) !void {
    const next_vreg = computeNextVReg(mfunc);
    try splitCriticalEdges(mfunc, next_vreg);
    try eliminatePhis(mfunc, next_vreg);
}

fn computeNextVReg(mfunc: *const mir.MFunction) u32 {

var max_vreg: u32 = 1000;
for (mfunc.blocks.items) |block| {
    for (block.instrs.items) |inst| {
        if (dstVReg(inst)) |v| {
            if (v >= max_vreg) max_vreg = v + 1;
        }
        var srcs: [8]u32 = undefined;
        const n = srcVregs(inst, &srcs);
        for (0..n) |i| {
            if (srcs[i] >= max_vreg) max_vreg = srcs[i] + 1;

            }
        }
    }
    for (mfunc.params) |p| {
        if (p == .vreg and p.vreg >= max_vreg) max_vreg = p.vreg + 1;
    }
    return max_vreg;
}

fn splitCriticalEdges(mfunc: *mir.MFunction, next_vreg: u32) !void {

var splits = std.ArrayList(struct {
    pred_idx: usize,
    succ_idx: usize,
    new_block_idx: usize,
}).init(mfunc.allocator);
defer splits.deinit();

var scratch: u32 = next_vreg;

for (mfunc.blocks.items, 0..) |*block, bi| {

var succ_count: usize = 0;
for (block.instrs.items) |inst| {
    switch (inst) {
        .jmp => succ_count += 1,
        .jcc => succ_count += 2,
        else => {},
    }
}
if (succ_count <= 1) continue;

for (block.instrs.items) |inst| {
    const targets: [2]?usize = switch (inst) {
        .jmp => |j| .{ j.target, null },
        .jcc => |j| .{ j.target, null },
        else => continue,
    };
    for (targets) |t_opt| {
        const target = t_opt orelse continue;
        if (target >= mfunc.blocks.items.len) continue;

var pred_count: usize = 0;
for (mfunc.blocks.items) |other| {
    for (other.instrs.items) |oi| {
        switch (oi) {
            .jmp => |j| {
                if (j.target == target) pred_count += 1;
            },
            .jcc => |j| {
                if (j.target == target) pred_count += 1;
            },

            else => {},
        }
    }
}

if (pred_count > 1) {
    var already_split = false;
    for (splits.items) |sp| {
        if (sp.pred_idx == bi and sp.succ_idx == target) {
            already_split = true;

        break;
    }
}
if (!already_split) {
    try splits.append(.{
        .pred_idx = bi,
        .succ_idx = target,
        .new_block_idx = mfunc.blocks.items.len + splits.items.len,
    });
}

            }
        }
    }
}

for (splits.items) |sp| {
    const new_label = try std.fmt.allocPrint(mfunc.allocator, "crit_edge_{d}", .{scratch});
    scratch += 1;

    var new_block = mir.MBlock{

    .label = new_label,
    .instrs = std.ArrayList(mir.MInst).init(mfunc.allocator),
};
try new_block.instrs.append(.{ .jmp = .{ .target = @intCast(sp.succ_idx) } });

try mfunc.blocks.append(new_block);

const pred = &mfunc.blocks.items[sp.pred_idx];
for (pred.instrs.items) |*inst| {
    switch (inst.*) {

.jmp => |*j| {
    if (j.target == @as(u32, @intCast(sp.succ_idx))) {
        j.target = @intCast(sp.new_block_idx);
    }
},
.jcc => |*j| {
    if (j.target == @as(u32, @intCast(sp.succ_idx))) {
        j.target = @intCast(sp.new_block_idx);
    }
},

            else => {},
        }
    }
}

for (mfunc.blocks.items) |*block| {
    for (block.instrs.items) |*inst| {
        switch (inst.*) {
            .jcc => |*j| {
                for (splits.items) |sp| {

                        if (j.target == @as(u32, @intCast(sp.succ_idx)) and sp.pred_idx == findBlockIndex(mfunc, block)) {
                            j.target = @intCast(sp.new_block_idx);
                        }
                    }
                },
                else => {},
            }
        }
    }
}

fn findBlockIndex(mfunc: *const mir.MFunction, target: *const mir.MBlock) usize {
    for (mfunc.blocks.items, 0..) |b, i| {
        if (b.label.ptr == target.label.ptr) return i;
    }
    return 0;
}

fn eliminatePhis(mfunc: *mir.MFunction, next_vreg: u32) !void {
    for (mfunc.blocks.items) |*block| {

var has_phi = false;
for (block.instrs.items) |inst| {
    if (inst == .phi) {
        has_phi = true;
        break;
    }
}
if (!has_phi) continue;

var phis = std.ArrayList(mir.PhiInst).init(mfunc.allocator);

defer {
    for (phis.items) |p| mfunc.allocator.free(p.incoming);
    phis.deinit();
}

var non_phis = std.ArrayList(mir.MInst).init(mfunc.allocator);
defer non_phis.deinit();

for (block.instrs.items) |inst| {
    switch (inst) {

        .phi => |p| {
            const owned_inc = try mfunc.allocator.dupe(mir.PhiIncoming, p.incoming);
            try phis.append(.{ .dst = p.dst, .incoming = owned_inc });
        },
        else => try non_phis.append(inst),
    }
}

block.instrs.clearRetainingCapacity();
for (non_phis.items) |inst| {

    try block.instrs.append(inst);
}

var copies_by_pred = std.AutoHashMap(usize, std.ArrayList(CopyPair)).init(mfunc.allocator);
defer {
    var it = copies_by_pred.iterator();
    while (it.next()) |entry| entry.value_ptr.deinit();
    copies_by_pred.deinit();
}

for (phis.items) |phi| {
    const dst_v = vregOf(phi.dst) orelse continue;
    for (phi.incoming) |inc| {
        const src_v = vregOf(inc.src) orelse continue;
        if (dst_v == src_v) continue;
        if (inc.pred_block >= mfunc.blocks.items.len) continue;

        const gop = try copies_by_pred.getOrPut(inc.pred_block);
        if (!gop.found_existing) gop.value_ptr.* = std.ArrayList(CopyPair).init(mfunc.allocator);
        try gop.value_ptr.append(.{ .dst = phi.dst, .src = inc.src });

    }
}

var pred_it = copies_by_pred.iterator();
while (pred_it.next()) |entry| {
    const pred_idx = entry.key_ptr.*;
    const copies = entry.value_ptr;
    if (copies.items.len == 0) continue;
    try resolveAndEmitCopies(mfunc, pred_idx, copies.items, next_vreg);
}

    }
}

const CopyPair = struct {
    dst: mir.MOperand,
    src: mir.MOperand,
};

fn resolveAndEmitCopies(
    mfunc: *mir.MFunction,

    pred_idx: usize,
    copies: []const CopyPair,
    base_scratch: u32,
) !void {
    const pred = &mfunc.blocks.items[pred_idx];

    var resolved = std.ArrayList(ResolvedCopy).init(mfunc.allocator);
    defer resolved.deinit();

    var remaining = std.ArrayList(ResolvedCopy).init(mfunc.allocator);

defer remaining.deinit();

for (copies) |cp| {
    if (vregOf(cp.dst)) |dv| {
        if (vregOf(cp.src) == dv) continue;
    }
    try remaining.append(.{ .dst = cp.dst, .src = cp.src });
}

var next_scratch = base_scratch;

while (remaining.items.len > 0) {
    var all_dsts = std.AutoHashMap(u32, void).init(mfunc.allocator);
    defer all_dsts.deinit();
    for (remaining.items) |cp| {
        if (vregOf(cp.dst)) |dv| try all_dsts.put(dv, {});
    }

    var safe_found = false;
    var i: usize = 0;
    while (i < remaining.items.len) {

const cp = remaining.items[i];
const src_v = vregOf(cp.src);
const is_safe = if (src_v) |sv| !all_dsts.contains(sv) else true;

if (is_safe) {
    try resolved.append(cp);
    _ = remaining.orderedRemove(i);
    safe_found = true;
} else {
    i += 1;

    }
}

if (!safe_found and remaining.items.len > 0) {
    const cp = remaining.orderedRemove(0);
    const tmp_v = next_scratch;
    next_scratch += 1;
    const tmp_op: mir.MOperand = .{ .vreg = tmp_v };

    try resolved.append(.{ .dst = tmp_op, .src = cp.src });

    try resolved.append(.{ .dst = cp.dst, .src = tmp_op });

    if (vregOf(cp.dst)) |dv| {
        for (remaining.items) |*other| {
            if (vregOf(other.src) == dv) {
                other.src = tmp_op;
            }
        }
    }
}

}

var insert_idx: usize = pred.instrs.items.len;
for (pred.instrs.items, 0..) |mi, i| {
    switch (mi) {
        .jmp, .jcc, .ret => {
            insert_idx = i;
            break;
        },
        else => {},

    }
}

var idx: usize = insert_idx;
for (resolved.items) |rc| {
    if (vregOf(rc.dst)) |dv| {
        if (vregOf(rc.src) == dv) continue;
    }
    try pred.instrs.insert(idx, .{ .mov = .{ .dst = rc.dst, .src = rc.src } });
    idx += 1;

    }
}

const ResolvedCopy = struct {
    dst: mir.MOperand,
    src: mir.MOperand,
};

fn dstVReg(inst: mir.MInst) ?u32 {
    return switch (inst) {

        .call => |m| if (!m.is_void and m.dst == .vreg) m.dst.vreg else null,
        .alloca => |m| if (m.dst == .vreg) m.dst.vreg else null,
        .load => |m| if (m.dst == .vreg) m.dst.vreg else null,
        .phi => |p| if (p.dst == .vreg) p.dst.vreg else null,
        else => null,
    };
}

fn srcVregs(inst: mir.MInst, buf: *[8]u32) usize {
    var n: usize = 0;

switch (inst) {
    .mov => |m| {
        if (m.src == .vreg) {
            buf[n] = m.src.vreg;
            n += 1;
        }
    },
    .add => |m| {
        if (m.src == .vreg) {
            buf[n] = m.src.vreg;

        n += 1;
    }
},
.sub => |m| {
    if (m.src == .vreg) {
        buf[n] = m.src.vreg;
        n += 1;
    }
},
.imul => |m| {

    if (m.src == .vreg) {
        buf[n] = m.src.vreg;
        n += 1;
    }
},
.idiv => |m| {
    if (m.divisor == .vreg) {
        buf[n] = m.divisor.vreg;
        n += 1;
    }

},
.@"and" => |m| {
    if (m.src == .vreg) {
        buf[n] = m.src.vreg;
        n += 1;
    }
},
.@"or" => |m| {
    if (m.src == .vreg) {
        buf[n] = m.src.vreg;

        n += 1;
    }
},
.xor => |m| {
    if (m.src == .vreg) {
        buf[n] = m.src.vreg;
        n += 1;
    }
},
.shl, .shr, .sar => |m| {

    if (m.amount == .vreg) {
        buf[n] = m.amount.vreg;
        n += 1;
    }
},
.not_op, .neg_op => |m| {
    if (m.dst == .vreg) {
        buf[n] = m.dst.vreg;
        n += 1;
    }

},
.cmp => |m| {
    if (m.a == .vreg) {
        buf[n] = m.a.vreg;
        n += 1;
    }
    if (m.b == .vreg) {
        buf[n] = m.b.vreg;
        n += 1;
    }

},
.cmp_flags => |m| {
    if (m.a == .vreg) {
        buf[n] = m.a.vreg;
        n += 1;
    }
    if (m.b == .vreg) {
        buf[n] = m.b.vreg;
        n += 1;
    }

},
.test_flags => |m| {
    if (m.a == .vreg) {
        buf[n] = m.a.vreg;
        n += 1;
    }
    if (m.b == .vreg) {
        buf[n] = m.b.vreg;
        n += 1;
    }

},
.call => |m| {
    for (0..m.arg_count) |j| {
        if (m.args[j] == .vreg) {
            buf[n] = m.args[j].vreg;
            n += 1;
        }
    }
},
.load => |m| {

    if (m.ptr == .vreg) {
        buf[n] = m.ptr.vreg;
        n += 1;
    }
},
.store => |m| {
    if (m.ptr == .vreg) {
        buf[n] = m.ptr.vreg;
        n += 1;
    }

    if (m.src == .vreg) {
        buf[n] = m.src.vreg;
        n += 1;
    }
},
.ret => |m| {
    switch (m) {
        .void_ret => {},
        .value => |v| {
            if (v == .vreg) {

                buf[n] = v.vreg;
                n += 1;
            }
        },
    }
},
.phi => |p| {
    for (p.incoming) |inc| {
        if (inc.src == .vreg) {
            buf[n] = inc.src.vreg;

                    n += 1;
                }
            }
        },
        else => {},
    }
    return n;
}

fn vregOf(op: mir.MOperand) ?u32 {

    return switch (op) {
        .vreg => |v| v,
        else => null,
    };
}

const std = @import("std");
const mir = @import("../mir.zig");

pub const VerifyError = error{
    InvalidBlockTarget,
    MissingTerminator,
    UnreachableBlock,
    UndefinedVReg,
    PhiNotEliminated,
};

fn checkDefined(defs: *std.AutoHashMap(u32, void), op: mir.MOperand) !void {
    if (op == .vreg and !defs.contains(op.vreg)) return error.UndefinedVReg;
}

fn collectDefinedVRegs(mfunc: *const mir.MFunction) std.AutoHashMap(u32, void) {
    var defs = std.AutoHashMap(u32, void).init(std.heap.page_allocator);
    for (mfunc.params) |p| {
        if (p == .vreg) defs.put(p.vreg, {}) catch {};
    }

for (mfunc.blocks.items) |*block| {
    for (block.instrs.items) |inst| {
        const dst = switch (inst) {
            .mov => |m| m.dst,
            .add => |a| a.dst,
            .sub => |s| s.dst,
            .imul => |m| m.dst,
            .idiv => |m| m.quotient,
            .@"and" => |a| a.dst,
            .@"or" => |o| o.dst,

                .string_const => |s| s.dst,
                else => continue,
            };
            if (dst == .vreg) defs.put(dst.vreg, {}) catch {};
        }
    }
    return defs;
}

fn checkUsedVRegs(inst: mir.MInst, defs: *std.AutoHashMap(u32, void)) !void {

switch (inst) {
    .mov => |m| try checkDefined(defs, m.src),
    .add => |a| try checkDefined(defs, a.src),
    .sub => |s| try checkDefined(defs, s.src),
    .imul => |m| try checkDefined(defs, m.src),
    .idiv => |m| {
        try checkDefined(defs, m.dividend);
        try checkDefined(defs, m.divisor);
    },
    .@"and" => |a| try checkDefined(defs, a.src),

.@"or" => |o| try checkDefined(defs, o.src),
.xor => |x| try checkDefined(defs, x.src),
.shl => |s| try checkDefined(defs, s.amount),
.shr => |s| try checkDefined(defs, s.amount),
.sar => |s| try checkDefined(defs, s.amount),
.not_op => |n| try checkDefined(defs, n.dst),
.neg_op => |n| try checkDefined(defs, n.dst),
.test_flags => |tf| {
    try checkDefined(defs, tf.a);
    try checkDefined(defs, tf.b);

},
.cmp => |c| {
    try checkDefined(defs, c.a);
    try checkDefined(defs, c.b);
},
.cmp_flags => |cf| {
    try checkDefined(defs, cf.a);
    try checkDefined(defs, cf.b);
},
.call => |c| {

    for (c.args[0..c.arg_count]) |arg| try checkDefined(defs, arg);
},
.load => |l| try checkDefined(defs, l.ptr),
.lea => |l| {
    try checkDefined(defs, l.base);
    if (l.index != .imm) try checkDefined(defs, l.index);
},
.store => |s| {
    try checkDefined(defs, s.ptr);
    try checkDefined(defs, s.src);

},
.ret => |r| switch (r) {
    .void_ret => {},
    .value => |v| try checkDefined(defs, v),
},
.phi => |p| {
    for (p.incoming) |inc| {
        try checkDefined(defs, inc.src);
    }
},

.fadd => |f| {
    try checkDefined(defs, f.a);
    try checkDefined(defs, f.b);
},
.fsub => |f| {
    try checkDefined(defs, f.a);
    try checkDefined(defs, f.b);
},
.fmul => |f| {
    try checkDefined(defs, f.a);

    try checkDefined(defs, f.b);
},
.fdiv => |f| {
    try checkDefined(defs, f.a);
    try checkDefined(defs, f.b);
},
.fneg_op => |f| try checkDefined(defs, f.dst),
.fsqrt_op => |f| try checkDefined(defs, f.dst),
.fcmp => |f| {
    try checkDefined(defs, f.a);

    try checkDefined(defs, f.b);
},
.sitofp => |c| try checkDefined(defs, c.src),
.fptosi => |c| try checkDefined(defs, c.src),
.fpext => |c| try checkDefined(defs, c.src),
.fptrunc => |c| try checkDefined(defs, c.src),
.sext_op => |c| try checkDefined(defs, c.src),
.zext_op => |c| try checkDefined(defs, c.src),
.trunc_op => |c| try checkDefined(defs, c.src),
.select => |s| {

    try checkDefined(defs, s.dst);
    try checkDefined(defs, s.src);
},
.event_dispatch => |m| {
    try checkDefined(defs, m.buf);
    try checkDefined(defs, m.size);
},
.transition_check => |m| {
    try checkDefined(defs, m.event);
},

        .guard_eval => |m| {
            try checkDefined(defs, m.lhs);
            try checkDefined(defs, m.rhs);
        },
        else => {},
    }
}

fn isTerminator(inst: mir.MInst) bool {
    return switch (inst) {

        .jmp, .jcc, .ret, .trap => true,
        else => false,
    };
}

fn checkBlockTargets(block: *const mir.MBlock, num_blocks: usize) !void {
    for (block.instrs.items) |inst| {
        switch (inst) {
            .jmp => |j| if (j.target >= num_blocks) return error.InvalidBlockTarget,
            .jcc => |j| if (j.target >= num_blocks) return error.InvalidBlockTarget,

            else => {},
        }
    }
}

pub fn verifyMir(mfunc: *const mir.MFunction) !void {
    const num_blocks = mfunc.blocks.items.len;
    if (num_blocks == 0) return;

    var defs = collectDefinedVRegs(mfunc);

defer defs.deinit();

for (mfunc.blocks.items) |*block| {
    try checkBlockTargets(block, num_blocks);
}

for (mfunc.blocks.items) |*block| {
    if (block.instrs.items.len > 0) {
        if (!isTerminator(block.instrs.items[block.instrs.items.len - 1])) {
            return error.MissingTerminator;

        }
    }
}

for (mfunc.blocks.items) |*block| {
    for (block.instrs.items) |inst| {
        try checkUsedVRegs(inst, &defs);
    }
}

var visited = std.AutoHashMap(usize, void).init(std.heap.page_allocator);
defer visited.deinit();
var queue = std.ArrayList(usize).init(std.heap.page_allocator);
defer queue.deinit();
try queue.append(0);

var front: usize = 0;
while (front < queue.items.len) {
    const b = queue.items[front];
    front += 1;

if (visited.contains(b)) continue;
try visited.put(b, {});
const block = &mfunc.blocks.items[b];
for (block.instrs.items) |inst| {
    const target = switch (inst) {
        .jmp => |j| j.target,
        .jcc => |j| j.target,
        else => continue,
    };
    if (!visited.contains(target)) {

                try queue.append(target);
            }
        }
    }

    for (0..num_blocks) |i| {
        if (!visited.contains(i)) return error.UnreachableBlock;
    }
}

pub fn verifyNoPhis(mfunc: *const mir.MFunction) !void {
    for (mfunc.blocks.items) |*block| {
        for (block.instrs.items) |inst| {
            if (inst == .phi) return error.PhiNotEliminated;
        }
    }
}

const std = @import("std");

pub const ResourceType = enum {
    input,
    transient,
    output,
    persistent,
};

pub const Resource = struct {

    name: []const u8,
    resource_type: ResourceType,
    format: []const u8,
    size_hint: []const u8,
};

pub const Pass = struct {
    name: []const u8,
    shader: []const u8,
    reads: [][]const u8,

    writes: [][]const u8,
    group_x: u32,
    group_y: u32,
    group_z: u32,
};

pub const Pipeline = struct {
    name: []const u8,
    resources: []Resource,
    passes: []Pass,

};

pub fn parsePipeline(allocator: std.mem.Allocator, source: []const u8) !Pipeline {
    var resources = std.ArrayList(Resource).init(allocator);
    var passes = std.ArrayList(Pass).init(allocator);

    var lines = std.ArrayList([]const u8).init(allocator);
    var line_iter = std.mem.tokenizeScalar(u8, source, '\n');
    while (line_iter.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t\r");

    if (trimmed.len == 0 or std.mem.startsWith(u8, trimmed, "//")) continue;
    try lines.append(trimmed);
}

var i: usize = 0;
var pipeline_name: ?[]const u8 = null;

while (i < lines.items.len) : (i += 1) {
    const line = lines.items[i];

if (std.mem.startsWith(u8, line, "pipeline ")) {
    const rest = std.mem.trim(u8, line["pipeline ".len..], " \t");
    if (std.mem.endsWith(u8, rest, "{")) {
        pipeline_name = std.mem.trim(u8, rest[0 .. rest.len - 1], " \t");
    } else {
        pipeline_name = rest;
    }
    continue;
}

if (std.mem.startsWith(u8, line, "resource ")) {
    const rest = std.mem.trim(u8, line["resource ".len..], " \t");
    const name = std.mem.trimRight(u8, rest, " {");
    var res_type: ResourceType = .transient;
    var format: []const u8 = "rgba16f";
    var size_hint: []const u8 = "render";

    i += 1;
    while (i < lines.items.len and !std.mem.eql(u8, lines.items[i], "}")) {
        const prop_line = std.mem.trim(u8, lines.items[i], " \t");

    if (parseProp(prop_line, "type")) |val| {
        res_type = std.meta.stringToEnum(ResourceType, val) orelse .transient;
    } else if (parseProp(prop_line, "format")) |val| {
        format = val;
    } else if (parseProp(prop_line, "size")) |val| {
        size_hint = val;
    }
    i += 1;
}

    try resources.append(Resource{
        .name = try allocator.dupe(u8, name),
        .resource_type = res_type,
        .format = try allocator.dupe(u8, format),
        .size_hint = try allocator.dupe(u8, size_hint),
    });
    continue;
}

if (std.mem.startsWith(u8, line, "pass ")) {

const rest = std.mem.trim(u8, line["pass ".len..], " \t");
const pass_name = std.mem.trimRight(u8, rest, " {");

var shader: ?[]const u8 = null;
var reads = std.ArrayList([]const u8).init(allocator);
var writes = std.ArrayList([]const u8).init(allocator);
var gx: u32 = 8;
var gy: u32 = 8;
var gz: u32 = 1;

i += 1;
while (i < lines.items.len and !std.mem.eql(u8, lines.items[i], "}")) {
    const prop_line = std.mem.trim(u8, lines.items[i], " \t");
    if (std.mem.startsWith(u8, prop_line, "shader ")) {
        shader = extractQuoted(prop_line["shader ".len..]);
    } else if (std.mem.startsWith(u8, prop_line, "read ")) {
        const rest2 = std.mem.trim(u8, prop_line["read ".len..], " \t;");
        var it2 = std.mem.tokenizeScalar(u8, rest2, ',');
        while (it2.next()) |token| {
            const t = std.mem.trim(u8, token, " \t\"");

        if (t.len > 0) try reads.append(try allocator.dupe(u8, t));
    }
} else if (std.mem.startsWith(u8, prop_line, "write ")) {
    const rest2 = std.mem.trim(u8, prop_line["write ".len..], " \t;");
    var it2 = std.mem.tokenizeScalar(u8, rest2, ',');
    while (it2.next()) |token| {
        const t = std.mem.trim(u8, token, " \t\"");
        if (t.len > 0) try writes.append(try allocator.dupe(u8, t));
    }
} else if (std.mem.startsWith(u8, prop_line, "dispatch(")) {

        parseDispatch(prop_line, &gx, &gy, &gz);
    }
    i += 1;
}

try passes.append(Pass{
    .name = try allocator.dupe(u8, pass_name),
    .shader = try allocator.dupe(u8, shader orelse "unknown"),
    .reads = try reads.toOwnedSlice(),
    .writes = try writes.toOwnedSlice(),

            .group_x = gx,
            .group_y = gy,
            .group_z = gz,
        });
        continue;
    }
}

return Pipeline{
    .name = try allocator.dupe(u8, pipeline_name orelse "TSS"),

        .resources = try resources.toOwnedSlice(),
        .passes = try passes.toOwnedSlice(),
    };
}

fn parseProp(line: []const u8, key: []const u8) ?[]const u8 {
    const prefix1 = std.fmt.allocPrint(std.heap.page_allocator, "{s} = ", .{key}) catch return null;
    defer std.heap.page_allocator.free(prefix1);
    if (std.mem.startsWith(u8, line, prefix1)) {
        return std.mem.trim(u8, line[prefix1.len..], " \t;\"");

    }
    const prefix2 = std.fmt.allocPrint(std.heap.page_allocator, "{s}=", .{key}) catch return null;
    defer std.heap.page_allocator.free(prefix2);
    if (std.mem.startsWith(u8, line, prefix2)) {
        return std.mem.trim(u8, line[prefix2.len..], " \t;\"");
    }
    return null;
}

fn extractQuoted(s: []const u8) []const u8 {

    const trimmed = std.mem.trim(u8, s, " \t;");
    if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
        return trimmed[1 .. trimmed.len - 1];
    }
    return trimmed;
}

fn parseDispatch(line: []const u8, gx: *u32, gy: *u32, gz: *u32) void {
    const start = "dispatch(".len;
    const inner = line[start..];

const end = std.mem.indexOfScalar(u8, inner, ')') orelse return;
const args_str = std.mem.trim(u8, inner[0..end], " \t");
var arg_iter = std.mem.tokenizeScalar(u8, args_str, ',');
const parts = [_]*u32{ gx, gy, gz };
var pi: usize = 0;
while (arg_iter.next()) |token| : (pi += 1) {
    const t = std.mem.trim(u8, token, " \t");
    if (pi < parts.len and t.len > 0) {
        parts[pi].* = std.fmt.parseInt(u32, t, 10) catch 8;
    }

    }
}

fn formatToCppEnum(format: []const u8) []const u8 {
    if (std.ascii.eqlIgnoreCase(format, "rgba8") or std.ascii.eqlIgnoreCase(format, "b8g8r8a8")) return "PF_B8G8R8A8";
    if (std.ascii.eqlIgnoreCase(format, "rgba16f") or std.ascii.eqlIgnoreCase(format, "floatrgba")) return "PF_FloatRGBA";
    if (std.ascii.eqlIgnoreCase(format, "r32f") or std.ascii.eqlIgnoreCase(format, "r32_float")) return "PF_R32_FLOAT";
    if (std.ascii.eqlIgnoreCase(format, "rg16f") or std.ascii.eqlIgnoreCase(format, "g16r16f")) return "PF_G16R16F";
    if (std.ascii.eqlIgnoreCase(format, "r16f") or std.ascii.eqlIgnoreCase(format, "r16_float")) return "PF_R16F";
    return "PF_FloatRGBA";

}

fn toPascalCase(allocator: std.mem.Allocator, s: []const u8) ![]const u8 {
    if (s.len == 0) return try allocator.dupe(u8, s);
    var buf = std.ArrayList(u8).init(allocator);
    var segments = std.mem.tokenizeScalar(u8, s, '_');
    while (segments.next()) |seg| {
        if (abbreviation(seg)) |abbr| {
            try buf.appendSlice(abbr);
        } else {

        for (seg, 0..) |c, j| {
            if (j == 0) {
                try buf.append(std.ascii.toUpper(c));
            } else {
                try buf.append(std.ascii.toLower(c));
            }
        }
    }
}
return try buf.toOwnedSlice();

}

fn abbreviation(seg: []const u8) ?[]const u8 {
    if (std.ascii.eqlIgnoreCase(seg, "rcas")) return "RCAS";
    if (std.ascii.eqlIgnoreCase(seg, "easu")) return "EASU";
    if (std.ascii.eqlIgnoreCase(seg, "fsr2")) return "FSR2";
    return null;
}

fn toUsfName(allocator: std.mem.Allocator, s: []const u8) ![]const u8 {

var buf = std.ArrayList(u8).init(allocator);
try buf.appendSlice("TSS");
var segments = std.mem.tokenizeScalar(u8, s, '_');
while (segments.next()) |seg| {
    if (abbreviation(seg)) |abbr| {
        try buf.appendSlice(abbr);
    } else {
        for (seg, 0..) |c, j| {
            if (j == 0) {
                try buf.append(std.ascii.toUpper(c));

                } else {
                    try buf.append(std.ascii.toLower(c));
                }
            }
        }
    }
    return try buf.toOwnedSlice();
}

pub fn generateShadersHeader(allocator: std.mem.Allocator, pipeline: *const Pipeline) ![]const u8 {

var buf = std.ArrayList(u8).init(allocator);
const w = buf.writer();

try w.writeAll(
    "#pragma once\n\n"
    ++ "#include \"CoreMinimal.h\"\n"
    ++ "#include \"DataDrivenShaderPlatformInfo.h\"\n"
    ++ "#include \"RenderGraph.h\"\n"
    ++ "#include \"GlobalShader.h\"\n"
    ++ "#include \"ShaderParameterStruct.h\"\n\n"

    ++ "\t} \\\n"
    ++ "};\n\n"
);

var seen = std.StringHashMap(void).init(allocator);
defer seen.deinit();

for (pipeline.passes) |pass| {
    if (seen.contains(pass.shader)) continue;
    try seen.put(pass.shader, {});

const cls = try toPascalCase(allocator, pass.shader);
defer allocator.free(cls);
const usf_n = try toUsfName(allocator, pass.shader);
defer allocator.free(usf_n);
const entry = try toPascalCase(allocator, pass.shader);
defer allocator.free(entry);

try w.print(
    "TSS_DECLARE_SHADER(FTSSShader_{s}, \"/Plugin/TSS/Private/{s}.usf\", \"{s}Main\")\n",

        .{ cls, usf_n, entry },
    );
}

try w.writeAll(
    "TSS_DECLARE_SHADER(FTSSShader_Copy, \"/Plugin/TSS/Private/TSSCopy.usf\", \"CopyMain\")\n"
    ++ "TSS_DECLARE_SHADER(FTSSShader_EASU, \"/Plugin/TSS/Private/TSSEASU.usf\", \"EASUMain\")\n"
);

return try buf.toOwnedSlice();

}

