pub fn generateViewExtensionCpp(allocator: std.mem.Allocator, pipeline: *const Pipeline) ![]const u8 {
    _ = pipeline;
    var buf = std.ArrayList(u8).init(allocator);
    const w = buf.writer();

    try w.writeAll(
        "#include \"TSSViewExtension.h\"\n"
        ++ "#include \"PostProcess/PostProcessing.h\"\n"
        ++ "#include \"TSSRuntime.h\"\n"

        ++ "{
"
        ++ "	delete Runtime;
"
        ++ "}

"
        ++ "float FTSSViewExtension::Halton(int32 Index, int32 Base)
"
        ++ "{
"
        ++ "	float Result = 0.0f;
"
        ++ "	float InvBase = 1.0f / Base;
"
        ++ "	float Fraction = InvBase;
"
        ++ "	while (Index > 0)
"
        ++ "	{
"

        ++ "		Result += (float)(Index % Base) * Fraction;
"
        ++ "		Index /= Base;
"
        ++ "		Fraction *= InvBase;
"
        ++ "	}
"
        ++ "	return Result;
"
        ++ "}

"
        ++ "void FTSSViewExtension::PreRenderView_RenderThread(FRDGBuilder& GraphBuilder, FSceneView& View)
"
        ++ "{
"
        ++ "	float Downscale = CVarTSSDownscale.GetValueOnRenderThread();
"
        ++ "	if (Downscale < SMALL_NUMBER) return;
"

        ++ "	}
"
        ++ "	{
"
        ++ "		FMatrix& InvViewProjMat = const_cast<FMatrix&>(View.ViewMatrices.GetInvViewProjectionMatrix());
"
        ++ "		InvViewProjMat = View.ViewMatrices.GetViewProjectionMatrix().Inverse();
"
        ++ "	}
"
        ++ "	JitterFrameIndex++;
"
        ++ "}

"
        ++ "void FTSSViewExtension::PrePostProcessPass_RenderThread(
"
        ++ "	FRDGBuilder& GraphBuilder,
"
        ++ "	const FSceneView& View,
"

        ++ "		PrevVP0 = FVector4f(PrevVP.M[0][0], PrevVP.M[0][1], PrevVP.M[0][2], PrevVP.M[0][3]);
"
        ++ "		PrevVP1 = FVector4f(PrevVP.M[1][0], PrevVP.M[1][1], PrevVP.M[1][2], PrevVP.M[1][3]);
"
        ++ "		PrevVP2 = FVector4f(PrevVP.M[2][0], PrevVP.M[2][1], PrevVP.M[2][2], PrevVP.M[2][3]);
"
        ++ "		PrevVP3 = FVector4f(PrevVP.M[3][0], PrevVP.M[3][1], PrevVP.M[3][2], PrevVP.M[3][3]);
"
        ++ "	}
"
        ++ "	LastViewFamilyOutput = ViewFamilyOutput;
"
        ++ "	Runtime->ExecutePlan(GraphBuilder, SceneColor, ViewFamilyOutput, Velocity, Depth, DisplaySize, Downscale, PrevVP0, PrevVP1, PrevVP2, PrevVP3, CurrInvVP0, CurrInvVP1, CurrInvVP2, CurrInvVP3, bUsePrevFrame);
"
        ++ "	PrevFrameWorldToClip = FMatrix44f(View.ViewMatrices.GetViewProjectionMatrix());
"
        ++ "	bUsePrevFrame = true;
"
        ++ "}

"

        ++ "float FTSSViewExtension::GetDownscaleFactor() const { return DownscaleFactor; }

"
        ++ "void FTSSViewExtension::SetDownscaleFactor(float Factor) { DownscaleFactor = FMath::Clamp(Factor, 0.25f, 1.0f); }

"
        ++ "void FTSSViewExtension::PostRenderView_RenderThread(
"
        ++ "	FRDGBuilder& GraphBuilder,
"
        ++ "	FSceneView& View)
"
        ++ "{
"
        ++ "	FRDGTextureRef TSSResult = Runtime->GetLastFinalOutput();
"
        ++ "	if (!TSSResult || !LastViewFamilyOutput)
"
        ++ "	{
"
        ++ "		UE_LOG(LogTemp, Warning, TEXT("TSS: PostRenderView skipped (no FinalOutput or ViewFamily)"));
"

    ++ "\t\t\t});\n"
    ++ "\t\tif (!bHasUAV)\n"
    ++ "\t\t{\n"
    ++ "\t\t\tAddCopyTexturePass(GraphBuilder, CopyDst, LastViewFamilyOutput);\n"
    ++ "\t\t}\n"
    ++ "\t}\n"
    ++ "}\n"
);

return try buf.toOwnedSlice();

}

fn writePersistentInit(w: anytype, allocator: std.mem.Allocator, pipeline: *const Pipeline, tex_name: []const u8, rt_field: []const u8, size_expr: []const u8, _: []const u8, debug_name: []const u8) !void {
    _ = allocator;
    _ = pipeline;
    const init_name = try std.fmt.allocPrint(std.heap.page_allocator, "{s}_Init", .{debug_name});
    defer std.heap.page_allocator.free(init_name);
    try w.writeAll("\tif (");
    try w.writeAll(rt_field);
    try w.writeAll("RT.IsValid() && bCacheValid && !bIsNative)\n");

try w.writeAll("\t{\n");
try w.writeAll("\t\tFRDGTextureRef ");
try w.writeAll(tex_name);
try w.writeAll("Tex = GraphBuilder.RegisterExternalTexture(");
try w.writeAll(rt_field);
try w.writeAll("RT, TEXT(\"");
try w.writeAll(debug_name);
try w.writeAll("\"));\n");
try w.writeAll("\t\tTextureCache.Add(TEXT(\"");
try w.writeAll(tex_name);

try w.writeAll("\"), ");
try w.writeAll(tex_name);
try w.writeAll("Tex);\n");
try w.writeAll("\t}\n");
try w.writeAll("\telse\n");
try w.writeAll("\t{\n");
try w.writeAll("\t\tFRDGTextureRef Init");
try w.writeAll(tex_name);
try w.writeAll(" = GraphBuilder.CreateTexture(\n");
try w.writeAll("\t\t\tFRDGTextureDesc::Create2D(");

try w.writeAll(tex_name);
try w.writeAll(", ");
try w.writeAll(size_expr);
try w.writeAll(",\n");
try w.writeAll("\t\t\t\tFClearValueBinding::None,\n");
try w.writeAll("\t\t\t\tTexCreate_UAV | TexCreate_ShaderResource),\n");
try w.writeAll("\t\t\tTEXT(\"");
try w.writeAll(init_name);
try w.writeAll("\"));\n");
try w.writeAll("\t\tTextureCache.Add(TEXT(\"");

    try w.writeAll(tex_name);
    try w.writeAll("\"), Init");
    try w.writeAll(tex_name);
    try w.writeAll(");\n");
    try w.writeAll("\t}\n\n");
}

