},
.PUSHFQ => {
    try code.append(0x9C);
},
.POPFQ => {
    try code.append(0x9D);
},

.CQO => {
    try code.append(0x48);
    try code.append(0x99);
},
.RET => try code.append(0xC3),
.NOP => try code.append(0x90),
.INT3 => try code.append(0xCC),
.UD2 => {
    try code.append(0x0F);
    try code.append(0x0B);

.SSE_MINPS     => try emitSseOp(code, 0, 0x5D, operands[0].reg, operands[1]),
.SSE_MAXPS     => try emitSseOp(code, 0, 0x5F, operands[0].reg, operands[1]),
.SSE_SQRTPS    => try emitSseOp(code, 0, 0x51, operands[0].reg, operands[1]),
.SSE_MOVLHPS   => try emitSseOp(code, 0, 0x16, operands[0].reg, operands[1]),
.SSE_SHUFPS => {
    if (operands.len < 3) return error.MissingOperands;
    try emitSseOp(code, 0, 0xC6, operands[0].reg, operands[1]);
    try code.append(@as(u8, @intCast(operands[2].imm64 & 0xFF)));
},
// SSE scalar single (prefix F3)

    const reg = operands[0].reg;
    const cc = @as(u8, @intCast(operands[1].imm64 & 0xF));
    if (reg >= 4) {
        try code.append(0x40 | @as(u8, @intCast((@as(u8, @intCast(reg)) >> 3) & 1)));
    }
    try code.append(0x0F);
    try code.append(0x90 | cc);
    try code.append(0xC0 | @as(u8, @intCast(reg & 7)));
},
.SSE_CVTSI2SS  => try emitSseOp(code, 0xF3, 0x2A, operands[0].reg, operands[1]),

.SSE_CVTTSS2SI => try emitSseOp(code, 0xF3, 0x2C, operands[0].reg, operands[1]),
.SSE_UCOMISS   => try emitSseOp(code, 0, 0x2E, operands[0].reg, operands[1]),
.SSE_SQRTSS    => try emitSseOp(code, 0xF3, 0x51, operands[0].reg, operands[1]),
.SSE_RSQRTSS   => try emitSseOp(code, 0xF3, 0x52, operands[0].reg, operands[1]),
.SSE_HADDPS    => try emitSseOp(code, 0xF2, 0x7C, operands[0].reg, operands[1]),
.SSE_DPPS => {
    if (operands.len < 3) return error.MissingOperands;
    try code.append(0x66);
    var rex: u8 = 0;
    if (operands[0].reg >= 8) rex |= 0x04;

    if (operands[1].reg >= 8) rex |= 0x01;
    if (rex != 0) try code.append(0x40 | rex);
    try code.append(0x0F);
    try code.append(0x3A);
    try code.append(0x40);
    const modrm: u8 = 0xC0 | (@as(u8, @intCast(operands[0].reg & 7)) << 3) | @as(u8, @intCast(operands[1].reg & 7));
    try code.append(modrm);
    try code.append(@as(u8, @intCast(operands[2].imm64 & 0xFF)));
},
.SSE_ROUNDSS => {

if (operands.len < 3) return error.MissingOperands;
try code.append(0x66);
var rex: u8 = 0;
if (operands[0].reg >= 8) rex |= 0x04;
if (operands[1].reg >= 8) rex |= 0x01;
if (rex != 0) try code.append(0x40 | rex);
try code.append(0x0F);
try code.append(0x3A);
try code.append(0x0A);
const modrm: u8 = 0xC0 | (@as(u8, @intCast(operands[0].reg & 7)) << 3) | @as(u8, @intCast(operands[1].reg & 7));

    try code.append(modrm);
    try code.append(@as(u8, @intCast(operands[2].imm64 & 0xFF)));
},
// SSE with 66 prefix
.SSE_MOVD_LD   => try emitSseOp(code, 0x66, 0x6E, operands[0].reg, operands[1]),
.SSE_MOVD_ST   => try emitSseOp(code, 0x66, 0x7E, operands[1].reg, operands[0]),
.SSE_MOVQ_LD   => try emitSseOp(code, 0xF3, 0x7E, operands[0].reg, operands[1]),
.SSE_MOVQ_ST   => try emitSseOp(code, 0x66, 0xD6, operands[1].reg, operands[0]),
.SSE_MOVSD_LD  => try emitSseOp(code, 0xF2, 0x10, operands[0].reg, operands[1]),
.SSE_MOVSD_ST  => try emitSseOp(code, 0xF2, 0x11, operands[1].reg, operands[0]),

.SSE_CVTSS2SD  => try emitSseOp(code, 0xF2, 0x5A, operands[0].reg, operands[1]),
.SSE_CVTSD2SS  => try emitSseOp(code, 0xF3, 0x5A, operands[0].reg, operands[1]),
.SSE_UCOMISD   => try emitSseOp(code, 0x66, 0x2E, operands[0].reg, operands[1]),
.SSE_SQRTSD    => try emitSseOp(code, 0xF2, 0x51, operands[0].reg, operands[1]),
.MOVSX_R64_R32 => {
    if (operands.len < 2) return error.MissingOperands;
    try emitModrmSibDisp(code, 0x48, 0x63, operands[0].reg, operands[1], 0);
},
.SSE_CVTSI2SS_64  => try emitSseOpRexW(code, 0xF3, 0x2A, operands),
.SSE_CVTSI2SD_64  => try emitSseOpRexW(code, 0xF2, 0x2A, operands),

.SSE_CVTTSS2SI_64 => try emitSseOpRexW(code, 0xF3, 0x2C, operands),
.SSE_CVTTSD2SI_64 => try emitSseOpRexW(code, 0xF2, 0x2C, operands),
.CMOV_R64_R64 => {
    if (operands.len < 3) return error.MissingOperands;
    const dst = operands[0].reg;
    const src = operands[1].reg;
    const cc = @as(u8, @intCast(operands[2].imm64 & 0xF));
    if (dst < 0 or dst > 15 or src < 0 or src > 15) return error.InvalidRegister;
    var rex: u8 = 0x48;
    if (dst >= 8) rex |= 0x04;

    if (src >= 8) rex |= 0x01;
    try code.append(rex);
    try code.append(0x0F);
    try code.append(0x40 | cc);
    try code.append(0xC0 | ((@as(u8, @intCast(dst & 7)) << 3) | @as(u8, @intCast(src & 7))));
},
.CMOV_R64_MEM => {
    if (operands.len < 3) return error.MissingOperands;
    const dst_reg = operands[0].reg;
    const m = operands[1];

            const cc = @as(u8, @intCast(operands[2].imm64 & 0xF));
            // CMOVcc r64, m64: REX.W 0F 4x ModRM
            // Use emitModrmSibDisp with prefix=0x0F, op=0x40|cc
            try emitModrmSibDisp(code, 0x48, 0x40 | cc, dst_reg, m, 0x0F);
        },
    }
}

fn emitJcc(code: *std.ArrayList(u8), opcode: u16, operands: []const Operand) !void {
    if (operands.len < 1) return error.MissingOperands;

    const b0: u8 = @intCast(opcode >> 8);
    const b1: u8 = @intCast(opcode & 0xFF);
    try code.append(b0);
    try code.append(b1);
    const disp_bytes: [4]u8 = @bitCast(@as(i32, @bitCast(@as(u32, @truncate(operands[0].imm64)))));
    try code.appendSlice(&disp_bytes);
}

fn emitSseOp(code: *std.ArrayList(u8), simd_prefix: u8, opcode: u8, reg: i16, m: Operand) !void {
    if (simd_prefix != 0) try code.append(simd_prefix);

    try emitModrmSibDisp(code, 0, opcode, reg, m, 0x0F);
}

fn emitSseOpRexW(code: *std.ArrayList(u8), simd_prefix: u8, opcode: u8, operands: []const Operand) !void {
    if (operands.len < 2) return error.MissingOperands;
    if (simd_prefix != 0) try code.append(simd_prefix);
    try emitModrmSibDisp(code, 0x48, opcode, operands[0].reg, operands[1], 0x0F);
}

fn prefetchRipRel(code: *std.ArrayList(u8), reg: u8) !void {

    try code.append(0x0F);
    try code.append(0x18);
    try code.append(0x05 | ((reg & 7) << 3));
    const zero: [4]u8 = .{ 0, 0, 0, 0 };
    try code.appendSlice(&zero);
}

fn emitModrmSibDisp(code: *std.ArrayList(u8), rex_base: u8, op: u8, reg: i16, m: Operand, prefix: u8) !void {
    var rex = rex_base;
    if (reg >= 8) rex |= 0x04; // REX.R

if (m.reg >= 8) {
    rex |= 0x01; // REX.B for register-direct
} else if (m.base_reg >= 0 and m.base_reg != 255) {
    if (m.base_reg >= 8) rex |= 0x01; // REX.B for base register
}
if (m.index_reg >= 8) rex |= 0x02; // REX.X for index register
if (rex != 0) try code.append(0x40 | rex);
if (prefix != 0) try code.append(prefix);

try code.append(op);

if (m.reg >= 0) {
    // Register-direct: mod=11
    const modrm: u8 = 0xC0 | (@as(u8, @intCast(reg & 7)) << 3) | @as(u8, @intCast(m.reg & 7));
    try code.append(modrm);
} else if (m.index_reg >= 0 and m.index_reg != 4) {
    // SIB addressing: [base + index*scale + disp]
    const mod: u8 = if (m.disp == 0 and m.base_reg != 5) 0 else if (m.disp >= -128 and m.disp <= 127) 1 else 2;
    const modrm: u8 = mod << 6 | (@as(u8, @intCast(reg & 7)) << 3) | 4;
    try code.append(modrm);

    const scale_enc: u8 = switch (m.scale) { 1 => 0, 2 => 1, 4 => 2, 8 => 3, else => 0 };
    const sib: u8 = (scale_enc << 6) | (@as(u8, @intCast(m.index_reg & 7)) << 3) | @as(u8, @intCast(m.base_reg & 7));
    try code.append(sib);
    if (mod == 1) {
        try code.append(@as(u8, @bitCast(@as(i8, @intCast(m.disp)))));
    } else if (mod == 2) {
        const disp_bytes: [4]u8 = @bitCast(m.disp);
        try code.appendSlice(&disp_bytes);
    }
} else if (m.base_reg == 255) {

    // RIP-relative
    try code.append(0x05 | (@as(u8, @intCast(reg & 7)) << 3));
    const disp_bytes: [4]u8 = @bitCast(m.disp);
    try code.appendSlice(&disp_bytes);
} else if (m.base_reg >= 0) {
    const mod: u8 = if (m.disp == 0 and m.base_reg != 5) 0 else if (m.disp >= -128 and m.disp <= 127) 1 else 2;
    const b = @as(u8, @intCast(m.base_reg & 7));
    if (b == 4) {
        // RSP/R12 as base requires SIB byte
        const modrm: u8 = mod << 6 | (@as(u8, @intCast(reg & 7)) << 3) | 4;

    try code.append(modrm);
    try code.append(0x24); // [rsp]
    if (mod == 1) {
        try code.append(@as(u8, @bitCast(@as(i8, @intCast(m.disp)))));
    } else if (mod == 2) {
        const disp_bytes: [4]u8 = @bitCast(m.disp);
        try code.appendSlice(&disp_bytes);
    }
} else {
    const modrm: u8 = mod << 6 | (@as(u8, @intCast(reg & 7)) << 3) | b;

        try code.append(modrm);
        if (mod == 1) {
            try code.append(@as(u8, @bitCast(@as(i8, @intCast(m.disp)))));
        } else if (mod == 2) {
            const disp_bytes: [4]u8 = @bitCast(m.disp);
            try code.appendSlice(&disp_bytes);
        }
    }
} else {
    // Absolute displacement with no base (mod=00, rm=101)

        try code.append(0x04 | (@as(u8, @intCast(reg & 7)) << 3));
        const disp_bytes: [4]u8 = @bitCast(m.disp);
        try code.appendSlice(&disp_bytes);
    }
}

const RegNames = [_][:0]const u8{
    "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi",
    "r8",  "r9",  "r10", "r11", "r12", "r13", "r14", "r15",
};

fn regName(reg: u8, rex_b: bool) [:0]const u8 {
    const r = if (rex_b) reg | 8 else reg & 7;
    return RegNames[r & 15];
}

fn modRMDecode(byte: u8) struct { mod: u8, reg: u8, rm: u8 } {
    return .{ .mod = byte >> 6, .reg = (byte >> 3) & 7, .rm = byte & 7 };
}

const DecodedInst = struct {
    mnemonic: []const u8,
    ops: []const u8,
    len: usize,
};

fn decodeOne(bytes: []const u8) !DecodedInst {
    if (bytes.len == 0) return error.EndOfStream;
    var pos: usize = 0;

const rex: u8 = if (pos < bytes.len and bytes[pos] >= 0x40 and bytes[pos] <= 0x4F) blk: {
    const r = bytes[pos];
    pos += 1;
    break :blk r;
} else 0;
const rex_w: bool = (rex & 8) != 0;

const two_byte: bool = if (pos < bytes.len and bytes[pos] == 0x0F) blk: {
    pos += 1;
    break :blk true;

} else false;

if (pos >= bytes.len) return error.EndOfStream;
const op = bytes[pos];
pos += 1;

var imm_size: usize = 0;
var needs_modrm = false;

const mnemonic: []const u8 = if (two_byte) blk: {

0x9A => { needs_modrm = true; break :blk "setp"; },
0x9B => { needs_modrm = true; break :blk "setnp"; },
0x9C => { needs_modrm = true; break :blk "setl"; },
0x9D => { needs_modrm = true; break :blk "setge"; },
0x9E => { needs_modrm = true; break :blk "setle"; },
0x9F => { needs_modrm = true; break :blk "setg"; },
0xD6 => { needs_modrm = true; break :blk "movq"; },
0x3A => {
    if (pos >= bytes.len) return error.EndOfStream;
    const op3 = bytes[pos]; pos += 1;

            needs_modrm = true;
            imm_size = 1;
            if (op3 == 0x0A) break :blk "roundss";
            if (op3 == 0x40) break :blk "dpps";
            return error.UnknownInstruction;
        },
        else => return error.UnknownInstruction,
    }
} else blk: {
    if (op >= 0x88 and op <= 0x8B) { needs_modrm = true;

    break :blk if (op == 0x89 or op == 0x8B) "mov" else "mov"; }
switch (op) {
    0x00...0x03 => { needs_modrm = true; break :blk "add"; },
    0x04 => { imm_size = 1; break :blk "add"; },
    0x08...0x0B => { needs_modrm = true; break :blk "or"; },
    0x20...0x23 => { needs_modrm = true; break :blk "and"; },
    0x28...0x2B => { needs_modrm = true; break :blk "sub"; },
    0x38...0x3B => { needs_modrm = true; break :blk "cmp"; },
    0x3C => { imm_size = 1; break :blk "cmp"; },
    0x50...0x5F => {

    const r = op & 7;
    _ = r;
    if (op >= 0x58) break :blk "pop";
    break :blk "push";
},
0x68 => { imm_size = 4; break :blk "push"; },
0x6A => { imm_size = 1; break :blk "push"; },
0x70 => { imm_size = 1; break :blk "jo"; },
0x71 => { imm_size = 1; break :blk "jno"; },
0x72 => { imm_size = 1; break :blk "jb"; },

0x7D => { imm_size = 1; break :blk "jge"; },
0x7E => { imm_size = 1; break :blk "jle"; },
0x7F => { imm_size = 1; break :blk "jg"; },
0x85 => { needs_modrm = true; break :blk "test"; },
0x8D => { needs_modrm = true; break :blk "lea"; },
0xB0...0xB7 => { imm_size = 1; break :blk "mov"; },
0xB8...0xBF => {
    if (rex_w) imm_size = 8 else imm_size = 4;
    break :blk "mov";
},

        0x09 => { needs_modrm = true; break :blk "or"; },
        0x21 => { needs_modrm = true; break :blk "and"; },
        0x39 => { needs_modrm = true; break :blk "cmp"; },
        0x0F => { break :blk "nop"; },
        0xCC => { break :blk "int3"; },
        else => return error.UnknownInstruction,
    }
};

if (pos >= bytes.len) return error.EndOfStream;

var mr: struct { mod: u8, reg: u8, rm: u8 } = undefined;
if (needs_modrm) {
    mr = modRMDecode(bytes[pos]); pos += 1;
}

if (needs_modrm and mr.mod != 3) {
    if (mr.rm == 4) {
        if (pos >= bytes.len) return error.EndOfStream;
        pos += 1; // skip SIB

    }
    if (mr.mod == 1) { if (pos >= bytes.len) return error.EndOfStream; pos += 1; }
    else if (mr.mod == 2 or (mr.mod == 0 and mr.rm == 5)) { if (pos + 4 > bytes.len) return error.EndOfStream; pos += 4; }
}

if (imm_size > 0) {
    if (pos + imm_size > bytes.len) return error.EndOfStream;
    pos += imm_size;
}

    return .{ .mnemonic = mnemonic, .ops = "", .len = pos };
}

pub fn disassemble(bytes: []const u8) ![]u8 {
    var result = std.ArrayList(u8).init(std.heap.page_allocator);
    errdefer result.deinit();
    var pos: usize = 0;
    var writer = result.writer();
    while (pos < bytes.len) {
        const saved = pos;

const decoded = decodeOne(bytes[pos..]) catch {
    try writer.print("  {x:0>4}: ??\n", .{saved});
    pos += 1;
    continue;
};
try writer.print("  {x:0>4}: ", .{saved});
for (bytes[saved..saved + decoded.len]) |b| try writer.print("{x:0>2} ", .{b});
try writer.print("  {s}", .{decoded.mnemonic});
try writer.writeAll("\n");
pos += decoded.len;

    }
    return result.toOwnedSlice();
}

/// x64 instruction encoder.
/// Pure encoding layer: opcode bytes, REX prefix, ModRM, SIB, displacement, immediate.
/// Re-exports the implementation from x64enc.zig.
const std = @import("std");
const ir = @import("ir/inst.zig");

pub const x64enc = @import("encoder/x64enc.zig");

pub const SimdPrefix = x64enc.SimdPrefix;
pub const OpCode = x64enc.OpCode;

pub const Operand = x64enc.Operand;
pub const emit = x64enc.emit;
pub const emitModrmSibDisp = x64enc.emitModrmSibDisp;

/// Encode a single x64 IR instruction to bytes.
pub fn emitInst(code: *std.ArrayList(u8), inst: ir.Instruction) !void {
    try x64enc.emit(code, inst.op, inst.operands[0..inst.olen]);
}

/// Emit an entire MachineFunction, recording block offsets and fixup positions.

pub const EmitInfo = struct {
    block_offsets: std.ArrayListUnmanaged(usize),
    fixup_positions: std.ArrayListUnmanaged(usize),
};

pub fn emitMachineFunc(code: *std.ArrayList(u8), mf: ir.MachineFunction) !EmitInfo {
    const allocator = mf.allocator;
    var info = EmitInfo{
        .block_offsets = .{},
        .fixup_positions = .{},

};
errdefer {
    info.block_offsets.deinit(allocator);
    info.fixup_positions.deinit(allocator);
}

try info.block_offsets.ensureTotalCapacity(allocator, mf.blocks.items.len);
try info.fixup_positions.ensureTotalCapacity(allocator, 32);

for (mf.blocks.items) |*block| {

info.block_offsets.appendAssumeCapacity(code.items.len);
for (block.instrs.items) |inst| {
    const fixup_offset: ?usize = switch (inst.op) {
        .JMP_REL32, .CALL_REL32 => code.items.len + 1,
        .JE_REL32, .JNE_REL32, .JG_REL32, .JGE_REL32,
        .JL_REL32, .JLE_REL32, .JA_REL32, .JB_REL32, .JBE_REL32,
        .JAE_REL32 => code.items.len + 2,
        else => null,
    };
    if (fixup_offset) |off| {

                info.fixup_positions.appendAssumeCapacity(off);
            }
            try emitInst(code, inst);
        }
    }

    return info;
}

/// Encode REX prefix byte for 64-bit operation.

/// rex_flags: bit0 = B (extends rm/oprand), bit1 = X (extends SIB index),
///            bit2 = R (extends reg), bit3 = W (64-bit operand size)
pub fn rexByte(w: u1, r: u1, x: u1, b: u1) u8 {
    return 0x40 | (@as(u8, b) << 0) | (@as(u8, x) << 1) | (@as(u8, r) << 2) | (@as(u8, w) << 3);
}

/// Encode ModRM byte.
/// mod: 0=mem, 1=mem+disp8, 2=mem+disp32, 3=register
/// reg: opcode extension or source register
/// rm:  destination register or memory operand

pub fn modrm(mod: u8, reg: u8, rm: u8) u8 {
    return ((mod & 3) << 6) | ((reg & 7) << 3) | (rm & 7);
}

/// Encode SIB byte.
/// scale: 0=1, 1=2, 2=4, 3=8
/// index: index register (4 = none)
/// base:  base register
pub fn sib(scale: u8, index: u8, base: u8) u8 {
    return ((scale & 3) << 6) | ((index & 7) << 3) | (base & 7);

}

/// Emit a 32-bit displacement.
pub fn emitDisp32(code: *std.ArrayList(u8), disp: i32) !void {
    try code.appendSlice(@ptrCast(&@as([4]u8, @bitCast(disp))));
}

/// Emit a 32-bit immediate.
pub fn emitImm32(code: *std.ArrayList(u8), imm: u32) !void {
    try code.appendSlice(@ptrCast(&@as([4]u8, @bitCast(imm))));

const std = @import("std");
const x64enc = @import("../encoder/x64enc.zig");

pub const OpCode = x64enc.OpCode;

pub const Operand = x64enc.Operand;

pub const Instruction = struct {
    op: OpCode,
    operands: [3]Operand,

    olen: u2,
};

pub const MachineBlock = struct {
    label: []const u8,
    instrs: std.ArrayListUnmanaged(Instruction),
};

pub const MachineFunction = struct {
    name: []const u8,

blocks: std.ArrayListUnmanaged(MachineBlock),
allocator: std.mem.Allocator,

pub fn init(allocator: std.mem.Allocator, name: []const u8) MachineFunction {
    return .{
        .name = name,
        .blocks = .{},
        .allocator = allocator,
    };
}

pub fn deinit(self: *MachineFunction) void {
    for (self.blocks.items) |*b| {
        b.instrs.deinit(self.allocator);
    }
    self.blocks.deinit(self.allocator);
}

pub fn appendBlock(self: *MachineFunction, label: []const u8) !usize {
    const idx = self.blocks.items.len;

    try self.blocks.append(self.allocator, .{
        .label = label,
        .instrs = .{},
    });
    return idx;
}

pub fn appendInstr(self: *MachineFunction, block_idx: usize, op: OpCode, operands: []const Operand) !void {
    const block = &self.blocks.items[block_idx];
    var instr = Instruction{

        .op = op,
        .operands = .{ .{}, .{}, .{} },
        .olen = @intCast(operands.len),
    };
    for (operands, 0..) |o, i| {
        instr.operands[i] = o;
    }
    try block.instrs.append(self.allocator, instr);
}

    pub fn appendInstr2(self: *MachineFunction, block_idx: usize, op: OpCode, o1: Operand, o2: Operand) !void {
        try self.appendInstr(block_idx, op, &.{ o1, o2 });
    }

    pub fn appendInstr1(self: *MachineFunction, block_idx: usize, op: OpCode, o1: Operand) !void {
        try self.appendInstr(block_idx, op, &.{o1});
    }
};

/// Shared context and helpers for x64 instruction selection sub-modules.
const std = @import("std");
const mir = @import("../../../mir/mir.zig");
const enc = @import("../encoder.zig");
const OpCode = enc.OpCode;
const Operand = enc.Operand;
const regalloc = @import("../../../regalloc/regalloc.zig");
const spill = @import("spill.zig");
pub const ir = @import("../ir/inst.zig");

pub const OffsetMap = std.AutoHashMap(u32, i32);

pub const BlockFixup = struct {
    disp_pos: usize,
    target: u32,
};

pub const CallFixup = struct {
    name: []const u8,
    disp_pos: usize,

};

pub const StringConstFixup = struct {
    data: []const u8,
};

pub const SelectResult = struct {
    mf: ir.MachineFunction,
    block_fixups: std.ArrayListUnmanaged(BlockFixup),
    call_fixups: std.ArrayListUnmanaged(CallFixup),

    string_fixups: std.ArrayListUnmanaged(StringConstFixup),

    pub fn deinit(self: *SelectResult, allocator: std.mem.Allocator) void {
        self.mf.deinit();
        self.block_fixups.deinit(allocator);
        self.call_fixups.deinit(allocator);
        self.string_fixups.deinit(allocator);
    }
};

};

pub fn resolveReg(ra: *const regalloc.RegAllocResult, op: mir.MOperand) i16 {
    return regalloc.regForOp(ra, op);
}

pub fn resolveOp(ra: *const regalloc.RegAllocResult, op: mir.MOperand) Operand {
    return switch (op) {
        .vreg => |v| blk: {
            if (ra.regs.get(v)) |r| break :blk .{ .reg = r };

            break :blk .{ .reg = -1 };
        },
        .phys => |r| .{ .reg = @as(i16, @intCast(r)) },
        .imm => |v| Operand.imm(v),
        .mem => |m| if (m.index) |idx|
            .{ .base_reg = @as(i16, @intCast(m.base)), .index_reg = @as(i16, @intCast(idx)), .scale = m.scale, .disp = m.offset }
        else
            .{ .base_reg = @as(i16, @intCast(m.base)), .disp = m.offset },
    };
}

pub fn resolveOpOrSpill(ctx: *Ctx, op: mir.MOperand) !Operand {
    return switch (op) {
        .vreg => |v| blk: {
            if (ctx.ra.regs.get(v)) |r| break :blk .{ .reg = r };
            try spill.loadSpilledOp(ctx, op, ctx.scratch);
            break :blk .{ .reg = ctx.scratch };
        },
        .phys => |r| .{ .reg = @as(i16, @intCast(r)) },
        .imm => |v| Operand.imm(v),

        .mem => |m| if (m.index) |idx|
            .{ .base_reg = @as(i16, @intCast(m.base)), .index_reg = @as(i16, @intCast(idx)), .scale = m.scale, .disp = m.offset }
        else
            .{ .base_reg = @as(i16, @intCast(m.base)), .disp = m.offset },
    };
}

pub fn append(ctx: *Ctx, op: OpCode, operands: []const Operand) !void {
    try ctx.mf.appendInstr(ctx.bi, op, operands);
}

pub fn append2(ctx: *Ctx, op: OpCode, o1: Operand, o2: Operand) !void {
    try ctx.mf.appendInstr2(ctx.bi, op, o1, o2);
}

pub fn append1(ctx: *Ctx, op: OpCode, o1: Operand) !void {
    try ctx.mf.appendInstr1(ctx.bi, op, o1);
}

pub fn append3(ctx: *Ctx, op: OpCode, o1: Operand, o2: Operand, o3: Operand) !void {

    try ctx.mf.appendInstr(ctx.bi, op, &.{ o1, o2, o3 });
}

pub fn condToJccOp(cc: mir.CondCode) OpCode {
    return switch (cc) {
        .eq => .JE_REL32,
        .ne => .JNE_REL32,
        .lt => .JL_REL32,
        .le => .JLE_REL32,
        .gt => .JG_REL32,

        .ge => .JGE_REL32,
    };
}

pub fn xmmScratch() i16 { return 15; }

pub fn moveGprToXmm(ctx: *Ctx, gpr: i16, xmm: i16, dtype: mir.DataType) !void {
    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xmm), Operand.r(gpr));
    } else {

        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xmm), Operand.r(gpr));
    }
}

pub fn moveXmmToXmm(ctx: *Ctx, src_xmm: i16, dst_xmm: i16, dtype: mir.DataType) !void {
    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(dst_xmm), Operand.xmm(src_xmm));
    } else {
        try append2(ctx, .SSE_MOVSS_LD, Operand.xmm(dst_xmm), Operand.xmm(src_xmm));
    }

}

pub fn loadFloatOpToXmm(ctx: *Ctx, op: mir.MOperand, into_xmm: i16, dtype: mir.DataType) !void {
    switch (op) {
        .vreg => {
            if (regalloc.isSpilled(ctx.ra, op)) {
                try spill.loadSpilledOp(ctx, op, ctx.scratch);
                try moveGprToXmm(ctx, ctx.scratch, into_xmm, dtype);
            } else {
                const reg = resolveReg(ctx.ra, op);

        if (reg != into_xmm) {
            try moveXmmToXmm(ctx, reg, into_xmm, dtype);
        }
    }
},
.imm => {
    try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(op.imm) });
    try moveGprToXmm(ctx, ctx.scratch, into_xmm, dtype);
},
else => {},

/// x64 control-flow instruction selection (branch/call/ret/select).
const std = @import("std");
const mir = @import("../../../mir/mir.zig");
const enc = @import("../encoder.zig");
const OpCode = enc.OpCode;
const Operand = enc.Operand;
const regalloc = @import("../../../regalloc/regalloc.zig");
const spill = @import("spill.zig");
const ctx_mod = @import("context.zig");
const Ctx = ctx_mod.Ctx;

const append2 = ctx_mod.append2;
const append1 = ctx_mod.append1;
const append3 = ctx_mod.append3;
const resolveReg = ctx_mod.resolveReg;
const resolveOp = ctx_mod.resolveOp;
const resolveOpOrSpill = ctx_mod.resolveOpOrSpill;
const condToJccOp = ctx_mod.condToJccOp;

pub fn selectJmp(ctx: *Ctx, j: mir.JmpInst, allocator: std.mem.Allocator) !void {
    try ctx.block_fixups.append(allocator, .{ .disp_pos = 0, .target = j.target });

    try append1(ctx, .JMP_REL32, Operand.imm(0));
}

pub fn selectJcc(ctx: *Ctx, j: mir.JccInst, allocator: std.mem.Allocator) !void {
    const jcc_op = condToJccOp(j.cc);
    try ctx.block_fixups.append(allocator, .{ .disp_pos = 0, .target = j.target });
    try append1(ctx, jcc_op, Operand.imm(0));
}

pub fn selectTrap(ctx: *Ctx) !void {

    try append1(ctx, .UD2, Operand.imm(0));
}

pub fn selectCall(ctx: *Ctx, c: mir.CallInst) !void {
    const int_arg_regs = [_]i16{ 1, 2, 8, 9 }; // RCX, RDX, R8, R9
    const float_arg_regs = [_]i16{ 16, 17, 18, 19 }; // XMM0-XMM3

    // Classify each argument as integer or float.
    var int_idx: usize = 0;
    var float_idx: usize = 0;

const is_float = dtype.isFloat();

// Immediate arguments: load directly into the destination register.
if (arg == .imm) {
    if (is_float) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(arg.imm) });
        if (float_idx < float_arg_regs.len) {
            const xs: i16 = 14;
            if (dtype == .f64) {
                try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xs), Operand.r(ctx.scratch));

        } else {
            try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
        }
        xmm_src[arg_count] = xs;
        xmm_dst[arg_count] = float_arg_regs[float_idx];
        float_idx += 1;
    }
} else {
    if (int_idx < int_arg_regs.len) {
        const dst = int_arg_regs[int_idx];

            try append2(ctx, .MOV_R64_IMM64, Operand.r(dst), .{ .imm64 = @bitCast(arg.imm) });
            gpr_src[arg_count] = dst;
            gpr_dst[arg_count] = dst;
            int_idx += 1;
        }
    }
    arg_count += 1;
    continue;
}

// Load spilled args.
if (regalloc.isSpilled(ctx.ra, arg)) {
    try spill.loadSpilledOp(ctx, arg, ctx.scratch);
    if (is_float) {
        xmm_src[arg_count] = ctx.scratch;
        // Actually we need to move from GPR scratch to XMM.
        const xs: i16 = 14; // temp XMM, avoid xmm15 (xmmScratch)
        if (dtype == .f64) {
            try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
        } else {

            try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
        }
        xmm_src[arg_count] = xs;
    } else {
        gpr_src[arg_count] = ctx.scratch;
    }
} else {
    const reg = resolveReg(ctx.ra, arg);
    if (is_float) {
        xmm_src[arg_count] = reg;

    } else {
        gpr_src[arg_count] = reg;
    }
}

if (is_float) {
    if (float_idx < float_arg_regs.len) {
        xmm_dst[arg_count] = float_arg_regs[float_idx];
        float_idx += 1;
    }

    } else {
        if (int_idx < int_arg_regs.len) {
            gpr_dst[arg_count] = int_arg_regs[int_idx];
            int_idx += 1;
        }
    }

    arg_count += 1;
}

// Now move GPR args to their destination registers.
// Handle conflicts: if src of arg[i] is the same as dst of arg[j], resolve via scratch.
for (0..arg_count) |i| {
    if (gpr_src[i] == -1) continue;
    const src = gpr_src[i];
    const dst = gpr_dst[i];
    if (dst == -1 or src == dst) continue;
    // Check if any later arg reads from this dst as source.
    for (i + 1..arg_count) |j| {
        if (gpr_src[j] == dst) {

            // Conflict: move current src via scratch.
            try append2(ctx, .MOV_R64_R64, Operand.r(ctx.scratch), Operand.r(src));
            gpr_src[i] = ctx.scratch;
            break;
        }
    }
}
for (0..arg_count) |i| {
    if (gpr_src[i] == -1) continue;
    const src = gpr_src[i];

    const dst = gpr_dst[i];
    if (dst == -1 or src == dst) continue;
    try append2(ctx, .MOV_R64_R64, Operand.r(dst), Operand.r(src));
}

// Move XMM args to their destination registers.
// Use scratch XMM (xmm15) for conflicts.
for (0..arg_count) |i| {
    if (xmm_src[i] == -1) continue;
    const src = xmm_src[i];

const dst = xmm_dst[i];
if (dst == -1 or src == dst) continue;
// Check conflict.
for (i + 1..arg_count) |j| {
    if (xmm_src[j] == dst) {
        const xs: i16 = 15; // xmmScratch
        try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(xs), Operand.xmm(src));
        xmm_src[i] = xs;
        break;
    }

    }
}
for (0..arg_count) |i| {
    if (xmm_src[i] == -1) continue;
    const src = xmm_src[i];
    const dst = xmm_dst[i];
    if (dst == -1 or src == dst) continue;
    try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(dst), Operand.xmm(src));
}

// Reserve shadow space (32 bytes) for the callee on Win64.
try append2(ctx, .SUB_R64_IMM32, Operand.r(4), Operand.imm(32));

// Emit the CALL.
try ctx.call_fixups.append(ctx.mf.allocator, .{ .name = c.name, .disp_pos = 0 });
try append1(ctx, .CALL_REL32, Operand.imm(0));

// Restore shadow space.
try append2(ctx, .ADD_R64_IMM32, Operand.r(4), Operand.imm(32));

// Collect the return value.
if (!c.is_void) {
    const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
    const dst_vreg = switch (c.dst) { .vreg => |v| v, else => 0 };
    const ret_dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
    if (ret_dtype.isFloat()) {
        // Float return is in xmm0 (reg 16).
        if (dst_spilled) {
            // Convert xmm0 bits to GPR scratch, then use storeSpilledOp.
            if (ret_dtype == .f64) {

        try append2(ctx, .SSE_MOVQ_ST, Operand.r(ctx.scratch), Operand.xmm(16));
    } else {
        try append2(ctx, .SSE_MOVD_ST, Operand.r(ctx.scratch), Operand.xmm(16));
    }
    try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
} else {
    const dst = resolveReg(ctx.ra, c.dst);
    if (dst != 16) {
        if (ret_dtype == .f64) {
            try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(dst), Operand.xmm(16));

            } else {
                try append2(ctx, .SSE_MOVSS_LD, Operand.xmm(dst), Operand.xmm(16));
            }
        }
    }
} else {
    // Integer return is in rax (reg 0).
    if (dst_spilled) {
        try spill.storeSpilledOp(ctx, c.dst, 0);
    } else {

                const dst = resolveReg(ctx.ra, c.dst);
                if (dst != 0) try append2(ctx, .MOV_R64_R64, Operand.r(dst), Operand.r(0));
            }
        }
    }
}

pub fn selectRet(ctx: *Ctx, r: mir.RetInst) !void {
    switch (r) {
        .void_ret => {

    // A void entry (main) returns with EAX as the process exit code;
    // zero it so successful programs exit with code 0.
    try append2(ctx, .XOR_R64_R64, Operand.r(0), Operand.r(0));
},
.value => |val| {
    // Determine the return register based on the value's type.
    const val_vreg = switch (val) { .vreg => |v| v, else => 0 };
    const dtype = ctx.mfunc.getVRegType(val_vreg) orelse .i64;

    if (dtype.isFloat()) {

// Float return: move to xmm0.
const val_spilled = regalloc.isSpilled(ctx.ra, val);
if (val_spilled) {
    try spill.loadSpilledOp(ctx, val, ctx.scratch);
    const xs: i16 = if (ctx.scratch == 15) 14 else 15; // avoid scratch conflict
    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    } else {
        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    }

    if (xs != 16) {
        if (dtype == .f64) {
            try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(16), Operand.xmm(xs));
        } else {
            try append2(ctx, .SSE_MOVSS_LD, Operand.xmm(16), Operand.xmm(xs));
        }
    }
} else {
    const val_r = resolveReg(ctx.ra, val);
    if (val_r != 16) {

            if (dtype == .f64) {
                try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(16), Operand.xmm(val_r));
            } else {
                try append2(ctx, .SSE_MOVSS_LD, Operand.xmm(16), Operand.xmm(val_r));
            }
        }
    }
} else {
    // Integer return: move to rax.
    const val_spilled = regalloc.isSpilled(ctx.ra, val);

if (val_spilled) {
    try spill.loadSpilledOp(ctx, val, 0);
} else {
    const val_r = resolveOp(ctx.ra, val);
    if (val_r.reg >= 0) {
        if (val_r.reg != 0) {
            try append2(ctx, .MOV_R64_R64, Operand.r(0), val_r);
        }
    } else {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(0), val_r);

                    }
                }
            }
        },
    }
}

pub fn selectSelect(ctx: *Ctx, s: mir.SelectInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);
    const src_is_imm = s.src == .imm;

const src_spilled = if (s.src == .vreg) regalloc.isSpilled(ctx.ra, s.src) else false;

if (dst_spilled) {
    if (src_is_imm) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(regalloc.SCRATCH_REG_2), .{ .imm64 = @bitCast(s.src.imm) });
        try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
        try append3(ctx, .CMOV_R64_R64, Operand.r(ctx.scratch), Operand.r(regalloc.SCRATCH_REG_2), .{ .imm64 = @intFromEnum(s.cc) });
    } else if (src_spilled) {
        try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
        const src_mem = regalloc.spilledMemOp(ctx.ra, s.src);

        try append3(ctx, .CMOV_R64_MEM, Operand.r(ctx.scratch), src_mem, .{ .imm64 = @intFromEnum(s.cc) });
    } else {
        try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
        const src_reg = resolveReg(ctx.ra, s.src);
        try append3(ctx, .CMOV_R64_R64, Operand.r(ctx.scratch), Operand.r(src_reg), .{ .imm64 = @intFromEnum(s.cc) });
    }
    try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
} else if (src_spilled) {
    const dst_reg = resolveReg(ctx.ra, s.dst);
    const src_mem = regalloc.spilledMemOp(ctx.ra, s.src);

    try append3(ctx, .CMOV_R64_MEM, Operand.r(dst_reg), src_mem, .{ .imm64 = @intFromEnum(s.cc) });
} else if (src_is_imm) {
    const dst_reg = resolveReg(ctx.ra, s.dst);
    try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(s.src.imm) });
    try append3(ctx, .CMOV_R64_R64, Operand.r(dst_reg), Operand.r(ctx.scratch), .{ .imm64 = @intFromEnum(s.cc) });
} else {
    const dst_reg = resolveReg(ctx.ra, s.dst);
    const src_reg = resolveReg(ctx.ra, s.src);
    try append3(ctx, .CMOV_R64_R64, Operand.r(dst_reg), Operand.r(src_reg), .{ .imm64 = @intFromEnum(s.cc) });
}

/// x64 type conversion instruction selection (sext/zext/trunc/sitofp/fptosi/fpext/fptrunc).
const mir = @import("../../../mir/mir.zig");
const enc = @import("../encoder.zig");
const OpCode = enc.OpCode;
const Operand = enc.Operand;
const regalloc = @import("../../../regalloc/regalloc.zig");
const spill = @import("spill.zig");
const ctx_mod = @import("context.zig");
const Ctx = ctx_mod.Ctx;
const append2 = ctx_mod.append2;

const resolveReg = ctx_mod.resolveReg;

pub fn selectConv(ctx: *Ctx, c: mir.ConvInst, ss32_op: OpCode, sd32_op: OpCode, ss64_op: OpCode, sd64_op: OpCode) !void {
    const dst_vreg = switch (c.dst) { .vreg => |v| v, else => 0 };
    const src_vreg = switch (c.src) { .vreg => |v| v, else => 0 };
    const dst_dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
    const src_dtype = ctx.mfunc.getVRegType(src_vreg) orelse .i64;
    const is_single_float = (src_dtype == .f32) or (dst_dtype == .f32);
    const is_64bit_int = (src_dtype == .i64) or (dst_dtype == .i64);

const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
const src_spilled = regalloc.isSpilled(ctx.ra, c.src);

const src_reg: i16 = if (src_spilled) blk: {
    try spill.loadSpilledOp(ctx, c.src, ctx.scratch);
    break :blk ctx.scratch;
} else switch (c.src) {
    .vreg => resolveReg(ctx.ra, c.src),
    .imm => |v| blk: {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(v) });

        break :blk ctx.scratch;
    },
    else => resolveReg(ctx.ra, c.src),
};
const dst_reg = if (dst_spilled) ctx.scratch else resolveReg(ctx.ra, c.dst);

const conv_op: OpCode = blk: {
    if (is_single_float) {
        break :blk if (is_64bit_int) ss64_op else ss32_op;
    } else {

            break :blk if (is_64bit_int) sd64_op else sd32_op;
        }
    };

    try append2(ctx, conv_op, Operand.xmm(dst_reg), Operand.r(src_reg));

    if (dst_spilled) {
        try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
    }
}

pub fn selectConvSingle(ctx: *Ctx, c: mir.ConvInst, sse_op: OpCode) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, c.src);

    if (src_spilled) {
        try spill.loadSpilledOp(ctx, c.src, ctx.scratch);
    }
    if (dst_spilled) {
        try spill.loadSpilledOp(ctx, c.dst, ctx.scratch);

}

const src_reg = if (src_spilled) ctx.scratch else resolveReg(ctx.ra, c.src);
const dst_reg = if (dst_spilled) ctx.scratch else resolveReg(ctx.ra, c.dst);

try append2(ctx, sse_op, Operand.xmm(dst_reg), Operand.xmm(src_reg));

if (dst_spilled) {
    try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
}

}

pub fn selectSext(ctx: *Ctx, c: mir.ConvInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
    const src_spilled = if (c.src == .vreg) regalloc.isSpilled(ctx.ra, c.src) else false;

    if (src_spilled) {
        try spill.loadSpilledOp(ctx, c.src, ctx.scratch);
    }

const src_reg: i16 = if (src_spilled) ctx.scratch else switch (c.src) {
    .vreg => resolveReg(ctx.ra, c.src),
    .imm => |v| blk: {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(v) });
        break :blk ctx.scratch;
    },
    else => resolveReg(ctx.ra, c.src),
};
const dst_reg = if (dst_spilled) ctx.scratch else resolveReg(ctx.ra, c.dst);

    try append2(ctx, .MOVSX_R64_R32, Operand.r(dst_reg), Operand.r(src_reg));

    if (dst_spilled) {
        try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
    }
}

pub fn selectZext(ctx: *Ctx, c: mir.ConvInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
    const src_spilled = if (c.src == .vreg) regalloc.isSpilled(ctx.ra, c.src) else false;

if (src_spilled) {
    try spill.loadSpilledOp(ctx, c.src, ctx.scratch);
}

const src_reg: i16 = if (src_spilled) ctx.scratch else switch (c.src) {
    .vreg => resolveReg(ctx.ra, c.src),
    .imm => |v| blk: {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(v) });
        break :blk ctx.scratch;

    },
    else => resolveReg(ctx.ra, c.src),
};
const dst_reg = if (dst_spilled) ctx.scratch else resolveReg(ctx.ra, c.dst);

try append2(ctx, .MOVZX_R64_R32, Operand.r(dst_reg), Operand.r(src_reg));

if (dst_spilled) {
    try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
}

}

pub fn selectTrunc(ctx: *Ctx, c: mir.ConvInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, c.dst);
    const src_spilled = if (c.src == .vreg) regalloc.isSpilled(ctx.ra, c.src) else false;

    if (src_spilled) {
        try spill.loadSpilledOp(ctx, c.src, ctx.scratch);
    }

const src_reg: i16 = if (src_spilled) ctx.scratch else switch (c.src) {
    .vreg => resolveReg(ctx.ra, c.src),
    .imm => |v| blk: {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(v) });
        break :blk ctx.scratch;
    },
    else => resolveReg(ctx.ra, c.src),
};
const dst_reg = if (dst_spilled) ctx.scratch else resolveReg(ctx.ra, c.dst);

    try append2(ctx, .MOV_R32_R32, Operand.r(dst_reg), Operand.r(src_reg));

    if (dst_spilled) {
        try spill.storeSpilledOp(ctx, c.dst, ctx.scratch);
    }
}

/// x64 floating-point instruction selection (SSE scalar).
const mir = @import("../../../mir/mir.zig");
const enc = @import("../encoder.zig");
const OpCode = enc.OpCode;
const Operand = enc.Operand;
const regalloc = @import("../../../regalloc/regalloc.zig");
const spill = @import("spill.zig");
const ctx_mod = @import("context.zig");
const Ctx = ctx_mod.Ctx;
const append2 = ctx_mod.append2;

const resolveReg = ctx_mod.resolveReg;
const xmmScratch = ctx_mod.xmmScratch;
const loadFloatOpToXmm = ctx_mod.loadFloatOpToXmm;
const moveGprToXmm = ctx_mod.moveGprToXmm;

pub fn selectFBinOp(ctx: *Ctx, f: mir.FloatBinOp, ss_op: OpCode, sd_op: OpCode) !void {
    const dst_vreg = switch (f.dst) { .vreg => |v| v, else => 0 };
    const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
    const sse_op: OpCode = if (dtype == .f64) sd_op else ss_op;
    const xs = xmmScratch();

const dst_spilled = regalloc.isSpilled(ctx.ra, f.dst);

if (dst_spilled) {
    try loadFloatOpToXmm(ctx, f.a, xs, dtype);
    try loadFloatOpToXmm(ctx, f.b, xs, dtype);
    try append2(ctx, sse_op, Operand.xmm(xs), Operand.xmm(xs));
    try spill.storeSpilledOp(ctx, f.dst, ctx.scratch);
} else {
    const dst = resolveReg(ctx.ra, f.dst);
    try loadFloatOpToXmm(ctx, f.a, dst, dtype);

if (f.b == .imm) {
    try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), Operand.imm(@bitCast(f.b.imm)));
    try moveGprToXmm(ctx, ctx.scratch, xs, dtype);
    try append2(ctx, sse_op, Operand.xmm(dst), Operand.xmm(xs));
} else if (regalloc.isSpilled(ctx.ra, f.b)) {
    try loadFloatOpToXmm(ctx, f.b, xs, dtype);
    try append2(ctx, sse_op, Operand.xmm(dst), Operand.xmm(xs));
} else {
    const b_reg = resolveReg(ctx.ra, f.b);
    try append2(ctx, sse_op, Operand.xmm(dst), Operand.xmm(b_reg));

        }
    }
}

pub fn selectFNeg(ctx: *Ctx, n: mir.UnaryInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, n.dst);
    const dst_vreg = switch (n.dst) { .vreg => |v| v, else => 0 };
    const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
    const xs = xmmScratch();

if (dst_spilled) {
    try spill.loadSpilledOp(ctx, n.dst, ctx.scratch);
    if (dtype == .f64) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @as(u64, 0x8000000000000000) });
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    } else {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @as(u64, 0x80000000) });
        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    }
    try append2(ctx, .SSE_XORPS, Operand.xmm(ctx.scratch), Operand.xmm(xs));

    try spill.storeSpilledOp(ctx, n.dst, ctx.scratch);
} else {
    const dst = resolveReg(ctx.ra, n.dst);
    if (dtype == .f64) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @as(u64, 0x8000000000000000) });
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    } else {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = @as(u64, 0x80000000) });
        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(xs), Operand.r(ctx.scratch));
    }

        try append2(ctx, .SSE_XORPS, Operand.xmm(dst), Operand.xmm(xs));
    }
}

pub fn selectFSqrt(ctx: *Ctx, s: mir.UnaryInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);
    const dst_vreg = switch (s.dst) { .vreg => |v| v, else => 0 };
    const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;

    if (dst_spilled) {

        try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
        const sqrt_op: OpCode = if (dtype == .f64) .SSE_SQRTSD else .SSE_SQRTSS;
        try append2(ctx, sqrt_op, Operand.xmm(ctx.scratch), Operand.xmm(ctx.scratch));
        try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
    } else {
        const dst = resolveReg(ctx.ra, s.dst);
        const sqrt_op: OpCode = if (dtype == .f64) .SSE_SQRTSD else .SSE_SQRTSS;
        try append2(ctx, sqrt_op, Operand.xmm(dst), Operand.xmm(dst));
    }
}

pub fn selectFCmp(ctx: *Ctx, c: mir.FCmpInst) !void {
    const a_spilled = regalloc.isSpilled(ctx.ra, c.a);
    const b_spilled = regalloc.isSpilled(ctx.ra, c.b);
    const a_vreg = switch (c.a) { .vreg => |v| v, else => 0 };
    const dtype = ctx.mfunc.getVRegType(a_vreg) orelse .i64;
    const ucomi_op: OpCode = if (dtype == .f64) .SSE_UCOMISD else .SSE_UCOMISS;

    if (a_spilled) {
        try spill.loadSpilledOp(ctx, c.a, ctx.scratch);

}
if (b_spilled) {
    try spill.loadSpilledOp(ctx, c.b, ctx.scratch);
}

const a_reg = if (a_spilled) ctx.scratch else resolveReg(ctx.ra, c.a);
const b_reg = if (b_spilled) ctx.scratch else resolveReg(ctx.ra, c.b);

try append2(ctx, ucomi_op, Operand.xmm(a_reg), Operand.xmm(b_reg));

const dst = resolveReg(ctx.ra, c.dst);
const setcc_op: u64 = switch (c.cc) {
    .eq => 0x94,
    .ne => 0x95,
    .lt => 0x9C,
    .le => 0x9E,
    .gt => 0x9F,
    .ge => 0x9D,
};
try append2(ctx, .SETCC_R8, Operand.r(dst), .{ .imm64 = setcc_op });

/// x64 integer arithmetic instruction selection.
const mir = @import("../../../mir/mir.zig");
const enc = @import("../encoder.zig");
const OpCode = enc.OpCode;
const Operand = enc.Operand;
const regalloc = @import("../../../regalloc/regalloc.zig");
const spill = @import("spill.zig");
const ctx_mod = @import("context.zig");
const Ctx = ctx_mod.Ctx;
const append2 = ctx_mod.append2;

const append1 = ctx_mod.append1;
const resolveReg = ctx_mod.resolveReg;
const resolveOp = ctx_mod.resolveOp;
const resolveOpOrSpill = ctx_mod.resolveOpOrSpill;

pub fn selectMov(ctx: *Ctx, m: mir.MovInst) !void {
    if (regalloc.isRemat(ctx.ra, m.dst)) return;

    const dst_spilled = regalloc.isSpilled(ctx.ra, m.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, m.src);

const dst_vreg = switch (m.dst) { .vreg => |v| v, else => 0 };
const dst_is_xmm = dst_vreg != 0 and (ctx.mfunc.getVRegClass(dst_vreg) orelse .gpr) == .xmm;
const src_vreg = switch (m.src) { .vreg => |v| v, else => 0 };
const src_is_xmm = src_vreg != 0 and (ctx.mfunc.getVRegClass(src_vreg) orelse .gpr) == .xmm;

if (dst_spilled and src_spilled) {
    try spill.loadSpilledOp(ctx, m.src, ctx.scratch);
    try spill.storeSpilledOp(ctx, m.dst, ctx.scratch);
} else if (dst_spilled) {

    const src_val = try resolveOpOrSpill(ctx, m.src);
    const val_reg = if (src_val.reg >= 0) src_val.reg else ctx.scratch;
    if (src_val.reg < 0) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, m.dst, if (src_val.reg >= 0) val_reg else ctx.scratch);
} else if (src_spilled) {
    if (dst_is_xmm) {
        try spill.loadSpilledOp(ctx, m.src, ctx.scratch);
        const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;

    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(@intCast(dst_vreg - 1 + 16)), Operand.r(ctx.scratch));
    } else {
        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(@intCast(dst_vreg - 1 + 16)), Operand.r(ctx.scratch));
    }
} else {
    try spill.loadSpilledOp(ctx, m.src, ctx.scratch);
    const dst = resolveReg(ctx.ra, m.dst);
    try append2(ctx, .MOV_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));
}

} else {
    const dst = resolveReg(ctx.ra, m.dst);
    const src = resolveOp(ctx.ra, m.src);
    if (dst_is_xmm) {
        if (src.reg >= 0) {
            const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
            if (dtype == .f64) {
                try append2(ctx, .SSE_MOVSD_LD, Operand.xmm(dst), Operand.xmm(src.reg));
            } else {
                try append2(ctx, .SSE_MOVSS_LD, Operand.xmm(dst), Operand.xmm(src.reg));

    }
} else {
    const dtype = ctx.mfunc.getVRegType(dst_vreg) orelse .i64;
    try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), src);
    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVQ_LD, Operand.xmm(dst), Operand.r(ctx.scratch));
    } else {
        try append2(ctx, .SSE_MOVD_LD, Operand.xmm(dst), Operand.r(ctx.scratch));
    }
}

} else if (src_is_xmm) {
    const dtype = ctx.mfunc.getVRegType(src_vreg) orelse .i64;
    if (dtype == .f64) {
        try append2(ctx, .SSE_MOVQ_ST, Operand.xmm(src.reg), Operand.r(dst));
    } else {
        try append2(ctx, .SSE_MOVD_ST, Operand.xmm(src.reg), Operand.r(dst));
    }
} else if (src.reg >= 0) {
    if (dst == src.reg) return;
    try append2(ctx, .MOV_R64_R64, Operand.r(dst), src);

        } else {
            try append2(ctx, .MOV_R64_IMM64, Operand.r(dst), src);
        }
    }
}

pub fn selectAdd(ctx: *Ctx, a: mir.AddInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, a.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, a.src);

if (dst_spilled and src_spilled) {
    try spill.loadSpilledOp(ctx, a.dst, ctx.scratch);
    const src_mem = regalloc.spilledMemOp(ctx.ra, a.src);
    try append2(ctx, .ADD_R64_MEM, Operand.r(ctx.scratch), src_mem);
    try spill.storeSpilledOp(ctx, a.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, a.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, a.src);
    if (src_val.reg >= 0) {
        if (src_val.reg == ctx.scratch) {

            try append2(ctx, .ADD_R64_R64, Operand.r(ctx.scratch), Operand.r(ctx.scratch));
        } else {
            try append2(ctx, .ADD_R64_R64, Operand.r(ctx.scratch), src_val);
        }
    } else {
        try append2(ctx, .ADD_R64_IMM32, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, a.dst, ctx.scratch);
} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, a.dst);

    try spill.loadSpilledOp(ctx, a.src, ctx.scratch);
    try append2(ctx, .ADD_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));
} else {
    const dst = resolveReg(ctx.ra, a.dst);
    const src_val = resolveOp(ctx.ra, a.src);
    switch (a.src) {
        .imm => try append2(ctx, .ADD_R64_IMM32, Operand.r(dst), src_val),
        else => try append2(ctx, .ADD_R64_R64, Operand.r(dst), src_val),
    }
}

}

pub fn selectSub(ctx: *Ctx, s: mir.SubInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, s.src);

    if (dst_spilled and src_spilled) {
        try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
        const src_mem = regalloc.spilledMemOp(ctx.ra, s.src);
        try append2(ctx, .SUB_R64_MEM, Operand.r(ctx.scratch), src_mem);

    try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, s.src);
    if (src_val.reg >= 0) {
        if (src_val.reg == ctx.scratch) {
            try append2(ctx, .SUB_R64_R64, Operand.r(ctx.scratch), Operand.r(ctx.scratch));
        } else {
            try append2(ctx, .SUB_R64_R64, Operand.r(ctx.scratch), src_val);
        }

    } else {
        try append2(ctx, .SUB_R64_IMM32, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, s.dst);
    try spill.loadSpilledOp(ctx, s.src, ctx.scratch);
    try append2(ctx, .SUB_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));
} else {
    const dst = resolveReg(ctx.ra, s.dst);

        const src_val = resolveOp(ctx.ra, s.src);
        switch (s.src) {
            .imm => try append2(ctx, .SUB_R64_IMM32, Operand.r(dst), src_val),
            else => try append2(ctx, .SUB_R64_R64, Operand.r(dst), src_val),
        }
    }
}

pub fn selectIMul(ctx: *Ctx, m: mir.IMulInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, m.dst);

const src_spilled = regalloc.isSpilled(ctx.ra, m.src);

if (dst_spilled and src_spilled) {
    try spill.loadSpilledOp(ctx, m.dst, ctx.scratch);
    const src_mem = regalloc.spilledMemOp(ctx.ra, m.src);
    try append2(ctx, .IMUL_R64_R64, Operand.r(ctx.scratch), src_mem);
    try spill.storeSpilledOp(ctx, m.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, m.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, m.src);

    if (src_val.reg >= 0) {
        try append2(ctx, .IMUL_R64_R64, Operand.r(ctx.scratch), src_val);
    } else {
        try append2(ctx, .IMUL_R64_IMM32, Operand.r(ctx.scratch), .{ .reg = ctx.scratch, .imm64 = src_val.imm64 });
    }
    try spill.storeSpilledOp(ctx, m.dst, ctx.scratch);
} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, m.dst);
    try spill.loadSpilledOp(ctx, m.src, ctx.scratch);
    try append2(ctx, .IMUL_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));

    } else {
        const dst = resolveReg(ctx.ra, m.dst);
        const src_val = resolveOp(ctx.ra, m.src);
        switch (m.src) {
            .imm => try append2(ctx, .IMUL_R64_IMM32, Operand.r(dst), .{ .reg = dst, .imm64 = src_val.imm64 }),
            else => try append2(ctx, .IMUL_R64_R64, Operand.r(dst), src_val),
        }
    }
}

pub fn selectSetCC(ctx: *Ctx, s: mir.SetCCInst) !void {
    const cc: u64 = @intFromEnum(s.cc);
    const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);

    if (dst_spilled) {
        try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), .{ .imm64 = 0 });
        try append2(ctx, .SETCC_R8, Operand.r(ctx.scratch), .{ .imm64 = cc });
        try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
    } else {
        const dst_reg = resolveReg(ctx.ra, s.dst);

        try append2(ctx, .MOV_R64_IMM64, Operand.r(dst_reg), .{ .imm64 = 0 });
        try append2(ctx, .SETCC_R8, Operand.r(dst_reg), .{ .imm64 = cc });
    }
}

pub fn selectIDiv(ctx: *Ctx, m: mir.IDivInst) !void {
    const quotient_spilled = regalloc.isSpilled(ctx.ra, m.quotient);
    const quotient_reg = if (quotient_spilled) -1 else resolveReg(ctx.ra, m.quotient);
    const quotient_is_rax = !quotient_spilled and quotient_reg == 0;

if (!quotient_is_rax) {
    try append1(ctx, .PUSH_R64, Operand.r(0));
}
try append1(ctx, .PUSH_R64, Operand.r(2));

const raw_src = try resolveOpOrSpill(ctx, m.divisor);
const src_op = if (raw_src.reg >= 0 or raw_src.base_reg >= 0 or raw_src.index_reg >= 0) raw_src else blk: {
    try append2(ctx, .MOV_R64_IMM64, Operand.r(ctx.scratch), raw_src);
    break :blk Operand.r(ctx.scratch);
};

if (quotient_spilled) {
    try spill.loadSpilledOp(ctx, m.quotient, 0);
} else if (!quotient_is_rax) {
    try append2(ctx, .MOV_R64_R64, Operand.r(0), Operand.r(quotient_reg));
} else {
    const dividend_reg = resolveReg(ctx.ra, m.dividend);
    if (dividend_reg != 0) {
        try append2(ctx, .MOV_R64_R64, Operand.r(0), Operand.r(dividend_reg));
    }

}

try append1(ctx, .CQO, .{});
try append1(ctx, .IDIV_R64, src_op);

if (!quotient_is_rax) {
    try append2(ctx, .MOV_R64_R64, Operand.r(ctx.scratch), Operand.r(0));
}
try append1(ctx, .POP_R64, Operand.r(2));
if (!quotient_is_rax) {

    try append1(ctx, .POP_R64, Operand.r(0));
    if (quotient_spilled) {
        try spill.storeSpilledOp(ctx, m.quotient, ctx.scratch);
    } else if (quotient_reg != 0) {
        try append2(ctx, .MOV_R64_R64, Operand.r(quotient_reg), Operand.r(ctx.scratch));
    }
}

const remainder_spilled = regalloc.isSpilled(ctx.ra, m.remainder);
const remainder_reg = if (remainder_spilled) -1 else resolveReg(ctx.ra, m.remainder);

if (remainder_reg != 2) {
    if (remainder_spilled) {
        try append2(ctx, .MOV_R64_R64, Operand.r(ctx.scratch), Operand.r(2));
        try spill.storeSpilledOp(ctx, m.remainder, ctx.scratch);
    } else {
        try append2(ctx, .MOV_R64_R64, Operand.r(remainder_reg), Operand.r(2));
    }
} else if (remainder_spilled) {
    try spill.storeSpilledOp(ctx, m.remainder, 2);
}

}

pub fn selectAnd(ctx: *Ctx, a: mir.AndInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, a.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, a.src);

    if (dst_spilled and src_spilled) {
        try spill.loadSpilledOp(ctx, a.dst, ctx.scratch);
        try spill.loadSpilledOp(ctx, a.src, 1);
        try append2(ctx, .AND_R64_R64, Operand.r(ctx.scratch), Operand.r(1));

    try spill.storeSpilledOp(ctx, a.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, a.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, a.src);
    if (src_val.reg >= 0) {
        try append2(ctx, .AND_R64_R64, Operand.r(ctx.scratch), src_val);
    } else {
        try append2(ctx, .AND_R64_IMM32, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, a.dst, ctx.scratch);

} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, a.dst);
    try spill.loadSpilledOp(ctx, a.src, ctx.scratch);
    try append2(ctx, .AND_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));
} else {
    const dst = resolveReg(ctx.ra, a.dst);
    const src_val = resolveOp(ctx.ra, a.src);
    if (src_val.reg >= 0) {
        try append2(ctx, .AND_R64_R64, Operand.r(dst), src_val);
    } else {

            try append2(ctx, .AND_R64_IMM32, Operand.r(dst), src_val);
        }
    }
}

pub fn selectOr(ctx: *Ctx, o: mir.OrInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, o.dst);
    const src_spilled = regalloc.isSpilled(ctx.ra, o.src);

    if (dst_spilled and src_spilled) {

    try spill.loadSpilledOp(ctx, o.dst, ctx.scratch);
    try spill.loadSpilledOp(ctx, o.src, 1);
    try append2(ctx, .OR_R64_R64, Operand.r(ctx.scratch), Operand.r(1));
    try spill.storeSpilledOp(ctx, o.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, o.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, o.src);
    if (src_val.reg >= 0) {
        try append2(ctx, .OR_R64_R64, Operand.r(ctx.scratch), src_val);
    } else {

        try append2(ctx, .OR_R64_IMM32, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, o.dst, ctx.scratch);
} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, o.dst);
    try spill.loadSpilledOp(ctx, o.src, ctx.scratch);
    try append2(ctx, .OR_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));
} else {
    const dst = resolveReg(ctx.ra, o.dst);
    const src_val = resolveOp(ctx.ra, o.src);

        if (src_val.reg >= 0) {
            try append2(ctx, .OR_R64_R64, Operand.r(dst), src_val);
        } else {
            try append2(ctx, .OR_R64_IMM32, Operand.r(dst), src_val);
        }
    }
}

pub fn selectXor(ctx: *Ctx, x: mir.XorInst) !void {
    const dst_spilled = regalloc.isSpilled(ctx.ra, x.dst);

const src_spilled = regalloc.isSpilled(ctx.ra, x.src);

if (dst_spilled and src_spilled) {
    try spill.loadSpilledOp(ctx, x.dst, ctx.scratch);
    try spill.loadSpilledOp(ctx, x.src, 1);
    try append2(ctx, .XOR_R64_R64, Operand.r(ctx.scratch), Operand.r(1));
    try spill.storeSpilledOp(ctx, x.dst, ctx.scratch);
} else if (dst_spilled) {
    try spill.loadSpilledOp(ctx, x.dst, ctx.scratch);
    const src_val = try resolveOpOrSpill(ctx, x.src);

    if (src_val.reg >= 0) {
        try append2(ctx, .XOR_R64_R64, Operand.r(ctx.scratch), src_val);
    } else {
        try append2(ctx, .XOR_R64_IMM32, Operand.r(ctx.scratch), src_val);
    }
    try spill.storeSpilledOp(ctx, x.dst, ctx.scratch);
} else if (src_spilled) {
    const dst = resolveReg(ctx.ra, x.dst);
    try spill.loadSpilledOp(ctx, x.src, ctx.scratch);
    try append2(ctx, .XOR_R64_R64, Operand.r(dst), Operand.r(ctx.scratch));

    } else {
        const dst = resolveReg(ctx.ra, x.dst);
        const src_val = resolveOp(ctx.ra, x.src);
        if (src_val.reg >= 0) {
            try append2(ctx, .XOR_R64_R64, Operand.r(dst), src_val);
        } else {
            try append2(ctx, .XOR_R64_IMM32, Operand.r(dst), src_val);
        }
    }
}

pub fn selectShift(ctx: *Ctx, s: mir.ShiftInst, cl_op: OpCode, imm_op: OpCode) !void {
    if (s.amount == .imm) {
        const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);
        if (dst_spilled) {
            try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
            try append2(ctx, imm_op, Operand.r(ctx.scratch), .{ .imm64 = @bitCast(s.amount.imm) });
            try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
        } else {
            const dst = resolveReg(ctx.ra, s.dst);

        try append2(ctx, imm_op, Operand.r(dst), .{ .imm64 = @bitCast(s.amount.imm) });
    }
    return;
}

const dst_spilled = regalloc.isSpilled(ctx.ra, s.dst);
const amt_spilled = regalloc.isSpilled(ctx.ra, s.amount);

if (amt_spilled) {
    try spill.loadSpilledOp(ctx, s.amount, 1);

} else {
    const amt = resolveReg(ctx.ra, s.amount);
    if (amt != 1) {
        try append2(ctx, .MOV_R64_R64, Operand.r(1), Operand.r(amt));
    }
}

if (dst_spilled) {
    try spill.loadSpilledOp(ctx, s.dst, ctx.scratch);
    try append1(ctx, cl_op, Operand.r(ctx.scratch));

        try spill.storeSpilledOp(ctx, s.dst, ctx.scratch);
    } else {
        const dst = resolveReg(ctx.ra, s.dst);
        try append1(ctx, cl_op, Operand.r(dst));
    }
}

