try x64.emit(&p.cbuf.bytes, .MOVZX_R64_MEM8, &.{ x64.Operand.r(Reg.RBX), x64.Operand.mem(Reg.RSI, 0) });
try x64.emit(&p.cbuf.bytes, .CMP_R32_R32, &.{ x64.Operand.r(Reg.RAX), x64.Operand.r(Reg.RBX) });

