try x64.emit(&p.cbuf.bytes, .TEST_R32_R32, &.{ x64.Operand.r(Reg.RAX), x64.Operand.r(Reg.RAX) });
try emitCondLongJmp(p, .JE_REL32, try allocLabelId(p, "exit_process", .{}));
