            .name = self.internName(self.firstIdentifierText(n)),
            .mutable = false,
            .span = self.nodeSpan(n),
        } });
    }
} else if (child.kind() == .type_ref) {
    if (child.asNode()) |n| {
        type_ann = self.lowerTypeRef(n);
