fn lowerMatchExpr(self: *AstBuilder, node: SyntaxNode) ExprId {
    var scrutinee: ?ExprId = null;
    var arms = std.ArrayList(AstExpr.MatchArm).init(self.arena.allocator);

    var iter = node.childNodes();
    while (iter.next()) |child| {
        if (child.kind() == .match_expr) {
            // match arm
            var pat_id: PatId = PatId.INVALID;
            var arm_body: ?ExprId = null;

var arm_iter = child.childNodes();
while (arm_iter.next()) |ac| {
    if (ac.kind() == .identifier) {
        pat_id = self.arena.addPattern(.{ .identifier = .{
            .name = self.internName(self.tokenText(ac)),
            .mutable = false,
            .span = self.nodeSpan(ac),
        } });
    } else if (arm_body == null) {
        arm_body = self.lowerExpr(ac);

        }
    }
    arms.append(.{
        .pattern = if (pat_id.isValid()) pat_id else self.arena.addPattern(.{ .missing = .{ .span = self.nodeSpan(child) } }),
        .guard = null,
        .body = arm_body orelse self.arena.addExpr(.{ .missing = .{ .span = self.nodeSpan(child) } }),
    }) catch break;
} else if (scrutinee == null) {
    scrutinee = self.lowerExpr(child);
}

    }

    return self.arena.addExpr(.{ .match_expr = .{
        .scrutinee = scrutinee orelse self.arena.addExpr(.{ .missing = .{ .span = self.nodeSpan(node) } }),
        .arms = arms.toOwnedSlice() catch &.{},
        .span = self.nodeSpan(node),
    } });
}

pub fn lowerTypeRef(self: *AstBuilder, node: SyntaxNode) TypeRefId {

return switch (node.kind()) {
    .named_type => self.lowerNamedType(node),
    .type_ref => {
        var iter = node.childNodes();
        while (iter.next()) |child| {
            return self.lowerTypeRef(child);
        }
        return self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } });
    },
    .pointer_type => self.lowerPointerType(node),

        .array_type => self.lowerArrayType(node),
        .slice_type => self.lowerSliceType(node),
        .tuple_type => self.lowerTupleType(node),
        .fn_type => self.lowerFnType(node),
        .optional_type => self.lowerOptionalType(node),
        else => self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),
    };
}

fn lowerNamedType(self: *AstBuilder, node: SyntaxNode) TypeRefId {

var name: SymbolId = SymbolId.INVALID;
var iter = node.childNodes();
while (iter.next()) |child| {
    if (child.kind() == .identifier and !name.isValid()) {
        name = self.internName(self.firstIdentifierText(child));
    }
}
return self.arena.addTypeRef(.{ .named = .{
    .name = name,
    .type_args = &.{},

        .span = self.nodeSpan(node),
    } });
}

fn lowerPointerType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var mutable = false;
    var pointee: ?TypeRefId = null;
    var iter = node.childNodes();
    while (iter.next()) |child| {
        if (child.kind() == .kw_mut) {

        mutable = true;
    } else if (child.kind() == .type_ref or child.kind() == .named_type) {
        pointee = self.lowerTypeRef(child);
    }
}
return self.arena.addTypeRef(.{ .pointer = .{
    .mutable = mutable,
    .pointee = pointee orelse self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),
    .span = self.nodeSpan(node),
} });

}

fn lowerArrayType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var element: ?TypeRefId = null;
    var iter = node.childNodes();
    while (iter.next()) |child| {
        if (child.kind() == .type_ref or child.kind() == .named_type) {
            element = self.lowerTypeRef(child);
        }
    }

    return self.arena.addTypeRef(.{ .array = .{
        .element = element orelse self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),
        .length = null,
        .span = self.nodeSpan(node),
    } });
}

fn lowerSliceType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var element: ?TypeRefId = null;
    var iter = node.childNodes();

    while (iter.next()) |child| {
        if (child.kind() == .type_ref or child.kind() == .named_type) {
            element = self.lowerTypeRef(child);
        }
    }
    return self.arena.addTypeRef(.{ .slice = .{
        .element = element orelse self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),
        .span = self.nodeSpan(node),
    } });
}

fn lowerTupleType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var elements = std.ArrayList(TypeRefId).init(self.arena.allocator);
    var iter = node.childNodes();
    while (iter.next()) |child| {
        elements.append(self.lowerTypeRef(child)) catch break;
    }
    return self.arena.addTypeRef(.{ .tuple = .{
        .elements = elements.toOwnedSlice() catch &.{},
        .span = self.nodeSpan(node),

    } });
}

fn lowerFnType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var params = std.ArrayList(TypeRefId).init(self.arena.allocator);
    var return_type: ?TypeRefId = null;
    var after_arrow = false;

    var iter = node.childNodes();
    while (iter.next()) |child| {

if (child.kind() == .arrow) {
    after_arrow = true;
    continue;
}
if (child.kind() == .type_ref or child.kind() == .named_type) {
    if (after_arrow) {
        return_type = self.lowerTypeRef(child);
    } else {
        params.append(self.lowerTypeRef(child)) catch break;
    }

        }
    }

    return self.arena.addTypeRef(.{ .fn_type = .{
        .params = params.toOwnedSlice() catch &.{},
        .return_type = return_type orelse self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),
        .span = self.nodeSpan(node),
    } });
}

fn lowerOptionalType(self: *AstBuilder, node: SyntaxNode) TypeRefId {
    var inner: ?TypeRefId = null;
    var iter = node.childNodes();
    while (iter.next()) |child| {
        if (child.kind() == .type_ref or child.kind() == .named_type) {
            inner = self.lowerTypeRef(child);
        }
    }
    return self.arena.addTypeRef(.{ .optional = .{
        .inner = inner orelse self.arena.addTypeRef(.{ .missing = .{ .span = self.nodeSpan(node) } }),

        .span = self.nodeSpan(node),
    } });
}

fn syntaxKindToBinOp(self: *AstBuilder, kind: SyntaxKind) ast_node.BinOp {
    _ = self;
    return switch (kind) {
        .plus => .add,
        .minus => .sub,
        .star => .mul,

        .percent_eq => .assign_mod,
        .dot_dot => .range,
        .dot_dot_eq => .range_inclusive,
        else => .add,
    };
}

fn syntaxKindToUnaryOp(self: *AstBuilder, kind: SyntaxKind) ast_node.UnaryOp {
    _ = self;
    return switch (kind) {

        .minus => .negate,
        .bang => .not,
        .tilde => .bitwise_not,
        .star => .deref,
        .amp => .address,
        .kw_ref => .ref,
        else => .negate,
    };
}

fn firstIdentifierText(self: *AstBuilder, node_or_token: anytype) []const u8 {
    _ = self;
    const T = @TypeOf(node_or_token);
    if (T == SyntaxNode) {
        var iter = node_or_token.childTokens();
        while (iter.next()) |tok| {
            if (tok.kind() == .identifier) return tok.text();
        }
        return "";
    } else if (T == SyntaxElement) {

        if (node_or_token.asToken()) |tok| {
            return tok.text();
        }
        return "";
    } else {
        return node_or_token.text();
    }
}

fn firstTokenText(self: *AstBuilder, node: SyntaxNode) []const u8 {

    _ = self;
    var iter = node.childTokens();
    if (iter.next()) |tok| return tok.text();
    return "";
}

fn tokenText(self: *AstBuilder, node: SyntaxNode) []const u8 {
    return self.firstTokenText(node);
}

fn nodeSpan(self: *AstBuilder, node: SyntaxNode) SourceSpan {
    _ = self;
    return .{
        .file_id = 0,
        .start = node.spanStart(),
        .end = node.spanEnd(),
    };
}

fn elementSpan(self: *AstBuilder, elem: SyntaxElement) SourceSpan {

        _ = self;
        return .{
            .file_id = 0,
            .start = elem.spanStart(),
            .end = elem.spanEnd(),
        };
    }
};

const SourceSpan = @import("../source/location/span.zig").SourceSpan;

const std = @import("std");
const ast_node = @import("ast_node.zig");
const arena_mod = @import("arena.zig");

pub const AstExpr = ast_node.AstExpr;
pub const AstStmt = ast_node.AstStmt;
pub const AstDecl = ast_node.AstDecl;
pub const AstTypeRef = ast_node.AstTypeRef;
pub const AstPattern = ast_node.AstPattern;
pub const ExprId = ast_node.ExprId;

pub const StmtId = ast_node.StmtId;
pub const DeclId = ast_node.DeclId;
pub const PatId = ast_node.PatId;
pub const TypeRefId = ast_node.TypeRefId;
pub const AstArena = arena_mod.AstArena;

pub fn dumpDecl(arena: *const AstArena, id: DeclId, writer: anytype, indent: u32) anyerror!void {
    const decl = arena.getDecl(id) orelse return;
    switch (decl) {
        .fn_decl => |d| {

try writeIndent(writer, indent);
try writer.print("FnDecl {s}\n", .{d.name});
if (d.params.len > 0) {
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Params:\n");
    for (d.params) |p| {
        try writeIndent(writer, indent + 2);
        try writer.print("Param {s}", .{p.name});
        if (p.type_ref) |tr| {
            try writer.writeAll(" : ");

            try dumpTypeRef(arena, tr, writer);
        }
        try writer.writeAll("\n");
    }
}
if (d.return_type) |rt| {
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Return: ");
    try dumpTypeRef(arena, rt, writer);
    try writer.writeAll("\n");

    }
    if (d.body) |body| {
        try writeIndent(writer, indent + 1);
        try writer.writeAll("Body:\n");
        try dumpStmt(arena, body, writer, indent + 2);
    }
},
.struct_decl => |d| {
    try writeIndent(writer, indent);
    try writer.print("StructDecl {s}\n", .{d.name});

    for (d.fields) |f| {
        try writeIndent(writer, indent + 1);
        try writer.print("Field {} : ", .{f.name});
        try dumpTypeRef(arena, f.type_ref, writer);
        try writer.writeAll("\n");
    }
},
.enum_decl => |d| {
    try writeIndent(writer, indent);
    try writer.print("EnumDecl {s}\n", .{d.name});

    for (d.variants) |v| {
        try writeIndent(writer, indent + 1);
        try writer.print("Variant {}\n", .{v.name});
    }
},
.trait_decl => |d| {
    try writeIndent(writer, indent);
    try writer.print("TraitDecl {s}\n", .{d.name});
},
.impl_decl => |d| {

    try writeIndent(writer, indent);
    try writer.writeAll("ImplDecl\n");
    try writeIndent(writer, indent + 1);
    try writer.writeAll("SelfType: ");
    try dumpTypeRef(arena, d.self_type, writer);
    try writer.writeAll("\n");
},
.type_alias => |d| {
    try writeIndent(writer, indent);
    try writer.print("TypeAlias {s} = ", .{d.name});

    try dumpTypeRef(arena, d.target_type, writer);
    try writer.writeAll("\n");
},
.import => |d| {
    try writeIndent(writer, indent);
    try writer.print("Import {s}\n", .{d.path});
},
.module => |d| {
    try writeIndent(writer, indent);
    try writer.print("Module {s}\n", .{d.name});

    },
    .extern_fn => |d| {
        try writeIndent(writer, indent);
        try writer.print("ExternFn {s}\n", .{d.name});
    },
    .missing => {
        try writeIndent(writer, indent);
        try writer.writeAll("MissingDecl\n");
    },
}

}

pub fn dumpStmt(arena: *const AstArena, id: StmtId, writer: anytype, indent: u32) anyerror!void {
    const stmt = arena.getStmt(id) orelse return;
    switch (stmt) {
        .let => |s| {
            try writeIndent(writer, indent);
            try writer.writeAll("Let\n");
            try writeIndent(writer, indent + 1);
            try writer.writeAll("Pattern: ");

try dumpPat(arena, s.pattern, writer);
try writer.writeAll("\n");
if (s.type_annotation) |ta| {
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Type: ");
    try dumpTypeRef(arena, ta, writer);
    try writer.writeAll("\n");
}
if (s.init) |i| {
    try writeIndent(writer, indent + 1);

        try writer.writeAll("Init: ");
        try dumpExpr(arena, i, writer);
        try writer.writeAll("\n");
    }
},
.@"var" => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("Var\n");
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Pattern: ");

    try dumpPat(arena, s.pattern, writer);
    try writer.writeAll("\n");
    if (s.init) |i| {
        try writeIndent(writer, indent + 1);
        try writer.writeAll("Init: ");
        try dumpExpr(arena, i, writer);
        try writer.writeAll("\n");
    }
},
.const_stmt => |s| {

try writeIndent(writer, indent);
try writer.writeAll("Const\n");
try writeIndent(writer, indent + 1);
try writer.writeAll("Pattern: ");
try dumpPat(arena, s.pattern, writer);
try writer.writeAll("\n");
try writeIndent(writer, indent + 1);
try writer.writeAll("Init: ");
try dumpExpr(arena, s.init, writer);
try writer.writeAll("\n");

},
.expr_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("ExprStmt: ");
    try dumpExpr(arena, s.expr, writer);
    try writer.writeAll("\n");
},
.block => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("Block\n");

    for (s.stmts) |sid| {
        try dumpStmt(arena, sid, writer, indent + 1);
    }
},
.if_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("If\n");
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Cond: ");
    try dumpExpr(arena, s.condition, writer);

    try writer.writeAll("\n");
    try dumpStmt(arena, s.then_block, writer, indent + 1);
    if (s.else_branch) |eb| {
        try writeIndent(writer, indent + 1);
        try writer.writeAll("Else:\n");
        try dumpStmt(arena, eb, writer, indent + 2);
    }
},
.while_stmt => |s| {
    try writeIndent(writer, indent);

    try writer.writeAll("While\n");
    try writeIndent(writer, indent + 1);
    try writer.writeAll("Cond: ");
    try dumpExpr(arena, s.condition, writer);
    try writer.writeAll("\n");
    try dumpStmt(arena, s.body, writer, indent + 1);
},
.for_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("For\n");

    try writeIndent(writer, indent + 1);
    try writer.writeAll("Iterable: ");
    try dumpExpr(arena, s.iterable, writer);
    try writer.writeAll("\n");
    try dumpStmt(arena, s.body, writer, indent + 1);
},
.loop_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("Loop\n");
    try dumpStmt(arena, s.body, writer, indent + 1);

},
.return_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("Return");
    if (s.value) |v| {
        try writer.writeAll(": ");
        try dumpExpr(arena, v, writer);
    }
    try writer.writeAll("\n");
},

.break_stmt => {
    try writeIndent(writer, indent);
    try writer.writeAll("Break\n");
},
.continue_stmt => {
    try writeIndent(writer, indent);
    try writer.writeAll("Continue\n");
},
.defer_stmt => |s| {
    try writeIndent(writer, indent);

    try writer.writeAll("Defer\n");
    try dumpStmt(arena, s.body, writer, indent + 1);
},
.errdefer_stmt => |s| {
    try writeIndent(writer, indent);
    try writer.writeAll("Errdefer\n");
    try dumpStmt(arena, s.body, writer, indent + 1);
},
.missing => {
    try writeIndent(writer, indent);

            try writer.writeAll("MissingStmt\n");
        },
    }
}

pub fn dumpExpr(arena: *const AstArena, id: ExprId, writer: anytype) anyerror!void {
    const expr = arena.getExpr(id) orelse return;
    switch (expr) {
        .literal => |e| {
            try writer.print("Literal({s})", .{@tagName(e.kind)});

},
.identifier => |e| {
    try writer.print("Ident({s})", .{e.name});
},
.binary => |e| {
    try writer.print("Binary({s}) ", .{@tagName(e.op)});
    try writer.writeAll("[");
    try dumpExpr(arena, e.left, writer);
    try writer.writeAll(", ");
    try dumpExpr(arena, e.right, writer);

    try writer.writeAll("]");
},
.unary => |e| {
    try writer.print("Unary({s}) ", .{@tagName(e.op)});
    try writer.writeAll("[");
    try dumpExpr(arena, e.operand, writer);
    try writer.writeAll("]");
},
.call => |e| {
    try writer.writeAll("Call[");

    try dumpExpr(arena, e.callee, writer);
    for (e.args) |arg| {
        try writer.writeAll(", ");
        try dumpExpr(arena, arg, writer);
    }
    try writer.writeAll("]");
},
.member => |e| {
    try writer.writeAll("Member[");
    try dumpExpr(arena, e.object, writer);

    try writer.print(".{s}]", .{e.member});
},
.index => |e| {
    try writer.writeAll("Index[");
    try dumpExpr(arena, e.object, writer);
    try writer.writeAll(", ");
    try dumpExpr(arena, e.index, writer);
    try writer.writeAll("]");
},
.paren => |e| {

    try writer.writeAll("Paren[");
    try dumpExpr(arena, e.inner, writer);
    try writer.writeAll("]");
},
.if_expr => |e| {
    try writer.writeAll("If[");
    try dumpExpr(arena, e.condition, writer);
    try writer.writeAll(", ");
    try dumpExpr(arena, e.then_block, writer);
    if (e.else_branch) |eb| {

        try writer.writeAll(", else=");
        try dumpExpr(arena, eb, writer);
    }
    try writer.writeAll("]");
},
.while_expr => |e| {
    try writer.writeAll("While[");
    try dumpExpr(arena, e.condition, writer);
    try writer.writeAll(", ");
    try dumpExpr(arena, e.body, writer);

    try writer.writeAll("]");
},
.for_expr => |e| {
    try writer.writeAll("For[");
    try dumpExpr(arena, e.iterable, writer);
    try writer.writeAll(", ");
    try dumpExpr(arena, e.body, writer);
    try writer.writeAll("]");
},
.loop_expr => |e| {

    try writer.writeAll("Loop[");
    try dumpExpr(arena, e.body, writer);
    try writer.writeAll("]");
},
.block => |e| {
    try writer.writeAll("Block[\n");
    for (e.stmts) |sid| {
        try dumpStmt(arena, sid, writer, 1);
    }
    try writer.writeAll("]");

},
.assign => |e| {
    try writer.writeAll("Assign[");
    try dumpExpr(arena, e.target, writer);
    try writer.writeAll(" = ");
    try dumpExpr(arena, e.value, writer);
    try writer.writeAll("]");
},
.return_expr => |e| {
    try writer.writeAll("Return");

    if (e.value) |v| {
        try writer.writeAll("[");
        try dumpExpr(arena, v, writer);
        try writer.writeAll("]");
    }
},
.break_expr => {
    try writer.writeAll("Break");
},
.continue_expr => {

    try writer.writeAll("Continue");
},
.closure => |e| {
    try writer.writeAll("Closure[");
    try dumpExpr(arena, e.body, writer);
    try writer.writeAll("]");
},
.match_expr => |e| {
    try writer.writeAll("Match[");
    try dumpExpr(arena, e.scrutinee, writer);

    try writer.print(" with {d} arms]", .{e.arms.len});
},
.range => |e| {
    try writer.writeAll("Range[");
    if (e.start) |s| try dumpExpr(arena, s, writer);
    try writer.writeAll("..");
    if (e.end) |en| try dumpExpr(arena, en, writer);
    try writer.writeAll("]");
},
.try_expr => |e| {

    try writer.writeAll("Try[");
    try dumpExpr(arena, e.operand, writer);
    try writer.writeAll("]");
},
.type_cast => |e| {
    try writer.writeAll("Cast[");
    try dumpExpr(arena, e.operand, writer);
    try writer.writeAll(" as ");
    try dumpTypeRef(arena, e.target_type, writer);
    try writer.writeAll("]");

        },
        .missing => {
            try writer.writeAll("MissingExpr");
        },
    }
}

pub fn dumpTypeRef(arena: *const AstArena, id: TypeRefId, writer: anytype) anyerror!void {
    const tr = arena.getTypeRef(id) orelse return;
    switch (tr) {

.named => |t| {
    try writer.print("{s}", .{t.name});
},
.pointer => |t| {
    try writer.writeAll("*");
    if (t.mutable) try writer.writeAll("mut ");
    try dumpTypeRef(arena, t.pointee, writer);
},
.array => |t| {
    try writer.writeAll("[");

    try dumpTypeRef(arena, t.element, writer);
    try writer.writeAll("]");
},
.slice => |t| {
    try writer.writeAll("[]");
    try dumpTypeRef(arena, t.element, writer);
},
.tuple => |t| {
    try writer.writeAll("(");
    for (t.elements, 0..) |elem, i| {

        if (i > 0) try writer.writeAll(", ");
        try dumpTypeRef(arena, elem, writer);
    }
    try writer.writeAll(")");
},
.fn_type => |t| {
    try writer.writeAll("fn(");
    for (t.params, 0..) |param, i| {
        if (i > 0) try writer.writeAll(", ");
        try dumpTypeRef(arena, param, writer);

    }
    try writer.writeAll(") -> ");
    try dumpTypeRef(arena, t.return_type, writer);
},
.optional => |t| {
    try writer.writeAll("?");
    try dumpTypeRef(arena, t.inner, writer);
},
.missing => {
    try writer.writeAll("MissingType");

        },
    }
}

pub fn dumpPat(arena: *const AstArena, id: PatId, writer: anytype) anyerror!void {
    const pat = arena.getPattern(id) orelse return;
    switch (pat) {
        .identifier => |p| {
            try writer.print("Pat({s})", .{p.name});
        },

.wildcard => {
    try writer.writeAll("Pat(_)");
},
.literal => |p| {
    try writer.writeAll("Pat(");
    try dumpExpr(arena, p.value, writer);
    try writer.writeAll(")");
},
.tuple => |p| {
    try writer.writeAll("Pat(");

    for (p.elements, 0..) |elem, i| {
        if (i > 0) try writer.writeAll(", ");
        try dumpPat(arena, elem, writer);
    }
    try writer.writeAll(")");
},
.path => |p| {
    try writer.print("Pat({s})", .{p.path});
},
.missing => {

            try writer.writeAll("Pat(Missing)");
        },
    }
}

pub fn dumpModule(arena: *const AstArena, decls: []const DeclId, writer: anytype) anyerror!void {
    try writer.writeAll("Module\n");
    for (decls) |did| {
        try dumpDecl(arena, did, writer, 1);
    }

}

fn writeIndent(writer: anytype, indent: u32) !void {
    var i: u32 = 0;
    while (i < indent) : (i += 1) {
        try writer.writeAll("  ");
    }
}

const std = @import("std");
const ast_node = @import("ast_node.zig");
const arena_mod = @import("arena.zig");

pub const ExprId = ast_node.ExprId;
pub const StmtId = ast_node.StmtId;
pub const DeclId = ast_node.DeclId;
pub const PatId = ast_node.PatId;
pub const TypeRefId = ast_node.TypeRefId;
pub const AstArena = arena_mod.AstArena;

pub fn AstVisitor(comptime Context: type) type {
    return struct {
        ctx: Context,
        arena: *AstArena,

        const Self = @This();

        pub fn init(arena: *AstArena, ctx: Context) Self {
            return .{ .ctx = ctx, .arena = arena };

}

pub fn visitExpr(self: *Self, id: ExprId) void {
    const expr = self.arena.getExpr(id) orelse return;
    switch (expr) {
        .literal => |e| self.onLiteral(e),
        .identifier => |e| self.onIdentifier(e),
        .binary => |e| {
            self.onBinary(e);
            self.visitExpr(e.left);

    self.visitExpr(e.right);
},
.unary => |e| {
    self.onUnary(e);
    self.visitExpr(e.operand);
},
.call => |e| {
    self.onCall(e);
    self.visitExpr(e.callee);
    for (e.args) |arg| self.visitExpr(arg);

},
.member => |e| {
    self.onMember(e);
    self.visitExpr(e.object);
},
.index => |e| {
    self.onIndex(e);
    self.visitExpr(e.object);
    self.visitExpr(e.index);
},

.paren => |e| {
    self.onParen(e);
    self.visitExpr(e.inner);
},
.if_expr => |e| {
    self.onIfExpr(e);
    self.visitExpr(e.condition);
    self.visitExpr(e.then_block);
    if (e.else_branch) |eb| self.visitExpr(eb);
},

.while_expr => |e| {
    self.onWhileExpr(e);
    self.visitExpr(e.condition);
    self.visitExpr(e.body);
},
.for_expr => |e| {
    self.onForExpr(e);
    self.visitExpr(e.iterable);
    self.visitExpr(e.body);
},

.loop_expr => |e| {
    self.onLoopExpr(e);
    self.visitExpr(e.body);
},
.block => |e| {
    self.onBlockExpr(e);
    for (e.stmts) |sid| self.visitStmt(sid);
},
.assign => |e| {
    self.onAssignExpr(e);

    self.visitExpr(e.target);
    self.visitExpr(e.value);
},
.return_expr => |e| {
    self.onReturnExpr(e);
    if (e.value) |v| self.visitExpr(v);
},
.break_expr => |e| self.onBreakExpr(e),
.continue_expr => |e| self.onContinueExpr(e),
.closure => |e| {

    self.onClosureExpr(e);
    self.visitExpr(e.body);
},
.match_expr => |e| {
    self.onMatchExpr(e);
    self.visitExpr(e.scrutinee);
    for (e.arms) |arm| {
        self.visitPat(arm.pattern);
        if (arm.guard) |g| self.visitExpr(g);
        self.visitExpr(arm.body);

    }
},
.range => |e| {
    self.onRangeExpr(e);
    if (e.start) |s| self.visitExpr(s);
    if (e.end) |en| self.visitExpr(en);
},
.try_expr => |e| {
    self.onTryExpr(e);
    self.visitExpr(e.operand);

        },
        .type_cast => |e| {
            self.onTypeCastExpr(e);
            self.visitExpr(e.operand);
            self.visitTypeRef(e.target_type);
        },
        .missing => |e| self.onMissingExpr(e),
    }
}

pub fn visitStmt(self: *Self, id: StmtId) void {
    const stmt = self.arena.getStmt(id) orelse return;
    switch (stmt) {
        .let => |s| {
            self.onLetStmt(s);
            self.visitPat(s.pattern);
            if (s.type_annotation) |t| self.visitTypeRef(t);
            if (s.init) |i| self.visitExpr(i);
        },
        .@"var" => |s| {

    self.onVarStmt(s);
    self.visitPat(s.pattern);
    if (s.type_annotation) |t| self.visitTypeRef(t);
    if (s.init) |i| self.visitExpr(i);
},
.const_stmt => |s| {
    self.onConstStmt(s);
    self.visitPat(s.pattern);
    if (s.type_annotation) |t| self.visitTypeRef(t);
    self.visitExpr(s.init);

},
.expr_stmt => |s| {
    self.onExprStmt(s);
    self.visitExpr(s.expr);
},
.block => |s| {
    self.onBlockStmt(s);
    for (s.stmts) |sid| self.visitStmt(sid);
},
.if_stmt => |s| {

    self.onIfStmt(s);
    self.visitExpr(s.condition);
    self.visitStmt(s.then_block);
    if (s.else_branch) |eb| self.visitStmt(eb);
},
.while_stmt => |s| {
    self.onWhileStmt(s);
    self.visitExpr(s.condition);
    self.visitStmt(s.body);
},

.for_stmt => |s| {
    self.onForStmt(s);
    self.visitExpr(s.iterable);
    self.visitStmt(s.body);
},
.loop_stmt => |s| {
    self.onLoopStmt(s);
    self.visitStmt(s.body);
},
.return_stmt => |s| {

    self.onReturnStmt(s);
    if (s.value) |v| self.visitExpr(v);
},
.break_stmt => |s| self.onBreakStmt(s),
.continue_stmt => |s| self.onContinueStmt(s),
.defer_stmt => |s| {
    self.onDeferStmt(s);
    self.visitStmt(s.body);
},
.errdefer_stmt => |s| {

            self.onErrdeferStmt(s);
            self.visitStmt(s.body);
        },
        .missing => |s| self.onMissingStmt(s),
    }
}

pub fn visitDecl(self: *Self, id: DeclId) void {
    const decl = self.arena.getDecl(id) orelse return;
    switch (decl) {

.fn_decl => |d| {
    self.onFnDecl(d);
    if (d.body) |b| self.visitStmt(b);
},
.struct_decl => |d| self.onStructDecl(d),
.enum_decl => |d| self.onEnumDecl(d),
.trait_decl => |d| self.onTraitDecl(d),
.impl_decl => |d| self.onImplDecl(d),
.type_alias => |d| self.onTypeAliasDecl(d),
.import => |d| self.onImportDecl(d),

        .module => |d| self.onModuleDecl(d),
        .extern_fn => |d| self.onExternFnDecl(d),
        .missing => |d| self.onMissingDecl(d),
    }
}

pub fn visitPat(self: *Self, id: PatId) void {
    const pat = self.arena.getPattern(id) orelse return;
    switch (pat) {
        .identifier => |p| self.onIdentifierPat(p),

.wildcard => |p| self.onWildcardPat(p),
.literal => |p| {
    self.onLiteralPat(p);
    self.visitExpr(p.value);
},
.tuple => |p| {
    self.onTuplePat(p);
    for (p.elements) |eid| self.visitPat(eid);
},
.path => |p| self.onPathPat(p),

        .missing => |p| self.onMissingPat(p),
    }
}

pub fn visitTypeRef(self: *Self, id: TypeRefId) void {
    const tr = self.arena.getTypeRef(id) orelse return;
    switch (tr) {
        .named => |t| self.onNamedType(t),
        .pointer => |t| {
            self.onPointerType(t);

    self.visitTypeRef(t.pointee);
},
.array => |t| {
    self.onArrayType(t);
    self.visitTypeRef(t.element);
    if (t.length) |l| self.visitExpr(l);
},
.slice => |t| {
    self.onSliceType(t);
    self.visitTypeRef(t.element);

},
.tuple => |t| {
    self.onTupleType(t);
    for (t.elements) |eid| self.visitTypeRef(eid);
},
.fn_type => |t| {
    self.onFnType(t);
    self.visitTypeRef(t.return_type);
},
.optional => |t| {

            self.onOptionalType(t);
            self.visitTypeRef(t.inner);
        },
        .missing => |t| self.onMissingType(t),
    }
}

