    };
}

pub fn deinit(self: *QueryContext) void {
    var it = self.dependencies.iterator();
    while (it.next()) |entry| {
        entry.value_ptr.deinit();
    }
    self.dependencies.deinit();
    self.cache.deinit();
}

pub fn lookup(self: *const QueryContext, key: u64) ?QueryResult {
    return self.cache.get(key);
}

