pub fn typeCheckSource(source: []const u8, allocator: std.mem.Allocator) !struct {
    hir_arena: HirArena,
    engine: TypeEngine,
    errors: ErrorList,
    resolver: resolver_mod.Resolver,
    ast_arena: ast_arena_mod.AstArena,
} {

var lexer = Lexer.init(source, 0, allocator);
