        .span = span,
        .kind = .missing,
    });
}

pub fn missingType(self: *HirLowering) LowerError!TypeId {
    return self.hir.addType(.{
        .builtin = .{ .kind = .void_type },
    });

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;

pub fn lowerAssignExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .assign => |a| {
            const target = try self.lowerExpr(a.target);
            const value = try self.lowerExpr(a.value);

            return self.assign(target, value, a.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;

pub fn lowerBinaryExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .binary => |b| {
            const left = try self.lowerExpr(b.left);
            const right = try self.lowerExpr(b.right);

            const op = self.lowerBinOp(b.op);
            return self.binary(op, left, right, b.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;

pub fn lowerBlockExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .block => |b| {
            const stmts = try self.lowerStmtSlice(b.stmts);
            const last = if (stmts.len > 0) blk: {

            const last_sid = stmts[stmts.len - 1];
            const stmt = self.hir.getStmt(last_sid) orelse break :blk try self.missingExpr(b.span);
            if (stmt.kind == .expr) break :blk stmt.kind.expr.expr;
            break :blk try self.missingExpr(b.span);
        } else try self.missingExpr(b.span);
        return self.block(stmts, last, b.span);
    },
    .paren => |p| self.lowerExpr(p.inner),
    else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const std = @import("std");

pub fn lowerCallExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .call => |c| {
            const callee = try self.lowerExpr(c.callee);

            var args = std.ArrayList(ExprId).init(self.hir.allocator());
            for (c.args) |arg| {
                args.append(try self.lowerExpr(arg)) catch return error.OutOfMemory;
            }
            return self.call(callee, args.toOwnedSlice() catch return error.OutOfMemory, c.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const TypeId = @import("../lower.zig").TypeId;
const DefId = @import("../lower.zig").DefId;
const UNK = @import("../lower.zig").UNK;
const std = @import("std");

pub fn lowerClosureExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });

switch (ast_expr) {
    .closure => |c| {
        var params = std.ArrayList(@import("../../expr.zig").HirExpr.HirExprKind.ClosureParam).init(self.hir.allocator());
        for (c.params) |p| {
            const def = self.resolveName(p.name);
            params.append(.{
                .span = p.span,
                .def = def,
                .ty = UNK,
                .mutable = false,

    }) catch return error.OutOfMemory;
}
const body = try self.lowerExpr(c.body);
const return_type = if (c.return_type) |rt| try self.lowerTypeRefId(rt) else UNK;
return self.hir.addExpr(.{
    .span = c.span,
    .ty = UNK,
    .kind = .{ .closure = .{
        .params = params.toOwnedSlice() catch return error.OutOfMemory,
        .return_type = return_type,

                    .body = body,
                } },
            });
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const DefId = @import("../lower.zig").DefId;
const LabelId = @import("../lower.zig").LabelId;

pub fn lowerIfExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .if_expr => |i| {

            const cond = try self.lowerExpr(i.condition);
            const then_branch = try self.lowerExpr(i.then_block);
            const else_branch = if (i.else_branch) |eb| try self.lowerExpr(eb) else try self.missingExpr(i.span);
            return self.ifExpr(cond, then_branch, else_branch, i.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerWhileExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {

    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .while_expr => |w| {
            const cond = try self.lowerExpr(w.condition);
            const body = try self.lowerExpr(w.body);
            return self.whileExpr(cond, body, w.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerForExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .for_expr => |f| {
            const iterable = try self.lowerExpr(f.iterable);
            const body = try self.lowerExpr(f.body);
            const iter_def = self.resolveName(f.iter_var);
            return self.forExpr(iter_def, iterable, body, f.span);
        },

        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerLoopExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .loop_expr => |l| {
            const body = try self.lowerExpr(l.body);
            return self.loopExpr(body, l.span);

        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerReturnExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .return_expr => |r| {
            const value = if (r.value) |v| try self.lowerExpr(v) else try self.missingExpr(r.span);

            return self.returnExpr(value, r.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerBreakExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .break_expr => |b| {

            const label = LabelId.INVALID;
            const value = try self.missingExpr(b.span);
            return self.breakExpr(label, value, b.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

pub fn lowerContinueExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });

    switch (ast_expr) {
        .continue_expr => |c| {
            return self.continueExpr(LabelId.INVALID, c.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const HirLiteral = @import("../../literal.zig").HirLiteral;

pub fn lowerLiteralExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .literal => |l| {
            const lit_val: HirLiteral = switch (l.kind) {

            .integer => .{ .int = 0 },
            .float => .{ .float = 0.0 },
            .boolean => .{ .boolean = false },
            .string => .{ .string = @import("../lower.zig").SymbolId.INVALID },
            .char, .byte, .byte_string, .null_value => .{ .int = 0 },
        };
        return self.literal(lit_val, l.span);
    },
    else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const HirExpr = @import("../lower.zig").HirExpr;
const UNK = @import("../lower.zig").UNK;
const std = @import("std");

pub fn lowerMatchExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {

.match_expr => |m| {
    const scrutinee = try self.lowerExpr(m.scrutinee);
    var arms = std.ArrayList(HirExpr.HirExprKind.MatchArm).init(self.hir.allocator());
    for (m.arms) |arm| {
        const pat = try self.lowerPattern(arm.pattern);
        const body = try self.lowerExpr(arm.body);
        const guard = if (arm.guard) |g| try self.lowerExpr(g) else ExprId.INVALID;
        arms.append(.{
            .span = .{ .file_id = 0, .start = 0, .end = 0 },
            .pattern = pat,

        .guard = guard,
        .body = body,
    }) catch return error.OutOfMemory;
}
return self.hir.addExpr(.{
    .span = m.span,
    .ty = UNK,
    .kind = .{ .match_expr = .{
        .scrutinee = scrutinee,
        .arms = arms.toOwnedSlice() catch return error.OutOfMemory,

                } },
            });
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;
const DefId = @import("../lower.zig").DefId;

pub fn lowerMemberExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .member => |m| {
            const object = try self.lowerExpr(m.object);

        const field_def = self.resolveName(m.member);
        _ = field_def;
        return self.hir.addExpr(.{
            .span = m.span,
            .ty = @import("../lower.zig").UNK,
            .kind = .{ .field = .{ .object = object, .field = DefId.INVALID } },
        });
    },
    else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
}

const HirLowering = @import("../lower.zig").HirLowering;
const LowerError = @import("../lower.zig").LowerError;
const ExprId = @import("../lower.zig").ExprId;

pub fn lowerUnaryExpr(self: *HirLowering, ast_eid: @import("../lower.zig").AstExprId) LowerError!ExprId {
    const ast_expr = self.ast.getExpr(ast_eid) orelse return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 });
    switch (ast_expr) {
        .unary => |u| {
            const operand = try self.lowerExpr(u.operand);
            const op = self.lowerUnaryOp(u.op);

            return self.unary(op, operand, u.span);
        },
        else => return self.missingExpr(.{ .file_id = 0, .start = 0, .end = 0 }),
    }
}

