pub fn lowerStateItem(self: *HirLowering, state: ast.StateDefNode) LowerError!ItemId {
    var fields = std.ArrayList(HirItemKind.StateVar).init(self.hir.allocator());

for (state.variables.items) |_| {
    fields.append(.{
        .name = .INVALID,
        .ty = .INVALID,
