fn resolveFnDecl(self: *Resolver, arena: *AstArena, f: AstDecl.FnDecl) void {
    if (!f.name.isValid()) return;

    const def_id = self.addDef(.function, f.name, DefId.INVALID);

    if (f.body) |body_id| {
        const fn_scope = self.scopes.pushScope(.function, self.current_scope, def_id);

if (self.defs.getDef(def_id)) |d| {
    d.owner = def_id;
}

const prev_scope = self.current_scope;
const prev_owner = self.current_owner;
self.current_scope = fn_scope;
self.current_owner = def_id;

for (f.params) |param| {

            self.resolveParam(param, def_id);
        }

        self.resolveStmt(arena, body_id);

        self.current_scope = prev_scope;
        self.current_owner = prev_owner;
    }
}

fn resolveParam(self: *Resolver, param: ParamDef, owner: DefId) void {
    if (!param.name.isValid()) return;
    _ = self.addDef(.parameter, param.name, owner);
}

fn resolveStructDecl(self: *Resolver, s: AstDecl.StructDecl) void {
    if (!s.name.isValid()) return;

    const def_id = self.addDef(.struct_type, s.name, DefId.INVALID);
    if (self.defs.getDef(def_id)) |d| {

        d.owner = def_id;
    }

    for (s.fields) |field| {
        if (field.name.isValid()) {
            _ = self.addDef(.field, field.name, def_id);
        }
    }
}

fn resolveEnumDecl(self: *Resolver, e: AstDecl.EnumDecl) void {
    if (!e.name.isValid()) return;

    const def_id = self.addDef(.enum_type, e.name, DefId.INVALID);
    if (self.defs.getDef(def_id)) |d| {
        d.owner = def_id;
    }

    for (e.variants) |variant| {
        if (variant.name.isValid()) {

            _ = self.addDef(.enum_variant, variant.name, def_id);
        }
    }
}

fn resolveTraitDecl(self: *Resolver, arena: *AstArena, t: AstDecl.TraitDecl) void {
    if (!t.name.isValid()) return;

    const def_id = self.addDef(.trait, t.name, DefId.INVALID);
    if (self.defs.getDef(def_id)) |d| {

        d.owner = def_id;
    }

    for (t.methods) |method| {
        self.resolveFnDecl(arena, method);
    }
}

fn resolveImplDecl(self: *Resolver, arena: *AstArena, impl: AstDecl.ImplDecl) void {
    const impl_scope = self.scopes.pushScope(.block, self.current_scope, DefId.INVALID);

    const prev_scope = self.current_scope;
    self.current_scope = impl_scope;

    for (impl.methods) |method| {
        self.resolveFnDecl(arena, method);
    }

    self.current_scope = prev_scope;
}

fn resolveTypeAlias(self: *Resolver, t: AstDecl.TypeAliasDecl) void {
    if (!t.name.isValid()) return;
    _ = self.addDef(.type_alias, t.name, DefId.INVALID);
}

fn resolveImport(self: *Resolver, i: AstDecl.ImportDecl) void {
    const name = if (i.alias) |alias| alias else i.path;
    if (name.isValid()) {
        _ = self.addDef(.import, name, DefId.INVALID);
    }

}

fn resolveExternFn(self: *Resolver, e: AstDecl.ExternFnDecl) void {
    if (!e.name.isValid()) return;
    _ = self.addDef(.function, e.name, DefId.INVALID);
}

fn resolveStmt(self: *Resolver, arena: *AstArena, stmt_id: StmtId) void {
    if (!stmt_id.isValid()) return;
    const stmt = arena.getStmt(stmt_id) orelse return;

switch (stmt) {
    .let => |l| {
        self.resolvePatternDef(arena, l.pattern);
        if (l.init) |init_id| {
            self.resolveExpr(arena, init_id);
        }
    },
    .@"var" => |v| {
        self.resolvePatternDef(arena, v.pattern);
        if (v.init) |init_id| {

        self.resolveExpr(arena, init_id);
    }
},
.const_stmt => |c| {
    self.resolvePatternDef(arena, c.pattern);
    self.resolveExpr(arena, c.init);
},
.expr_stmt => |e| self.resolveExpr(arena, e.expr),
.block => |b| self.resolveBlock(arena, b.stmts),
.if_stmt => |i| {

    self.resolveExpr(arena, i.condition);
    self.resolveStmt(arena, i.then_block);
    if (i.else_branch) |eb| {
        self.resolveStmt(arena, eb);
    }
},
.while_stmt => |w| {
    self.resolveExpr(arena, w.condition);
    self.resolveStmt(arena, w.body);
},

.for_stmt => |f| {
    self.resolveExpr(arena, f.iterable);
    const for_scope = self.scopes.pushScope(.block, self.current_scope, DefId.INVALID);
    const prev_scope = self.current_scope;
    self.current_scope = for_scope;
    if (f.iter_var.isValid()) {
        _ = self.addDef(.local, f.iter_var, self.current_owner);
    }
    self.resolveStmt(arena, f.body);
    self.current_scope = prev_scope;

    },
    .loop_stmt => |l| self.resolveStmt(arena, l.body),
    .return_stmt => |r| {
        if (r.value) |v| self.resolveExpr(arena, v);
    },
    .break_stmt, .continue_stmt => {},
    .defer_stmt => |d| self.resolveStmt(arena, d.body),
    .errdefer_stmt => |d| self.resolveStmt(arena, d.body),
    .missing => {},
}

}

fn resolveBlock(self: *Resolver, arena: *AstArena, stmts: []const StmtId) void {
    for (stmts) |stmt_id| {
        self.resolveStmt(arena, stmt_id);
    }
}

fn resolvePatternDef(self: *Resolver, arena: *AstArena, pat_id: PatId) void {
    if (!pat_id.isValid()) return;

const pat = arena.getPattern(pat_id) orelse return;
switch (pat) {
    .identifier => |i| {
        if (i.name.isValid()) {
            _ = self.addDef(.local, i.name, self.current_owner);
        }
    },
    .tuple => |t| {
        for (t.elements) |elem| {
            self.resolvePatternDef(arena, elem);

            }
        },
        .wildcard, .literal, .path, .missing => {},
    }
}

fn resolveExpr(self: *Resolver, arena: *AstArena, expr_id: ExprId) void {
    if (!expr_id.isValid()) return;
    const expr = arena.getExpr(expr_id) orelse return;
    switch (expr) {

.identifier => |id| {
    self.resolveIdentifier(expr_id, id.name);
},
.binary => |b| {
    self.resolveExpr(arena, b.left);
    self.resolveExpr(arena, b.right);
},
.unary => |u| {
    self.resolveExpr(arena, u.operand);
},

.call => |c| {
    self.resolveExpr(arena, c.callee);
    for (c.args) |arg| {
        self.resolveExpr(arena, arg);
    }
},
.member => |m| {
    self.resolveExpr(arena, m.object);
},
.index => |i| {

    self.resolveExpr(arena, i.object);
    self.resolveExpr(arena, i.index);
},
.paren => |p| {
    self.resolveExpr(arena, p.inner);
},
.if_expr => |i| {
    self.resolveExpr(arena, i.condition);
    self.resolveExpr(arena, i.then_block);
    if (i.else_branch) |eb| {

        self.resolveExpr(arena, eb);
    }
},
.while_expr => |w| {
    self.resolveExpr(arena, w.condition);
    self.resolveExpr(arena, w.body);
},
.for_expr => |f| {
    self.resolveExpr(arena, f.iterable);
    const for_scope = self.scopes.pushScope(.block, self.current_scope, DefId.INVALID);

    const prev_scope = self.current_scope;
    self.current_scope = for_scope;
    if (f.iter_var.isValid()) {
        _ = self.addDef(.local, f.iter_var, self.current_owner);
    }
    self.resolveExpr(arena, f.body);
    self.current_scope = prev_scope;
},
.loop_expr => |l| {
    self.resolveExpr(arena, l.body);

},
.block => |b| {
    self.resolveBlock(arena, b.stmts);
},
.assign => |a| {
    self.resolveExpr(arena, a.target);
    self.resolveExpr(arena, a.value);
},
.return_expr => |r| {
    if (r.value) |v| self.resolveExpr(arena, v);

},
.break_expr, .continue_expr => {},
.closure => |c| {
    const clo_scope = self.scopes.pushScope(.closure, self.current_scope, DefId.INVALID);
    const prev_scope = self.current_scope;
    self.current_scope = clo_scope;
    for (c.params) |param| {
        self.resolveParam(param, DefId.INVALID);
    }
    self.resolveExpr(arena, c.body);

    self.current_scope = prev_scope;
},
.match_expr => |m| {
    self.resolveExpr(arena, m.scrutinee);
    for (m.arms) |arm| {
        const arm_scope = self.scopes.pushScope(.block, self.current_scope, DefId.INVALID);
        const prev_scope = self.current_scope;
        self.current_scope = arm_scope;
        self.resolvePatternDef(arena, arm.pattern);
        if (arm.guard) |g| self.resolveExpr(arena, g);

        self.resolveExpr(arena, arm.body);
        self.current_scope = prev_scope;
    }
},
.range => |r| {
    if (r.start) |s| self.resolveExpr(arena, s);
    if (r.end) |e| self.resolveExpr(arena, e);
},
.try_expr => |t| {
    self.resolveExpr(arena, t.operand);

        },
        .type_cast => |tc| {
            self.resolveExpr(arena, tc.operand);
        },
        .literal, .missing => {},
    }
}

fn resolveIdentifier(self: *Resolver, expr_id: ExprId, name: SymbolId) void {
    if (!name.isValid()) return;

    if (self.scopes.lookupInScope(self.current_scope, name)) |def_id| {
        self.refs.append(.{ .expr_id = expr_id, .def_id = def_id }) catch {};
    }
}

pub fn lookupDef(self: *const Resolver, name: SymbolId) ?DefId {
    return self.scopes.lookupInScope(self.current_scope, name);
}

    pub fn resolvedCount(self: *const Resolver) usize {
        return self.refs.items.len;
    }

    pub fn defCount(self: *const Resolver) usize {
        return self.defs.defs.items.len;
    }
};

const std = @import("std");
const def_mod = @import("def.zig");

pub const DefId = def_mod.DefId;
pub const SymbolId = def_mod.SymbolId;
pub const DefKind = def_mod.DefKind;
pub const Def = def_mod.Def;

pub const ScopeKind = enum {
    module,

    function,
    block,
    closure,
    loop,
};

pub const Scope = struct {
    id: u32,
    kind: ScopeKind,
    parent: ?u32,

owner: DefId,
symbols: std.AutoHashMap(SymbolId, DefId),
defs: std.ArrayList(DefId),

pub fn deinit(self: *Scope) void {
    self.symbols.deinit();
    self.defs.deinit();
}

pub fn define(self: *Scope, name: SymbolId, def_id: DefId) void {

        self.symbols.put(name, def_id) catch {};
        self.defs.append(def_id) catch {};
    }
};

pub const ScopeChain = struct {
    scopes: std.ArrayList(Scope),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) ScopeChain {

    return .{
        .scopes = std.ArrayList(Scope).init(allocator),
        .allocator = allocator,
    };
}

pub fn deinit(self: *ScopeChain) void {
    for (self.scopes.items) |*scope| {
        scope.deinit();
    }

    self.scopes.deinit();
}

pub fn pushScope(self: *ScopeChain, kind: ScopeKind, parent: ?u32, owner: DefId) u32 {
    const id: u32 = @intCast(self.scopes.items.len);
    self.scopes.append(.{
        .id = id,
        .kind = kind,
        .parent = parent,
        .owner = owner,

        .symbols = std.AutoHashMap(SymbolId, DefId).init(self.allocator),
        .defs = std.ArrayList(DefId).init(self.allocator),
    }) catch return 0;
    return id;
}

pub fn getScope(self: *const ScopeChain, id: u32) ?*const Scope {
    if (id >= self.scopes.items.len) return null;
    return &self.scopes.items[id];
}

pub fn getScopeMut(self: *ScopeChain, id: u32) ?*Scope {
    if (id >= self.scopes.items.len) return null;
    return &self.scopes.items[id];
}

pub fn defineInScope(self: *ScopeChain, scope_id: u32, name: SymbolId, def_id: DefId) void {
    if (self.getScopeMut(scope_id)) |scope| {
        scope.define(name, def_id);
    }

}

pub fn lookupInScope(self: *const ScopeChain, scope_id: u32, name: SymbolId) ?DefId {
    var current_id: ?u32 = scope_id;
    while (current_id) |sid| {
        if (self.getScope(sid)) |scope| {
            if (scope.symbols.get(name)) |def_id| {
                return def_id;
            }
            current_id = scope.parent;

            } else {
                break;
            }
        }
        return null;
    }
};

const std = @import("std");
const Allocator = std.mem.Allocator;
const ast = @import("../../ast.zig");

pub const SymbolKind = enum {
    variable,
    param,
    function,
    state,
    struct_def,

    enum_def,
    module,
};

pub const Symbol = struct {
    name: []const u8,
    kind: SymbolKind,
    type_id: ast.TypeId,
    type_name: ?[]const u8,
    scope_level: u32,

};

pub const Scope = struct {
    level: u32,
    parent: ?*Scope,
    symbols: std.StringHashMap(Symbol),
    allocator: Allocator,

    pub fn init(allocator: Allocator, level: u32, parent: ?*Scope) Scope {
        return .{

        .level = level,
        .parent = parent,
        .symbols = std.StringHashMap(Symbol).init(allocator),
        .allocator = allocator,
    };
}

pub fn deinit(self: *Scope) void {
    self.symbols.deinit();
}

};

pub const ScopeTable = struct {
    root: *Scope,
    current: *Scope,
    allocator: Allocator,

    pub fn init(allocator: Allocator) !ScopeTable {
        const root = try allocator.create(Scope);
        root.* = Scope.init(allocator, 0, null);

    return .{
        .root = root,
        .current = root,
        .allocator = allocator,
    };
}

pub fn deinit(self: *ScopeTable) void {
    self.destroyScope(self.root);
}

fn destroyScope(self: *ScopeTable, scope: *Scope) void {
    scope.deinit();
    self.allocator.destroy(scope);
}

pub fn pushScope(self: *ScopeTable) !void {
    const new_scope = try self.allocator.create(Scope);
    new_scope.* = Scope.init(self.allocator, self.current.level + 1, self.current);
    self.current = new_scope;

}

pub fn popScope(self: *ScopeTable) void {
    if (self.current.parent) |parent| {
        const old = self.current;
        old.deinit();
        self.allocator.destroy(old);
        self.current = parent;
    }
}

pub fn define(
    self: *ScopeTable,
    name: []const u8,
    kind: SymbolKind,
    type_id: ast.TypeId,
    type_name: ?[]const u8,
) !void {
    const sym = Symbol{
        .name = name,

        .kind = kind,
        .type_id = type_id,
        .type_name = type_name,
        .scope_level = self.current.level,
    };
    try self.current.symbols.put(name, sym);
}

pub fn lookup(self: *ScopeTable, name: []const u8) ?Symbol {
    var scope: ?*Scope = self.current;

    while (scope) |s| {
        if (s.symbols.get(name)) |found| return found;
        scope = s.parent;
    }
    return null;
}

pub fn lookupCurrent(self: *ScopeTable, name: []const u8) ?Symbol {
    return self.current.symbols.get(name);
}

    pub fn isDefinedInCurrentScope(self: *ScopeTable, name: []const u8) bool {
        return self.current.symbols.contains(name);
    }
};

const std = @import("std");
const Allocator = std.mem.Allocator;
const ast = @import("ast.zig");
const scope_mod = @import("scope.zig");

pub const SemaError = error{
    UndefinedVariable,
    UndefinedFunction,
    UndefinedState,
    UndefinedStruct,

    ContinueOutsideLoop,
    ReturnTypeMismatch,
    NegativeArrayIndex,
    OutOfMemory,
};

pub const TypedVarInfo = struct {
    name: []const u8,
    type_id: ast.TypeId,
    type_name: ?[]const u8,

    scope_level: u32,
};

pub const SemaResult = struct {
    allocator: Allocator,
    typed_vars: std.ArrayList(TypedVarInfo),
    defined_func_names: std.ArrayList([]const u8),
    defined_struct_names: std.ArrayList([]const u8),
    defined_enum_names: std.ArrayList([]const u8),

pub fn deinit(self: *const SemaResult) void {
    for (self.typed_vars.items) |v| {
        self.allocator.free(v.name);
        if (v.type_name) |tn| self.allocator.free(tn);
    }
    self.typed_vars.deinit();
    for (self.defined_func_names.items) |n| self.allocator.free(n);
    self.defined_func_names.deinit();
    for (self.defined_struct_names.items) |n| self.allocator.free(n);
    self.defined_struct_names.deinit();

    for (self.defined_enum_names.items) |n| self.allocator.free(n);
    self.defined_enum_names.deinit();
}

pub fn lookupVarType(self: *const SemaResult, name: []const u8) ?ast.TypeId {
    var i: usize = self.typed_vars.items.len;
    while (i > 0) {
        i -= 1;
        if (std.mem.eql(u8, self.typed_vars.items[i].name, name)) {
            return self.typed_vars.items[i].type_id;

        }
    }
    return null;
}

pub fn isFunction(self: *const SemaResult, name: []const u8) bool {
    for (self.defined_func_names.items) |n| {
        if (std.mem.eql(u8, n, name)) return true;
    }
    return false;

}

pub fn isStruct(self: *const SemaResult, name: []const u8) bool {
    for (self.defined_struct_names.items) |n| {
        if (std.mem.eql(u8, n, name)) return true;
    }
    return false;
}

pub fn isEnum(self: *const SemaResult, name: []const u8) bool {

        for (self.defined_enum_names.items) |n| {
            if (std.mem.eql(u8, n, name)) return true;
        }
        return false;
    }
};

pub fn analyze(allocator: Allocator, program: ast.ProgramNode, src: []const u8, file_path: []const u8) !SemaResult {

    // ── Rich AST data stores (kept for detailed type info) ──

var defined_funcs = std.StringHashMap(ast.EntryDecl).init(allocator);
defer defined_funcs.deinit();

var defined_structs = std.StringHashMap(ast.StructDef).init(allocator);
defer defined_structs.deinit();

var defined_enums = std.StringHashMap(ast.EnumDecl).init(allocator);
defer defined_enums.deinit();

// ── Symbol Table: replaces local_vars, local_var_types, defined_states ──

var symtab = try scope_mod.ScopeTable.init(allocator);
defer symtab.deinit();

// Register global symbols in root scope
for (program.plan.states.items) |state| {
    if (symtab.isDefinedInCurrentScope(state.name)) {
        const ln = findLineNumber(src, state.name);
        std.log.err("{s}:{d}: error: duplicate state definition '{s}'", .{ file_path, ln, state.name });
        return SemaError.DuplicateDefinition;
    }

    try symtab.define(state.name, .state, .void, null);
}

for (program.common.func_defs.items) |func| {
    if (symtab.isDefinedInCurrentScope(func.name)) {
        const ln = findLineNumber(src, func.name);
        std.log.err("{s}:{d}: error: duplicate function definition '{s}'", .{ file_path, ln, func.name });
        return SemaError.DuplicateDefinition;
    }
    const rt = func.return_type orelse "void";

    try symtab.define(func.name, .function, ast.TypeId.fromName(rt), func.return_type);
    try defined_funcs.put(func.name, func);
}

{
    var struct_it = program.common.struct_defs.iterator();
    while (struct_it.next()) |entry| {
        try symtab.define(entry.key_ptr.*, .struct_def, .struct_type, entry.key_ptr.*);
        try defined_structs.put(entry.key_ptr.*, entry.value_ptr.*);
    }

}

for (program.common.enums.items) |en| {
    if (symtab.isDefinedInCurrentScope(en.name)) {
        const ln = findLineNumber(src, en.name);
        std.log.err("{s}:{d}: error: duplicate enum definition '{s}'", .{ file_path, ln, en.name });
        return SemaError.DuplicateDefinition;
    }
    try symtab.define(en.name, .enum_def, .enum_type, en.name);
    try defined_enums.put(en.name, en);

}

// ── Pass 2: Validate imports ──
for (program.common.imports.items) |imp| {
    const file = std.fs.cwd().openFile(imp.path, .{}) catch {
        const ln = findLineNumber(src, imp.path);
        std.log.err("{s}:{d}: error: import file not found '{s}'", .{ file_path, ln, imp.path });
        return SemaError.ImportNotFound;
    };
    file.close();

}

// ── Pass 3: Validate transitions & state bodies ──
for (program.plan.states.items) |state| {
    for (state.transitions.items) |trans| {
        if (symtab.lookup(trans.target) == null) {
            const ln = findLineNumber(src, state.name);
            std.log.err("{s}:{d}: error: undefined state '{s}' in transition from state '{s}'", .{ file_path, ln, trans.target, state.name });
            return SemaError.UndefinedState;
        }

    }
    if (state.enter_body) |body| {
        try validateBody(allocator, body, state.name, state.variables.items, &symtab, &defined_funcs, &defined_structs, &defined_enums, file_path, src);
    }
}

// ── Pass 4: Validate function bodies & return counts ──
for (program.common.func_defs.items) |func| {
    try validateFuncBody(allocator, func, &symtab, &defined_funcs, &defined_structs, &defined_enums, file_path, src);
}

// ── Build SemaResult with collected typed context ──
var result = SemaResult{
    .allocator = allocator,
    .typed_vars = std.ArrayList(TypedVarInfo).init(allocator),
    .defined_func_names = std.ArrayList([]const u8).init(allocator),
    .defined_struct_names = std.ArrayList([]const u8).init(allocator),
    .defined_enum_names = std.ArrayList([]const u8).init(allocator),
};
errdefer result.deinit();

for (program.common.func_defs.items) |func| {
    try result.defined_func_names.append(try allocator.dupe(u8, func.name));
}
{
    var struct_it = program.common.struct_defs.iterator();
    while (struct_it.next()) |entry| {
        try result.defined_struct_names.append(try allocator.dupe(u8, entry.key_ptr.*));
    }
}

    for (program.common.enums.items) |en| {
        try result.defined_enum_names.append(try allocator.dupe(u8, en.name));
    }

    // Collect typed variables from symtab by walking all scopes
    try collectTypedVars(&symtab, &result);

    return result;
}

fn collectTypedVars(symtab: *scope_mod.ScopeTable, result: *SemaResult) !void {
    var scope: ?*scope_mod.Scope = symtab.current;
    while (scope) |s| {
        var it = s.symbols.iterator();
        while (it.next()) |entry| {
            const sym = entry.value_ptr.*;
            try result.typed_vars.append(.{
                .name = try result.allocator.dupe(u8, sym.name),
                .type_id = sym.type_id,
                .type_name = if (sym.type_name) |tn| try result.allocator.dupe(u8, tn) else null,

                .scope_level = sym.scope_level,
            });
        }
        scope = s.parent;
    }
}

fn validateFuncBody(
    allocator: Allocator,
    func: ast.EntryDecl,

    parent_symtab: *scope_mod.ScopeTable,
    defined_funcs: *const std.StringHashMap(ast.EntryDecl),
    defined_structs: *const std.StringHashMap(ast.StructDef),
    defined_enums: *const std.StringHashMap(ast.EnumDecl),
    file_path: []const u8,
    src: []const u8,
) !void {
    // Push a new scope for this function
    try parent_symtab.pushScope();
    defer parent_symtab.popScope();

// Register parameters in the function scope
for (func.params.items) |param| {
    const type_id = ast.TypeId.fromName(param.type_name);
    try parent_symtab.define(param.name, .param, type_id, param.type_name);
    try validateTypeRef(param.type_name, defined_structs, defined_enums, file_path, src);
}

var return_count: usize = 0;
for (func.body_lines.items) |line| {

const trimmed = std.mem.trim(u8, line, " \t\r\n");
if (trimmed.len == 0) continue;

if (std.mem.startsWith(u8, trimmed, "return")) return_count += 1;

if (std.mem.startsWith(u8, trimmed, "var ")) {
    const rest = trimmed["var ".len..];
    const name = extractVarName(rest);
    const vtype = extractVarType(rest);
    if (name.len > 0) {

            const type_id = if (vtype) |vt| ast.TypeId.fromName(vt) else .unknown;
            try parent_symtab.define(name, .variable, type_id, vtype);
            if (vtype) |vt| {
                try validateTypeRef(vt, defined_structs, defined_enums, file_path, src);
            }
        }
    }

    try validateBodyLine(allocator, trimmed, parent_symtab, defined_funcs, defined_structs, defined_enums, file_path, src);
}

const has_return_type = func.return_type != null;
if (has_return_type and return_count == 0) {
    if (func.return_type) |rt| {
        if (!std.mem.eql(u8, rt, "void")) {
            const ln = findLineNumber(src, func.name);
            std.log.err("{s}:{d}: error: function '{s}' declares return type '{s}' but has no return statement", .{ file_path, ln, func.name, rt });
            return SemaError.ReturnTypeMismatch;
        }
    }

    }
    if (!has_return_type and return_count > 0) {
        const ln2 = findLineNumber(src, func.name);
        std.log.err("{s}:{d}: error: function '{s}' has return statements but declares no return type", .{ file_path, ln2, func.name });
        return SemaError.ReturnTypeMismatch;
    }
}

fn validateBody(
    allocator: Allocator,

// Push a new scope for the state entry body
try parent_symtab.pushScope();
defer parent_symtab.popScope();

// Register state variables
for (state_vars) |v| {
    const type_id = ast.TypeId.fromName(v.type_name);
    try parent_symtab.define(v.name, .variable, type_id, v.type_name);
    try validateTypeRef(v.type_name, defined_structs, defined_enums, file_path, src);
}

var brace_depth: i32 = 0;
var loop_levels = std.ArrayList(i32).init(allocator);
defer loop_levels.deinit();

var lines = std.mem.splitScalar(u8, body, '\n');
while (lines.next()) |line| {
    var stmts = std.mem.splitScalar(u8, line, ';');
    while (stmts.next()) |stmt| {
        const trimmed = std.mem.trim(u8, stmt, " \t\r\n");

if (trimmed.len == 0) continue;

const is_break = std.mem.eql(u8, trimmed, "break");
const is_continue = std.mem.eql(u8, trimmed, "continue");
if (is_break or is_continue) {
    if (loop_levels.items.len == 0) {
        const ln = findLineNumber(src, trimmed);
        if (is_break) {
            std.log.err("{s}:{d}: error: 'break' outside loop in state '{s}'", .{ file_path, ln, state_name });
            return SemaError.BreakOutsideLoop;

        } else {
            std.log.err("{s}:{d}: error: 'continue' outside loop in state '{s}'", .{ file_path, ln, state_name });
            return SemaError.ContinueOutsideLoop;
        }
    }
}

if (std.mem.startsWith(u8, trimmed, "var ")) {
    const rest = trimmed["var ".len..];
    const name = extractVarName(rest);

    const vtype = extractVarType(rest);
    if (name.len > 0) {
        const type_id = if (vtype) |vt| ast.TypeId.fromName(vt) else .unknown;
        try parent_symtab.define(name, .variable, type_id, vtype);
        if (vtype) |vt| {
            try validateTypeRef(vt, defined_structs, defined_enums, file_path, src);
        }
    }
}

const has_while = std.mem.indexOf(u8, trimmed, "while") != null;
const has_for = std.mem.indexOf(u8, trimmed, "for") != null;
var loop_pending = has_while or has_for;

