pub fn merge(a: SourceSpan, b: SourceSpan) SourceSpan {

    if (a.file_id != b.file_id) return a;
    return .{
        .file_id = a.file_id,
        .start = if (a.start < b.start) a.start else b.start,
        .end = if (a.end > b.end) a.end else b.end,
    };
