pub fn check(self: *TypeChecker) TypeCheckError!void {
    var i: u32 = 0;

    while (i < self.hir.itemCount()) : (i += 1) {
        const item_id = HirItemId.new(i);

        const item = self.hir.getItem(item_id) orelse continue;

        try self.checkItem(item);

    }
