const std = @import("std");
const hir_mod = @import("../hir/arena.zig");
const HirArena = hir_mod.HirArena;
const HirExpr = hir_mod.HirExpr;
const HirStmt = hir_mod.HirStmt;
const HirItem = hir_mod.HirItem;
const type_sys = @import("../type_system/type_system.zig");
const TypeEngine = type_sys.TypeEngine;
const TypeId = type_sys.TypeId;
const ExprId = hir_mod.ExprId;

const StmtId = hir_mod.StmtId;
const ItemId = hir_mod.ItemId;

pub const VerifyTypedError = error{
    UnresolvedExprType,
    InvalidExprType,
    InvalidReturnType,
    TypeMismatch,
};

pub fn verifyTypedHIR(
    arena: *const HirArena,
    engine: *const TypeEngine,
) VerifyTypedError!void {
    var i: u32 = 0;
    while (i < arena.itemCount()) : (i += 1) {
        const item_id = ItemId.new(i);
        const item = arena.getItem(item_id) orelse continue;
        try verifyTypedItem(arena, engine, item);
    }

}

fn verifyTypedItem(
    arena: *const HirArena,
    engine: *const TypeEngine,
    item: HirItem,
) VerifyTypedError!void {
    switch (item.kind) {
        .fn_decl => |f| {
            if (f.body.isValid()) {

        if (arena.getBody(f.body)) |body| {
            try verifyTypedExpr(arena, engine, body.entry);
        }
    }
},
.const_item => |c| {
    if (c.init.isValid()) {
        try verifyTypedExpr(arena, engine, c.init);
    }
},

.impl_item => |im| {
    for (im.methods) |m| {
        if (m.body.isValid()) {
            if (arena.getBody(m.body)) |body| {
                try verifyTypedExpr(arena, engine, body.entry);
            }
        }
    }
},
else => {},

    }
}

fn verifyTypedExpr(
    arena: *const HirArena,
    engine: *const TypeEngine,
    expr_id: ExprId,
) VerifyTypedError!void {
    if (!expr_id.isValid()) return;
    const expr = arena.getExpr(expr_id) orelse return;

if (!expr.ty.isValid()) return;

if (engine.get(expr.ty)) |data| {
    if (data == .infer_var) {
        return error.UnresolvedExprType;
    }
}

switch (expr.kind) {

.binary => |b| {
    if (b.left.isValid()) try verifyTypedExpr(arena, engine, b.left);
    if (b.right.isValid()) try verifyTypedExpr(arena, engine, b.right);
},
.unary => |u| {
    if (u.operand.isValid()) try verifyTypedExpr(arena, engine, u.operand);
},
.call => |c| {
    if (c.callee.isValid()) try verifyTypedExpr(arena, engine, c.callee);
    for (c.args) |arg| {

        if (arg.isValid()) try verifyTypedExpr(arena, engine, arg);
    }
},
.if_expr => |i| {
    if (i.condition.isValid()) try verifyTypedExpr(arena, engine, i.condition);
    if (i.then_branch.isValid()) try verifyTypedExpr(arena, engine, i.then_branch);
    if (i.else_branch.isValid()) try verifyTypedExpr(arena, engine, i.else_branch);
},
.assign => |a| {
    if (a.target.isValid()) try verifyTypedExpr(arena, engine, a.target);

    if (a.value.isValid()) try verifyTypedExpr(arena, engine, a.value);
},
.return_expr => |r| {
    if (r.value.isValid()) try verifyTypedExpr(arena, engine, r.value);
},
.block => |b| {
    for (b.stmts) |sid| {
        if (sid.isValid()) try verifyTypedStmt(arena, engine, sid);
    }
    if (b.result.isValid()) try verifyTypedExpr(arena, engine, b.result);

},
.while_expr => |w| {
    if (w.condition.isValid()) try verifyTypedExpr(arena, engine, w.condition);
    if (w.body.isValid()) try verifyTypedExpr(arena, engine, w.body);
},
.for_expr => |f| {
    if (f.iterable.isValid()) try verifyTypedExpr(arena, engine, f.iterable);
    if (f.body.isValid()) try verifyTypedExpr(arena, engine, f.body);
},
.loop_expr => |l| {

    if (l.body.isValid()) try verifyTypedExpr(arena, engine, l.body);
},
.break_expr => |b| {
    if (b.value.isValid()) try verifyTypedExpr(arena, engine, b.value);
},
.match_expr => |m| {
    if (m.scrutinee.isValid()) try verifyTypedExpr(arena, engine, m.scrutinee);
    for (m.arms) |arm| {
        if (arm.body.isValid()) try verifyTypedExpr(arena, engine, arm.body);
    }

},
.closure => |c| {
    if (c.body.isValid()) try verifyTypedExpr(arena, engine, c.body);
},
.field => |f| {
    if (f.object.isValid()) try verifyTypedExpr(arena, engine, f.object);
},
.index => |i| {
    if (i.object.isValid()) try verifyTypedExpr(arena, engine, i.object);
    if (i.index.isValid()) try verifyTypedExpr(arena, engine, i.index);

},
.range => |r| {
    if (r.start.isValid()) try verifyTypedExpr(arena, engine, r.start);
    if (r.end.isValid()) try verifyTypedExpr(arena, engine, r.end);
},
.type_cast => |tc| {
    if (tc.operand.isValid()) try verifyTypedExpr(arena, engine, tc.operand);
},
.ref => |r| {
    if (r.operand.isValid()) try verifyTypedExpr(arena, engine, r.operand);

},
.deref => |d| {
    if (d.operand.isValid()) try verifyTypedExpr(arena, engine, d.operand);
},
.method_call => |mc| {
    if (mc.object.isValid()) try verifyTypedExpr(arena, engine, mc.object);
    for (mc.args) |arg| {
        if (arg.isValid()) try verifyTypedExpr(arena, engine, arg);
    }
},

        .path, .literal, .continue_expr, .missing => {},
    }
}

fn verifyTypedStmt(
    arena: *const HirArena,
    engine: *const TypeEngine,
    stmt_id: StmtId,
) VerifyTypedError!void {
    if (!stmt_id.isValid()) return;

const stmt = arena.getStmt(stmt_id) orelse return;

switch (stmt.kind) {
    .local_decl => |ld| {
        if (ld.init) |init_id| {
            if (init_id.isValid()) try verifyTypedExpr(arena, engine, init_id);
        }
    },
    .expr => |es| {
        if (es.expr.isValid()) try verifyTypedExpr(arena, engine, es.expr);

},
.block => |bs| {
    for (bs.stmts) |sid| {
        if (sid.isValid()) try verifyTypedStmt(arena, engine, sid);
    }
},
.if_stmt => |ifs| {
    if (ifs.condition.isValid()) try verifyTypedExpr(arena, engine, ifs.condition);
    if (ifs.then_branch.isValid()) try verifyTypedStmt(arena, engine, ifs.then_branch);
    if (ifs.else_branch) |eb| {

        if (eb.isValid()) try verifyTypedStmt(arena, engine, eb);
    }
},
.while_stmt => |ws| {
    if (ws.condition.isValid()) try verifyTypedExpr(arena, engine, ws.condition);
    if (ws.body.isValid()) try verifyTypedStmt(arena, engine, ws.body);
},
.for_stmt => |fs| {
    if (fs.iterable.isValid()) try verifyTypedExpr(arena, engine, fs.iterable);
    if (fs.body.isValid()) try verifyTypedStmt(arena, engine, fs.body);

},
.loop_stmt => |ls| {
    if (ls.body.isValid()) try verifyTypedStmt(arena, engine, ls.body);
},
.return_stmt => |rs| {
    if (rs.value) |val| {
        if (val.isValid()) try verifyTypedExpr(arena, engine, val);
    }
},
.break_stmt => |bs| {

    if (bs.value) |val| {
        if (val.isValid()) try verifyTypedExpr(arena, engine, val);
    }
},
.defer_stmt => |ds| {
    if (ds.body.isValid()) try verifyTypedStmt(arena, engine, ds.body);
},
.errdefer_stmt => |eds| {
    if (eds.body.isValid()) try verifyTypedStmt(arena, engine, eds.body);
},

        .continue_stmt, .missing => {},
    }
}

const std = @import("std");
const types_mod = @import("types.zig");
const TypeData = types_mod.TypeData;
const TypeId = types_mod.TypeId;
const TypeVarId = types_mod.TypeVarId;

pub const TypeArena = struct {
    backing: std.mem.Allocator,
    aa_ptr: ?*std.heap.ArenaAllocator,
    types: std.ArrayList(TypeData),

interning: std.AutoHashMap(InternKey, TypeId),

const InternKey = struct {
    tag: @TypeOf(@as(TypeData, undefined)),
    index: u32,
};

pub fn init(backing: std.mem.Allocator) TypeArena {
    const aa_ptr = backing.create(std.heap.ArenaAllocator) catch unreachable;
    aa_ptr.* = std.heap.ArenaAllocator.init(backing);

    const aa_alloc = aa_ptr.allocator();
    return .{
        .backing = backing,
        .aa_ptr = aa_ptr,
        .types = std.ArrayList(TypeData).init(aa_alloc),
        .interning = std.AutoHashMap(InternKey, TypeId).init(aa_alloc),
    };
}

pub fn deinit(self: *TypeArena) void {

    if (self.aa_ptr) |aa| {
        aa.deinit();
        self.backing.destroy(aa);
        self.aa_ptr = null;
    }
}

pub fn allocator(self: *TypeArena) std.mem.Allocator {
    return self.aa_ptr.?.allocator();
}

pub fn intern(self: *TypeArena, td: TypeData) TypeId {
    const idx: u32 = @intCast(self.types.items.len);
    self.types.append(td) catch return TypeId.INVALID;
    return TypeId.new(idx);
}

pub fn internSlice(self: *TypeArena, comptime T: type, items: []const T) ![]const TypeId {
    const alloc = self.allocator();
    var result = std.ArrayList(TypeId).init(alloc);

    for (items) |item| {
        result.append(self.intern(item)) catch return error.OutOfMemory;
    }
    return result.toOwnedSlice() catch return error.OutOfMemory;
}

pub fn get(self: *const TypeArena, id: TypeId) ?TypeData {
    if (!id.isValid() or id.index >= self.types.items.len) return null;
    return self.types.items[id.index];
}

pub fn count(self: *const TypeArena) u32 {
    return @intCast(self.types.items.len);
}

pub fn builtin(self: *TypeArena, kind: types_mod.BuiltinKind) TypeId {
    return self.intern(.{ .builtin = kind });
}

pub fn pointer(self: *TypeArena, mutable: types_mod.Mutability, pointee: TypeId) TypeId {

    return self.intern(.{ .pointer = .{ .mutable = mutable, .pointee = pointee } });
}

pub fn slice(self: *TypeArena, element: TypeId) TypeId {
    return self.intern(.{ .slice = .{ .element = element } });
}

pub fn array(self: *TypeArena, element: TypeId, length: u64) TypeId {
    return self.intern(.{ .array = .{ .element = element, .length = length } });
}

pub fn tuple(self: *TypeArena, elements: []const TypeId) TypeId {
    const owned = self.allocator().alloc(TypeId, elements.len) catch return TypeId.INVALID;
    @memcpy(owned, elements);
    return self.intern(.{ .tuple = .{ .elements = owned } });
}

pub fn fnPtr(self: *TypeArena, params: []const TypeId, ret: TypeId, variadic: bool) TypeId {
    const owned = self.allocator().alloc(TypeId, params.len) catch return TypeId.INVALID;
    @memcpy(owned, params);

    return self.intern(.{ .fn_ptr = .{ .params = owned, .ret = ret, .is_variadic = variadic } });
}

pub fn reference(self: *TypeArena, mutable: types_mod.Mutability, referent: TypeId) TypeId {
    return self.intern(.{ .reference = .{ .mutable = mutable, .referent = referent } });
}

pub fn optional(self: *TypeArena, inner: TypeId) TypeId {
    return self.intern(.{ .optional = .{ .inner = inner } });
}

pub fn errorUnion(self: *TypeArena, ok: TypeId, err: TypeId) TypeId {
    return self.intern(.{ .error_union = .{ .ok = ok, .err = err } });
}

pub fn adt(self: *TypeArena, def_id: ids.DefId, args: []const TypeId) TypeId {
    const owned = self.allocator().alloc(TypeId, args.len) catch return TypeId.INVALID;
    @memcpy(owned, args);
    return self.intern(.{ .adt = .{ .def_id = def_id, .args = owned } });
}

pub fn typeParam(self: *TypeArena, index: u32, name: ids.SymbolId) TypeId {
    return self.intern(.{ .type_param = .{ .index = index, .name = name } });
}

pub fn inferVar(self: *TypeArena, var_id: TypeVarId) TypeId {
    return self.intern(.{ .infer_var = .{ .var_id = var_id } });
}

pub fn resolvedVar(self: *TypeArena, target: TypeId) TypeId {

    return self.intern(.{ .resolved_var = target });
}

pub fn never(self: *TypeArena) TypeId {
    return self.intern(.{ .never = {} });
}

pub fn unit(self: *TypeArena) TypeId {
    return self.intern(.{ .unit = {} });
}

pub fn errorType(self: *TypeArena) TypeId {
    return self.intern(.{ .error_type = {} });
}

pub fn voidType(self: *TypeArena) TypeId {
    return self.builtin(.void_type);
}

pub fn format(self: *const TypeArena, id: TypeId, writer: anytype) !void {

        if (self.get(id)) |td| {
            try td.format("", .{}, writer);
        } else {
            try writer.print("Type({d})", .{id.index});
        }
    }
};

const ids = @import("../foundation/ids/ids.zig");

test "TypeArena: create primitives" {
    var arena = TypeArena.init(std.testing.allocator);
    defer arena.deinit();

    const i32_ty = arena.builtin(.i32_type);
    const bool_ty = arena.builtin(.bool_type);
    const void_ty = arena.voidType();

    try std.testing.expect(i32_ty.isValid());
    try std.testing.expect(bool_ty.isValid());

    try std.testing.expect(void_ty.isValid());
    try std.testing.expect(i32_ty.index != bool_ty.index);
    try std.testing.expect(arena.count() == 3);

    const got = arena.get(i32_ty);
    try std.testing.expect(got != null);
    try std.testing.expect(got.?.builtin == .i32_type);
}

test "TypeArena: compound types" {

var arena = TypeArena.init(std.testing.allocator);
defer arena.deinit();

const i32_ty = arena.builtin(.i32_type);
const bool_ty = arena.builtin(.bool_type);

const ref_ty = arena.reference(.@"const", i32_ty);
try std.testing.expect(ref_ty.isValid());
const ref_data = arena.get(ref_ty).?.reference;
try std.testing.expect(ref_data.mutable == .@"const");

