const std = @import("std");

/// LLVM bitstream writer matching LLVM 13 format.
pub const Writer = struct {
    allocator: std.mem.Allocator,
    words: std.ArrayListUnmanaged(u32),
    cur_bit: u32,
    block_size_words: std.ArrayListUnmanaged(u32),
    code_len_stack: std.ArrayListUnmanaged(u32),

pub fn init(a: std.mem.Allocator) Writer {
    return .{
        .allocator = a,
        .words = .{},
        .cur_bit = 0,
        .block_size_words = .{},
        .code_len_stack = .{},
    };
}

pub fn deinit(self: *Writer) void {
    self.words.deinit(self.allocator);
    self.block_size_words.deinit(self.allocator);
    self.code_len_stack.deinit(self.allocator);
}

fn grow(self: *Writer, need: u32) !void {
    const n = (self.cur_bit + need + 31) / 32;
    while (self.words.items.len < n)
        try self.words.append(self.allocator, 0);

}

/// Put `val` in lowest `n` bits, LSB-first (matching LLVM 13 BitstreamWriter::Emit).
/// LLVM packs values into words from bit 0 upward with no bit reversal.
fn put(self: *Writer, val: u32, n: u32) !void {
    if (n == 0) return;
    try self.grow(n);
    var v = val;
    var remaining = n;
    while (remaining > 0) {

const wi = self.cur_bit / 32;
const bi = self.cur_bit % 32;
const space = 32 - bi;
const take = @min(remaining, space);
const mask = (@as(u32, 1) << @intCast(take)) -% 1;
const bits = v & mask;
self.words.items[wi] |= bits << @intCast(bi);
v >>= @intCast(take);
self.cur_bit += take;
remaining -= take;

    }
}

fn align_(self: *Writer) !void {
    const off = self.cur_bit % 32;
    if (off != 0) try self.put(0, 32 - off);
}

/// Current word index (0-based).
fn wordIndex(self: *Writer) u32 {

    return self.cur_bit / 32;
}

/// VBR(n): continuation bit 0 (LSB), data bits n-1..1 (LLVM 3.0+ format).
pub fn vbr(self: *Writer, value: u64, n: u32) !void {
    const db = n - 1;
    const msk = (@as(u64, 1) << @intCast(db)) - 1;
    var v = value;
    while (v >= (@as(u64, 1) << @intCast(db))) {
        try self.put(@as(u32, @intCast((v & msk) << 1)) | 1, n);

        v >>= @intCast(db);
    }
    try self.put(@as(u32, @intCast((v & msk) << 1)), n);
}

pub fn fixed(self: *Writer, val: u32, n: u32) !void {
    try self.put(val, n);
}

/// Emit a full 32-bit word (little-endian byte order, MSB-first bits).

fn emitWord(self: *Writer, val: u32) !void {
    // Flush any partial bits in the current word, then write 'val' as the next word.
    try self.align_();
    const wi = self.wordIndex();
    try self.grow(32);
    self.words.items[wi] = val;
    self.cur_bit += 32;
}

/// Backpatch a 32-bit word at a given word index.

fn backpatchWord(self: *Writer, wi: u32, val: u32) void {
    if (wi < self.words.items.len) {
        self.words.items[wi] = val;
    }
}

/// Enter subblock (LLVM 13 format).
/// Layout: [ENTER_SUBBLOCK(2)] [BlockID VBR(8)] [CodeLen VBR(4)] [align32] [BlockSize: 32-bit fixed word]
pub fn enterBlock(self: *Writer, id: u32, code_len: u32) !void {
    try self.fixed(1, 2);   // ENTER_SUBBLOCK

    try self.vbr(id, 8);    // BlockID VBR(8)
    try self.vbr(code_len, 4); // CodeLen VBR(4)

    // emitWord handles 32-bit alignment then writes the block-size word
    try self.emitWord(0);    // placeholder 32-bit block size
    const wi = self.wordIndex() - 1;
    try self.block_size_words.append(self.allocator, wi);
    try self.code_len_stack.append(self.allocator, code_len);
}

/// Exit subblock (matches LLVM 13 ExitBlock).
/// Writes END_BLOCK, aligns to word boundary, pushes a new word,
/// then backpatches block size.
pub fn exitBlock(self: *Writer) !void {
    try self.fixed(0, 2);    // END_BLOCK
    try self.align_();        // align to word boundary (LLVM FlushToWord)

    const end_wi = self.wordIndex();
    const size_wi = self.block_size_words.pop() orelse return;
    _ = self.code_len_stack.pop();

    const sz = end_wi - size_wi - 1;
    self.backpatchWord(size_wi, sz);
    const debug = @import("std").debug;
    debug.print("exitBlock: size_wi={d}, end_wi={d}, sz={d} (words.len={d})\n", .{ size_wi, end_wi, sz, self.words.items.len });
}

/// Unabbreviated record: abbrev=3, code=VBR(CodeLen), num_elts=VBR6, operands=VBR6...
/// LLVM 13 UNABBREV_RECORD includes an explicit operand count after the code.
pub fn record(self: *Writer, code: u32, ops: []const u32) !void {

    const code_len = self.code_len_stack.getLast();
    try self.fixed(3, 2);
    try self.vbr(code, code_len);
    try self.vbr(@as(u32, @intCast(ops.len)), 6);
    for (ops) |op| try self.vbr(op, 6);
}

pub fn finish(self: *Writer) ![]u8 {
    try self.align_();
    const nw = self.wordIndex();

        self.words.shrinkAndFree(self.allocator, nw);
        return std.mem.sliceAsBytes(self.words.items);
    }
};

const std = @import("std");
const Allocator = std.mem.Allocator;
const gpu_ir = @import("gpu_ir.zig");

/// Generate C++ UE shader class from GPU IR
pub fn generateCppFromIr(allocator: Allocator, ir: *const gpu_ir.IrModule) ![]const u8 {
    var buf = std.ArrayList(u8).init(allocator);
    const w = buf.writer();

    for (ir.functions.items) |func| {

const class_name = try std.fmt.allocPrint(allocator, "FTSSShader_{s}", .{func.kernel_name});
defer allocator.free(class_name);

// Class declaration
try w.print("class {s} : public FGlobalShader\n", .{class_name});
try w.writeAll("{\n");
try w.writeAll("public:\n");
try w.print("\tDECLARE_GLOBAL_SHADER({s});\n", .{class_name});
try w.print("\tSHADER_USE_PARAMETER_STRUCT({s}, FGlobalShader);\n", .{class_name});
try w.writeAll("\n");

// FParameters struct
try w.writeAll("\tBEGIN_SHADER_PARAMETER_STRUCT(FParameters, )\n");

// Resource declarations
for (ir.resources.items) |*res| {
    try w.writeAll("\t\t");
    try writeResourceParam(w, res);
}

// Cbuffer declarations
for (ir.cbuffer_members.items) |*mem| {
    try w.writeAll("\t\t");
    try writeCbufferParam(w, mem);
}

try w.writeAll("\tEND_SHADER_PARAMETER_STRUCT()\n");
try w.writeAll("};\n\n");

// IMPLEMENT_GLOBAL_SHADER macro

        const usf_path = try std.fmt.allocPrint(allocator, "/Plugin/TSS/Private/TSS{s}.usf", .{func.kernel_name});
        defer allocator.free(usf_path);
        const entry_name = try std.fmt.allocPrint(allocator, "{s}Main", .{func.kernel_name});
        defer allocator.free(entry_name);
        try w.print("IMPLEMENT_GLOBAL_SHADER({s}, \"{s}\", \"{s}\", SF_Compute);\n\n", .{ class_name, usf_path, entry_name });
    }

    return buf.toOwnedSlice();
}

fn writeResourceParam(w: anytype, res: *const gpu_ir.IrResourceDecl) !void {
    const param_type = switch (res.type_ref) {
        .texture2d => "SHADER_PARAMETER_RDG_TEXTURE",
        .rw_texture2d => "SHADER_PARAMETER_RDG_TEXTURE_UAV",
        .sampler => "SHADER_PARAMETER_SAMPLER",
        else => "SHADER_PARAMETER_RDG_TEXTURE",
    };

    const hlsl_type = switch (res.type_ref) {
        .texture2d => "Texture2D<float4>",

        .rw_texture2d => "RWTexture2D<float4>",
        .sampler => "SamplerState",
        else => "Texture2D<float4>",
    };

    try w.print("{s}({s}, {s})\n", .{ param_type, hlsl_type, res.name });
}

fn writeCbufferParam(w: anytype, mem: *const gpu_ir.IrCbufferMember) !void {
    const cpp_type = switch (mem.type_ref) {

        .vec3u => "FUintVector3",
        .vec4u => "FUintVector4",
        else => "float",
    };

    try w.print("SHADER_PARAMETER({s}, {s})\n", .{ cpp_type, mem.name });
}

pub const backend: gpu_ir.BackendApi = .{
    .name = "C++",

    .target = .cpp,
    .file_extension = "cpp",
    .description = "Unreal Engine C++ shader class",
    .compile = compileCppFromIr,
};

fn compileCppFromIr(allocator: Allocator, ir: *const gpu_ir.IrModule, options: gpu_ir.CompileOptions) !gpu_ir.CompileResult {
    _ = options;
    const cpp = try generateCppFromIr(allocator, ir);
    return gpu_ir.CompileResult{

        .bytecode = cpp,
        .allocator = allocator,
    };
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const gpu_ir = @import("gpu_ir.zig");
const bc = @import("dxil_bitcode.zig");

pub const backend: gpu_ir.BackendApi = .{
    .name = "DXIL",
    .target = .dxil,
    .file_extension = "dxil",
    .description = "Direct3D DXIL shader bytecode (native LLVM bitcode)",

    .compile = compileDxilFromIr,
};

fn compileDxilFromIr(allocator: Allocator, ir: *const gpu_ir.IrModule, _: gpu_ir.CompileOptions) !gpu_ir.CompileResult {
    const dxil_bytes = try emitDxilContainer(allocator, ir);
    return gpu_ir.CompileResult{
        .bytecode = dxil_bytes,
        .allocator = allocator,
    };
}

fn emitDxilContainer(allocator: Allocator, ir: *const gpu_ir.IrModule) ![]u8 {
    // 1. Generate LLVM bitcode
    var bw = bc.Writer.init(allocator);
    defer bw.deinit();
    try emitLlvmModule(&bw, ir);
    const llvm_bc = try bw.finish();

    // 2. Build parts
    const func = &ir.functions.items[0];

const psv = try buildPsv(allocator, func);
const dxil_payload = try buildDxilPayload(allocator, llvm_bc);

// 3. Write container: DXBC header + part offset table + parts with 8-byte gaps
const gap: u32 = 8;
const num_parts: u32 = 2;
const header_size: u32 = 32 + num_parts * 4;
const total: u32 = header_size +
    (8 + @as(u32, @intCast(psv.len)) + gap) +
    (8 + @as(u32, @intCast(dxil_payload.len)) + gap);

var buf = try allocator.alloc(u8, total);
@memset(buf, 0);
var pos: u32 = 0;

@memcpy(buf[pos..][0..4], "DXBC");
pos += 20;
std.mem.writeInt(u32, buf[pos..][0..4], 1, .little);
pos += 4;
std.mem.writeInt(u32, buf[pos..][0..4], total, .little);

pos += 4;
std.mem.writeInt(u32, buf[pos..][0..4], num_parts, .little);
pos += 4;

const off_table = pos;
pos += num_parts * 4;

var cur_off: u32 = header_size;

std.mem.writeInt(u32, buf[off_table..][0..4], cur_off, .little);

std.mem.writeInt(u32, buf[cur_off..][0..4], 0x30565350, .little);
std.mem.writeInt(u32, buf[cur_off + 4 ..][0..4], 8 + @as(u32, @intCast(psv.len)), .little);
@memcpy(buf[cur_off + 8 ..][0..psv.len], psv);
cur_off += 8 + @as(u32, @intCast(psv.len)) + gap;

std.mem.writeInt(u32, buf[off_table + 4 ..][0..4], cur_off, .little);
std.mem.writeInt(u32, buf[cur_off..][0..4], 0x4C495844, .little);
std.mem.writeInt(u32, buf[cur_off + 4 ..][0..4], 8 + @as(u32, @intCast(dxil_payload.len)), .little);
@memcpy(buf[cur_off + 8 ..][0..dxil_payload.len], dxil_payload);

    return buf;
}

fn buildPsv(allocator: Allocator, func: *const gpu_ir.IrFunction) ![]u8 {
    const psv_len: usize = 70;
    const psv = try allocator.alloc(u8, psv_len);
    @memset(psv, 0);
    std.mem.writeInt(u32, psv[0..4], 0x34, .little);
    std.mem.writeInt(u32, psv[24..28], 0xFFFFFFFF, .little);
    std.mem.writeInt(u32, psv[28..32], 5, .little);

std.mem.writeInt(u32, psv[40..44], func.numthreads.x, .little);
std.mem.writeInt(u32, psv[44..48], func.numthreads.y, .little);
std.mem.writeInt(u32, psv[48..52], func.numthreads.z, .little);
std.mem.writeInt(u32, psv[52..56], 1, .little);
std.mem.writeInt(u32, psv[60..64], 8, .little);
if (func.name.len >= 4) {
    @memcpy(psv[65..69], func.name[0..4]);
} else {
    psv[65] = 'm';
    psv[66] = 'a';

        psv[67] = 'i';
        psv[68] = 'n';
    }
    return psv;
}

fn buildDxilPayload(allocator: Allocator, llvm_bc: []const u8) ![]u8 {
    const bc_align_bytes: u32 = 12 * 4; // 48 bytes from BC wrapper start to bitstream
    const bc_wrapper_sz: usize = bc_align_bytes;
    const dxil_data_sz: usize = 24 + bc_wrapper_sz + llvm_bc.len;

const payload = try allocator.alloc(u8, dxil_data_sz);
@memset(payload, 0);

const bitcode_sz: u32 = @as(u32, @intCast(bc_wrapper_sz + llvm_bc.len));
std.mem.writeInt(u32, payload[0..4], 0x00050060, .little);
std.mem.writeInt(u32, payload[4..8], (24 + bitcode_sz + 3) / 4, .little);
@memcpy(payload[8..12], "DXIL");
std.mem.writeInt(u32, payload[12..16], 0x100, .little);
std.mem.writeInt(u32, payload[16..20], 24, .little);
std.mem.writeInt(u32, payload[20..24], bitcode_sz, .little);

    std.mem.writeInt(u32, payload[24..28], 0xDEC04342, .little);
    std.mem.writeInt(u32, payload[28..32], 0x0C21, .little);
    std.mem.writeInt(u32, payload[32..36], 12, .little);

    // padding from byte 36 to byte 71 (36 bytes) is already 0 from @memset

    @memcpy(payload[72..][0..llvm_bc.len], llvm_bc);
    return payload;
}

fn emitLlvmModule(bw: *bc.Writer, ir: *const gpu_ir.IrModule) !void {
    _ = ir;
    try bw.enterBlock(8, 2); // MODULE_BLOCK

    // Version = 2 (LLVM 3.7)
    try bw.record(1, &.{2});

    // Target triple
    try bw.record(2, &.{ 'd', 'x', 'i', 'l', '-', 'm', 's', '-', 'd', 'x' });

// Data layout
const dl = "e-m:e-p:32:32-i1:32-i8:32-i16:32-i32:32-i64:64-f16:32-f32:32-f64:64-n8:16:32:64";
var dl_ops: [100]u32 = undefined;
for (dl, 0..) |c, i| dl_ops[i] = c;
try bw.record(3, dl_ops[0..dl.len]);

// ── TYPE TABLE (LLVM 13 codes) ──
try bw.enterBlock(10, 2); // TYPE_BLOCK
try bw.record(1, &.{13}); // NUMENTRY: 13 types

try bw.record(2, &.{}); // TYPE_VOID → type 0
try bw.record(3, &.{}); // TYPE_FLOAT → type 1
try bw.record(7, &.{32}); // TYPE_INTEGER: width=32 → type 2 (i32/u32)
try bw.record(7, &.{16}); // TYPE_INTEGER: width=16 → type 3 (i16)
try bw.record(7, &.{1}); // TYPE_INTEGER: width=1 → type 4 (i1/bool)
try bw.record(8, &.{1}); // TYPE_POINTER: elt=type1(float), addrspace=0 → type 5 (float*)
try bw.record(12, &.{2, 1}); // TYPE_VECTOR: count=2, elt=float → type 6 (<2 x f32>)
try bw.record(12, &.{3, 1}); // TYPE_VECTOR: count=3, elt=float → type 7 (<3 x f32>)
try bw.record(12, &.{4, 1}); // TYPE_VECTOR: count=4, elt=float → type 8 (<4 x f32>)
try bw.record(12, &.{2, 2}); // TYPE_VECTOR: count=2, elt=i32 → type 9 (<2 x i32>)

try bw.record(12, &.{3, 2}); // TYPE_VECTOR: count=3, elt=i32 → type 10 (<3 x i32>)
try bw.record(12, &.{4, 2}); // TYPE_VECTOR: count=4, elt=i32 → type 11 (<4 x i32>)
try bw.record(21, &.{0, 0}); // TYPE_FUNCTION: vararg=0, retty=void=type0 → type 12
try bw.exitBlock(); // TYPE_BLOCK

// ── FUNCTION DECLARATION ──
// [value_id=0, type=12, callingconv=0, isproto=0, linkage=0, ...]
try bw.record(8, &.{ 0, 12, 0, 0, 0, 0, 0, 0, 0, 0, 0 });

// ── FUNCTION BLOCK ──

try bw.enterBlock(12, 2); // FUNCTION_BLOCK
try bw.record(1, &.{1}); // DECLARE_BLOCKS: 1 basic block

// Constants block: define i32 values used in metadata and instructions
try bw.enterBlock(11, 2); // CONSTANTS_BLOCK
// CST_CODE_SETTYPE(1): set current type to i32 (type 2)
try bw.record(1, &.{2});
// CST_CODE_INTEGER(4): define integer constants (LLVM 13: INTEGER=4, not 2)
try bw.record(4, &.{0}); // value 1: i32 0
try bw.record(4, &.{1}); // value 2: i32 1

try bw.record(4, &.{6}); // value 3: i32 6
try bw.record(4, &.{9}); // value 4: i32 9
try bw.record(4, &.{4}); // value 5: i32 4
try bw.exitBlock(); // CONSTANTS_BLOCK

// INST_BLOCK for basic block 0
try bw.enterBlock(13, 2); // INST_BLOCK
// ret void: INST_CODE_RET=1, record = [0] (void return)
try bw.record(1, &.{0});
try bw.exitBlock(); // INST_BLOCK

// Metadata nodes
// !0 = !{!"dxcoob..."} → node containing md ref to #0
try emitMdNode(bw, &.{.{
    .tag = .metadata,
    .val = 0, // md_id 0
}}); // md #3

// !1 = !{i32 1, i32 0}
try emitMdNode(bw, &.{

    .{ .tag = .value, .val = 2 }, // value_id 2 = i32 1
    .{ .tag = .value, .val = 1 }, // value_id 1 = i32 0
}); // md #4

// !2 = !{i32 1, i32 9}
try emitMdNode(bw, &.{
    .{ .tag = .value, .val = 2 }, // value_id 2 = i32 1
    .{ .tag = .value, .val = 4 }, // value_id 4 = i32 9
}); // md #5

// !3 = !{!"cs", i32 6, i32 0}
try emitMdNode(bw, &.{
    .{ .tag = .metadata, .val = 1 }, // md_id 1 = "cs"
    .{ .tag = .value, .val = 3 }, // value_id 3 = i32 6
    .{ .tag = .value, .val = 1 }, // value_id 1 = i32 0
}); // md #6

// !6 = !{i32 1, i32 1, i32 1}
try emitMdNode(bw, &.{
    .{ .tag = .value, .val = 2 },

    .{ .tag = .value, .val = 2 },
    .{ .tag = .value, .val = 2 },
}); // md #7

// !5 = !{i32 4, !6}
try emitMdNode(bw, &.{
    .{ .tag = .value, .val = 5 }, // value_id 5 = i32 4
    .{ .tag = .metadata, .val = 7 }, // md_id 7 = !6
}); // md #8

// !4 = !{void ()* @main, !"main", null, null, !5}
try emitMdNode(bw, &.{
    .{ .tag = .value, .val = 0 }, // value_id 0 = @main
    .{ .tag = .metadata, .val = 2 }, // md_id 2 = "main"
    .{ .tag = .null, .val = 0 },
    .{ .tag = .null, .val = 0 },
    .{ .tag = .metadata, .val = 8 }, // md_id 8 = !5
}); // md #9

// Named metadata

    try emitMdNamed(bw, "llvm.ident", 3); // = !{!0}
    try emitMdNamed(bw, "dx.version", 4); // = !{!1}
    try emitMdNamed(bw, "dx.valver", 5); // = !{!2}
    try emitMdNamed(bw, "dx.shaderModel", 6); // = !{!3}
    try emitMdNamed(bw, "dx.entryPoints", 9); // = !{!4}

    try bw.exitBlock(); // METADATA_BLOCK
    try bw.exitBlock(); // MODULE_BLOCK
}

const MdOperand = struct {
    tag: enum { null, value, metadata },
    val: u32,
};

fn emitMdString(bw: *bc.Writer, s: []const u8) !void {
    var ops: [256]u32 = undefined;
    for (s, 0..) |c, i| ops[i] = c;
    try bw.record(1, ops[0..s.len]);
}

fn emitMdNode(bw: *bc.Writer, ops: []const MdOperand) !void {
    // METADATA_NODE (code 3) with old-style encoding:
    // First operand: number of elements
    // Then each element: null=0, value=(id+1)<<1, metadata=(id<<1)|1
    var buf: [32]u32 = undefined;
    buf[0] = @as(u32, @intCast(ops.len));
    for (ops, 0..) |op, i| {
        buf[i + 1] = switch (op.tag) {
            .null => 0,

            .value => (op.val + 1) << 1,
            .metadata => (op.val << 1) | 1,
        };
    }
    try bw.record(3, buf[0 .. ops.len + 1]);
}

fn emitMdNamed(bw: *bc.Writer, name: []const u8, md_id: u32) !void {
    // METADATA_NAME (code 4): name chars
    var nops: [128]u32 = undefined;

    for (name, 0..) |c, i| nops[i] = c;
    try bw.record(4, nops[0..name.len]);
    // METADATA_NAMED_NODE (code 5): metadata ID
    try bw.record(5, &.{md_id});
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;
const gpu_ir = @import("gpu_ir.zig");
const gpu_ir = @import("gpu_ir.zig");

/// Generate HLSL directly from GPU AST (legacy path)
pub fn generateHlsl(allocator: Allocator, module: *const gpu_ir.GpuModule) ![]const u8 {
    var buf = std.ArrayList(u8).init(allocator);
    const w = buf.writer();

for (module.kernels.items) |kernel| {
    for (kernel.resources.items) |res| {
        try emitResourceDecl(w, &res);
    }
    try w.writeAll("\n");

    if (kernel.cbuffer_members.items.len > 0) {
        try emitCbufferDecl(w, kernel.cbuffer_members.items);
        try w.writeAll("\n");
    }

for (kernel.entries.items) |entry| {
    try w.print("[numthreads({}, {}, {})]\n", .{ entry.numthreads.x, entry.numthreads.y, entry.numthreads.z });
    try w.print("void {s}(uint3 __tid : SV_DispatchThreadID)", .{entry.name});
    try w.writeAll("{\n");
    try w.print("    uint {s} = __tid.x;\n", .{entry.x_param});
    try w.print("    uint {s} = __tid.y;\n", .{entry.y_param});
    for (entry.body_lines.items) |line| {
        try w.print("    {s}\n", .{ line });
    }

            try w.writeAll("}\n");
        }
    }

    return buf.toOwnedSlice();
}

/// Generate HLSL from GPU IR (Phase 4 pipeline)
pub fn generateHlslFromIr(allocator: Allocator, ir: *const gpu_ir.IrModule) ![]const u8 {
    var buf = std.ArrayList(u8).init(allocator);

const w = buf.writer();

try w.writeAll("#include \"/Engine/Public/Platform.ush\"\n");
try w.writeAll("\n");

for (ir.resources.items) |res| {
    try emitIrResourceDecl(w, &res);
}
try w.writeAll("\n");

if (ir.cbuffer_members.items.len > 0) {
    try emitIrCbuffer(w, ir.cbuffer_members.items);
    try w.writeAll("\n");
}

var declared_names = std.StringHashMap(void).init(allocator);
defer {
    var rit = declared_names.keyIterator();
    while (rit.next()) |k| allocator.free(k.*);
    declared_names.deinit();

}
for (ir.resources.items) |res| {
    const name = try allocator.dupe(u8, res.name);
    try declared_names.put(name, {});
}
for (ir.cbuffer_members.items) |mem| {
    if (!declared_names.contains(mem.name)) {
        const name = try allocator.dupe(u8, mem.name);
        try declared_names.put(name, {});
    }

}

for (ir.functions.items) |func| {
    for (func.globals_lines.items) |line| {
        try w.print("{s}\n", .{line});
    }

    try w.print("[numthreads({}, {}, {})]\n", .{ func.numthreads.x, func.numthreads.y, func.numthreads.z });
    const entry_name = try std.fmt.allocPrint(allocator, "{s}Main", .{func.kernel_name});
    try w.print("void {s}(uint3 __tid : SV_DispatchThreadID)", .{entry_name});

try w.writeAll("{\n");
try w.print("    uint {s} = __tid.x;\n", .{func.x_param});
try w.print("    uint {s} = __tid.y;\n", .{func.y_param});

for (func.locals.items) |local| {
    const lt = typeRefToHlslType(local.type_ref);
    try w.print("    {s} {s}", .{ lt, local.name });
    for (local.array_dims) |dim| {
        try w.print("[{d}]", .{dim});
    }

    try w.writeAll(";\n");
    const name = try allocator.dupe(u8, local.name);
    try declared_names.put(name, {});
}

if (func.passthrough_body.items.len > 0) {
    for (func.passthrough_body.items) |line| {
        try w.print("    {s}\n", .{ line });
    }
} else {

            try emitIrFunctionBody(w, allocator, &func, &declared_names);
        }

        try w.writeAll("}\n");
    }

    return buf.toOwnedSlice();
}

const ForLoopInfo = struct {

    header_idx: usize,
    body_idx: usize,
    continue_idx: usize,
    exit_idx: usize,
};

fn scanForLoops(func: *const gpu_ir.IrFunction, allocator: Allocator) !std.AutoHashMap(usize, ForLoopInfo) {
    var loops = std.AutoHashMap(usize, ForLoopInfo).init(allocator);
    for (func.blocks.items, 0..) |*block, idx| {
        if (!std.mem.eql(u8, block.label, "for.header")) continue;

if (block.instrs.items.len == 0) continue;
const last = block.instrs.getLast();
if (last.op != .branch) continue;
const cb = last.data.cond_branch;
const body_idx = cb.then_block;
const exit_idx = cb.else_block;
var continue_idx: ?usize = null;
for (func.blocks.items, 0..) |*other, oidx| {
    if (other.instrs.items.len == 0) continue;
    const last2 = other.instrs.getLast();

            if (last2.op == .ret and last2.data == .block_target and last2.data.block_target == idx) {
                continue_idx = oidx;
            }
        }
        if (continue_idx) |ci| {
            try loops.put(idx, ForLoopInfo{ .header_idx = idx, .body_idx = body_idx, .continue_idx = ci, .exit_idx = exit_idx });
        }
    }
    return loops;
}

fn emitInst(w: anytype, func: *const gpu_ir.IrFunction, var_names: *std.AutoHashMap(gpu_ir.ValueId, []const u8), resource_names: *const std.StringHashMap(void), inst: *const gpu_ir.IrInst) !void {
    const name_owned = var_names.get(inst.result).?;
    const t = typeRefToHlslType(inst.ty);
    switch (inst.op) {
        .phi, .branch, .ret, .loop => return,
        .@"const" => {
            try w.print("    {s}", .{name_owned});
            switch (inst.ty) {
                .f32, .vec2f, .vec3f, .vec4f, .f16 => try w.print(" = {d}", .{inst.data.float_val}),

        else => try w.print(" = {d}", .{inst.data.int_val}),
    }
},
.load => {
    if (resource_names.contains(inst.data.string) or isArrayLocal(func.locals, inst.data.string)) return;
    try w.print("    {s} = {s}", .{ name_owned, inst.data.string });
},
.store => {
    const base = if (inst.data == .string and inst.data.string.len > 0) inst.data.string else var_names.get(inst.operands[0]).?;
    try w.print("    {s}", .{base});

    for (inst.operands[1..inst.operands.len - 1]) |idx_op| try w.print("[{s}]", .{var_names.get(idx_op).?});
    try w.writeAll(" = ");
    try w.writeAll(var_names.get(inst.operands[inst.operands.len - 1]).?);
},
.add => try w.print("    {s} = {s} + {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.sub => try w.print("    {s} = {s} - {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.mul => try w.print("    {s} = {s} * {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.div => try w.print("    {s} = {s} / {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.mod => try w.print("    {s} = {s} % {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.call => {

if (std.mem.eql(u8, inst.data.call_info.callee, "@array_get")) {
    try w.print("    {s} = {s}[{s}]", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? });
} else if (inst.ty == .void) {
    if (isIntrinsicMethod(inst.data.call_info.callee) and inst.data.call_info.args.len >= 1) {
        try w.print("    {s}.{s}(", .{ var_names.get(inst.data.call_info.args[0]).?, inst.data.call_info.callee });
        for (inst.data.call_info.args[1..], 0..) |arg, i| {
            if (i > 0) try w.writeAll(", ");
            try w.writeAll(var_names.get(arg).?);
        }
    } else {

        try w.print("    {s}(", .{inst.data.call_info.callee});
        for (inst.data.call_info.args, 0..) |arg, i| {
            if (i > 0) try w.writeAll(", ");
            try w.writeAll(var_names.get(arg).?);
        }
    }
    try w.writeAll(")");
} else {
    if (isIntrinsicMethod(inst.data.call_info.callee) and inst.data.call_info.args.len >= 1) {
        try w.print("    {s} = {s}.{s}(", .{ name_owned, var_names.get(inst.data.call_info.args[0]).?, inst.data.call_info.callee });

    for (inst.data.call_info.args[1..], 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg).?);
    }
} else {
    try w.print("    {s} = {s}(", .{ name_owned, inst.data.call_info.callee });
    for (inst.data.call_info.args, 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg).?);
    }

        }
        try w.writeAll(")");
    }
},
.extract => {
    const swz = "xyzw"[inst.data.extract_info.index];
    try w.print("    {s} = {s}.{c}", .{ name_owned, var_names.get(inst.operands[0]).?, swz });
},
.composite => {
    try w.print("    {s} = {s}(", .{ name_owned, t });

    for (inst.operands, 0..) |op, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(op).?);
    }
    try w.writeAll(")");
},
.max => try w.print("    {s} = max({s}, {s})", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.min => try w.print("    {s} = min({s}, {s})", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.abs => try w.print("    {s} = abs({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.floor => try w.print("    {s} = floor({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),

.wave_get_lane_index => try w.print("    {s} = WaveGetLaneIndex()", .{name_owned}),
.wave_is_first_lane => try w.print("    {s} = WaveIsFirstLane()", .{name_owned}),
.wave_active_all_equal => try w.print("    {s} = WaveActiveAllEqual({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.quad_read_across_x => try w.print("    {s} = QuadReadAcrossX({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.quad_read_across_y => try w.print("    {s} = QuadReadAcrossY({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.select => try w.print("    {s} = {s} ? {s} : {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).?, var_names.get(inst.operands[2]).? }),
.cast => {
    const to_type = typeRefToHlslType(inst.ty);
    try w.print("    {s} = ({s}){s}", .{ name_owned, to_type, var_names.get(inst.operands[0]).? });
},

        .entry_point, .sample, .atomic, .barrier => {
            try w.print("    {s} = 0 /* unhandled op {s} */", .{ name_owned, @tagName(inst.op) });
        },
    }
    try w.writeAll(";\n");
}

fn emitForLoop(w: anytype, allocator: Allocator, func: *const gpu_ir.IrFunction, var_names: *std.AutoHashMap(gpu_ir.ValueId, []const u8), resource_names: *const std.StringHashMap(void), visited: *std.AutoHashMap(usize, void), for_loops: *const std.AutoHashMap(usize, ForLoopInfo), loop: ForLoopInfo) !void {
    _ = for_loops;
    const header = &func.blocks.items[loop.header_idx];

var phi_incrs = std.ArrayList(struct { phi_val: gpu_ir.ValueId, incr_val: gpu_ir.ValueId }).init(allocator);
defer phi_incrs.deinit();
for (header.instrs.items) |*inst| {
    if (inst.op == .phi and inst.operands.len >= 2) {
        const name = var_names.get(inst.result).?;
        const init_name = var_names.get(inst.operands[0]).?;
        try w.print("    {s} = {s};\n", .{ name, init_name });
        try phi_incrs.append(.{ .phi_val = inst.result, .incr_val = inst.operands[1] });
    }
}

var cond_name: ?[]const u8 = null;
try w.writeAll("    while (true) {\n");
for (header.instrs.items) |*inst| {
    if (inst.op == .phi) {
    } else if (inst.op == .branch) {
        if (inst.operands.len > 0) {
            cond_name = var_names.get(inst.operands[0]).?;
        }
    } else {
        try emitInst(w, func, var_names, resource_names, inst);

    }
}
if (cond_name) |cn| try w.print("        if (!({s})) break;\n", .{cn});
try visited.put(loop.body_idx, {});
try visited.put(loop.continue_idx, {});
try visited.put(loop.header_idx, {});
const body_block = &func.blocks.items[loop.body_idx];
for (body_block.instrs.items) |*inst| try emitInst(w, func, var_names, resource_names, inst);
const cont_block = &func.blocks.items[loop.continue_idx];
for (cont_block.instrs.items) |*inst| try emitInst(w, func, var_names, resource_names, inst);

for (phi_incrs.items) |pv| {
    const name = var_names.get(pv.phi_val).?;
    const incr_name = var_names.get(pv.incr_val).?;
    try w.print("        {s} = {s};\n", .{ name, incr_name });
}
try w.writeAll("    }\n");
if (!visited.contains(loop.exit_idx)) {
    try visited.put(loop.exit_idx, {});
    const exit_block = &func.blocks.items[loop.exit_idx];
    for (exit_block.instrs.items) |*inst| try emitInst(w, func, var_names, resource_names, inst);

    }
}

fn isArrayLocal(locals: std.ArrayList(gpu_ir.LocalDecl), name: []const u8) bool {
    for (locals.items) |local| {
        if (local.array_dims.len > 0 and std.mem.eql(u8, local.name, name)) return true;
    }
    return false;
}

fn emitIrFunctionBody(w: anytype, allocator: Allocator, func: *const gpu_ir.IrFunction, resource_names: *const std.StringHashMap(void)) !void {
    var var_names = std.AutoHashMap(gpu_ir.ValueId, []const u8).init(allocator);
    defer var_names.deinit();

    var next_temp: u32 = 0;

    for (func.blocks.items) |*block| {
        for (block.instrs.items) |*inst| {
            var name_buf: [16]u8 = undefined;
            if (inst.op == .load and (resource_names.contains(inst.data.string) or isArrayLocal(func.locals, inst.data.string))) {

            try var_names.put(inst.result, try allocator.dupe(u8, inst.data.string));
        } else {
            const name = try std.fmt.bufPrint(&name_buf, "_t{d}", .{next_temp});
            const name_owned = try allocator.dupe(u8, name);
            next_temp += 1;
            try var_names.put(inst.result, name_owned);
        }
    }
}

for (func.blocks.items) |*block| {
    for (block.instrs.items) |*inst| {
        if (inst.op == .branch or inst.op == .ret) continue;
        if (inst.op == .load and (resource_names.contains(inst.data.string) or isArrayLocal(func.locals, inst.data.string))) continue;
        const name_owned = var_names.get(inst.result).?;
        const t = typeRefToHlslType(inst.ty);
        try w.print("    {s} {s};\n", .{ t, name_owned });
    }
}

var for_loops = try scanForLoops(func, allocator);
defer {
    var flit = for_loops.keyIterator();
    while (flit.next()) |k| allocator.destroy(k);
    for_loops.deinit();
}

var visited = std.AutoHashMap(usize, void).init(allocator);
defer visited.deinit();

try emitBlock(w, allocator, func, &var_names, resource_names, &visited, &for_loops, 0, null);

for (func.blocks.items, 0..) |_, idx| {
    if (!visited.contains(idx)) {
        try emitBlock(w, allocator, func, &var_names, resource_names, &visited, &for_loops, idx, null);
    }
}

var it = var_names.iterator();
while (it.next()) |entry| {

        allocator.free(entry.value_ptr.*);
    }
}

fn emitBlock(w: anytype, allocator: Allocator, func: *const gpu_ir.IrFunction, var_names: *std.AutoHashMap(gpu_ir.ValueId, []const u8), resource_names: *const std.StringHashMap(void), visited: *std.AutoHashMap(usize, void), for_loops: *const std.AutoHashMap(usize, ForLoopInfo), block_idx: usize, cond_phi: ?gpu_ir.ValueId) !void {
    if (for_loops.contains(block_idx)) {
        return emitForLoop(w, allocator, func, var_names, resource_names, visited, for_loops, for_loops.get(block_idx).?);
    }
    if (visited.contains(block_idx)) return;
    try visited.put(block_idx, {});

const block = &func.blocks.items[block_idx];

for (block.instrs.items) |*inst| {
    var emit_semicolon = true;
    const name_owned = var_names.get(inst.result).?;
    const t = typeRefToHlslType(inst.ty);

    switch (inst.op) {
        .phi => {

    if (cond_phi) |cond| {
        const cond_name = var_names.get(cond).?;
        if (inst.operands.len >= 2) {
            const v0 = var_names.get(inst.operands[0]).?;
            const v1 = var_names.get(inst.operands[1]).?;
            try w.print("    {s} = {s} ? {s} : {s};\n", .{ name_owned, cond_name, v0, v1 });
        }
    }
    emit_semicolon = false;
},

.branch => {
    const cond_name = var_names.get(inst.operands[0]).?;
    const cb = inst.data.cond_branch;

    try w.print("    if ({s}) {{\n", .{cond_name});
    try emitBlock(w, allocator, func, var_names, resource_names, visited, for_loops, cb.then_block, null);
    try w.writeAll("    } else {\n");
    try emitBlock(w, allocator, func, var_names, resource_names, visited, for_loops, cb.else_block, null);
    try w.print("    }}\n", .{});

const then_blk = &func.blocks.items[cb.then_block];
const else_blk = &func.blocks.items[cb.else_block];

var then_merge: ?gpu_ir.BlockId = null;
if (then_blk.instrs.items.len > 0) {
    const last = then_blk.instrs.getLast();
    if (last.op == .ret and last.data == .block_target) then_merge = last.data.block_target;
}
var else_merge: ?gpu_ir.BlockId = null;
if (else_blk.instrs.items.len > 0) {

    const last = else_blk.instrs.getLast();
    if (last.op == .ret and last.data == .block_target) else_merge = last.data.block_target;
}

if (then_merge) |tm| {
    if (else_merge) |em| {
        if (tm == em) {
            try emitBlock(w, allocator, func, var_names, resource_names, visited, for_loops, tm, inst.operands[0]);
        }
    }

    }

    emit_semicolon = false;
    return;
},
.ret => {
    if (inst.data == .block_target) {
        emit_semicolon = false;
        return;
    } else {

        if (inst.operands.len > 0) {
            try w.print("    return {s}", .{var_names.get(inst.operands[0]).?});
        } else {
            try w.writeAll("    return");
        }
    }
},
.select => {
    try w.print("    {s} = {s} ? {s} : {s}", .{
        name_owned,

        var_names.get(inst.operands[0]).?,
        var_names.get(inst.operands[1]).?,
        var_names.get(inst.operands[2]).?,
    });
},
.cast => {
    const to_type = typeRefToHlslType(inst.ty);
    try w.print("    {s} = ({s}){s}", .{
        name_owned,
        to_type,

        var_names.get(inst.operands[0]).?,
    });
},
.@"const" => {
    try w.print("    {s}", .{name_owned});
    switch (inst.ty) {
        .f32, .vec2f, .vec3f, .vec4f, .f16 => {
            try w.print(" = {d}", .{inst.data.float_val});
        },
        else => {

            try w.print(" = {d}", .{inst.data.int_val});
        },
    }
},
.load => {
    if (resource_names.contains(inst.data.string) or isArrayLocal(func.locals, inst.data.string)) {
        try var_names.put(inst.result, try allocator.dupe(u8, inst.data.string));
        emit_semicolon = false;
    } else {
        try w.print("    {s} = {s}", .{ name_owned, inst.data.string });

    }
},
.store => {
    const base = if (inst.data == .string and inst.data.string.len > 0)
        inst.data.string
    else
        var_names.get(inst.operands[0]).?;
    try w.print("    {s}", .{base});
    for (inst.operands[1..inst.operands.len - 1]) |idx_op| {
        try w.print("[{s}]", .{var_names.get(idx_op).?});

    }
    try w.writeAll(" = ");
    try w.writeAll(var_names.get(inst.operands[inst.operands.len - 1]).?);
},
.add => try w.print("    {s} = {s} + {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.sub => try w.print("    {s} = {s} - {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.mul => try w.print("    {s} = {s} * {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.div => try w.print("    {s} = {s} / {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.mod => try w.print("    {s} = {s} % {s}", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.call => {

if (std.mem.eql(u8, inst.data.call_info.callee, "@array_get")) {
    try w.print("    {s} = {s}[{s}]", .{
        name_owned,
        var_names.get(inst.operands[0]).?,
        var_names.get(inst.operands[1]).?,
    });
} else if (inst.ty == .void) {
    if (isIntrinsicMethod(inst.data.call_info.callee) and inst.data.call_info.args.len >= 1) {
        try w.print("    {s}.{s}(", .{
            var_names.get(inst.data.call_info.args[0]).?,

        inst.data.call_info.callee,
    });
    for (inst.data.call_info.args[1..], 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg).?);
    }
} else {
    try w.print("    {s}(", .{inst.data.call_info.callee});
    for (inst.data.call_info.args, 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");

            try w.writeAll(var_names.get(arg).?);
        }
    }
    try w.writeAll(")");
} else {
    if (isIntrinsicMethod(inst.data.call_info.callee) and inst.data.call_info.args.len >= 1) {
        try w.print("    {s} = {s}.{s}(", .{
            name_owned,
            var_names.get(inst.data.call_info.args[0]).?,
            inst.data.call_info.callee,

    });
    for (inst.data.call_info.args[1..], 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg).?);
    }
} else {
    try w.print("    {s} = {s}(", .{ name_owned, inst.data.call_info.callee });
    for (inst.data.call_info.args, 0..) |arg, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg).?);

            }
        }
        try w.writeAll(")");
    }
},
.extract => {
    const idx = inst.data.extract_info.index;
    const swz = "xyzw"[idx];
    try w.print("    {s} = {s}.{c}", .{ name_owned, var_names.get(inst.operands[0]).?, swz });
},

.composite => {
    try w.print("    {s} = {s}(", .{ name_owned, t });
    for (inst.operands, 0..) |op, i| {
        if (i > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(op).?);
    }
    try w.writeAll(")");
},
.max => try w.print("    {s} = max({s}, {s})", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),
.min => try w.print("    {s} = min({s}, {s})", .{ name_owned, var_names.get(inst.operands[0]).?, var_names.get(inst.operands[1]).? }),

.not => try w.print("    {s} = !({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.loop => {
    emit_semicolon = false;
},
.wave_read_lane_first => try w.print("    {s} = WaveReadLaneFirst({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.wave_get_lane_index => try w.print("    {s} = WaveGetLaneIndex()", .{name_owned}),
.wave_is_first_lane => try w.print("    {s} = WaveIsFirstLane()", .{name_owned}),
.wave_active_all_equal => try w.print("    {s} = WaveActiveAllEqual({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.quad_read_across_x => try w.print("    {s} = QuadReadAcrossX({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),
.quad_read_across_y => try w.print("    {s} = QuadReadAcrossY({s})", .{ name_owned, var_names.get(inst.operands[0]).? }),

            .entry_point, .sample, .atomic, .barrier => {
                try w.print("    {s} = 0 /* unhandled op {s} */", .{ name_owned, @tagName(inst.op) });
            },
        }
        if (emit_semicolon) try w.writeAll(";\n");
    }
}

fn isIntrinsicMethod(name: []const u8) bool {
    return std.mem.eql(u8, name, "SampleLevel") or

fn emitIrResourceDecl(w: anytype, res: *const gpu_ir.IrResourceDecl) !void {
    const type_s = switch (res.type_ref) {
        .texture2d => "Texture2D",
        .rw_texture2d => "RWTexture2D",
        .sampler => "SamplerState",
        else => "Texture2D",
    };
    const fmt_s = typeRefToHlslType(res.format);
    if (res.type_ref == .sampler) {
        try w.print("{s} {s};\n", .{ type_s, res.name });

    } else {
        try w.print("{s}<{s}> {s};\n", .{ type_s, fmt_s, res.name });
    }
}

fn typeRefToHlslType(tr: gpu_ir.TypeRef) []const u8 {
    return switch (tr) {
        .f32 => "float",
        .i32 => "int",
        .u32 => "uint",

        .mat4x4f => "float4x4",
        else => "float",
    };
}

fn emitIrCbuffer(w: anytype, members: []const gpu_ir.IrCbufferMember) !void {
    try w.print("cbuffer TSS_Constants : register(b{}) {{\n", .{ members[0].slot });
    for (members) |mem| {
        try w.print("    {s} {s};\n", .{ typeRefToHlslType(mem.type_ref), mem.name });
    }

    try w.writeAll("};\n");
}

