const std = @import("std");
const bir = @import("../../bir.zig");

pub const AliasResult = enum {
    NoAlias,
    MayAlias,
    MustAlias,
};

const PtrKind = enum { resource, alloca, unknown };

pub fn query(func: *const bir.Function, a: bir.ValueId, b: bir.ValueId) AliasResult {
    if (a == b) return .MustAlias;
    const ka = resolvePtrKind(func, a);
    const kb = resolvePtrKind(func, b);
    if (ka == .unknown or kb == .unknown) return .MayAlias;
    if (ka == .resource and kb == .resource) return .NoAlias;
    if (ka == .alloca and kb == .alloca) return .NoAlias;
    if ((ka == .resource and kb == .alloca) or (ka == .alloca and kb == .resource)) return .NoAlias;
    return .MayAlias;

}

fn resolvePtrKind(func: *const bir.Function, val: bir.ValueId) PtrKind {
    if (val == bir.NO_VALUE) return .unknown;
    const vi = &func.value_info.items[val - 1];
    if (vi.def.block == bir.INVALID_ID) return .unknown;
    const block = &func.blocks.items[vi.def.block];
    if (vi.def.idx >= block.instrs.items.len) return .unknown;
    const inst = &block.instrs.items[vi.def.idx];
    return switch (inst.op) {

        .resource => .resource,
        .alloca => .alloca,
        else => .unknown,
    };
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const NO_VALUE = bir.NO_VALUE;

pub const Edge = struct { from: bir.BlockId, to: bir.BlockId };

/// Lightweight CFG wrapper: preds/succs live in BasicBlock directly.
/// buildCFG populates block.preds and block.succs + computes RPO.
/// Consumers access edges via blocks.items[id].preds / .succs.

pub const CFG = struct {
    allocator: Allocator,
    entry: bir.BlockId,
    rpo: std.ArrayList(bir.BlockId),

    pub fn deinit(self: *CFG) void {
        self.rpo.deinit();
    }
};

pub fn buildCFG(allocator: Allocator, func: *bir.Function) !CFG {
    // Clear and rebuild preds/succs
    for (func.blocks.items) |*block| {
        block.preds.clearRetainingCapacity();
        block.succs.clearRetainingCapacity();
    }

    for (func.blocks.items, 0..) |*block, bi| {
        const bid = @as(bir.BlockId, @intCast(bi));
        if (block.instrs.items.len == 0) continue;

const terminator = &block.instrs.items[block.instrs.items.len - 1];
switch (terminator.op) {
    .br => {
        const target = terminator.data.block_target;
        if (target < func.blocks.items.len) {
            try block.succs.append(target);
            try func.blocks.items[target].preds.append(bid);
        }
    },

.cond_br => {
    const then_b = terminator.data.cond_branch.then_block;
    const else_b = terminator.data.cond_branch.else_block;
    if (then_b < func.blocks.items.len) {
        try block.succs.append(then_b);
        try func.blocks.items[then_b].preds.append(bid);
    }
    if (else_b < func.blocks.items.len) {
        try block.succs.append(else_b);
        try func.blocks.items[else_b].preds.append(bid);

            }
        },
        .ret, .unreachable_op => {},
        else => {},
    }
}

var cfg = CFG{
    .allocator = allocator,
    .entry = 0,

        .rpo = std.ArrayList(bir.BlockId).init(allocator),
    };

    try computeRPO(&cfg, func);
    return cfg;
}

fn computeRPO(cfg: *CFG, func: *bir.Function) !void {
    cfg.rpo.clearRetainingCapacity();
    var visited = try std.DynamicBitSet.initEmpty(cfg.allocator, func.blocks.items.len);

defer visited.deinit();

try dfsPostorder(cfg, func, cfg.entry, &visited);

var i: usize = 0;
if (cfg.rpo.items.len > 0) {
    var j: usize = cfg.rpo.items.len - 1;
    while (i < j) {
        const tmp = cfg.rpo.items[i];
        cfg.rpo.items[i] = cfg.rpo.items[j];

            cfg.rpo.items[j] = tmp;
            i += 1;
            j -= 1;
        }
    }
}

fn dfsPostorder(cfg: *CFG, func: *bir.Function, bid: bir.BlockId, visited: *std.DynamicBitSet) !void {
    if (bid >= func.blocks.items.len) return;
    if (visited.isSet(bid)) return;

    visited.set(bid);

    const succs = func.blocks.items[bid].succs.items;
    for (succs) |succ| {
        try dfsPostorder(cfg, func, succ, visited);
    }

    try cfg.rpo.append(bid);
}

pub fn dumpCFG(cfg: *const CFG, func: *const bir.Function, writer: anytype) !void {
    try writer.writeAll("; CFG\n");
    for (func.blocks.items, 0..) |*block, bi| {
        const bid = @as(bir.BlockId, @intCast(bi));
        try writer.print("  block_{d}: preds=[", .{bid});
        for (block.preds.items, 0..) |pred, pi| {
            if (pi > 0) try writer.writeAll(", ");
            try writer.print("{d}", .{pred});
        }
        try writer.writeAll("] succs=[");

    for (block.succs.items, 0..) |succ, si| {
        if (si > 0) try writer.writeAll(", ");
        try writer.print("{d}", .{succ});
    }
    try writer.writeAll("]\n");
}
try writer.print("; RPO: ", .{});
for (cfg.rpo.items, 0..) |bid, i| {
    if (i > 0) try writer.writeAll(" -> ");
    try writer.print("{d}", .{bid});

    }
    try writer.writeAll("\n");
}

pub fn isBackEdge(cfg: *const CFG, _: *const bir.Function, from: bir.BlockId, to: bir.BlockId) bool {
    const from_rpo = getRPOPos(cfg, from) orelse return false;
    const to_rpo = getRPOPos(cfg, to) orelse return false;
    return from_rpo >= to_rpo;
}

fn getRPOPos(cfg: *const CFG, bid: bir.BlockId) ?usize {
    for (cfg.rpo.items, 0..) |b, i| {
        if (b == bid) return i;
    }
    return null;
}

// ─── Validation ───

pub const ValidationError = error{

    EntryHasPredecessor,
    MissingTerminator,
    ExtraTerminator,
    InvalidBranchTarget,
    UnreachableBlock,
    BlockMissingInCFG,
};

pub fn validate(cfg: *const CFG, func: *const bir.Function) ValidationError!void {
    if (cfg.entry >= func.blocks.items.len) return error.BlockMissingInCFG;

if (func.blocks.items[cfg.entry].preds.items.len > 0) return error.EntryHasPredecessor;

for (func.blocks.items, 0..) |*block, bi| {
    const bid = @as(bir.BlockId, @intCast(bi));
    _ = bid;

    const n = block.instrs.items.len;
    if (n == 0) continue;

    var term_count: u32 = 0;

for (block.instrs.items) |inst| {
    if (isTerminator(inst.op)) {
        term_count += 1;
        if (term_count > 1) return error.ExtraTerminator;

        switch (inst.op) {
            .br => {
                const target = inst.data.block_target;
                if (target >= func.blocks.items.len) return error.InvalidBranchTarget;
            },

            .cond_br => {
                const cb = inst.data.cond_branch;
                if (cb.then_block >= func.blocks.items.len) return error.InvalidBranchTarget;
                if (cb.else_block >= func.blocks.items.len) return error.InvalidBranchTarget;
            },
            else => {},
        }
    }
}

        if (n > 0) {
            const last = &block.instrs.items[n - 1];
            if (!isTerminator(last.op)) return error.MissingTerminator;
        }
    }
}

fn isTerminator(op: bir.Op) bool {
    return switch (op) {
        .br, .cond_br, .ret, .unreachable_op => true,

        else => false,
    };
}

// ─── CFG Mutation Helpers ───

pub fn getExitBlocks(cfg: *const CFG, func: *const bir.Function) std.ArrayList(bir.BlockId) {
    var exits = std.ArrayList(bir.BlockId).init(cfg.allocator);
    for (func.blocks.items, 0..) |*block, bi| {
        if (block.instrs.items.len == 0) continue;

        const last = block.instrs.items[block.instrs.items.len - 1];
        if (last.op == .ret or last.op == .unreachable_op) {
            exits.append(@as(bir.BlockId, @intCast(bi))) catch {};
        }
    }
    return exits;
}

pub fn getBlockSuccessors(func: *const bir.Function, bid: bir.BlockId) []const bir.BlockId {
    return func.blocks.items[bid].succs.items;

}

pub fn replaceSuccessor(_: *CFG, func: *bir.Function, from: bir.BlockId, old_succ: bir.BlockId, new_succ: bir.BlockId) void {
    const from_block = &func.blocks.items[from];
    for (from_block.succs.items, 0..) |s, i| {
        if (s == old_succ) {
            from_block.succs.items[i] = new_succ;
            break;
        }
    }

    const new_block = &func.blocks.items[new_succ];
    for (new_block.preds.items, 0..) |p, i| {
        if (p == from) {
            _ = new_block.preds.swapRemove(i);
            break;
        }
    }
    new_block.preds.append(from) catch {};
}

pub fn removeBlockFromCFG(_: *CFG, func: *bir.Function, bid: bir.BlockId) void {
    const block = &func.blocks.items[bid];
    for (block.preds.items) |pred| {
        const pred_block = &func.blocks.items[pred];
        for (pred_block.succs.items, 0..) |s, i| {
            if (s == bid) {
                _ = pred_block.succs.swapRemove(i);
                break;
            }
        }

}
for (block.succs.items) |succ| {
    const succ_block = &func.blocks.items[succ];
    for (succ_block.preds.items, 0..) |p, i| {
        if (p == bid) {
            _ = succ_block.preds.swapRemove(i);
            break;
        }
    }
}

    block.preds.clearRetainingCapacity();
    block.succs.clearRetainingCapacity();
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../cfg/cfg.zig");
const INVALID_ID = bir.INVALID_ID;
const BlockId = bir.BlockId;
const Function = bir.Function;

pub const DominatorTree = struct {
    allocator: ?std.mem.Allocator,

idom: []const BlockId,
children: []const []const BlockId,
depth: []const u32,
_child_data: []const BlockId,

pub fn deinit(self: *DominatorTree) void {
    const aa = self.allocator orelse return;
    aa.free(self.idom);
    aa.free(self.children);
    aa.free(self.depth);

    aa.free(self._child_data);
}

pub fn dominates(self: *const DominatorTree, a: BlockId, b: BlockId) bool {
    if (a == b) return true;
    var cur = b;
    while (cur != INVALID_ID) {
        if (cur == a) return true;
        cur = self.idom[cur];
    }

    return false;
}

pub fn strictlyDominates(self: *const DominatorTree, a: BlockId, b: BlockId) bool {
    if (a == b) return false;
    var cur = self.idom[b];
    while (cur != INVALID_ID) {
        if (cur == a) return true;
        cur = self.idom[cur];
    }

    return false;
}

pub fn getImmediateDominator(self: *const DominatorTree, block: BlockId) BlockId {
    return self.idom[block];
}

pub fn getDepth(self: *const DominatorTree, block: BlockId) u32 {
    return self.depth[block];
}

};

pub const DominanceFrontier = struct {
    allocator: ?std.mem.Allocator,
    offsets: []const u32,
    nodes: []const BlockId,

    pub fn deinit(self: *DominanceFrontier) void {
        const aa = self.allocator orelse return;
        aa.free(self.offsets);

    aa.free(self.nodes);
}

pub fn get(self: *const DominanceFrontier, block: BlockId) []const BlockId {
    const start = self.offsets[block];
    const end = self.offsets[block + 1];
    return self.nodes[start..end];
}

pub fn contains(self: *const DominanceFrontier, block: BlockId, target: BlockId) bool {

        for (self.get(block)) |dfb| if (dfb == target) return true;
        return false;
    }
};

fn compress(anc: []BlockId, best: []BlockId, semi: []u32, dfs_order: []u32, v: BlockId) BlockId {
    if (anc[v] == INVALID_ID) return v;
    if (anc[anc[v]] != INVALID_ID) {
        const root = compress(anc, best, semi, dfs_order, anc[v]);
        if (dfs_order[semi[best[anc[v]]]] < dfs_order[semi[best[v]]]) {

            best[v] = best[anc[v]];
        }
        anc[v] = root;
    }
    return anc[v];
}

pub fn buildDominators(allocator: Allocator, cfg: *const bir_cfg.CFG, func: *const Function) !DominatorTree {
    const n = func.blocks.items.len;
    if (n == 0) {

    return DominatorTree{ .allocator = allocator, .idom = &.{}, .children = &.{}, .depth = &.{}, ._child_data = &.{} };
}

const Entry = cfg.entry;
const parent = try allocator.alloc(BlockId, n);
const semi = try allocator.alloc(u32, n);
const idom = try allocator.alloc(BlockId, n);
const vertex = try allocator.alloc(BlockId, n);
const ancestor = try allocator.alloc(BlockId, n);
const best = try allocator.alloc(BlockId, n);

const bucket = try allocator.alloc(std.ArrayList(BlockId), n);
const preds = try allocator.alloc(std.ArrayList(BlockId), n);

for (0..n) |i| {
    idom[i] = INVALID_ID;
    semi[i] = @as(u32, @intCast(i));
    parent[i] = INVALID_ID;
    ancestor[i] = INVALID_ID;
    best[i] = @as(BlockId, @intCast(i));
    vertex[i] = INVALID_ID;

    bucket[i] = std.ArrayList(BlockId).init(allocator);
    preds[i] = std.ArrayList(BlockId).init(allocator);
}

for (0..n) |i| {
    const bid = @as(BlockId, @intCast(i));
    for (func.blocks.items[bid].succs.items) |succ| {
        try preds[succ].append(bid);
    }
}

var stack = std.ArrayList(BlockId).init(allocator);
defer stack.deinit();
try stack.append(Entry);

const vis = try allocator.alloc(bool, n);
defer allocator.free(vis);
@memset(vis, false);
vis[Entry] = true;

var df_count: u32 = 0;
while (stack.items.len > 0) {
    const v = stack.pop().?;
    vertex[df_count] = v;
    df_count += 1;
    for (func.blocks.items[v].succs.items) |succ| {
        if (!vis[succ]) {
            vis[succ] = true;
            parent[succ] = v;
            try stack.append(succ);

        }
    }
}

const dfs_order = try allocator.alloc(u32, n);
defer allocator.free(dfs_order);
for (0..df_count) |i| {
    dfs_order[vertex[i]] = @as(u32, @intCast(i));
}

{
    var i: u32 = df_count;
    while (i > 0) {
        i -= 1;
        const w = vertex[i];
        if (w == Entry) continue;

        for (preds[w].items) |v| {
            var u = v;
            if (dfs_order[u] == INVALID_ID) continue;

    if (dfs_order[u] > dfs_order[w]) {
        _ = compress(ancestor, best, semi, dfs_order, u);
        u = best[u];
    }
    if (dfs_order[semi[u]] < dfs_order[semi[w]]) {
        semi[w] = semi[u];
    }
}

try bucket[semi[w]].append(w);

const p = parent[w];
if (p != INVALID_ID) {
    ancestor[w] = p;
    for (bucket[p].items) |v| {
        _ = compress(ancestor, best, semi, dfs_order, v);
        if (semi[best[v]] == semi[v]) {
            idom[v] = p;
        } else {
            idom[v] = best[v];

                }
            }
            bucket[p].clearRetainingCapacity();
        }
    }
}

for (1..df_count) |idx| {
    const w = vertex[idx];
    if (w == Entry) continue;

    if (idom[w] != @as(BlockId, @intCast(semi[w]))) {
        idom[w] = idom[idom[w]];
    }
}
idom[Entry] = INVALID_ID;

for (0..n) |j| {
    bucket[j].deinit();
    preds[j].deinit();
}

allocator.free(bucket);
allocator.free(preds);
allocator.free(ancestor);
allocator.free(best);
allocator.free(semi);
allocator.free(vertex);
allocator.free(parent);

const child_count = try allocator.alloc(usize, n);
defer allocator.free(child_count);

@memset(child_count, 0);
for (idom) |p| {
    if (p != INVALID_ID) child_count[p] = child_count[p] + 1;
}

const write_pos = try allocator.alloc(usize, n);
var total: usize = 0;
for (0..n) |i| {
    write_pos[i] = total;
    total += child_count[i];

}

const flat = try allocator.alloc(BlockId, total);
for (idom, 0..) |p, bid| {
    if (p == INVALID_ID) continue;
    flat[write_pos[p]] = @as(BlockId, @intCast(bid));
    write_pos[p] += 1;
}

const children = try allocator.alloc([]const BlockId, n);

for (0..n) |i| {
    children[i] = flat[write_pos[i] - child_count[i] .. write_pos[i]];
}
allocator.free(write_pos);

const depth = try allocator.alloc(u32, n);
@memset(depth, 0);
for (0..n) |bid| {
    var cur = idom[bid];
    while (cur != INVALID_ID) {

            depth[bid] += 1;
            cur = idom[cur];
        }
    }

    return DominatorTree{ .allocator = allocator, .idom = idom, .children = children, .depth = depth, ._child_data = flat };
}

pub fn buildDominanceFrontiers(allocator: Allocator, cfg: *const bir_cfg.CFG, func: *const Function, dom_tree: *const DominatorTree) !DominanceFrontier {
    const n = func.blocks.items.len;

if (n == 0) return DominanceFrontier{ .allocator = allocator, .offsets = &.{}, .nodes = &.{} };

const lists = try allocator.alloc(std.ArrayList(BlockId), n);
for (0..n) |i| {
    lists[i] = std.ArrayList(BlockId).init(allocator);
}

for (0..n) |i| {
    const bid = @as(BlockId, @intCast(i));
    for (func.blocks.items[bid].succs.items) |succ| {

        if (!dom_tree.strictlyDominates(bid, succ)) {
            try lists[bid].append(succ);
        }
    }
}

var po = std.ArrayList(BlockId).init(allocator);
defer po.deinit();
const vis = try allocator.alloc(bool, n);
defer allocator.free(vis);

@memset(vis, false);
var stack = std.ArrayList(BlockId).init(allocator);
defer stack.deinit();
try stack.append(cfg.entry);
while (stack.items.len > 0) {
    const top = stack.pop().?;
    if (vis[top]) continue;
    vis[top] = true;
    try po.append(top);
    for (dom_tree.children[top]) |child| try stack.append(child);

}
for (0..po.items.len / 2) |k| {
    const a = po.items[k];
    const b = po.items[po.items.len - 1 - k];
    po.items[k] = b;
    po.items[po.items.len - 1 - k] = a;
}

for (po.items) |bid| {
    for (dom_tree.children[bid]) |child| {

        for (lists[child].items) |x| {
            if (!dom_tree.strictlyDominates(bid, x)) {
                try lists[bid].append(x);
            }
        }
    }
}

const offsets = try allocator.alloc(u32, n + 1);
offsets[0] = 0;

for (0..n) |i| {
    offsets[i + 1] = offsets[i] + @as(u32, @intCast(lists[i].items.len));
}
const nodes = try allocator.alloc(BlockId, offsets[n]);
for (0..n) |i| {
    @memcpy(nodes[offsets[i]..offsets[i + 1]], lists[i].items);
    lists[i].deinit();
}
allocator.free(lists);

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../cfg/cfg.zig");
const bir_dominators = @import("../dominator/dominator.zig");
const BlockId = bir.BlockId;
const Function = bir.Function;

pub const Loop = struct {
    header: BlockId,

    back_edges: []const bir_cfg.Edge,
    body: []const BlockId,
    depth: u32,
};

pub const LoopInfo = struct {
    loops: []const Loop,
    top_level: []const usize,
    block_map: []const ?usize,
    depth_map: []const u32,

pub fn contains(self: *const LoopInfo, block: BlockId, loop_idx: usize) bool {
    if (block >= self.block_map.len) return false;
    return self.block_map[block] == loop_idx;
}

pub fn getLoopDepth(self: *const LoopInfo, block: BlockId) u32 {
    if (block >= self.depth_map.len) return 0;
    return self.depth_map[block];
}

pub fn get(self: *const LoopInfo, idx: usize) *const Loop {
    return &self.loops[idx];
}

pub fn deinit(self: *const LoopInfo, allocator: Allocator) void {
    for (self.loops) |lp| {
        allocator.free(lp.back_edges);
        allocator.free(lp.body);
    }

        allocator.free(self.loops);
        allocator.free(self.top_level);
        allocator.free(self.block_map);
        allocator.free(self.depth_map);
    }
};

fn computeDepth(loops: []const Loop, header: BlockId) u32 {
    var depth: u32 = 1;
    for (loops) |other| {

    if (other.header == header) continue;
    for (other.body) |b| {
        if (b == header) {
            const d = computeDepth(loops, other.header) + 1;
            if (d > depth) depth = d;
            break;
        }
    }
}
return depth;

}

fn isNested(loops: []const Loop, header: BlockId) bool {
    for (loops) |other| {
        if (other.header == header) continue;
        for (other.body) |b| if (b == header) return true;
    }
    return false;
}

pub fn findLoops(allocator: Allocator, _: *const bir_cfg.CFG, func: *const Function, dom_tree: *const bir_dominators.DominatorTree) !LoopInfo {
    const n = func.blocks.items.len;
    if (n == 0) {
        return LoopInfo{
            .loops = &.{},
            .top_level = &.{},
            .block_map = &.{},
            .depth_map = &.{},
        };
    }

var raw_loops = std.ArrayList(Loop).init(allocator);
errdefer {
    for (raw_loops.items) |lp| {
        allocator.free(lp.back_edges);
        allocator.free(lp.body);
    }
    raw_loops.deinit();
}

for (0..n) |i| {
    const bid = @as(BlockId, @intCast(i));
    for (func.blocks.items[bid].succs.items) |succ| {
        if (succ >= n or succ == bid) continue;
        if (dom_tree.dominates(succ, bid)) {
            const header = succ;
            var body = std.ArrayList(BlockId).init(allocator);
            try body.append(header);
            const visited = try allocator.alloc(bool, n);
            defer allocator.free(visited);

@memset(visited, false);
visited[header] = true;
var stack = std.ArrayList(BlockId).init(allocator);
defer stack.deinit();
try stack.append(bid);
while (stack.items.len > 0) {
    const cur = stack.pop().?;
    if (visited[cur]) continue;
    visited[cur] = true;
    try body.append(cur);

    for (func.blocks.items[cur].preds.items) |pred| {
        if (!visited[pred]) try stack.append(pred);
    }
}
const body_sorted = try allocator.dupe(BlockId, body.items);
const be = try allocator.dupe(bir_cfg.Edge, &.{.{ .from = bid, .to = succ }});
try raw_loops.append(.{
    .header = header,
    .back_edges = be,
    .body = body_sorted,

                .depth = 1,
            });
        }
    }
}

for (raw_loops.items) |*lp| lp.depth = computeDepth(raw_loops.items, lp.header);

// Pre-allocate the arrays that LoopInfo will own.
// These may fail; raw_loops errdefer still covers loop bodies.

const block_map = try allocator.alloc(?usize, n);
errdefer allocator.free(block_map);
for (0..n) |j| block_map[j] = null;

const depth_map = try allocator.alloc(u32, n);
errdefer allocator.free(depth_map);
@memset(depth_map, 0);

for (raw_loops.items, 0..) |lp, idx| {
    for (lp.body) |b| {

        if (block_map[b] == null) block_map[b] = idx;
    }
}

for (raw_loops.items) |lp| {
    for (lp.body) |b| {
        if (lp.depth > depth_map[b]) depth_map[b] = lp.depth;
    }
}

var top_level = std.ArrayList(usize).init(allocator);
for (raw_loops.items, 0..) |lp, idx| {
    if (!isNested(raw_loops.items, lp.header)) try top_level.append(idx);
}

const top_level_slice = try top_level.toOwnedSlice();
// raw_loops.toOwnedSlice() is the LAST fallible call — after this,
// all memory is owned by the returned LoopInfo or is already freed.
const loops = try raw_loops.toOwnedSlice();

    return LoopInfo{
        .loops = loops,
        .top_level = top_level_slice,
        .block_map = block_map,
        .depth_map = depth_map,
    };
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;
const bir_cfg = @import("cfg/cfg.zig");
const bir_dominators = @import("dominator/dominator.zig");
const bir_loops = @import("loops/loops.zig");
const PreservedAnalyses = @import("../optimizer/pass_types.zig").PreservedAnalyses;
const AnalysisKind = @import("../optimizer/pass_types.zig").AnalysisKind;

const ir = @import("../core/module.zig");
const Module = ir.Module;

const FunctionId = @import("../core/value.zig").FunctionId;

/// Per-function cached analysis results.
const PerFunctionEntry = struct {
    allocator: Allocator,
    cfg: ?bir_cfg.CFG = null,
    dom: ?DominanceAnalysis = null,
    loop: ?LoopAnalysis = null,

    fn deinit(self: *PerFunctionEntry) void {

        if (self.cfg) |*c| c.deinit();
        if (self.dom) |*d| {
            d.tree.deinit();
            d.frontier.deinit();
        }
        if (self.loop) |*l| l.info.deinit(self.allocator);
    }
};

pub const DominanceAnalysis = struct {

    tree: bir_dominators.DominatorTree,
    frontier: bir_dominators.DominanceFrontier,
};

pub const LoopAnalysis = struct {
    info: bir_loops.LoopInfo,
};

pub const AnalysisManager = struct {
    gpa: Allocator,

module: *Module,
cache: std.AutoHashMap(FunctionId, *PerFunctionEntry),

pub fn init(allocator: Allocator, module: *Module) AnalysisManager {
    return AnalysisManager{
        .gpa = allocator,
        .module = module,
        .cache = std.AutoHashMap(FunctionId, *PerFunctionEntry).init(allocator),
    };
}

pub fn deinit(self: *AnalysisManager) void {
    var it = self.cache.valueIterator();
    while (it.next()) |entry| {
        entry.*.deinit();
        self.gpa.destroy(entry.*);
    }
    self.cache.deinit();
}

pub fn getAllocator(self: *const AnalysisManager) Allocator {
    return self.gpa;
}

fn getOrCreateEntry(self: *AnalysisManager, func_id: FunctionId) !*PerFunctionEntry {
    if (self.cache.get(func_id)) |entry| return entry;
    const alloc = self.gpa;
    const entry = try alloc.create(PerFunctionEntry);
    entry.* = PerFunctionEntry{ .allocator = alloc };
    try self.cache.put(func_id, entry);

    return entry;
}

/// Ensure CFG is built for the given function. Returns cached if available.
fn ensureCFG(self: *AnalysisManager, entry: *PerFunctionEntry, func_id: FunctionId) !*const bir_cfg.CFG {
    if (entry.cfg) |*c| return c;
    const func = self.module.getFunctionMut(func_id);
    entry.cfg = try bir_cfg.buildCFG(self.gpa, func);
    return &entry.cfg.?;
}

/// Ensure DominatorTree + DominanceFrontier for the given function.
fn ensureDom(self: *AnalysisManager, entry: *PerFunctionEntry, func_id: FunctionId) !*const DominanceAnalysis {
    if (entry.dom) |*d| return d;
    const cfg = try self.ensureCFG(entry, func_id);
    const func = self.module.getFunction(func_id);
    const tree = try bir_dominators.buildDominators(self.gpa, cfg, func);
    const frontier = try bir_dominators.buildDominanceFrontiers(self.gpa, cfg, func, &tree);
    entry.dom = DominanceAnalysis{ .tree = tree, .frontier = frontier };
    return &entry.dom.?;

}

/// Ensure LoopInfo for the given function.
fn ensureLoop(self: *AnalysisManager, entry: *PerFunctionEntry, func_id: FunctionId) !*const LoopAnalysis {
    if (entry.loop) |*l| return l;
    const dom = try self.ensureDom(entry, func_id);
    const cfg = try self.ensureCFG(entry, func_id);
    const func = self.module.getFunction(func_id);
    const info = try bir_loops.findLoops(self.gpa, cfg, func, &dom.tree);
    entry.loop = LoopAnalysis{ .info = info };

    return &entry.loop.?;
}

// ─── Public query API ───

pub fn getCFG(self: *AnalysisManager, func_id: FunctionId) !*const bir_cfg.CFG {
    const entry = try self.getOrCreateEntry(func_id);
    return self.ensureCFG(entry, func_id);
}

pub fn getDomTree(self: *AnalysisManager, func_id: FunctionId) !*const bir_dominators.DominatorTree {
    const entry = try self.getOrCreateEntry(func_id);
    const dom = try self.ensureDom(entry, func_id);
    return &dom.tree;
}

pub fn getDomFrontier(self: *AnalysisManager, func_id: FunctionId) !*const bir_dominators.DominanceFrontier {
    const entry = try self.getOrCreateEntry(func_id);
    const dom = try self.ensureDom(entry, func_id);
    return &dom.frontier;

}

pub fn getLoopInfo(self: *AnalysisManager, func_id: FunctionId) !*const bir_loops.LoopInfo {
    const entry = try self.getOrCreateEntry(func_id);
    const loop = try self.ensureLoop(entry, func_id);
    return &loop.info;
}

// ─── Invalidation ───

/// Invalidate all cached analyses for a single function.
pub fn invalidate(self: *AnalysisManager, func_id: FunctionId) void {
    if (self.cache.fetchRemove(func_id)) |kv| {
        kv.value.deinit();
        self.gpa.destroy(kv.value);
    }
}

/// Invalidate all cached analyses across all functions.
pub fn invalidateAll(self: *AnalysisManager) void {

    var it = self.cache.valueIterator();
    while (it.next()) |entry| {
        entry.*.deinit();
        self.gpa.destroy(entry.*);
    }
    self.cache.clearRetainingCapacity();
}

/// Selective invalidation based on PreservedAnalyses.
/// Respects analysis dependencies:

///   - invalidating .cfg invalidates .dominators and .loops
///   - invalidating .dominators invalidates .loops
///   - invalidating .loops does NOT invalidate .dominators or .cfg
pub fn invalidatePreserved(self: *AnalysisManager, preserved: PreservedAnalyses) void {
    const invalid_cfg = !preserved.isPreserved(.cfg);
    const invalid_dom = !preserved.isPreserved(.dominators);
    const invalid_loop = !preserved.isPreserved(.loops);

    if (!invalid_cfg and !invalid_dom and !invalid_loop) return;

var it = self.cache.valueIterator();
while (it.next()) |entry_ptr| {
    const entry = entry_ptr.*;
    if (invalid_cfg) {
        if (entry.cfg) |*c| c.deinit();
        entry.cfg = null;
        if (entry.dom) |*d| {
            d.tree.deinit();
            d.frontier.deinit();
        }

    entry.dom = null;
    if (entry.loop) |*l| l.info.deinit(entry.allocator);
    entry.loop = null;
} else if (invalid_dom) {
    if (entry.dom) |*d| {
        d.tree.deinit();
        d.frontier.deinit();
    }
    entry.dom = null;
    if (entry.loop) |*l| l.info.deinit(entry.allocator);

                entry.loop = null;
            } else if (invalid_loop) {
                if (entry.loop) |*l| l.info.deinit(entry.allocator);
                entry.loop = null;
            }
        }
    }
};

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../cfg/cfg.zig");
const bir_dominators = @import("../dominator/dominator.zig");
const bir_alias = @import("../alias/alias.zig");
const NO_VALUE = bir.NO_VALUE;
const BlockId = bir.BlockId;
const ValueId = bir.ValueId;

pub const MemOpKey = struct { block: BlockId, idx: u32 };

pub const MemorySSA = struct {
    allocator: Allocator,
    func: *const bir.Function,
    cfg: *const bir_cfg.CFG,
    dom_tree: *const bir_dominators.DominatorTree,

    reaching_def: std.AutoHashMap(MemOpKey, MemOpKey),
    stored_val: std.AutoHashMap(MemOpKey, ValueId),

    pub fn getReachingStore(self: *const MemorySSA, block: BlockId, idx: u32) ?MemOpKey {
        return self.reaching_def.get(.{ .block = block, .idx = idx });
    }

    pub fn getStoredValue(self: *const MemorySSA, store: MemOpKey) ?ValueId {
        return self.stored_val.get(store);
    }
};

pub fn build(allocator: Allocator, func: *const bir.Function, cfg: *const bir_cfg.CFG, dom_tree: *const bir_dominators.DominatorTree) !MemorySSA {
    var ssa = MemorySSA{
        .allocator = allocator,
        .func = func,
        .cfg = cfg,
        .dom_tree = dom_tree,
        .reaching_def = std.AutoHashMap(MemOpKey, MemOpKey).init(allocator),
        .stored_val = std.AutoHashMap(MemOpKey, ValueId).init(allocator),
    };

const nblocks = func.blocks.items.len;

var df = try bir_dominators.buildDominanceFrontiers(allocator, cfg, func, dom_tree);
defer df.deinit();

var store_sites = try allocator.alloc(std.ArrayList(MemOpKey), nblocks);
defer {
    for (store_sites) |*sl| sl.deinit();
    allocator.free(store_sites);
}

for (0..nblocks) |i| {
    store_sites[i] = std.ArrayList(MemOpKey).init(allocator);
}

var load_sites = try allocator.alloc(std.ArrayList(MemOpKey), nblocks);
defer {
    for (load_sites) |*ll| ll.deinit();
    allocator.free(load_sites);
}
for (0..nblocks) |i| {

    load_sites[i] = std.ArrayList(MemOpKey).init(allocator);
}

for (func.blocks.items, 0..) |*block, bi| {
    const bid = @as(BlockId, @intCast(bi));
    for (block.instrs.items, 0..) |*inst, ii| {
        const idx = @as(u32, @intCast(ii));
        switch (inst.op) {
            .store => {
                try store_sites[bid].append(.{ .block = bid, .idx = idx });

            },
            .load => {
                try load_sites[bid].append(.{ .block = bid, .idx = idx });
            },
            else => {},
        }
    }
}

