const BIRError = error{ TypeError, UnknownExpression, OutOfMemory };

var t_void: TypeId = bir_types.INVALID_TYPE;
var t_i1: TypeId = bir_types.INVALID_TYPE;
var t_i8: TypeId = bir_types.INVALID_TYPE;
var t_i16: TypeId = bir_types.INVALID_TYPE;

var t_i32: TypeId = bir_types.INVALID_TYPE;
var t_i64: TypeId = bir_types.INVALID_TYPE;
var t_u8: TypeId = bir_types.INVALID_TYPE;
var t_u16: TypeId = bir_types.INVALID_TYPE;
var t_u32: TypeId = bir_types.INVALID_TYPE;
var t_u64: TypeId = bir_types.INVALID_TYPE;
var t_f32: TypeId = bir_types.INVALID_TYPE;
var t_f64: TypeId = bir_types.INVALID_TYPE;
var t_ptr: TypeId = bir_types.INVALID_TYPE;

fn ensureTypes(module: *bir.Module) !void {
    if (t_void == bir_types.INVALID_TYPE) {
        t_void = try module.types.voidType();
        t_i1 = try module.types.scalarType(.i1);
        t_i8 = try module.types.scalarType(.i8);
        t_i16 = try module.types.scalarType(.i16);
        t_i32 = try module.types.scalarType(.i32);
        t_i64 = try module.types.scalarType(.i64);
        t_u8 = try module.types.scalarType(.u8);
        t_u16 = try module.types.scalarType(.u16);

        t_u32 = try module.types.scalarType(.u32);
        t_u64 = try module.types.scalarType(.u64);
        t_f32 = try module.types.scalarType(.f32);
        t_f64 = try module.types.scalarType(.f64);
        t_ptr = try module.types.pointerType(0, .generic);
    }
}

fn mapType(module: *bir.Module, type_name: []const u8) !TypeId {
    if (std.mem.eql(u8, type_name, "void")) return t_void;

if (std.mem.eql(u8, type_name, "bool")) return t_i1;
if (std.mem.eql(u8, type_name, "i8")) return t_i8;
if (std.mem.eql(u8, type_name, "i16")) return t_i16;
if (std.mem.eql(u8, type_name, "i32")) return t_i32;
if (std.mem.eql(u8, type_name, "i64") or std.mem.eql(u8, type_name, "int")) return t_i64;
if (std.mem.eql(u8, type_name, "u8")) return t_u8;
if (std.mem.eql(u8, type_name, "u16")) return t_u16;
if (std.mem.eql(u8, type_name, "u32")) return t_u32;
if (std.mem.eql(u8, type_name, "u64")) return t_u64;
if (std.mem.eql(u8, type_name, "f32")) return t_f32;

    if (std.mem.eql(u8, type_name, "f64")) return t_f64;
    if (std.mem.eql(u8, type_name, "string")) return t_ptr;
    if (std.mem.eql(u8, type_name, "ptr")) return t_ptr;
    const owned = try module.allocator.dupe(u8, type_name);
    return module.types.add(.{ .custom_opaque = owned });
}

pub fn lowerProgram(allocator: Allocator, program: *const ast.ProgramNode) !bir.Module {
    var module = bir.Module.init(allocator);
    errdefer module.deinit();

    for (program.common.func_defs.items) |func| {
        try lowerFunction(allocator, &module, func);
    }
    if (program.plan.states.items.len > 0) {
        try lowerStateMachine(allocator, &module, program.plan.states.items);
    }
    return module;
}

fn makeInst(allocator: Allocator, op: Op, ty: TypeId, ops: []const ValueId, data: Inst.Data) !Inst {

    var owned_ops: []ValueId = &.{};
    if (ops.len > 0) {
        owned_ops = try allocator.dupe(ValueId, ops);
    }
    return .{ .op = op, .ty = ty, .result = NO_VALUE, .operands = owned_ops, .data = data };
}

const VarInfo = struct {
    value: ValueId,
    type_id: TypeId,

};

fn lowerFunction(
    allocator: Allocator,
    module: *bir.Module,
    func: ast.EntryDecl,
) !void {
    try ensureTypes(module);
    const ret_type = if (func.return_type) |rt| try mapType(module, rt) else t_void;
    const func_id = try module.addFunction(func.name, ret_type, .internal);

{
    const fn_mut = module.getFunctionMut(func_id);
    const owned_params = try allocator.alloc(bir.FuncParam, func.params.items.len);
    const owned_values = try allocator.alloc(ValueId, func.params.items.len);
    for (func.params.items, 0..) |param, i| {
        owned_params[i] = .{ .name = try allocator.dupe(u8, param.name), .ty = try mapType(module, param.type_name) };
        owned_values[i] = try fn_mut.createValue();
    }
    fn_mut.params = owned_params;

    fn_mut.param_values = owned_values;
}

const entry_id = try module.addBlock(func_id, "entry");
var b = Builder{
    .alloc = allocator,
    .mod = module,
    .fid = func_id,
    .blk = entry_id,
    .vars = std.StringHashMap(VarInfo).init(allocator),

    .ret_type = ret_type,
    .func_return_types = std.StringHashMap(TypeId).init(allocator),
};
defer b.vars.deinit();
defer b.func_return_types.deinit();

for (func.params.items, 0..) |param, i| {
    const param_ty = try mapType(module, param.type_name);
    const pval = module.getFunction(func_id).param_values[i];
    try b.vars.put(param.name, .{ .value = pval, .type_id = param_ty });

    {
        const fn_mut = module.getFunctionMut(func_id);
        const owned_name = try allocator.dupe(u8, param.name);
        try fn_mut.value_debug_names.put(pval, owned_name);
    }
}

var body_joined = std.ArrayList(u8).init(allocator);
defer body_joined.deinit();
for (func.body_lines.items, 0..) |line, i| {

        if (i > 0) try body_joined.append(';');
        try body_joined.appendSlice(line);
    }
    if (body_joined.items.len > 0) try lowerBodyStr(&b, body_joined.items, ';');
    if (!b.terminated()) try b.retVoid();
}

fn lowerStateMachine(
    allocator: Allocator,
    module: *bir.Module,

    states: []const ast.StateDefNode,
) !void {
    try ensureTypes(module);

    var sm = try module.addStateMachine("plan", @intCast(states.len));

    for (states, 0..) |state, si| {
        const entry_fn = try lowerStateEntry(allocator, module, state);
        const exit_fn = try lowerStateExit(allocator, module, state);
        try sm.states.append(.{

    .name = try allocator.dupe(u8, state.name),
    .entry_fn = entry_fn,
    .exit_fn = exit_fn,
    .variables_count = @intCast(state.variables.items.len),
});
for (state.transitions.items) |t| {
    const target_idx = blk: {
        for (states, 0..) |s, ti| {
            if (std.mem.eql(u8, s.name, t.target)) break :blk @as(u32, @intCast(ti));
        }

    break :blk 0;
};

var event_id: u32 = 0;
if (t.is_always) {
    event_id = 0;
} else if (t.event_name) |ename| {
    if (sm.event_id_map.get(ename)) |existing| {
        event_id = existing;
    } else {

        event_id = @intCast(sm.event_names.items.len);
        try sm.event_names.append(try allocator.dupe(u8, ename));
        try sm.event_id_map.put(sm.event_names.items[event_id], event_id);
    }
}

const guard_fn: ?bir.FunctionId = null;
var guard_expr_owned: ?[]const u8 = null;
if (t.guard) |guard_expr| {
    guard_expr_owned = try allocator.dupe(u8, guard_expr);

}

var action_fn: ?bir.FunctionId = null;
if (t.body) |action_body| {
    const act_name = try std.fmt.allocPrint(allocator, "action_{s}_{s}", .{ state.name, t.target });
    defer allocator.free(act_name);
    const afid = try module.addFunction(act_name, t_void, .internal);
    const aeid = try module.addBlock(afid, "entry");
    var ab = Builder{
        .alloc = allocator,

    .mod = module,
    .fid = afid,
    .blk = aeid,
    .vars = std.StringHashMap(VarInfo).init(allocator),
    .ret_type = t_void,
    .func_return_types = std.StringHashMap(TypeId).init(allocator),
};
defer ab.vars.deinit();
defer ab.func_return_types.deinit();
try lowerBodyStr(&ab, action_body, ';');

    if (!ab.terminated()) try ab.retVoid();
    action_fn = afid;
}

try sm.transitions.append(.{
    .event_id = event_id,
    .from_state_idx = @intCast(si),
    .to_state_idx = target_idx,
    .guard_fn = guard_fn,
    .action_fn = action_fn,

                .guard_expr = guard_expr_owned,
            });
        }
    }
}

fn lowerStateEntry(
    allocator: Allocator,
    module: *bir.Module,
    state: ast.StateDefNode,

) !bir.FunctionId {
    try ensureTypes(module);
    const nm = try std.fmt.allocPrint(allocator, "state_{s}_entry", .{state.name});
    defer allocator.free(nm);
    const fid = try module.addFunction(nm, t_void, .entry);
    const eid = try module.addBlock(fid, "entry");
    var b = Builder{
        .alloc = allocator,
        .mod = module,
        .fid = fid,

    .blk = eid,
    .vars = std.StringHashMap(VarInfo).init(allocator),
    .ret_type = t_void,
    .func_return_types = std.StringHashMap(TypeId).init(allocator),
};
defer b.vars.deinit();
defer b.func_return_types.deinit();

for (state.variables.items) |v| {
    const vt = try mapType(module, v.type_name);

    const slot = try b.emitOp(.alloca, vt, &.{}, .{ .none = {} });
    try b.vars.put(v.name, .{ .value = slot, .type_id = vt });
    if (v.default_value) |dv| {
        const val = try lowerExpr(&b, dv);
        if (val != NO_VALUE) try b.emitStore(vt, slot, val);
    }
}
if (state.enter_body) |body| {
    try lowerBodyStr(&b, body, ';');
}

    if (!b.terminated()) try b.retVoid();
    return fid;
}

fn lowerStateExit(
    allocator: Allocator,
    module: *bir.Module,
    state: ast.StateDefNode,
) !?bir.FunctionId {
    try ensureTypes(module);

const body = state.exit_body orelse return null;
const tb = std.mem.trim(u8, body, " \t\r\n");
if (tb.len == 0) return null;

const nm = try std.fmt.allocPrint(allocator, "state_{s}_exit", .{state.name});
defer allocator.free(nm);
const fid = try module.addFunction(nm, t_void, .internal);
const eid = try module.addBlock(fid, "entry");
var b = Builder{
    .alloc = allocator,

    .mod = module,
    .fid = fid,
    .blk = eid,
    .vars = std.StringHashMap(VarInfo).init(allocator),
    .ret_type = t_void,
    .func_return_types = std.StringHashMap(TypeId).init(allocator),
};
defer b.vars.deinit();
defer b.func_return_types.deinit();
try lowerBodyStr(&b, tb, ';');

    if (!b.terminated()) try b.retVoid();
    return fid;
}

const Builder = struct {
    alloc: Allocator,
    mod: *bir.Module,
    fid: bir.FunctionId,
    blk: BlockId,
    vars: std.StringHashMap(VarInfo),

ret_type: TypeId,
func_return_types: std.StringHashMap(TypeId),

fn terminated(self: *Builder) bool {
    const bl = self.mod.getFunctionMut(self.fid).getBlock(self.blk);
    if (bl.instrs.items.len == 0) return false;
    const last = bl.instrs.items[bl.instrs.items.len - 1];
    return last.op == .ret or last.op == .br or last.op == .cond_br;
}

fn emitOp(self: *Builder, op: Op, ty: TypeId, ops: []const ValueId, data: Inst.Data) !ValueId {
    return self.mod.addInst(self.fid, self.blk, try makeInst(self.alloc, op, ty, ops, data));
}

fn emitRet(self: *Builder, val: ValueId, ty: TypeId) !void {
    if (val != NO_VALUE) {
        _ = try self.emitOp(.ret, ty, &.{val}, .{ .none = {} });
    } else {
        _ = try self.emitOp(.ret, t_void, &.{}, .{ .none = {} });
    }

}

fn retVoid(self: *Builder) !void {
    _ = try self.emitOp(.ret, t_void, &.{}, .{ .none = {} });
}

fn emitBr(self: *Builder, target: BlockId) !void {
    _ = try self.emitOp(.br, t_void, &.{}, .{ .block_target = target });
}

fn emitCondBr(self: *Builder, cond: ValueId, then_b: BlockId, else_b: BlockId) !void {
    _ = try self.emitOp(.cond_br, t_void, &.{cond}, .{ .cond_branch = .{ .cond = cond, .then_block = then_b, .else_block = else_b } });
}

fn emitStore(self: *Builder, ty: TypeId, slot: ValueId, val: ValueId) !void {
    _ = try self.emitOp(.store, ty, &.{ slot, val }, .{ .none = {} });
}

fn emitLoad(self: *Builder, slot: ValueId, ty: TypeId) !ValueId {
    return self.emitOp(.load, ty, &.{slot}, .{ .none = {} });

}

fn emitAlloca(self: *Builder, ty: TypeId) !ValueId {
    return self.emitOp(.alloca, ty, &.{}, .{ .none = {} });
}

fn emitConstInt(self: *Builder, v: i64) !ValueId {
    return self.emitOp(.@"const", t_i64, &.{}, .{ .const_data = .{ .int = v } });
}

fn emitConstBool(self: *Builder, v: bool) !ValueId {
    return self.emitOp(.@"const", t_i1, &.{}, .{ .const_data = .{ .bool = v } });
}

fn emitConstStr(self: *Builder, s: []const u8) !ValueId {
    const owned = try self.alloc.dupe(u8, s);
    return self.emitOp(.@"const", t_ptr, &.{}, .{ .string = owned });
}

fn emitBinOp(self: *Builder, op: Op, lty: TypeId, rty: TypeId, l: ValueId, r: ValueId) !ValueId {

    const result_ty = self.inferBinResultType(lty, rty);
    return self.emitOp(op, result_ty, &.{ l, r }, .{ .none = {} });
}

fn inferBinResultType(_: *Builder, lty: TypeId, rty: TypeId) TypeId {
    if (lty == rty) return lty;
    if (lty == t_i1 or rty == t_i1) return t_i1;
    if (lty == t_f64 or rty == t_f64) return t_f64;
    if (lty == t_f32 or rty == t_f32) return t_f32;
    return lty;

}

fn emitNeg(self: *Builder, val: ValueId, ty: TypeId) !ValueId {
    if (ty == t_f32 or ty == t_f64) return BIRError.TypeError;
    const zero = try self.emitConstInt(0);
    return self.emitBinOp(.sub, ty, ty, zero, val);
}

fn emitCall(self: *Builder, name: []const u8, args: []const ValueId) !ValueId {
    const ret_ty = self.func_return_types.get(name) orelse t_void;

    const owned_name = try self.alloc.dupe(u8, name);
    const owned_args = try self.alloc.dupe(ValueId, args);
    return self.emitOp(.call, ret_ty, &.{}, .{ .named_call = .{ .name = owned_name, .args = owned_args } });
}

fn getVar(self: *Builder, name: []const u8) ?VarInfo {
    return self.vars.get(name);
}

fn newBlock(self: *Builder, label: []const u8) !BlockId {

        return self.mod.addBlock(self.fid, label);
    }
};

fn inferExprType(b: *Builder, expr: []const u8) TypeId {
    const t = std.mem.trim(u8, expr, " \t\r\n");
    if (t.len == 0) return t_void;

    if (std.mem.eql(u8, t, "true") or std.mem.eql(u8, t, "false")) return t_i1;

if (t[0] == '"') return t_ptr;

if (std.ascii.isDigit(t[0]) or (t.len > 1 and t[0] == '-' and std.ascii.isDigit(t[1]))) {
    if (std.mem.indexOfScalar(u8, t, '.') != null) return t_f64;
    return t_i64;
}

if (t[0] == '(') {
    if (findParenEnd(t, 0)) |end| {
        if (end == t.len - 1) return inferExprType(b, t[1..end]);

    }
}

if (std.mem.indexOfScalar(u8, t, '(')) |pp| {
    if (pp > 0) {
        const nm = std.mem.trim(u8, t[0..pp], " \t\r\n");
        if (b.func_return_types.get(nm)) |ret_ty| return ret_ty;
        if (std.mem.eql(u8, nm, "print")) return t_void;
        if (std.mem.eql(u8, nm, "malloc")) return t_ptr;
        if (std.mem.eql(u8, nm, "addr")) return t_ptr;

    }
}

const cmp_ops = [_][]const u8{ "==", "!=", "<=", ">=", "<", ">" };
for (cmp_ops) |op| {
    if (findBinOp(t, op)) |_| return t_i1;
}

const bool_ops = [_][]const u8{ "&&", "||" };
for (bool_ops) |op| {

    if (findBinOp(t, op)) |_| return t_i1;
}

const arop_ops = [_]struct { []const u8, TypeId }{
    .{ "+", t_i64 }, .{ "-", t_i64 }, .{ "*", t_i64 },
    .{ "/", t_i64 }, .{ "%", t_i64 },
};
for (arop_ops) |pair| {
    if (findBinOp(t, pair[0])) |parts| {
        const lty = inferExprType(b, parts.left);

        const rty = inferExprType(b, parts.right);
        if (lty == t_f64 or rty == t_f64) return t_f64;
        if (lty == t_f32 or rty == t_f32) return t_f32;
        if (lty == rty) return lty;
        return t_i64;
    }
}

if (t[0] == '-' and t.len > 1) return inferExprType(b, t[1..]);

    if (b.getVar(t)) |vi| return vi.type_id;

    return t_i64;
}

fn lowerStmt(b: *Builder, line: []const u8) anyerror!void {
    if (b.terminated()) return;

    if (std.mem.startsWith(u8, line, "return")) {
        const rest = std.mem.trim(u8, line["return".len..], " \t\r\n");

    if (rest.len == 0) {
        try b.retVoid();
    } else {
        const val = try lowerExpr(b, rest);
        const ty = inferExprType(b, rest);
        try b.emitRet(val, ty);
    }
    return;
}

if (std.mem.startsWith(u8, line, "var ")) {
    const rest = std.mem.trim(u8, line["var ".len..], " \t\r\n");
    const name = extractName(rest);
    if (name.len == 0) return;

    var var_type: TypeId = t_i64;
    if (extractVarType(rest)) |vt| {
        var_type = try mapType(b.mod, vt);
    }

const slot = try b.emitAlloca(var_type);
try b.vars.put(name, .{ .value = slot, .type_id = var_type });
{
    const fn_mut = b.mod.getFunctionMut(b.fid);
    const owned_name = try b.alloc.dupe(u8, name);
    try fn_mut.value_debug_names.put(slot, owned_name);
}

if (std.mem.indexOfScalar(u8, rest, '=')) |eq| {
    const expr_str = std.mem.trim(u8, rest[eq + 1 ..], " \t\r\n");

        const val = try lowerExpr(b, expr_str);
        if (val != NO_VALUE) {
            const expr_ty = inferExprType(b, expr_str);
            const store_ty = if (expr_ty != t_i64) expr_ty else var_type;
            try b.emitStore(store_ty, slot, val);
        }
    }
    return;
}

if (std.mem.startsWith(u8, line, "if ") or std.mem.startsWith(u8, line, "if(")) {
    try lowerIf(b, line);
    return;
}

if (std.mem.startsWith(u8, line, "while ") or std.mem.startsWith(u8, line, "while(")) {
    try lowerWhile(b, line);
    return;
}

if (std.mem.indexOfScalar(u8, line, '=')) |eq_idx| {
    const lhs = std.mem.trim(u8, line[0..eq_idx], " \t\r\n");
    const rhs = std.mem.trim(u8, line[eq_idx + 1 ..], " \t\r\n");
    if (lhs.len > 0 and rhs.len > 0) {
        if (b.getVar(lhs)) |vi| {
            const val = try lowerExpr(b, rhs);
            const expr_ty = inferExprType(b, rhs);
            const store_ty = if (expr_ty != t_i64) expr_ty else vi.type_id;
            try b.emitStore(store_ty, vi.value, val);
        }

        }
        return;
    }

    _ = try lowerExpr(b, line);
}

fn lowerExpr(b: *Builder, expr: []const u8) anyerror!ValueId {
    const t = std.mem.trim(u8, expr, " \t\r\n");
    if (t.len == 0) return NO_VALUE;

if (std.mem.eql(u8, t, "true")) return b.emitConstBool(true);
if (std.mem.eql(u8, t, "false")) return b.emitConstBool(false);

if (t[0] == '"') {
    const eq = std.mem.lastIndexOfScalar(u8, t, '"') orelse t.len;
    return b.emitConstStr(t[1..eq]);
}

if (std.ascii.isDigit(t[0]) or (t.len > 1 and t[0] == '-' and std.ascii.isDigit(t[1]))) {

    return b.emitConstInt(try std.fmt.parseInt(i64, t, 10));
}

if (t[0] == '(') {
    if (findParenEnd(t, 0)) |end| {
        if (end == t.len - 1) return lowerExpr(b, t[1..end]);
    }
}

if (std.mem.indexOfScalar(u8, t, '(')) |pp| {

    if (pp > 0) {
        const nm = std.mem.trim(u8, t[0..pp], " \t\r\n");
        if (findParenEnd(t, pp)) |c| {
            return lowerCallExpr(b, nm, std.mem.trim(u8, t[pp + 1 .. c], " \t\r\n"));
        }
    }
}

const ops = [_]struct { []const u8, Op }{
    .{ "+", .add }, .{ "-", .sub }, .{ "*", .mul },

    .{ "/", .div }, .{ "%", .mod },
    .{ "==", .eq }, .{ "!=", .ne },
    .{ "<=", .le }, .{ ">=", .ge },
    .{ "<", .lt },  .{ ">", .gt },
    .{ "&&", .and_op }, .{ "||", .or_op },
};
for (ops) |pair| {
    if (findBinOp(t, pair[0])) |parts| {
        const l = try lowerExpr(b, parts.left);
        const r = try lowerExpr(b, parts.right);

        const lty = inferExprType(b, parts.left);
        const rty = inferExprType(b, parts.right);
        return b.emitBinOp(pair[1], lty, rty, l, r);
    }
}

if (t[0] == '-' and t.len > 1) {
    const inner = try lowerExpr(b, t[1..]);
    const ty = inferExprType(b, t[1..]);
    return b.emitNeg(inner, ty);

    }

    if (b.getVar(t)) |vi| {
        return b.emitLoad(vi.value, vi.type_id);
    }

    std.log.err("error: unrecognized expression '{s}' in BIR lowering", .{t});
    return BIRError.UnknownExpression;
}

fn lowerCallExpr(b: *Builder, name: []const u8, args_str: []const u8) anyerror!ValueId {
    // Handle print built-in: dispatch to print_i64 (int) or print_str (string)
    const callee_name = if (std.mem.eql(u8, name, "print")) blk: {
        const trimmed = std.mem.trim(u8, args_str, " \t\r\n");
        break :blk if (trimmed.len > 0 and trimmed[0] == '"') "print_str" else "print_i64";
    } else name;

    var args = std.ArrayList(ValueId).init(b.alloc);
    defer args.deinit();
    if (args_str.len > 0) {

var depth: i32 = 0;
var in_str = false;
var start: usize = 0;
for (args_str, 0..) |c, i| {
    if (c == '"') in_str = !in_str;
    if (in_str) continue;
    if (c == '(') depth += 1;
    if (c == ')') depth -= 1;
    if (c == ',' and depth == 0) {
        const a = std.mem.trim(u8, args_str[start..i], " \t\r\n");

        if (a.len > 0) {
            const v = try lowerExpr(b, a);
            if (v != NO_VALUE) try args.append(v);
        }
        start = i + 1;
    }
}
const last = std.mem.trim(u8, args_str[start..], " \t\r\n");
if (last.len > 0) {
    const v = try lowerExpr(b, last);

            if (v != NO_VALUE) try args.append(v);
        }
    }
    return b.emitCall(callee_name, args.items);
}

fn lowerIf(b: *Builder, line: []const u8) anyerror!void {
    const rest = std.mem.trim(u8, line[3..], " \t\r\n");
    const cb = findBraceBlock(rest) orelse return;
    const cond_str = std.mem.trim(u8, rest[0..cb.body_start - 1], " \t\r\n");

const body_str = std.mem.trim(u8, rest[cb.body_start..cb.body_end], " \t\r\n");

const cond_val = try lowerExpr(b, cond_str);
if (cond_val == NO_VALUE) return;

const then_id = try b.newBlock("if_then");
const else_id = try b.newBlock("if_else");
const merge_id = try b.newBlock("if_merge");

try b.emitCondBr(cond_val, then_id, else_id);

    b.blk = then_id;
    try lowerBodyStr(b, body_str, ';');
    if (!b.terminated()) try b.emitBr(merge_id);

    b.blk = else_id;
    try b.emitBr(merge_id);

    b.blk = merge_id;
}

fn lowerWhile(b: *Builder, line: []const u8) anyerror!void {
    const rest = std.mem.trim(u8, line[6..], " \t\r\n");
    const cb = findBraceBlock(rest) orelse return;
    const cond_str = std.mem.trim(u8, rest[0..cb.body_start - 1], " \t\r\n");
    const body_str = std.mem.trim(u8, rest[cb.body_start..cb.body_end], " \t\r\n");

    const header_id = try b.newBlock("while_header");
    const body_id = try b.newBlock("while_body");
    const exit_id = try b.newBlock("while_exit");

try b.emitBr(header_id);

b.blk = header_id;
const cond_val = try lowerExpr(b, cond_str);
if (cond_val == NO_VALUE) return;
try b.emitCondBr(cond_val, body_id, exit_id);

b.blk = body_id;
try lowerBodyStr(b, body_str, ';');

    if (!b.terminated()) try b.emitBr(header_id);

    b.blk = exit_id;
}

fn lowerBodyStr(b: *Builder, body: []const u8, sep: u8) anyerror!void {
    var pos: usize = 0;
    while (pos < body.len) {
        while (pos < body.len and (body[pos] == ' ' or body[pos] == '\t' or body[pos] == '\r' or body[pos] == '\n')) : (pos += 1) {}
        if (pos >= body.len) break;

if (body[pos] == '{' or body[pos] == '}') {
    pos += 1;
    continue;
}

var depth: i32 = 0;
var in_str = false;
var start = pos;
while (pos < body.len) {
    const c = body[pos];

if (c == '"') in_str = !in_str;
if (in_str) {
    pos += 1;
    continue;
}
if (c == '(' or c == '{') depth += 1;
if (c == ')' or c == '}') {
    depth -= 1;
    if (depth < 0) {
        pos += 1;

        break;
    }
}
if (c == sep and depth == 0) {
    const stmt = std.mem.trim(u8, body[start..pos], " \t\r\n");
    pos += 1;
    start = pos;
    if (stmt.len > 0) try lowerStmt(b, stmt);
    break;
}

        pos += 1;
    }
    if (pos >= body.len or (pos == body.len)) {
        if (start < body.len) {
            const stmt = std.mem.trim(u8, body[start..body.len], " \t\r\n");
            if (stmt.len > 0) try lowerStmt(b, stmt);
        }
        break;
    }
}

}

const BraceBlock = struct { body_start: usize, body_end: usize };

fn findBraceBlock(text: []const u8) ?BraceBlock {
    var i: usize = 0;
    while (i < text.len and text[i] != '{') : (i += 1) {}
    if (i >= text.len) return null;
    const body_start = i + 1;
    var depth: i32 = 1;

    i = body_start;
    while (i < text.len and depth > 0) {
        if (text[i] == '{') depth += 1;
        if (text[i] == '}') depth -= 1;
        i += 1;
    }
    return .{ .body_start = body_start, .body_end = i - 1 };
}

const BinParts = struct { left: []const u8, right: []const u8 };

fn findBinOp(expr: []const u8, op: []const u8) ?BinParts {
    var depth: i32 = 0;
    var i: usize = expr.len;
    while (i > 0) {
        i -= 1;
        if (expr[i] == ')') depth += 1;
        if (expr[i] == '(') depth -= 1;
        if (depth != 0) continue;
        if (i + op.len > expr.len) continue;

if (!std.mem.eql(u8, expr[i .. i + op.len], op)) continue;
if (i == 0) return null;
if (i + op.len >= expr.len) return null;
if (std.mem.eql(u8, op, "=") and i + 1 < expr.len and expr[i + 1] == '=') continue;
if (std.mem.eql(u8, op, "!") and i + 1 < expr.len and expr[i + 1] == '=') continue;
if (std.mem.eql(u8, op, "<") and i + 1 < expr.len and expr[i + 1] == '=') continue;
if (std.mem.eql(u8, op, ">") and i + 1 < expr.len and expr[i + 1] == '=') continue;
if (std.mem.eql(u8, op, "&") and i + 1 < expr.len and expr[i + 1] == '&') continue;
if (std.mem.eql(u8, op, "|") and i + 1 < expr.len and expr[i + 1] == '|') continue;
const left = std.mem.trim(u8, expr[0..i], " \t\r\n");

        const right = std.mem.trim(u8, expr[i + op.len ..], " \t\r\n");
        if (left.len > 0 and right.len > 0) return .{ .left = left, .right = right };
    }
    return null;
}

fn findParenEnd(line: []const u8, open: usize) ?usize {
    if (open >= line.len or line[open] != '(') return null;
    var depth: i32 = 0;
    var i = open;

while (i < line.len) {
    if (line[i] == '(') depth += 1;
    if (line[i] == ')') {
        depth -= 1;
        if (depth == 0) return i;
    }
    if (line[i] == '"') {
        i += 1;
        while (i < line.len and line[i] != '"') : (i += 1) {}
    }

        i += 1;
    }
    return null;
}

fn extractName(rest: []const u8) []const u8 {
    const t = std.mem.trim(u8, rest, " \t\r\n");
    var end: usize = 0;
    while (end < t.len and (std.ascii.isAlphanumeric(t[end]) or t[end] == '_')) : (end += 1) {}
    return t[0..end];

}

fn extractVarType(rest: []const u8) ?[]const u8 {
    const t = std.mem.trim(u8, rest, " \t\r\n");
    const colon_idx = std.mem.indexOfScalar(u8, t, ':') orelse return null;
    const after_colon = std.mem.trim(u8, t[colon_idx + 1 ..], " \t\r\n");
    var end: usize = 0;
    while (end < after_colon.len and std.ascii.isAlphanumeric(after_colon[end])) : (end += 1) {}
    if (end == 0) return null;
    const type_str = std.mem.trimRight(u8, after_colon[0..end], " \t\r\n");

    if (type_str.len == 0) return null;
    return type_str;
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("bir.zig");
const gpu_ir = @import("../../gpu/gpu_ir.zig");
const types_mod = @import("bir_types.zig");
const TypeId = types_mod.TypeId;

const Op = bir.Op;
const ValueId = bir.ValueId;
const BlockId = bir.BlockId;

const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;

pub fn lowerToBir(allocator: Allocator, module: *const gpu_ir.GpuModule) !bir.Module {
    var bir_mod = bir.Module.init(allocator);
    errdefer bir_mod.deinit();

    var type_map = try buildTypeMap(allocator, &bir_mod);
    defer type_map.deinit();

for (module.kernels.items) |*kernel| {
    var ir_resources = std.ArrayList(gpu_ir.IrResourceDecl).init(allocator);
    defer ir_resources.deinit();

    for (kernel.resources.items) |res| {
        const ir_res = gpuResourceToIr(&res);
        try ir_resources.append(.{
            .name = res.name,
            .type_ref = ir_res.@"0",
            .binding_prefix = ir_res.@"1",

    .binding_reg = res.binding.reg,
    .format = gpuResourceFormatToIr(&res),
});

const bir_ty = type_map.get(ir_res.@"0") orelse return error.TypeNotMapped;
try bir_mod.resources.append(.{
    .name = try allocator.dupe(u8, res.name),
    .ty = bir_ty,
    .binding = res.binding.reg,
    .space = res.binding.space,

    });
}

var ir_cbuffer = std.ArrayList(gpu_ir.IrCbufferMember).init(allocator);
defer ir_cbuffer.deinit();
for (kernel.cbuffer_members.items) |member| {
    try ir_cbuffer.append(.{
        .name = member.name,
        .type_ref = gpu_ir.scalarTypeToTypeRefWithWidth(member.scalar_type, member.vector_width),
        .slot = member.slot.reg,

    });
}

for (kernel.entries.items) |entry| {
    var func_types = extractFuncTypes(allocator, kernel.globals_lines.items);
    defer func_types.deinit();

    var filtered_body = std.ArrayList([]const u8).init(allocator);
    defer filtered_body.deinit();
    for (entry.body_lines.items) |line| {

            const trimmed = std.mem.trim(u8, line, " \t");
            if (trimmed.len > 0 and !std.mem.startsWith(u8, trimmed, "numthreads")) {
                try filtered_body.append(trimmed);
            }
        }

        // TODO: Reimplement body parsing without gpu_body_parser (deleted in GPU cleanup)
        return error.BodyParserNotYetPorted;
    }
}

    return bir_mod;
}

fn buildTypeMap(allocator: Allocator, bir_mod: *bir.Module) !std.AutoHashMap(gpu_ir.TypeRef, TypeId) {
    var map = std.AutoHashMap(gpu_ir.TypeRef, TypeId).init(allocator);
    errdefer map.deinit();

    try map.put(.void, try bir_mod.types.voidType());
    try map.put(.f32, try bir_mod.types.scalarType(.f32));

try map.put(.i32, try bir_mod.types.scalarType(.i32));
try map.put(.u32, try bir_mod.types.scalarType(.u32));
try map.put(.f16, try bir_mod.types.scalarType(.f16));
try map.put(.vec2f, try bir_mod.types.vectorType(.f32, 2));
try map.put(.vec3f, try bir_mod.types.vectorType(.f32, 3));
try map.put(.vec4f, try bir_mod.types.vectorType(.f32, 4));
try map.put(.vec2i, try bir_mod.types.vectorType(.i32, 2));
try map.put(.vec3i, try bir_mod.types.vectorType(.i32, 3));
try map.put(.vec4i, try bir_mod.types.vectorType(.i32, 4));
try map.put(.vec2u, try bir_mod.types.vectorType(.u32, 2));

    try map.put(.vec3u, try bir_mod.types.vectorType(.u32, 3));
    try map.put(.vec4u, try bir_mod.types.vectorType(.u32, 4));
    try map.put(.texture2d, try bir_mod.types.textureType(.tex2d));
    try map.put(.rw_texture2d, try bir_mod.types.textureType(.rw_tex2d));
    try map.put(.sampler, try bir_mod.types.samplerType());
    try map.put(.mat4x4f, try bir_mod.types.add(.{ .matrix = .{ .scalar = .f32, .rows = 4, .cols = 4 } }));

    return map;
}

fn convertIrFunction(allocator: Allocator, bir_mod: *bir.Module, func_id: bir.FunctionId, ir_func: *const gpu_ir.IrFunction, type_map: *const std.AutoHashMap(gpu_ir.TypeRef, TypeId)) !void {
    const fn_ptr = bir_mod.getFunctionMut(func_id);

    const old_block_count = ir_func.blocks.items.len;
    var block_order = std.ArrayList(usize).init(allocator);
    defer block_order.deinit();
    for (0..old_block_count) |i| try block_order.append(i);
    _ = &block_order;

    for (0..old_block_count) |b_idx| {

    const old_block = &ir_func.blocks.items[b_idx];
    _ = try bir_mod.addBlock(func_id, old_block.label);
}

var old_to_new_value = std.AutoHashMap(gpu_ir.ValueId, ValueId).init(allocator);
defer old_to_new_value.deinit();
try old_to_new_value.ensureTotalCapacity(@intCast(ir_func.blocks.items.len * 32));

const total_insts = blk: {
    var count: usize = 0;

    for (ir_func.blocks.items) |b| count += b.instrs.items.len;
    break :blk count;
};
for (0..total_insts) |_| _ = try fn_ptr.createValue();

var next_new_val: ValueId = 1;
    for (0..old_block_count) |_b_idx| {
        const old_block = &ir_func.blocks.items[_b_idx];

        for (old_block.instrs.items) |*old_inst| {

        const old_val = old_inst.result;
        const new_val = next_new_val;
        next_new_val += 1;
        old_to_new_value.putAssumeCapacityNoClobber(old_val, new_val);
    }
}

for (0..old_block_count) |_b_idx| {
    const old_block = &ir_func.blocks.items[_b_idx];
    const bid = @as(BlockId, @intCast(_b_idx));

for (old_block.instrs.items) |*old_inst| {
    const bir_inst = try convertInst(allocator, bir_mod, func_id, old_inst, type_map, &old_to_new_value) orelse continue;
    const block = fn_ptr.getBlock(bid);
    const idx = block.instrs.items.len;
    try block.instrs.append(bir_inst);

    if (bir_inst.result != NO_VALUE) {
        fn_ptr.getValueInfo(bir_inst.result).def = .{ .block = bid, .idx = @as(u32, @intCast(idx)) };
    }

for (bir_inst.operands) |op_val| {
    if (op_val != NO_VALUE) {
        try fn_ptr.getValueInfo(op_val).uses.append(bir_inst.result);
    }
}

{
    var ref_list = std.ArrayList(ValueId).init(allocator);
    defer ref_list.deinit();

                    try bir.collectDataRefs(&bir_inst.data, &ref_list);
                    for (ref_list.items) |ref| {
                        if (ref != NO_VALUE) {
                            try fn_ptr.getValueInfo(ref).uses.append(bir_inst.result);
                        }
                    }
                }
            }
        }
}

fn convertInst(allocator: Allocator, _bir_mod: *bir.Module, _func_id: bir.FunctionId, old_inst: *const gpu_ir.IrInst, type_map: *const std.AutoHashMap(gpu_ir.TypeRef, TypeId), value_map: *const std.AutoHashMap(gpu_ir.ValueId, ValueId)) !?bir.Inst {
    _ = _func_id;
    _ = _bir_mod;

    const bir_op = convertOpWithType(old_inst.op, old_inst.ty, old_inst.data) orelse return null;
    const new_val = value_map.get(old_inst.result) orelse return error.ValueNotMapped;
    const bir_ty = type_map.get(old_inst.ty) orelse return error.TypeNotMapped;
    const operands = try remapValues(allocator, old_inst.operands, value_map);
    errdefer if (operands.len > 0) allocator.free(operands);

const data = try convertData(allocator, old_inst.data, old_inst.op, type_map, value_map);
errdefer {
    switch (data) {
        .phi_incoming => |v| allocator.free(v),
        .named_call => |v| { allocator.free(v.name); allocator.free(v.args); },
        .gep_info => |v| allocator.free(v.indices),
        .vector_shuffle => |v| allocator.free(v.mask),
        .string => |v| if (v.len > 0) allocator.free(v),
        else => {},

    }
}

return bir.Inst{
    .op = bir_op,
    .ty = bir_ty,
    .result = new_val,
    .operands = operands,
    .data = data,
};

}

fn convertOpWithType(op: gpu_ir.Op, ty: gpu_ir.TypeRef, data: gpu_ir.IrInst.Data) ?bir.Op {
    const is_float = switch (ty) {
        .f32, .f16, .vec2f, .vec3f, .vec4f, .mat4x4f => true,
        else => false,
    };
    return switch (op) {
        .entry_point => null,
        .load => .resource,

        .quad_read_across_x => .quad_read_across_x,
        .quad_read_across_y => .quad_read_across_y,
    };
}

fn convertData(allocator: Allocator, old_data: gpu_ir.IrInst.Data, _old_op: gpu_ir.Op, type_map: *const std.AutoHashMap(gpu_ir.TypeRef, TypeId), value_map: *const std.AutoHashMap(gpu_ir.ValueId, ValueId)) !bir.Inst.Data {
    _ = &type_map;
    _ = &value_map;
    _ = &_old_op;
    switch (old_data) {

.none => return .{ .none = {} },
.int_val => |v| return .{ .const_data = .{ .int = v } },
.float_val => |v| return .{ .const_data = .{ .float = v } },
.string => |s| return .{ .string = try allocator.dupe(u8, s) },
.block_target => |b| return .{ .block_target = b },
.cond_branch => |cb| {
    const cond = mapValue(cb.cond, value_map);
    return .{ .cond_branch = .{
        .cond = cond,
        .then_block = cb.then_block,

        .else_block = cb.else_block,
    } };
},
.phi_incoming => |inc| {
    const new_inc = try allocator.alloc(bir.PhiIncoming, inc.len);
    for (inc, 0..) |item, i| {
        new_inc[i] = .{
            .value = mapValue(item.value, value_map),
            .block = item.block,
        };

    }
    return .{ .phi_incoming = new_inc };
},
.sample_info => |si| {
    return .{ .sample_info = .{
        .tex = mapValue(si.tex, value_map),
        .sampler = mapValue(si.sampler, value_map),
        .coord = mapValue(si.coord, value_map),
        .lod = NO_VALUE,
        .offset = null,

    } };
},
.atomic_info => |ai| {
    return .{ .atomic_info = .{
        .ptr = mapValue(ai.ptr, value_map),
        .val = mapValue(ai.val, value_map),
        .order = .relaxed,
    } };
},
.barrier_kind => |bk| return .{ .barrier_kind = @as(bir.BarrierKind, @enumFromInt(@intFromEnum(bk))) },

.composite_info => return .{ .none = {} },
.extract_info => |ei| return .{ .extract_info = .{ .index = ei.index } },
.cast_info => |ci| {
    const from = type_map.get(ci.from) orelse return error.TypeNotMapped;
    const to = type_map.get(ci.to) orelse return error.TypeNotMapped;
    const kind = inferCastKind(ci.from, ci.to);
    return .{ .cast_info = .{ .kind = kind, .from = from, .to = to } };
},
.call_info => |ci| {
    if (isIntrinsicMethod(ci.callee) or std.mem.eql(u8, ci.callee, "@array_get")) {

    const new_args = try remapValues(allocator, ci.args, value_map);
    return .{ .named_call = .{
        .name = try allocator.dupe(u8, ci.callee),
        .args = new_args,
    } };
}
const new_args = try remapValues(allocator, ci.args, value_map);
return .{ .named_call = .{
    .name = try allocator.dupe(u8, ci.callee),
    .args = new_args,

            } };
        },
        .wave_op => |wo| {
            const source = if (wo.source != 0) mapValue(wo.source, value_map) else NO_VALUE;
            _ = source;
            return .{ .none = {} };
        },
    }
}

fn inferCastKind(from: gpu_ir.TypeRef, to: gpu_ir.TypeRef) bir.CastKind {
    const from_float = isFloatType(from);
    const to_float = isFloatType(to);
    const from_int = isIntType(from);
    const to_int = isIntType(to);
    if (from_float and to_float) return .f2f;
    if (from_float and to_int) return .f2i;
    if (from_int and to_float) return .i2f;
    if (from_int and to_int) return .i2i;
    return .bitcast;

}

fn isFloatType(tr: gpu_ir.TypeRef) bool {
    return switch (tr) {
        .f32, .f16, .vec2f, .vec3f, .vec4f, .mat4x4f => true,
        else => false,
    };
}

fn isIntType(tr: gpu_ir.TypeRef) bool {

    return switch (tr) {
        .i32, .u32, .vec2i, .vec3i, .vec4i, .vec2u, .vec3u, .vec4u => true,
        else => false,
    };
}

fn isIntrinsicMethod(name: []const u8) bool {
    return std.mem.eql(u8, name, "SampleLevel") or
        std.mem.eql(u8, name, "Sample") or
        std.mem.eql(u8, name, "Load") or

        std.mem.eql(u8, name, "GetDimensions") or
        std.mem.eql(u8, name, "Gather") or
        std.mem.eql(u8, name, "GatherRed") or
        std.mem.eql(u8, name, "GatherGreen") or
        std.mem.eql(u8, name, "GatherBlue") or
        std.mem.eql(u8, name, "GatherAlpha");
}

fn mapValue(old: gpu_ir.ValueId, value_map: *const std.AutoHashMap(gpu_ir.ValueId, ValueId)) ValueId {
    if (value_map.get(old)) |v| return v;

    return NO_VALUE;
}

fn remapValues(allocator: Allocator, old_operands: []const gpu_ir.ValueId, value_map: *const std.AutoHashMap(gpu_ir.ValueId, ValueId)) ![]ValueId {
    if (old_operands.len == 0) return &.{};
    const new_ops = try allocator.alloc(ValueId, old_operands.len);
    for (old_operands, 0..) |old_v, i| {
        new_ops[i] = mapValue(old_v, value_map);
    }
    return new_ops;

}

fn gpuResourceToIr(res: *const gpu_ir.ResourceDecl) struct { gpu_ir.TypeRef, u8 } {
    return switch (res.gpu_type.kind) {
        .resource_typed => |rt| switch (rt.kind) {
            .texture2d => .{ .texture2d, 't' },
            .rw_texture2d => .{ .rw_texture2d, 'u' },
            else => .{ .texture2d, 't' },
        },
        .resource => |rk| switch (rk) {

            .sampler_state => .{ .sampler, 's' },
            else => .{ .texture2d, 't' },
        },
        else => .{ .texture2d, 't' },
    };
}

fn gpuResourceFormatToIr(res: *const gpu_ir.ResourceDecl) gpu_ir.TypeRef {
    return switch (res.gpu_type.kind) {
        .resource_typed => |rt| gpu_ir.scalarTypeToTypeRefWithWidth(rt.format, rt.width),

        else => .f32,
    };
}

fn cleanupIrFunc(allocator: Allocator, ir_func: *const gpu_ir.IrFunction) void {
    for (ir_func.blocks.items) |b| {
        for (b.instrs.items) |inst| {
            if (inst.operands.len > 0) allocator.free(inst.operands);
            switch (inst.data) {
                .phi_incoming => |v| allocator.free(v),

        .string => |s| if (s.len > 0) allocator.free(s),
        .call_info => |ci| {
            if (ci.callee.len > 0) allocator.free(ci.callee);
            if (ci.args.len > 0) allocator.free(ci.args);
        },
        else => {},
    }
}
b.instrs.deinit();
allocator.free(b.label);

    }
    ir_func.blocks.deinit();
    for (ir_func.locals.items) |l| {
        allocator.free(l.name);
        allocator.free(l.array_dims);
    }
    ir_func.locals.deinit();
}

fn extractFuncTypes(allocator: Allocator, globals_lines: []const []const u8) std.StringHashMap(gpu_ir.TypeRef) {

var map = std.StringHashMap(gpu_ir.TypeRef).init(allocator);
for (globals_lines) |line| {
    const trimmed = std.mem.trim(u8, line, " \t\r\n");
    if (trimmed.len == 0) continue;
    const lparen = std.mem.indexOfScalar(u8, trimmed, '(') orelse continue;
    const before_paren = trimmed[0..lparen];
    const rp = std.mem.lastIndexOfScalar(u8, before_paren, ' ');
    const rn = std.mem.lastIndexOfScalar(u8, before_paren, '\t');
    const space = @max(rp orelse 0, rn orelse 0);
    if (space == 0 or space + 1 >= before_paren.len) continue;

        const name = before_paren[space + 1 ..];
        const type_str = std.mem.trim(u8, before_paren[0..space], " \t");
        const type_ref = gpu_ir.parseTypeRef(type_str) orelse continue;
        map.put(name, type_ref) catch {};
    }
    return map;
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("bir.zig");
const types = @import("bir_types.zig");
const bir_cfg = @import("bir_cfg.zig");

fn typeToHlsl(tid: types.TypeId, tt: *const types.TypeTable) []const u8 {
    const t = tt.get(tid);
    return switch (t.kind) {
        .void => "void",

},
.vector => |v| switch (v.scalar) {
    .f32 => switch (v.len) {
        2 => "float2",
        3 => "float3",
        4 => "float4",
        else => "float",
    },
    .u32 => switch (v.len) {
        2 => "uint2",

    3 => "uint3",
    4 => "uint4",
    else => "uint",
},
.i32 => switch (v.len) {
    2 => "int2",
    3 => "int3",
    4 => "int4",
    else => "int",
},

    .f16 => switch (v.len) {
        2 => "min16float2",
        3 => "min16float3",
        4 => "min16float4",
        else => "min16float",
    },
    else => "float",
},
.pointer => "uint",
.array => |a| blk: {

    const elem = typeToHlsl(a.elem, tt);
    break :blk elem;
},
.texture => |tk| switch (tk) {
    .tex2d => "Texture2D<float4>",
    .rw_tex2d => "RWTexture2D<float4>",
    .tex2d_array => "Texture2DArray<float4>",
    .tex3d => "Texture3D<float4>",
    .rw_tex3d => "RWTexture3D<float4>",
    else => "Texture2D<float4>",

        },
        else => "float",
    };
}

fn emitResourceDecl(w: anytype, res: *const bir.ResourceDecl, tt: *const types.TypeTable) !void {
    const tstr = typeToHlsl(res.ty, tt);
    const prefix = resourceRegisterPrefix(res.ty, tt);
    try w.print("{s} {s} : register({c}{d});\n", .{ tstr, res.name, prefix, res.binding });
}

fn resourceRegisterPrefix(tid: types.TypeId, tt: *const types.TypeTable) u8 {
    const t = tt.get(tid);
    return switch (t.kind) {
        .texture => |tk| switch (tk) {
            .rw_tex1d, .rw_tex2d, .rw_tex3d => 'u',
            else => 't',
        },
        .sampler => 's',
        .buffer => |bk| switch (bk) {

            .rw_structured, .rw_raw, .rw_typed => 'u',
            .constant => 'b',
            else => 't',
        },
        else => 't',
    };
}

pub fn generateHlsl(allocator: Allocator, module: *bir.Module) ![]const u8 {
    var buf = std.ArrayList(u8).init(allocator);

const w = buf.writer();

try w.writeAll("// Generated by BIR→HLSL\n");
try w.writeAll("#include \"/Engine/Public/Platform.ush\"\n\n");

for (module.resources.items) |res| {
    try emitResourceDecl(w, &res, &module.types);
}
try w.writeAll("\n");

for (module.functions.items) |*func| {
    try w.print("[numthreads({}, {}, {})]\n", .{ func.numthreads.x, func.numthreads.y, func.numthreads.z });
    try w.print("void {s}(uint3 __tid : SV_DispatchThreadID)\n", .{func.name});
    try w.writeAll("{\n");

    var var_names = std.AutoHashMap(bir.ValueId, []const u8).init(module.allocator);
    defer var_names.deinit();

    for (func.blocks.items) |*block| {
        for (block.instrs.items) |inst| {

if (inst.result == bir.NO_VALUE) continue;
const vname = if (inst.op == .resource)
    inst.data.string
else
    try std.fmt.allocPrint(module.allocator, "_v{d}", .{inst.result});
try var_names.put(inst.result, vname);
if (inst.op == .resource) continue;
if (inst.op == .store) continue;
const tstr = typeToHlsl(inst.ty, &module.types);
if (!std.mem.eql(u8, tstr, "void")) {

            try w.print("    {s} {s};\n", .{ tstr, vname });
        }
    }
}

var cfg = try bir_cfg.buildCFG(allocator, func);
defer cfg.deinit();

for (cfg.rpo.items) |bid| {
    const block = &func.blocks.items[bid];

        for (block.instrs.items) |inst| {
            if (isTerminator(inst.op)) continue;
            try emitInst(w, &inst, &var_names, &module.types);
        }
    }

    try w.writeAll("    return;\n");
    try w.writeAll("}\n\n");
}

    return buf.toOwnedSlice();
}

fn isTerminator(op: bir.Op) bool {
    return switch (op) {
        .br, .cond_br, .ret, .unreachable_op => true,
        else => false,
    };
}

fn emitInst(w: anytype, inst: *const bir.Inst, var_names: *const std.AutoHashMap(bir.ValueId, []const u8), tt: *const types.TypeTable) !void {
    const name = if (inst.result != bir.NO_VALUE) var_names.get(inst.result) else null;

    switch (inst.op) {
        .br, .cond_br, .ret, .unreachable_op => {},
        .phi => {
            if (name) |n| {
                switch (inst.data) {
                    .phi_incoming => |incoming| {
                        try w.print("    // phi: {s} = merge ", .{n});

                for (incoming, 0..) |inc, pi| {
                    if (pi > 0) try w.writeAll(", ");
                    try w.print("%{d} from block_{d}", .{ inc.value, inc.block });
                }
                try w.writeAll("\n");
            },
            else => {},
        }
    }
},

.@"const" => {
    if (name) |n| {
        switch (inst.data) {
            .const_data => |cd| {
                switch (cd) {
                    .int => |v| try w.print("    {s} = {d};\n", .{ n, v }),
                    .float => |v| try w.print("    {s} = {d};\n", .{ n, v }),
                    .bool => |v| try w.print("    {s} = {};\n", .{ n, @as(i32, @intFromBool(v)) }),
                    else => try w.print("    {s} = 0;\n", .{n}),
                }

            },
            else => try w.print("    {s} = 0;\n", .{n}),
        }
    }
},
.thread_id => {
    if (name) |n| {
        switch (inst.data) {
            .group_info => |gi| {
                const dims = [_][]const u8{ "x", "y", "z" };

                try w.print("    {s} = __tid.{s};\n", .{ n, dims[@as(usize, @intCast(gi.dim))] });
            },
            else => try w.print("    {s} = __tid.x;\n", .{n}),
        }
    }
},
.add, .sub, .mul, .div, .mod,
.fadd, .fsub, .fmul, .fdiv, .fmod,
=> {
    if (name) |n| {

const op_sym = switch (inst.op) {
    .add, .fadd => "+",
    .sub, .fsub => "-",
    .mul, .fmul => "*",
    .div, .fdiv => "/",
    .mod, .fmod => "%",
    else => "?",
};
if (inst.operands.len >= 2) {
    const lhs = var_names.get(inst.operands[0]) orelse "0";

            const rhs = var_names.get(inst.operands[1]) orelse "0";
            try w.print("    {s} = {s} {s} {s};\n", .{ n, lhs, op_sym, rhs });
        }
    }
},
.neg, .fneg => {
    if (name) |n| {
        if (inst.operands.len >= 1) {
            const op = var_names.get(inst.operands[0]) orelse "0";
            try w.print("    {s} = -({s});\n", .{ n, op });

        }
    }
},
.lt, .le, .gt, .ge, .eq, .ne,
.flt, .fle, .fgt, .fge, .feq, .fne,
=> {
    if (name) |n| {
        const op_sym = switch (inst.op) {
            .lt, .flt => "<",
            .le, .fle => "<=",

    .gt, .fgt => ">",
    .ge, .fge => ">=",
    .eq, .feq => "==",
    .ne, .fne => "!=",
    else => "?",
};
if (inst.operands.len >= 2) {
    const lhs = var_names.get(inst.operands[0]) orelse "0";
    const rhs = var_names.get(inst.operands[1]) orelse "0";
    try w.print("    {s} = {s} {s} {s};\n", .{ n, lhs, op_sym, rhs });

        }
    }
},
.resource => {},
.texture_sample => {
    if (name) |n| {
        switch (inst.data) {
            .sample_info => |si| {
                const tex = var_names.get(si.tex) orelse "?";
                const samp = var_names.get(si.sampler) orelse "?";

        const coord = var_names.get(si.coord) orelse "0";
        if (si.lod) |lod_val| {
            const lod = var_names.get(lod_val) orelse "0";
            try w.print("    {s} = {s}.SampleLevel({s}, {s}, {s});\n", .{ n, tex, samp, coord, lod });
        } else {
            try w.print("    {s} = {s}.Sample({s}, {s});\n", .{ n, tex, samp, coord });
        }
    },
    else => {},
}

    }
},
.texture_load => {
    if (name) |n| {
        if (inst.operands.len >= 3) {
            const tex = var_names.get(inst.operands[0]) orelse "?";
            const coord_x = var_names.get(inst.operands[1]) orelse "0";
            const coord_y = var_names.get(inst.operands[2]) orelse "0";
            try w.print("    {s} = {s}.Load(uint3({s}, {s}, 0));\n", .{ n, tex, coord_x, coord_y });
        }

    }
},
.texture_store => {
    switch (inst.data) {
