fn emitNamedCall(w: anytype, name: []const u8, nc: anytype, var_names: *const std.AutoHashMap(bir.ValueId, []const u8)) !void {
    const callee = nc.name;
    if (std.mem.eql(u8, callee, "@array_get")) {
        try w.print("    {s} = {s}[{s}]", .{ name, var_names.get(nc.args[0]) orelse "?", var_names.get(nc.args[1]) orelse "0" });
    } else if (std.mem.eql(u8, callee, "SampleLevel")) {
        const tex = var_names.get(nc.args[0]) orelse "?";
        const samp = var_names.get(nc.args[1]) orelse "?";
        const coord = var_names.get(nc.args[2]) orelse "0";

    const lod = if (nc.args.len > 3) var_names.get(nc.args[3]) orelse "0" else "0";
    try w.print("    {s} = {s}.SampleLevel({s}, {s}, {s})", .{ name, tex, samp, coord, lod });
} else if (std.mem.eql(u8, callee, "Sample")) {
    const tex = var_names.get(nc.args[0]) orelse "?";
    const samp = var_names.get(nc.args[1]) orelse "?";
    const coord = var_names.get(nc.args[2]) orelse "0";
    try w.print("    {s} = {s}.Sample({s}, {s})", .{ name, tex, samp, coord });
} else if (std.mem.eql(u8, callee, "Load")) {
    const tex = var_names.get(nc.args[0]) orelse "?";
    if (nc.args.len >= 3) {

        const cx = var_names.get(nc.args[1]) orelse "0";
        const cy = var_names.get(nc.args[2]) orelse "0";
        try w.print("    {s} = {s}.Load(uint3({s}, {s}, 0))", .{ name, tex, cx, cy });
    } else {
        const coord = var_names.get(nc.args[1]) orelse "0";
        try w.print("    {s} = {s}.Load({s})", .{ name, tex, coord });
    }
} else if (std.mem.eql(u8, callee, "GetDimensions")) {
    const tex = var_names.get(nc.args[0]) orelse "?";
    if (nc.args.len >= 3) {

        const out_w = var_names.get(nc.args[1]) orelse "?";
        const out_h = var_names.get(nc.args[2]) orelse "?";
        try w.print("    {s}.GetDimensions({s}, {s})", .{ tex, out_w, out_h });
    } else {
        try w.print("    {s}.GetDimensions()", .{tex});
    }
} else if (std.mem.startsWith(u8, callee, "Gather")) {
    const tex = var_names.get(nc.args[0]) orelse "?";
    const samp = var_names.get(nc.args[1]) orelse "?";
    const coord = if (nc.args.len > 2) var_names.get(nc.args[2]) orelse "0" else "0";

    try w.print("    {s} = {s}.{s}({s}, {s})", .{ name, tex, callee, samp, coord });
} else {
    try w.print("    {s} = {s}(", .{ name, callee });
    for (nc.args, 0..) |arg, ai| {
        if (ai > 0) try w.writeAll(", ");
        try w.writeAll(var_names.get(arg) orelse "?");
    }
    try w.writeAll(")");
}
try w.writeAll(";\n");

}

fn emitNamedCallNoResult(w: anytype, nc: anytype, var_names: *const std.AutoHashMap(bir.ValueId, []const u8)) !void {
    const callee = nc.name;
    if (std.mem.eql(u8, callee, "GetDimensions")) {
        const tex = var_names.get(nc.args[0]) orelse "?";
        if (nc.args.len >= 3) {
            const out_w = var_names.get(nc.args[1]) orelse "?";
            const out_h = var_names.get(nc.args[2]) orelse "?";
            try w.print("    {s}.GetDimensions({s}, {s})", .{ tex, out_w, out_h });

        } else {
            try w.print("    {s}.GetDimensions()", .{tex});
        }
        try w.writeAll(";\n");
    }
}

