const Op = bir.Op;

const CmpDef = struct { op0: u32, op1: u32, cc: mir.CondCode };

fn sizeToMemSize(size: u32) mir.MemSize {
    return switch (size) {

        1 => .u8,
        2 => .u16,
        4 => .u32,
        8 => .u64,
        else => .u64,
    };
}

fn birTypeToDataType(types: *const bir.types.TypeTable, ty: bir.types.TypeId) mir.DataType {
    const t = types.get(ty);

return switch (t.kind) {
    .scalar => |sk| switch (sk) {
        .i1, .i8, .i16, .i32, .i64 => .i64,
        .u8, .u16, .u32, .u64 => .i64,
        .f16, .f32 => .f32,
        .f64 => .f64,
        .bf16 => .f32,
    },
    .pointer => .i64,
    .void => .void,

        else => .i64,
    };
}

fn findCmpDef(bir_func: *const bir.Function, val: u32) ?CmpDef {
    if (val == bir.NO_VALUE or val == 0) return null;
    if (val - 1 >= bir_func.value_info.items.len) return null;
    const vi = &bir_func.value_info.items[val - 1];
    if (vi.def.block == bir.INVALID_ID or vi.def.idx == bir.INVALID_ID) return null;
    if (vi.def.block >= bir_func.blocks.items.len) return null;

const def_block = &bir_func.blocks.items[vi.def.block];
if (vi.def.idx >= def_block.instrs.items.len) return null;
const def_inst = &def_block.instrs.items[vi.def.idx];
const ops = def_inst.operands;
if (ops.len < 2) return null;
const cc: mir.CondCode = switch (def_inst.op) {
    .eq => .eq,
    .ne => .ne,
    .lt => .lt,
    .le => .le,

        .gt => .gt,
        .ge => .ge,
        else => return null,
    };
    return CmpDef{ .op0 = ops[0], .op1 = ops[1], .cc = cc };
}

pub fn lowerModuleToMir(allocator: std.mem.Allocator, mod: *const bir.Module) ![]mir.MFunction {
    var mfuncs = std.ArrayList(mir.MFunction).init(allocator);
    errdefer for (mfuncs.items) |*mf| mf.deinit();

    for (mod.functions.items) |*func| {
        const mf = try lowerToMir(allocator, &mod.types, func);
        try mfuncs.append(mf);
    }
    for (mod.state_machines.items) |*sm| {
        const mf = try lowerStateMachine(allocator, mod, sm);
        try mfuncs.append(mf);
    }
    return mfuncs.toOwnedSlice();
}

fn allocVreg(next: *u32) u32 {
    const v = next.*;
    next.* += 1;
    return v;
}

pub fn lowerStateMachine(allocator: std.mem.Allocator, mod: *const bir.Module, sm: *const bir.StateMachine) !mir.MFunction {
    var mfunc = mir.MFunction.init(allocator, sm.name);
    errdefer mfunc.deinit();

var next_vreg: u32 = 1;

const state_slot = allocVreg(&next_vreg);  // vreg 1 = state slot

const init_st = &sm.states.items[sm.initial_state_idx];

// Block 0: entry — state_init, enter initial state, call entry function
{
    var block = mir.MBlock{ .label = try allocator.dupe(u8, "entry"), .instrs = std.ArrayList(mir.MInst).init(allocator) };
    errdefer { allocator.free(block.label); block.instrs.deinit(); }

try block.instrs.append(.{ .alloca = .{ .size = 8, .dst = .{ .vreg = state_slot } } });
try block.instrs.append(.{ .state_init = .{ .initial_state = .{ .imm = @as(i64, @intCast(sm.initial_state_idx)) } } });
try block.instrs.append(.{ .state_enter = .{ .state_id = .{ .imm = @as(i64, @intCast(sm.initial_state_idx)) } } });

const entry_name = try std.fmt.allocPrint(allocator, "state_{s}_entry", .{init_st.name});
const cargs: [14]mir.MOperand = @splat(.{ .imm = 0 });
try block.instrs.append(.{ .call = .{ .name = entry_name, .args = cargs, .arg_count = 0, .dst = .{ .imm = 0 }, .is_void = true } });

try block.instrs.append(.{ .jmp = .{ .target = 1 } });

    try mfunc.blocks.append(block);
}

// Block 1: event_loop — dispatch event, check transitions via cmp+jcc
{
    var block = mir.MBlock{ .label = try allocator.dupe(u8, "event_loop"), .instrs = std.ArrayList(mir.MInst).init(allocator) };
    errdefer { allocator.free(block.label); block.instrs.deinit(); }

    const event_val = allocVreg(&next_vreg);
    const buf_val = allocVreg(&next_vreg);

const size_val = allocVreg(&next_vreg);
try block.instrs.append(.{ .mov = .{ .dst = .{ .vreg = buf_val }, .src = .{ .imm = 0 } } });
try block.instrs.append(.{ .mov = .{ .dst = .{ .vreg = size_val }, .src = .{ .imm = 0 } } });
try block.instrs.append(.{ .event_dispatch = .{ .dst = .{ .vreg = event_val }, .buf = .{ .vreg = buf_val }, .size = .{ .vreg = size_val } } });

// For each transition: cmp event, event_id → jcc to transition block
for (sm.transitions.items, 0..) |t, ti| {
    const block_idx: u32 = @as(u32, @intCast(2 + ti));
    _ = try allocator.dupe(u8, "");  // keep errdefer happy — no free needed
    try block.instrs.append(.{ .cmp = .{ .cc = .eq, .a = .{ .vreg = event_val }, .b = .{ .imm = @as(i64, @intCast(t.event_id)) } } });

        try block.instrs.append(.{ .jcc = .{ .cc = .eq, .target = block_idx } });
    }

    try block.instrs.append(.{ .jmp = .{ .target = 1 } });
    try mfunc.blocks.append(block);
}

// Blocks 2+: transition blocks — state_exit, state_enter, call action, jmp back
for (sm.transitions.items, 0..) |t, ti| {
    var block = mir.MBlock{ .label = try std.fmt.allocPrint(allocator, "trans_{d}", .{ti}), .instrs = std.ArrayList(mir.MInst).init(allocator) };

errdefer { allocator.free(block.label); block.instrs.deinit(); }

try block.instrs.append(.{ .state_exit = .{ .state_id = .{ .imm = @as(i64, @intCast(t.from_state_idx)) } } });
try block.instrs.append(.{ .state_enter = .{ .state_id = .{ .imm = @as(i64, @intCast(t.to_state_idx)) } } });

if (t.action_fn) |af| {
    const act_name = try allocator.dupe(u8, mod.functions.items[af].name);
    const aargs: [14]mir.MOperand = @splat(.{ .imm = 0 });
    try block.instrs.append(.{ .call = .{ .name = act_name, .args = aargs, .arg_count = 0, .dst = .{ .imm = 0 }, .is_void = true } });
}

        try block.instrs.append(.{ .jmp = .{ .target = 1 } });
        try mfunc.blocks.append(block);
    }

    return mfunc;
}

fn allocValue(next_vreg: *u32) u32 {
    const v = next_vreg.*;

    next_vreg.* += 1;
    return v;
}

pub fn lowerToMir(allocator: std.mem.Allocator, types: *const bir.types.TypeTable, bir_func: *const bir.Function) !mir.MFunction {
    if (settings.debug_ir) {
        const stderr4 = std.io.getStdErr().writer();
        stderr4.print("; BIR FUNC: '{s}' (blocks={d}, locals={d}, params={d})\n", .{bir_func.name, bir_func.blocks.items.len, bir_func.locals_count, bir_func.param_values.len}) catch {};
        for (bir_func.param_values, 0..) |pv, i| {
            stderr4.print(";   param[{d}]: value={d}\n", .{i, pv}) catch {};

}
for (bir_func.blocks.items, 0..) |bir_block, bi| {
    stderr4.print(";   blk {d} '{s}' ({d} instrs):\n", .{bi, bir_block.label, bir_block.instrs.items.len}) catch {};
    for (bir_block.instrs.items, 0..) |inst, ii| {
        stderr4.print(";     {d}: op={s} result={d} operands=[", .{ii, @tagName(inst.op), inst.result}) catch {};
        for (inst.operands, 0..) |op, oi| {
            if (oi > 0) stderr4.print(",", .{}) catch {};
            stderr4.print("{d}", .{op}) catch {};
        }
        stderr4.print("]\n", .{}) catch {};

        }
    }
}

var mfunc = mir.MFunction.init(allocator, bir_func.name);
errdefer mfunc.deinit();

// Map BIR param values to MIR param vregs (so x64 codegen emits MOVs from ABI registers)
{
    const mir_params = try allocator.alloc(mir.MOperand, bir_func.param_values.len);

    for (bir_func.param_values, 0..) |pv, i| {
        mir_params[i] = .{ .vreg = pv };
        const dt = birTypeToDataType(types, bir_func.params[i].ty);
        mfunc.putVReg(pv, dt) catch {};
    }
    mfunc.setParams(mir_params);
}

const NO_VALUE = bir.NO_VALUE;
var next_vreg: u32 = bir_func.locals_count + 1;

for (bir_func.blocks.items) |bir_block| {
    var mblock = mir.MBlock{
        .label = try allocator.dupe(u8, bir_block.label),
        .instrs = std.ArrayList(mir.MInst).init(allocator),
    };
    errdefer {
        allocator.free(mblock.label);
        mblock.instrs.deinit();
    }

for (bir_block.instrs.items) |inst| {
    const result = inst.result;

    switch (inst.op) {
        .@"const" => {
            if (result == NO_VALUE) continue;
            switch (inst.data) {
                .string => |s| {
                    const owned = try allocator.dupe(u8, s);

    try mblock.instrs.append(.{ .string_const = .{
        .dst = .{ .vreg = result },
        .data = owned,
    } });
},
else => {
    const val = switch (inst.data) {
        .const_data => |cd| switch (cd) {
            .int => |v| @as(i64, v),
            .float => |v| @as(i64, @intCast(@as(i64, @intFromFloat(v)))),

            .bool => |v| @as(i64, @intFromBool(v)),
            .undefined, .zero => 0,
        },
        else => 0,
    };
    try mblock.instrs.append(.{ .mov = .{
        .dst = .{ .vreg = result },
        .src = .{ .imm = val },
    } });
},

    }
},

.phi => {
    const inc = inst.data.phi_incoming;
    const mir_incoming = try allocator.alloc(mir.PhiIncoming, inc.len);
    for (inc, 0..) |incoming, ii| {
        mir_incoming[ii] = .{
            .src = .{ .vreg = incoming.value },
            .pred_block = @intCast(incoming.block),

        };
    }
    try mblock.instrs.append(.{ .phi = .{
        .dst = .{ .vreg = result },
        .incoming = mir_incoming,
    } });
},

.add => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;

    const lhs = inst.operands[0];
    const rhs = inst.operands[1];
    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = lhs } } });
    try mblock.instrs.append(.{ .add = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = rhs } } });
},

.sub => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    const lhs = inst.operands[0];
    const rhs = inst.operands[1];

    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = lhs } } });
    try mblock.instrs.append(.{ .sub = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = rhs } } });
},

.mul => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    const lhs = inst.operands[0];
    const rhs = inst.operands[1];
    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = lhs } } });
    try mblock.instrs.append(.{ .imul = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = rhs } } });

},

.div => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    const lhs = inst.operands[0];
    const rhs = inst.operands[1];
    const rem = allocValue(&next_vreg);
    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = lhs } } });
    try mblock.instrs.append(.{ .idiv = .{ .dividend = .{ .vreg = result }, .divisor = .{ .vreg = rhs }, .quotient = .{ .vreg = result }, .remainder = .{ .vreg = rem } } });
},

.mod => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    const lhs = inst.operands[0];
    const rhs = inst.operands[1];
    const q = allocValue(&next_vreg);
    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = q }, .src = .{ .vreg = lhs } } });
    try mblock.instrs.append(.{ .idiv = .{ .dividend = .{ .vreg = q }, .divisor = .{ .vreg = rhs }, .quotient = .{ .vreg = q }, .remainder = .{ .vreg = result } } });
},

.neg => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    const operand = inst.operands[0];
    try mblock.instrs.append(.{ .mov = .{ .dst = .{ .vreg = result }, .src = .{ .imm = 0 } } });
    try mblock.instrs.append(.{ .sub = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = operand } } });
},

.eq => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .eq } });

},
.ne => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .ne } });
},
.lt => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .lt } });
},
.le => if (result != NO_VALUE and inst.operands.len >= 2) {

    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .le } });
},
.gt => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .gt } });
},
.ge => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    try mblock.instrs.append(.{ .setcc = .{ .dst = .{ .vreg = result }, .cc = .ge } });

},

.br => {
    const target = inst.data.block_target;
    try mblock.instrs.append(.{ .jmp = .{ .target = target } });
},

.cond_br => {
    const cb = inst.data.cond_branch;
    const cmp_def = findCmpDef(bir_func, cb.cond);

    if (cmp_def) |cd| {
        try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = cd.op0 }, .b = .{ .vreg = cd.op1 } } });
        try mblock.instrs.append(.{ .jcc = .{ .cc = cd.cc, .target = cb.then_block } });
        try mblock.instrs.append(.{ .jmp = .{ .target = cb.else_block } });
    } else {
        try mblock.instrs.append(.{ .cmp_flags = .{ .a = .{ .vreg = cb.cond }, .b = .{ .imm = 0 } } });
        try mblock.instrs.append(.{ .jcc = .{ .cc = .ne, .target = cb.then_block } });
        try mblock.instrs.append(.{ .jmp = .{ .target = cb.else_block } });
    }
},

.ret => {
    if (inst.operands.len >= 1) {
        try mblock.instrs.append(.{ .ret = .{ .value = .{ .vreg = inst.operands[0] } } });
    } else {
        try mblock.instrs.append(.{ .ret = .void_ret });
    }
},

.call => {

if (inst.data != .named_call or result == NO_VALUE) continue;
const info = inst.data.named_call;
var args: [14]mir.MOperand = undefined;
for (&args) |*a| a.* = .{ .imm = 0 };
const count = @min(@as(u32, @intCast(info.args.len)), 14);
for (0..count) |i| args[i] = .{ .vreg = info.args[i] };
try mblock.instrs.append(.{ .call = .{
    .name = try allocator.dupe(u8, info.name),
    .args = args,
    .arg_count = count,

        .dst = .{ .vreg = result },
        .is_void = false,
    } });
},

.alloca => {
    if (result == NO_VALUE) continue;
    const size = types.sizeOf(inst.ty);
    try mblock.instrs.append(.{ .alloca = .{ .size = size, .dst = .{ .vreg = result } } });
},

.load => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    const load_size = sizeToMemSize(types.sizeOf(inst.ty));
    try mblock.instrs.append(.{ .load = .{ .dst = .{ .vreg = result }, .ptr = .{ .vreg = inst.operands[0] }, .size = load_size } });
},

.store => {
    if (inst.operands.len < 2) continue;
    const val_ty = inst.ty;

    const store_size = sizeToMemSize(types.sizeOf(val_ty));
    try mblock.instrs.append(.{ .store = .{ .ptr = .{ .vreg = inst.operands[0] }, .src = .{ .vreg = inst.operands[1] }, .size = store_size } });
},

.fadd => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    try mblock.instrs.append(.{ .fadd = .{ .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.fsub => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    try mblock.instrs.append(.{ .fsub = .{ .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.fmul => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;

    try mblock.instrs.append(.{ .fmul = .{ .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.fdiv => {
    if (result == NO_VALUE or inst.operands.len < 2) continue;
    try mblock.instrs.append(.{ .fdiv = .{ .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);

},

.fneg => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    try mblock.instrs.append(.{ .fneg_op = .{ .dst = .{ .vreg = result } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.sitofp => {

    if (result == NO_VALUE or inst.operands.len < 1) continue;
    try mblock.instrs.append(.{ .sitofp = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = inst.operands[0] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.fptosi => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    try mblock.instrs.append(.{ .fptosi = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = inst.operands[0] } } });
    const dt = birTypeToDataType(types, inst.ty);

    try mfunc.putVReg(result, dt);
},

.fpext => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    try mblock.instrs.append(.{ .fpext = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = inst.operands[0] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.fptrunc => {
    if (result == NO_VALUE or inst.operands.len < 1) continue;
    try mblock.instrs.append(.{ .fptrunc = .{ .dst = .{ .vreg = result }, .src = .{ .vreg = inst.operands[0] } } });
    const dt = birTypeToDataType(types, inst.ty);
    try mfunc.putVReg(result, dt);
},

.feq => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .fcmp = .{ .cc = .eq, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},

.fne => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .fcmp = .{ .cc = .ne, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},
.flt => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .fcmp = .{ .cc = .lt, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},
.fle => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .fcmp = .{ .cc = .le, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},
.fgt => if (result != NO_VALUE and inst.operands.len >= 2) {

    try mblock.instrs.append(.{ .fcmp = .{ .cc = .gt, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},
.fge => if (result != NO_VALUE and inst.operands.len >= 2) {
    try mblock.instrs.append(.{ .fcmp = .{ .cc = .ge, .dst = .{ .vreg = result }, .a = .{ .vreg = inst.operands[0] }, .b = .{ .vreg = inst.operands[1] } } });
},

.unreachable_op => {
    try mblock.instrs.append(.trap);
},

        else => {
            if (@import("builtin").mode == .Debug) {
                std.debug.print("Unsupported BIR operation in CPU backend: {s}\n", .{@tagName(inst.op)});
            }
            return error.UnsupportedBIRInstruction;
        },
    }
}

try mfunc.blocks.append(mblock);

    }

    return mfunc;
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../bir.zig");
const types = @import("../bir_types.zig");
const pipeline_gen = @import("../../../backend/mir/pipeline_gen.zig");

const Pipeline = pipeline_gen.Pipeline;
const Resource = pipeline_gen.Resource;
const ResourceType = pipeline_gen.ResourceType;

const AddressSpace = types.AddressSpace;

pub const LowerOptions = struct {
    target_shader_model: []const u8 = "cs_6_6",
};

pub fn lowerPipeline(allocator: Allocator, pipeline: *const Pipeline) !bir.Module {
    var module = bir.Module.init(allocator);

    try setupTypes(&module);

    try lowerResources(&module, pipeline.resources);
    try lowerPipelineFunc(&module, pipeline);

    return module;
}

fn setupTypes(module: *bir.Module) !void {
    _ = try module.types.voidType();
    _ = try module.types.scalarType(.i32);

_ = try module.types.scalarType(.u32);
_ = try module.types.scalarType(.f32);
_ = try module.types.scalarType(.f16);
_ = try module.types.scalarType(.i1);
_ = try module.types.vectorType(.f32, 2);
_ = try module.types.vectorType(.f32, 4);
_ = try module.types.vectorType(.u32, 2);
_ = try module.types.vectorType(.u32, 4);
_ = try module.types.textureType(.tex2d);
_ = try module.types.textureType(.rw_tex2d);

    _ = try module.types.samplerType();
}

fn lowerResources(module: *bir.Module, resources: []const Resource) !void {
    for (resources) |res| {
        const res_name = try module.allocator.dupe(u8, res.name);
        const tex_type: types.Type.TextureKind = switch (res.resource_type) {
            .input => .tex2d,
            .output => .rw_tex2d,
            .transient => .rw_tex2d,

    .persistent => .rw_tex2d,
};
const type_id = try module.types.textureType(tex_type);

try module.resources.append(.{
    .name = res_name,
    .ty = type_id,
    .binding = @as(u32, @intCast(module.resources.items.len)),
    .space = 0,
});

if (res.resource_type == .persistent) {
    const mem_name = try module.allocator.dupe(u8, res.name);
    try module.memory_regions.append(.{
        .name = mem_name,
        .ty = type_id,
        .space = .global,
        .size_val = 0,
        .alignment = 16,
    });

        }
    }
}

fn lowerPipelineFunc(module: *bir.Module, pipeline: *const Pipeline) !void {
    const void_ty = 0;
    const u32_ty = 2;
    const f32x4_ty = 7;

    const f_id = try module.addFunction("ExecutePlan", void_ty, .entry);

const fn0 = module.getFunctionMut(f_id);
if (pipeline.passes.len > 0) {
    fn0.numthreads = .{
        .x = pipeline.passes[0].group_x,
        .y = pipeline.passes[0].group_y,
        .z = pipeline.passes[0].group_z,
    };
}
const entry_block = try module.addBlock(f_id, "entry");
const final_block = try module.addBlock(f_id, "final");

var pass_block_ids = try std.ArrayList(bir.BlockId).initCapacity(module.allocator, pipeline.passes.len);
for (pipeline.passes) |pass| {
    const block_name = try std.fmt.allocPrint(module.allocator, "{s}", .{pass.name});
    const bid = try module.addBlock(f_id, block_name);
    pass_block_ids.appendAssumeCapacity(bid);
}

var res_map = std.StringHashMap(u32).init(module.allocator);
for (module.resources.items, 0..) |_, i| {

    try res_map.put(module.resources.items[i].name, @as(u32, @intCast(i)));
}

const tid_x = try module.addInst(f_id, entry_block, .{
    .op = .thread_id, .ty = u32_ty, .result = bir.NO_VALUE,
    .operands = &.{}, .data = .{ .group_info = .{ .dim = 0 } },
});
const tid_y = try module.addInst(f_id, entry_block, .{
    .op = .thread_id, .ty = u32_ty, .result = bir.NO_VALUE,
    .operands = &.{}, .data = .{ .group_info = .{ .dim = 1 } },

});

if (pipeline.passes.len > 0) {
    const fn_e = module.getFunctionMut(f_id);
    try fn_e.blocks.items[entry_block].instrs.append(.{
        .op = .br, .ty = void_ty, .result = bir.NO_VALUE,
        .operands = &.{}, .data = .{ .block_target = pass_block_ids.items[0] },
    });
}

for (pipeline.passes, 0..) |pass, pi| {
    const pass_block = pass_block_ids.items[pi];

    var loaded = std.ArrayList(bir.ValueId).init(module.allocator);
    defer loaded.deinit();

    for (pass.reads) |read_name| {
        const res_idx = res_map.get(read_name) orelse continue;
        const res = &module.resources.items[res_idx];
        const rv = try module.addInst(f_id, pass_block, .{

        .op = .resource, .ty = res.ty, .result = bir.NO_VALUE,
        .operands = &.{}, .data = .{ .string = try module.allocator.dupe(u8, read_name) },
    });
    const lv = try module.addInst(f_id, pass_block, .{
        .op = .texture_load, .ty = f32x4_ty, .result = bir.NO_VALUE,
        .operands = try module.allocator.dupe(bir.ValueId, &.{ rv, tid_x, tid_y }), .data = .none,
    });
    try loaded.append(lv);
}

const store_val = if (loaded.items.len > 0) loaded.items[0] else @as(bir.ValueId, 0);
for (pass.writes) |write_name| {
    const res_idx = res_map.get(write_name) orelse continue;
    const res = &module.resources.items[res_idx];
    const rv = try module.addInst(f_id, pass_block, .{
        .op = .resource, .ty = res.ty, .result = bir.NO_VALUE,
        .operands = &.{}, .data = .{ .string = try module.allocator.dupe(u8, write_name) },
    });
    const fn_p = module.getFunctionMut(f_id);
    try fn_p.blocks.items[pass_block].instrs.append(.{

        .op = .texture_store, .ty = void_ty, .result = bir.NO_VALUE,
        .operands = &.{}, .data = .{ .texture_store_info = .{
            .tex = rv, .coord_x = tid_x, .coord_y = tid_y, .val = store_val,
        }},
    });
}

const next_block = if (pi == pipeline.passes.len - 1) final_block else pass_block_ids.items[pi + 1];
const fn_p = module.getFunctionMut(f_id);
try fn_p.blocks.items[pass_block].instrs.append(.{

        .op = .br, .ty = void_ty, .result = bir.NO_VALUE,
        .operands = &.{}, .data = .{ .block_target = next_block },
    });
}

const fn_f = module.getFunctionMut(f_id);
try fn_f.blocks.items[final_block].instrs.append(.{
    .op = .ret, .ty = void_ty, .result = bir.NO_VALUE,
    .operands = &.{}, .data = .none,
});

}

pub fn dumpModule(module: *const bir.Module, writer: anytype) !void {
    try writer.writeAll("; BIR Module\n\n");

    try writer.writeAll("; Resources:\n");
    for (module.resources.items) |res| {
        try writer.print("  @resource.{s} : ", .{res.name});
        try writer.print("binding={d}\n", .{res.binding});
    }

try writer.writeAll("\n; Memory Regions:\n");
for (module.memory_regions.items) |mr| {
    try writer.print("  @mem.{s} : space={s}\n", .{ mr.name, @tagName(mr.space) });
}

try writer.writeAll("\n; Functions:\n");
for (module.functions.items) |func| {
    try writer.writeAll("define @");
    try writer.writeAll(func.name);

try writer.writeAll("()\n");
for (func.blocks.items) |block| {
    try writer.writeAll("  ");
    try writer.writeAll(block.label);
    try writer.writeAll(":");
    try writer.print(" ; {d} instrs\n", .{block.instrs.items.len});
    for (block.instrs.items) |inst| {
        if (inst.result != bir.NO_VALUE) {
            const vi = &func.value_info.items[inst.result - 1];
            try writer.print("    %{d} = {s}", .{ inst.result, @tagName(inst.op) });

if (vi.uses.items.len > 0) {
    try writer.print("  ; uses: ", .{});
    for (vi.uses.items, 0..) |user_val, ui| {
        if (ui > 0) try writer.writeAll(", ");
        try writer.print("%{d}", .{user_val});
    }
    try writer.writeAll("\n");
} else {
    try writer.writeAll("  ; (unused)\n");
}

} else {
    try writer.print("    {s}", .{@tagName(inst.op)});
}

switch (inst.data) {
    .block_target => |bt| try writer.print(" -> block_{d}", .{bt}),
    .string => |s| try writer.print(" \"{s}\"", .{s}),
    .group_info => |gi| try writer.print(" dim={d}", .{gi.dim}),
    .phi_incoming => |incoming| {
        try writer.writeAll(" [");

    for (incoming, 0..) |inc, pi| {
        if (pi > 0) try writer.writeAll(", ");
        try writer.print("%{d} from block_{d}", .{ inc.value, inc.block });
    }
    try writer.writeAll("]");
},
.const_data => |cd| {
    switch (cd) {
        .int => |v| try writer.print(" {d}", .{v}),
        .float => |v| try writer.print(" {d}", .{v}),

                        else => {},
                    }
                },
                else => {},
            }
            try writer.writeAll("\n");
        }
    }
    try writer.writeAll("\n");
}

for (module.state_machines.items) |sm| {
    try writer.print("\n; State Machine: {s}\n", .{sm.name});
    try writer.print(";   States ({d}):\n", .{sm.states.items.len});
    for (sm.states.items, 0..) |state, si| {
        try writer.print(";     [{d}] {s} entry=@{s}", .{ si, state.name, "" });
        const entry_fn = module.getFunction(state.entry_fn);
        try writer.print("@{s}", .{entry_fn.name});
        if (state.exit_fn) |efn| {
            const exit_fn = module.getFunction(efn);

        try writer.print(" exit=@{s}", .{exit_fn.name});
    }
    try writer.writeAll("\n");
}
try writer.print(";   Events ({d}):\n", .{sm.event_names.items.len});
for (sm.event_names.items, 0..) |ename, ei| {
    try writer.print(";     [{d}] \"{s}\"\n", .{ ei, ename });
}
try writer.print(";   Transitions ({d}):\n", .{sm.transitions.items.len});
for (sm.transitions.items) |t| {

const from = sm.states.items[t.from_state_idx].name;
const to = sm.states.items[t.to_state_idx].name;
try writer.print(";     {s} -> {s} (event={d}", .{ from, to, t.event_id });
if (t.guard_fn) |gf| {
    const gfn = module.getFunction(gf);
    try writer.print(" guard=@{s}", .{gfn.name});
}
if (t.guard_expr) |ge| {
    try writer.print(" guard_expr=\"{s}\"", .{ge});
}

            if (t.action_fn) |af| {
                const afn = module.getFunction(af);
                try writer.print(" action=@{s}", .{afn.name});
            }
            try writer.writeAll(")\n");
        }
    }
}

﻿const std = @import("std");
const Allocator = std.mem.Allocator;

const Module = @import("../core/module.zig").Module;
const AnalysisManager = @import("../analysis/manager.zig").AnalysisManager;
const PreservedAnalyses = @import("pass_types.zig").PreservedAnalyses;

pub usingnamespace @import("pass_types.zig");

pub const PassContext = struct {

    module: *Module,
    analysis: *AnalysisManager,
    allocator: Allocator,
};

pub const Pass = struct {
    name: []const u8,
    run: *const fn (ctx: *PassContext) anyerror!PreservedAnalyses,
};

pub const PassManager = struct {
    passes: std.ArrayList(Pass),
    allocator: Allocator,

    pub fn init(allocator: Allocator) PassManager {
        return .{
            .passes = std.ArrayList(Pass).init(allocator),
            .allocator = allocator,
        };
    }

pub fn deinit(self: *PassManager) void {
    self.passes.deinit();
}

pub fn addPass(self: *PassManager, pass: Pass) !void {
    try self.passes.append(pass);
}

pub fn run(self: *const PassManager, ctx: *PassContext) !void {

        for (self.passes.items) |pass| {
            const preserved = try pass.run(ctx);
            ctx.analysis.invalidatePreserved(preserved);
        }
    }
};

const std = @import("std");

/// Analysis identifiers (bitmask-based).
/// Dependencies: cfg → (post_dominators) → dominators → loops → scalar_evolution
pub const AnalysisKind = enum(u8) {
    cfg,
    dominators,
    post_dominators,
    loops,
    scalar_evolution,

memory_ssa,
alias,
call_graph,
_,

pub fn fromName(comptime name: []const u8) AnalysisKind {
    return comptime std.meta.stringToEnum(AnalysisKind, name) orelse @compileError("unknown analysis: " ++ name);
}

/// Returns true if preserving `this` implies preserving `other`

/// (e.g. preserving dominators implies preserving cfg).
pub fn implies(self: AnalysisKind, other: AnalysisKind) bool {
    return switch (self) {
        .call_graph => other == .call_graph,
        .scalar_evolution => other == .scalar_evolution or other == .loops or other == .dominators or other == .cfg,
        .loops => other == .loops or other == .dominators or other == .cfg,
        .dominators => other == .dominators or other == .cfg,
        .post_dominators => other == .post_dominators or other == .cfg,
        .memory_ssa => other == .memory_ssa or other == .alias or other == .cfg,
        .alias => other == .alias,

            .cfg => other == .cfg,
            _ => self == other,
        };
    }
};

const BitMask = u16;

/// PreservedAnalyses bitmask.
pub const PreservedAnalyses = struct {

mask: BitMask = 0,

pub fn preserve(self: *PreservedAnalyses, a: AnalysisKind) void {
    self.mask |= @as(BitMask, 1) << @intCast(@intFromEnum(a));
}

pub fn isPreserved(self: PreservedAnalyses, a: AnalysisKind) bool {
    return (self.mask & (@as(BitMask, 1) << @intCast(@intFromEnum(a)))) != 0;
}

pub fn all() PreservedAnalyses {
    return PreservedAnalyses{ .mask = ~@as(BitMask, 0) };
}

pub fn none() PreservedAnalyses {
    return PreservedAnalyses{ .mask = 0 };
}

pub fn merge(self: *PreservedAnalyses, other: PreservedAnalyses) void {
    self.mask &= other.mask;

    }
};

/// Legacy ChangeSet (kept for backward compat, new Pass API uses PreservedAnalyses directly).
pub const ChangeSet = struct {
    changed: bool = false,
    preserved: PreservedAnalyses = PreservedAnalyses.none(),
    analyses_cleared: bool = false,

    pub fn none() ChangeSet {

    return ChangeSet{};
}

pub fn all() ChangeSet {
    return ChangeSet{ .preserved = PreservedAnalyses.all() };
}

pub fn identity() ChangeSet {
    return ChangeSet{ .preserved = PreservedAnalyses.all() };
}

    pub fn preserve(self: *ChangeSet, a: AnalysisKind) void {
        self.preserved.preserve(a);
    }

    pub fn clearsAll(self: *const ChangeSet) bool {
        return self.analyses_cleared;
    }
};

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;
const ValueId = bir.ValueId;
const BlockId = bir.BlockId;
const PreservedAnalyses = bir.PreservedAnalyses;
const Module = bir.Module;

pub const CFGSimplifyPass = bir.Pass{
    .name = "cfg-simplify",
    .run = runCFGSimplify,
};

fn runCFGSimplify(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    const allocator = ctx.allocator;
    var changed = true;

while (changed) {
    changed = false;

    for (module.functions.items, 0..) |*func, fid| {
        if (func.blocks.items.len < 2) continue;
        const func_id = @as(bir.FunctionId, @intCast(fid));

        var cfg2 = try bir_cfg.buildCFG(allocator, func);
        defer cfg2.deinit();

    changed = try mergeStraightLine(module, func_id, func, &cfg2) or changed;
}

for (module.functions.items, 0..) |*func, fid| {
    if (func.blocks.items.len < 2) continue;
    const func_id = @as(bir.FunctionId, @intCast(fid));

    var cfg = try bir_cfg.buildCFG(allocator, func);
    defer cfg.deinit();

            changed = try redirectToSingleSuccessor(module, func_id, func, &cfg) or changed;
        }
    }
    return PreservedAnalyses.none();
}

fn redirectToSingleSuccessor(
    _: *Module,
    _: bir.FunctionId,
    func: *bir.Function,

    cfg: *const bir_cfg.CFG,
) !bool {
    var changed = false;
    var i: usize = func.blocks.items.len;
    while (i > 0) {
        i -= 1;
        const bid = @as(BlockId, @intCast(i));
        if (bid == cfg.entry) continue;

        const block = func.getBlock(bid);

if (block.instrs.items.len == 0) continue;

const last = &block.instrs.items[block.instrs.items.len - 1];
if (last.op != .br) continue;

const target = last.data.block_target;
if (target == bid) continue;

const preds = func.blocks.items[bid].preds.items;
if (preds.len == 0) continue;

        for (preds) |pred| {
            replaceBranchTarget(func, pred, bid, target);
        }

        changed = true;
    }
    return changed;
}

fn mergeStraightLine(
    module: *Module,
    func_id: bir.FunctionId,
    func: *bir.Function,
    cfg: *const bir_cfg.CFG,
) !bool {
    var changed = false;
    var i: usize = func.blocks.items.len;
    while (i > 0) {
        i -= 1;

const bid = @as(BlockId, @intCast(i));
if (bid == cfg.entry) continue;

const preds = func.blocks.items[bid].preds.items;
if (preds.len != 1) continue;

const pred = preds[0];
if (pred == bid) continue;

const pred_block = func.getBlock(pred);

if (pred_block.instrs.items.len == 0) continue;

const pred_term = &pred_block.instrs.items[pred_block.instrs.items.len - 1];
if (pred_term.op != .br) continue;
if (pred_term.data.block_target != bid) continue;

const target_block = func.getBlock(bid);
if (target_block.instrs.items.len == 0) continue;

const term_idx = pred_block.instrs.items.len - 1;

_ = pred_block.instrs.orderedRemove(term_idx);

for (target_block.instrs.items) |*src_inst| {
    const new_operands = try module.allocator.dupe(ValueId, src_inst.operands);

    const new_val = try module.addInst(func_id, pred, .{
        .op = src_inst.op,
        .ty = src_inst.ty,
        .result = NO_VALUE,
        .operands = new_operands,

                .data = cloneInstData(module.allocator, &src_inst.data),
            });

            replaceAllUses(func, src_inst.result, new_val);
        }

        changed = true;
    }
    return changed;
}

fn replaceBranchTarget(func: *bir.Function, from: BlockId, old_target: BlockId, new_target: BlockId) void {
    const block = func.getBlock(from);
    if (block.instrs.items.len == 0) return;
    const term = &block.instrs.items[block.instrs.items.len - 1];
    switch (term.op) {
        .br => {
            if (term.data.block_target == old_target) {
                term.data.block_target = new_target;
            }

},
.cond_br => {
    if (term.data.cond_branch.then_block == old_target) {
        term.data.cond_branch.then_block = new_target;
    }
    if (term.data.cond_branch.else_block == old_target) {
        term.data.cond_branch.else_block = new_target;
    }
},
else => {},

    }
}

fn cloneInstData(allocator: Allocator, data: *const bir.Inst.Data) bir.Inst.Data {
    switch (data.*) {
        .const_data => |cd| return .{ .const_data = cd },
        .block_target => |bt| return .{ .block_target = bt },
        .cond_branch => |cb| return .{ .cond_branch = cb },
        .none => return .{ .none = {} },
        .string => |s| return .{ .string = allocator.dupe(u8, s) catch return .{ .none = {} } },

.phi_incoming => |inc| return .{ .phi_incoming = allocator.dupe(bir.PhiIncoming, inc) catch return .{ .none = {} } },
.cast_info => |ci| return .{ .cast_info = ci },
.call_info => |ci| return .{ .call_info = .{
    .callee = ci.callee,
    .args = allocator.dupe(ValueId, ci.args) catch return .{ .none = {} },
} },
.gep_info => |gi| return .{ .gep_info = .{
    .ptr = gi.ptr,
    .indices = allocator.dupe(ValueId, gi.indices) catch return .{ .none = {} },
    .result_elem_type = gi.result_elem_type,

} },
.named_call => |nc| return .{ .named_call = .{
    .name = allocator.dupe(u8, nc.name) catch return .{ .none = {} },
    .args = allocator.dupe(ValueId, nc.args) catch return .{ .none = {} },
} },
.atomic_info => |ai| return .{ .atomic_info = ai },
.sample_info => |si| return .{ .sample_info = si },
.barrier_kind => |bk| return .{ .barrier_kind = bk },
.extract_info => |ei| return .{ .extract_info = ei },
.texture_store_info => |tsi| return .{ .texture_store_info = tsi },

    .vector_shuffle => |vs| return .{ .vector_shuffle = .{
        .a = vs.a,
        .b = vs.b,
        .mask = allocator.dupe(u32, vs.mask) catch return .{ .none = {} },
    } },
    .group_info => |gi| return .{ .group_info = gi },
    .fence_info => |fi| return .{ .fence_info = fi },
    .groupshared_size => |gs| return .{ .groupshared_size = gs },
    .branch_on_bit => |bb| return .{ .branch_on_bit = bb },
}

}

fn replaceAllUses(func: *bir.Function, old_val: ValueId, new_val: ValueId) void {
    if (old_val == new_val) return;
    if (old_val > func.locals_count) return;
    const old_vi = func.getValueInfo(old_val);
    const uses_copy = func.allocator.dupe(ValueId, old_vi.uses.items) catch return;
    defer func.allocator.free(uses_copy);

    for (uses_copy) |user_val| {

if (user_val == NO_VALUE or user_val > func.locals_count) continue;
const user_vi = func.getValueInfo(user_val);
if (user_vi.def.block == INVALID_ID) continue;
if (user_vi.def.block >= func.blocks.items.len) continue;
const block = func.getBlock(user_vi.def.block);
if (user_vi.def.idx >= block.instrs.items.len) continue;
const inst = &block.instrs.items[user_vi.def.idx];

for (inst.operands) |*op| {
    if (op.* == old_val) op.* = new_val;

}
switch (inst.data) {
    .phi_incoming => |incoming| {
        for (incoming) |*inc| {
            if (inc.value == old_val) inc.value = new_val;
        }
    },
    .cond_branch => |*cb| {
        if (cb.cond == old_val) cb.cond = new_val;
    },

.call_info => |*ci| {
    if (ci.callee == old_val) ci.callee = new_val;
    for (ci.args) |*arg| {
        if (arg.* == old_val) arg.* = new_val;
    }
},
.gep_info => |*gi| {
    if (gi.ptr == old_val) gi.ptr = new_val;
    for (gi.indices) |*idx| {
        if (idx.* == old_val) idx.* = new_val;

    }
},
.texture_store_info => |*tsi| {
    if (tsi.tex == old_val) tsi.tex = new_val;
    if (tsi.coord_x == old_val) tsi.coord_x = new_val;
    if (tsi.coord_y == old_val) tsi.coord_y = new_val;
    if (tsi.val == old_val) tsi.val = new_val;
},
.sample_info => |*si| {
    if (si.tex == old_val) si.tex = new_val;

    if (si.sampler == old_val) si.sampler = new_val;
    if (si.coord == old_val) si.coord = new_val;
    if (si.lod) |*lod| {
        if (lod.* == old_val) lod.* = new_val;
    }
    if (si.offset) |*off| {
        if (off.* == old_val) off.* = new_val;
    }
},
.atomic_info => |*ai| {

            if (ai.ptr == old_val) ai.ptr = new_val;
            if (ai.val == old_val) ai.val = new_val;
        },
        else => {},
    }

    const new_vi = func.getValueInfo(new_val);
    new_vi.uses.append(user_val) catch {};
}

