const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const bir_dominators = @import("../../analysis/dominator/dominator.zig");
const bir_loops = @import("../../analysis/loops/loops.zig");
const PreservedAnalyses = bir.PreservedAnalyses;
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;
const BlockId = bir.BlockId;

const ValueId = bir.ValueId;

pub const IVStrengthReducePass = bir.Pass{
    .name = "iv-strength-reduce",
    .run = runIVStrengthReduce,
};

fn runIVStrengthReduce(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    for (module.functions.items, 0..) |*func, fid| {

if (func.blocks.items.len < 3) continue;
const func_id = @as(bir.FunctionId, @intCast(fid));

const cfg = try ctx.analysis.getCFG(func_id);
const loop_info = try ctx.analysis.getLoopInfo(func_id);
const loops = loop_info.loops;

for (loops) |loop| {
    try reduceLoop(module, func_id, func, cfg, &loop);
}

    }
    return PreservedAnalyses.none();
}

const LoopIV = struct {
    phi_val: ValueId,
    init_val: ValueId,
    step_val: i64,
    cmp_op: bir.Op,
};

const MulCand = struct {
    result: ValueId,
    k: i64,
};

fn reduceLoop(module: *bir.Module, func_id: bir.FunctionId, func: *bir.Function, _: *const bir_cfg.CFG, loop: *const bir_loops.Loop) !void {
    if (loop.back_edges.len != 1) return;

    const header = loop.header;

const latch = loop.back_edges[0].from;
const preheader = findPreheader(func, loop) orelse return;

const iv = detectIV(func, loop, preheader, latch) orelse return;

var candidates = std.ArrayList(MulCand).init(module.allocator);
defer candidates.deinit();

for (loop.body) |bid| {
    const block = func.getBlock(bid);

for (block.instrs.items) |*inst| {
    if (inst.op != .mul) continue;
    if (inst.result == NO_VALUE) continue;

    const iv_idx: ?usize = for (inst.operands, 0..) |op, i| {
        if (op == iv.phi_val) break i;
    } else null;
    if (iv_idx == null) continue;

    const other = inst.operands[1 - iv_idx.?];

        const k = getConstInt(func, other) orelse continue;
        if (k <= 1) continue;

        try candidates.append(.{ .result = inst.result, .k = k });
    }
}

if (candidates.items.len == 0) return;

for (candidates.items) |cand| {

const mul_step = iv.step_val * cand.k;
const mul_init = (getConstInt(func, iv.init_val) orelse continue) * cand.k;

const acc_phi = try module.addPhi(func_id, header, getIVType(func, iv.phi_val), try module.allocator.dupe(bir.PhiIncoming, &.{
    .{ .value = NO_VALUE, .block = preheader },
    .{ .value = NO_VALUE, .block = latch },
}));

const init_c = try emitConstBefore(module, func, header, mul_init);
{

const hdr = func.getBlock(header);
for (hdr.instrs.items) |*inst| {
    if (inst.op != .phi) continue;
    if (inst.result != acc_phi) continue;
    for (inst.data.phi_incoming) |*inc| {
        if (inc.block == preheader) inc.value = init_c;
        if (inc.block == latch) inc.value = cand.result;
    }
    break;
}

}

const step_c = try emitConstBeforeTerminator(module, func, latch, mul_step);
const acc_next = try emitAddBeforeTerminator(module, func, latch, acc_phi, step_c);

{
    const hdr = func.getBlock(header);
    for (hdr.instrs.items) |*inst| {
        if (inst.op != .phi) continue;
        if (inst.result != acc_phi) continue;

        for (inst.data.phi_incoming) |*inc| {
            if (inc.block == latch) {
                inc.value = acc_next;
                break;
            }
        }
        break;
    }
}

    replaceAllUsesOf(func, cand.result, acc_phi);
}

for (loop.body) |bid| {
    const block = func.getBlock(bid);
    var i: usize = 0;
    while (i < block.instrs.items.len) {
        const inst = &block.instrs.items[i];
        if (inst.op == .mul and inst.result != NO_VALUE) {
            var dominated = false;

for (candidates.items) |cand| {
    if (cand.result == inst.result) {
        dominated = true;
        break;
    }
}
if (dominated) {
    module.removeInst(func_id, bid, @as(u32, @intCast(i)));
    continue;
}

            }
            i += 1;
        }
    }

    module.rebuildUses();
}

fn emitConstBefore(_: *bir.Module, func: *bir.Function, block_id: BlockId, val: i64) !ValueId {
    const block = func.getBlock(block_id);

var insert_idx: usize = 0;
for (block.instrs.items) |inst| {
    if (inst.op == .phi) {
        insert_idx += 1;
    } else {
        break;
    }
}
const vid = try func.createValue();
try block.instrs.insert(insert_idx, .{

        .op = .@"const",
        .ty = bir.types.INVALID_TYPE,
        .result = vid,
        .operands = &.{},
        .data = .{ .const_data = .{ .int = val } },
    });
    func.getValueInfo(vid).def = .{ .block = block_id, .idx = @as(u32, @intCast(insert_idx)) };
    shiftDefsAfter(func, block_id, insert_idx + 1);
    return vid;
}

fn emitConstBeforeTerminator(_: *bir.Module, func: *bir.Function, block_id: BlockId, val: i64) !ValueId {
    const block = func.getBlock(block_id);
    const insert_idx: usize = block.instrs.items.len - 1;
    const vid = try func.createValue();
    try block.instrs.insert(insert_idx, .{
        .op = .@"const",
        .ty = bir.types.INVALID_TYPE,
        .result = vid,
        .operands = &.{},

        .data = .{ .const_data = .{ .int = val } },
    });
    func.getValueInfo(vid).def = .{ .block = block_id, .idx = @as(u32, @intCast(insert_idx)) };
    shiftDefsAfter(func, block_id, insert_idx + 1);
    return vid;
}

fn emitAddBeforeTerminator(module: *bir.Module, func: *bir.Function, block_id: BlockId, lhs: ValueId, rhs: ValueId) !ValueId {
    const block = func.getBlock(block_id);
    const insert_idx: usize = block.instrs.items.len - 1;

const vid = try func.createValue();
try block.instrs.insert(insert_idx, .{
    .op = .add,
    .ty = getIVType(func, lhs),
    .result = vid,
    .operands = try module.allocator.dupe(ValueId, &.{ lhs, rhs }),
    .data = .{ .none = {} },
});
func.getValueInfo(vid).def = .{ .block = block_id, .idx = @as(u32, @intCast(insert_idx)) };
try func.getValueInfo(lhs).uses.append(vid);

    try func.getValueInfo(rhs).uses.append(vid);
    shiftDefsAfter(func, block_id, insert_idx + 1);
    return vid;
}

fn shiftDefsAfter(func: *bir.Function, block_id: BlockId, after_idx: usize) void {
    const block = func.getBlock(block_id);
    var i: u32 = @as(u32, @intCast(after_idx));
    while (i < block.instrs.items.len) : (i += 1) {
        const shifted = &block.instrs.items[i];

        if (shifted.result != NO_VALUE) {
            func.getValueInfo(shifted.result).def.idx = i;
        }
    }
}

fn replaceAllUsesOf(func: *bir.Function, old_val: ValueId, new_val: ValueId) void {
    if (old_val == new_val) return;
    const old_vi = func.getValueInfo(old_val);
    const uses_copy = func.allocator.dupe(ValueId, old_vi.uses.items) catch return;

defer func.allocator.free(uses_copy);

for (uses_copy) |user_val| {
    if (user_val == NO_VALUE or user_val > func.value_info.items.len) continue;
    const user_vi = func.getValueInfo(user_val);
    if (user_vi.def.block == INVALID_ID) continue;
    if (user_vi.def.block >= func.blocks.items.len) continue;
    const block = func.getBlock(user_vi.def.block);
    if (user_vi.def.idx >= block.instrs.items.len) continue;
    const inst = &block.instrs.items[user_vi.def.idx];

for (inst.operands) |*op| {
    if (op.* == old_val) op.* = new_val;
}
switch (inst.data) {
    .phi_incoming => |incoming| {
        for (incoming) |*inc| {
            if (inc.value == old_val) inc.value = new_val;
        }
    },

.cond_branch => |*cb| {
    if (cb.cond == old_val) cb.cond = new_val;
},
.texture_store_info => |*tsi| {
    if (tsi.tex == old_val) tsi.tex = new_val;
    if (tsi.coord_x == old_val) tsi.coord_x = new_val;
    if (tsi.coord_y == old_val) tsi.coord_y = new_val;
    if (tsi.val == old_val) tsi.val = new_val;
},
.sample_info => |*si| {

    if (si.tex == old_val) si.tex = new_val;
    if (si.sampler == old_val) si.sampler = new_val;
    if (si.coord == old_val) si.coord = new_val;
    if (si.lod) |*lod| { if (lod.* == old_val) lod.* = new_val; }
    if (si.offset) |*off| { if (off.* == old_val) off.* = new_val; }
},
.call_info => |*ci| {
    if (ci.callee == old_val) ci.callee = new_val;
    for (ci.args) |*arg| { if (arg.* == old_val) arg.* = new_val; }
},

.gep_info => |*gi| {
    if (gi.ptr == old_val) gi.ptr = new_val;
    for (gi.indices) |*idx| { if (idx.* == old_val) idx.* = new_val; }
},
.named_call => |*nc| {
    for (nc.args) |*arg| { if (arg.* == old_val) arg.* = new_val; }
},
.atomic_info => |*ai| {
    if (ai.ptr == old_val) ai.ptr = new_val;
    if (ai.val == old_val) ai.val = new_val;

            },
            else => {},
        }
    }

    old_vi.uses.clearRetainingCapacity();
}

fn detectIV(func: *bir.Function, loop: *const bir_loops.Loop, preheader: BlockId, latch: BlockId) ?LoopIV {
    const header = loop.header;

const hdr = func.getBlock(header);
if (hdr.instrs.items.len < 2) return null;

const term = &hdr.instrs.items[hdr.instrs.items.len - 1];
if (term.op != .cond_br) return null;

const cond_val = term.data.cond_branch.cond;
const cond_def = getDef(func, cond_val) orelse return null;

const is_cmp = switch (cond_def.op) {

    .lt, .le, .gt, .ge, .eq, .ne => true,
    else => false,
};
if (!is_cmp) return null;

var bound_val: ?i64 = null;
for (cond_def.operands) |op| {
    const op_def = getDef(func, op);
    if (op_def != null and op_def.?.op == .@"const") {
        if (op_def.?.data.const_data == .int) {

            bound_val = op_def.?.data.const_data.int;
        }
    }
}
if (bound_val == null) return null;

for (hdr.instrs.items) |*inst| {
    if (inst.op != .phi) continue;
    const incoming = inst.data.phi_incoming;
    if (incoming.len != 2) continue;

var from_preheader: ?ValueId = null;
var from_latch: ?ValueId = null;
for (incoming) |inc| {
    if (inc.block == preheader) from_preheader = inc.value;
    if (inc.block == latch) from_latch = inc.value;
}
if (from_preheader == null or from_latch == null) continue;

const init_def = getDef(func, from_preheader.?);

if (init_def == null or init_def.?.op != .@"const") continue;
if (init_def.?.data.const_data != .int) continue;

const latch_def = getDef(func, from_latch.?);
if (latch_def == null) continue;

if (latch_def.?.op != .add and latch_def.?.op != .sub) continue;

var step_val: i64 = undefined;
var has_iv = false;

var step_detected = false;
for (latch_def.?.operands) |op| {
    if (op == inst.result) {
        has_iv = true;
        continue;
    }
    const op_def = getDef(func, op);
    if (op_def != null and op_def.?.op == .@"const") {
        if (op_def.?.data.const_data == .int) {
            step_val = if (latch_def.?.op == .add) op_def.?.data.const_data.int else -op_def.?.data.const_data.int;

            step_detected = true;
        }
    }
}
if (!has_iv or !step_detected) continue;
if (step_val <= 0) continue;

return LoopIV{
    .phi_val = inst.result,
    .init_val = from_preheader.?,

            .step_val = step_val,
            .cmp_op = cond_def.op,
        };
    }

    return null;
}

fn findPreheader(func: *const bir.Function, loop: *const bir_loops.Loop) ?BlockId {
    const header = loop.header;

var result: ?BlockId = null;
for (func.blocks.items[header].preds.items) |pred| {
    var in_body = false;
    for (loop.body) |b| {
        if (b == pred) {
            in_body = true;
            break;
        }
    }
    if (!in_body) {

            if (result != null) return null;
            result = pred;
        }
    }
    return result;
}

fn getDef(func: *bir.Function, val: ValueId) ?*const bir.Inst {
    if (val == NO_VALUE) return null;
    if (val > func.value_info.items.len) return null;

    const vi = &func.value_info.items[val - 1];
    if (vi.def.block == INVALID_ID) return null;
    if (vi.def.block >= func.blocks.items.len) return null;
    const block = &func.blocks.items[vi.def.block];
    if (vi.def.idx >= block.instrs.items.len) return null;
    return &block.instrs.items[vi.def.idx];
}

fn getConstInt(func: *bir.Function, val: ValueId) ?i64 {
    const def = getDef(func, val) orelse return null;

    if (def.op != .@"const") return null;
    if (def.data.const_data == .int) return def.data.const_data.int;
    return null;
}

fn getIVType(func: *bir.Function, phi_val: ValueId) bir.TypeId {
    const vi = func.getValueInfo(phi_val);
    if (vi.def.block == INVALID_ID) return bir.types.INVALID_TYPE;
    if (vi.def.block >= func.blocks.items.len) return bir.types.INVALID_TYPE;
    const block = &func.blocks.items[vi.def.block];

    if (vi.def.idx >= block.instrs.items.len) return bir.types.INVALID_TYPE;
    return block.instrs.items[vi.def.idx].ty;
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const bir_dominators = @import("../../analysis/dominator/dominator.zig");
const bir_loops = @import("../../analysis/loops/loops.zig");
const PreservedAnalyses = bir.PreservedAnalyses;
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;

pub const LICMPass = bir.Pass{
    .name = "licm",
    .run = runLICM,
};

fn runLICM(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    for (module.functions.items, 0..) |*func, fid| {
        if (func.blocks.items.len < 2) continue;
        const func_id = @as(bir.FunctionId, @intCast(fid));

    const cfg = try ctx.analysis.getCFG(func_id);
    const dom_tree = try ctx.analysis.getDomTree(func_id);
    const loop_info = try ctx.analysis.getLoopInfo(func_id);
    const loops = loop_info.loops;

    for (loops) |loop| {
        try hoistLoop(module, func_id, func, cfg, dom_tree, &loop);
    }
}

    return PreservedAnalyses.none();
}

fn hoistLoop(module: *bir.Module, func_id: bir.FunctionId, func: *bir.Function, cfg: *const bir_cfg.CFG, _: *const bir_dominators.DominatorTree, loop: *const bir_loops.Loop) !void {
    const allocator = module.allocator;
    const preheader = findPreheader(func, loop) orelse return;

    var in_loop_set = try allocator.alloc(bool, func.blocks.items.len);
    defer allocator.free(in_loop_set);
    @memset(in_loop_set, false);

for (loop.body) |b| {
    if (b < func.blocks.items.len) in_loop_set[b] = true;
}

var invariant = std.AutoHashMap(bir.ValueId, void).init(allocator);
defer invariant.deinit();

var changed = true;
while (changed) {
    changed = false;

for (cfg.rpo.items) |bid| {
    if (!in_loop_set[bid]) continue;
    const block = func.getBlock(bid);
    for (block.instrs.items) |*inst| {
        if (inst.result == NO_VALUE) continue;
        if (inst.op == .phi) continue;
        if (invariant.contains(inst.result)) continue;
        if (!isHoistable(inst.op)) continue;
        if (allOperandsInvariant(func, in_loop_set, &invariant, inst)) {
            try invariant.put(inst.result, {});

                changed = true;
            }
        }
    }
}

if (invariant.count() == 0) return;

var old_to_new = std.AutoHashMap(bir.ValueId, bir.ValueId).init(allocator);
defer old_to_new.deinit();

for (cfg.rpo.items) |bid| {
    if (!in_loop_set[bid]) continue;
    const block = func.getBlock(bid);
    const block_instrs = try allocator.dupe(bir.Inst, block.instrs.items);
    defer allocator.free(block_instrs);

    for (block_instrs) |*inst| {
        if (inst.result == NO_VALUE) continue;
        if (!invariant.contains(inst.result)) continue;

var new_operands = try allocator.dupe(bir.ValueId, inst.operands);
for (new_operands, 0..) |op, j| {
    if (old_to_new.get(op)) |new_op| {
        new_operands[j] = new_op;
    }
}

const new_val = try module.addInst(func_id, preheader, .{
    .op = inst.op,

            .ty = inst.ty,
            .result = NO_VALUE,
            .operands = new_operands,
            .data = cloneData(allocator, &inst.data),
        });
        try old_to_new.put(inst.result, new_val);
    }
}

for (cfg.rpo.items) |bid| {

if (!in_loop_set[bid]) continue;
const block = func.getBlock(bid);
for (block.instrs.items) |*inst| {
    for (inst.operands, 0..) |op, j| {
        if (old_to_new.get(op)) |new_op| {
            inst.operands[j] = new_op;
        }
    }
    switch (inst.data) {
        .phi_incoming => |incoming| {

    for (incoming) |*inc| {
        if (old_to_new.get(inc.value)) |nv| inc.value = nv;
    }
},
.texture_store_info => |*tsi| {
    if (old_to_new.get(tsi.tex)) |nv| tsi.tex = nv;
    if (old_to_new.get(tsi.coord_x)) |nv| tsi.coord_x = nv;
    if (old_to_new.get(tsi.coord_y)) |nv| tsi.coord_y = nv;
    if (old_to_new.get(tsi.val)) |nv| tsi.val = nv;
},

.sample_info => |*si| {
    if (old_to_new.get(si.tex)) |nv| si.tex = nv;
    if (old_to_new.get(si.sampler)) |nv| si.sampler = nv;
    if (old_to_new.get(si.coord)) |nv| si.coord = nv;
    if (si.lod) |*lod| { if (old_to_new.get(lod.*)) |nv| lod.* = nv; }
    if (si.offset) |*off| { if (old_to_new.get(off.*)) |nv| off.* = nv; }
},
.call_info => |*ci| {
    if (old_to_new.get(ci.callee)) |nv| ci.callee = nv;
    for (ci.args) |*arg| {

        if (old_to_new.get(arg.*)) |nv| arg.* = nv;
    }
},
.gep_info => |*gi| {
    if (old_to_new.get(gi.ptr)) |nv| gi.ptr = nv;
    for (gi.indices) |*idx| {
        if (old_to_new.get(idx.*)) |nv| idx.* = nv;
    }
},
.cond_branch => |*cb| {

                if (old_to_new.get(cb.cond)) |nv| cb.cond = nv;
            },
            .atomic_info => |*ai| {
                if (old_to_new.get(ai.ptr)) |nv| ai.ptr = nv;
                if (old_to_new.get(ai.val)) |nv| ai.val = nv;
            },
            else => {},
        }
    }
}

    module.rebuildUses();
}

fn findPreheader(func: *const bir.Function, loop: *const bir_loops.Loop) ?bir.BlockId {
    const header = loop.header;
    var result: ?bir.BlockId = null;
    for (func.blocks.items[header].preds.items) |pred| {
        var in_body = false;
        for (loop.body) |b| {

        if (b == pred) {
            in_body = true;
            break;
        }
    }
    if (!in_body) {
        if (result != null) return null;
        result = pred;
    }
}

    return result;
}

fn isHoistable(op: bir.Op) bool {
    return switch (op) {
        .add, .sub, .mul, .div, .mod, .neg,
        .fadd, .fsub, .fmul, .fdiv, .fmod, .fneg, .fma,
        .sqrt, .rsqrt, .exp, .log, .sin, .cos,
        .floor, .ceil, .frac, .abs, .saturate, .lerp,
        .eq, .ne, .lt, .le, .gt, .ge,

    };
}

fn allOperandsInvariant(func: *const bir.Function, in_loop_set: []const bool, invariant: *const std.AutoHashMap(bir.ValueId, void), inst: *const bir.Inst) bool {
    for (inst.operands) |op_val| {
        if (op_val == NO_VALUE) continue;
        if (!isValueLoopInvariant(func, in_loop_set, invariant, op_val)) return false;
    }

    switch (inst.data) {

.sample_info => |si| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, si.tex)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, si.sampler)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, si.coord)) return false;
    if (si.lod) |lod| {
        if (!isValueLoopInvariant(func, in_loop_set, invariant, lod)) return false;
    }
    if (si.offset) |off| {
        if (!isValueLoopInvariant(func, in_loop_set, invariant, off)) return false;
    }

},
.texture_store_info => |tsi| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, tsi.tex)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, tsi.coord_x)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, tsi.coord_y)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, tsi.val)) return false;
},
.phi_incoming => |incoming| {
    for (incoming) |inc| {
        if (!isValueLoopInvariant(func, in_loop_set, invariant, inc.value)) return false;

    }
},
.call_info => |ci| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, ci.callee)) return false;
    for (ci.args) |arg| {
        if (!isValueLoopInvariant(func, in_loop_set, invariant, arg)) return false;
    }
},
.gep_info => |gi| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, gi.ptr)) return false;

    for (gi.indices) |idx| {
        if (!isValueLoopInvariant(func, in_loop_set, invariant, idx)) return false;
    }
},
.cond_branch => |cb| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, cb.cond)) return false;
},
.atomic_info => |ai| {
    if (!isValueLoopInvariant(func, in_loop_set, invariant, ai.ptr)) return false;
    if (!isValueLoopInvariant(func, in_loop_set, invariant, ai.val)) return false;

        },
        .vector_shuffle => |vs| {
            if (!isValueLoopInvariant(func, in_loop_set, invariant, vs.a)) return false;
            if (!isValueLoopInvariant(func, in_loop_set, invariant, vs.b)) return false;
        },
        else => {},
    }

    return true;
}

fn isValueLoopInvariant(func: *const bir.Function, in_loop_set: []const bool, invariant: *const std.AutoHashMap(bir.ValueId, void), val: bir.ValueId) bool {
    if (val == NO_VALUE) return true;
    const vi = &func.value_info.items[val - 1];
    if (vi.def.block == INVALID_ID) return true;
    if (vi.def.block >= func.blocks.items.len) return true;
    if (!in_loop_set[vi.def.block]) return true;
    if (invariant.contains(val)) return true;
    return false;
}

fn cloneData(allocator: Allocator, data: *const bir.Inst.Data) bir.Inst.Data {
    switch (data.*) {
        .string => |s| return .{ .string = allocator.dupe(u8, s) catch return .{ .none = {} } },
        .phi_incoming => |incoming| {
            const copy = allocator.dupe(bir.PhiIncoming, incoming) catch return .{ .none = {} };
            return .{ .phi_incoming = copy };
        },
        .call_info => |ci| {
            const args_copy = allocator.dupe(bir.ValueId, ci.args) catch return .{ .none = {} };

    return .{ .call_info = .{ .callee = ci.callee, .args = args_copy } };
},
.gep_info => |gi| {
    const idx_copy = allocator.dupe(bir.ValueId, gi.indices) catch return .{ .none = {} };
    return .{ .gep_info = .{ .ptr = gi.ptr, .indices = idx_copy, .result_elem_type = gi.result_elem_type } };
},
.vector_shuffle => |vs| {
    const mask_copy = allocator.dupe(u32, vs.mask) catch return .{ .none = {} };
    return .{ .vector_shuffle = .{ .a = vs.a, .b = vs.b, .mask = mask_copy } };
},

        else => return data.*,
    }
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const bir_dominators = @import("../../analysis/dominator/dominator.zig");
const bir_loops = @import("../../analysis/loops/loops.zig");
const PreservedAnalyses = bir.PreservedAnalyses;
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;
const BlockId = bir.BlockId;

const ValueId = bir.ValueId;

pub const LoopRotatePass = bir.Pass{
    .name = "loop-rotate",
    .run = runLoopRotate,
};

fn runLoopRotate(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    for (module.functions.items, 0..) |*func, fid| {

if (func.blocks.items.len < 3) continue;
const func_id = @as(bir.FunctionId, @intCast(fid));

const cfg = try ctx.analysis.getCFG(func_id);
const loop_info = try ctx.analysis.getLoopInfo(func_id);
const loops = loop_info.loops;

for (loops) |loop| {
    try rotateLoop(module, func_id, func, cfg, &loop);
}

    }
    return PreservedAnalyses.none();
}

fn rotateLoop(module: *bir.Module, func_id: bir.FunctionId, func: *bir.Function, _: *const bir_cfg.CFG, loop: *const bir_loops.Loop) !void {
    if (loop.back_edges.len != 1) return;

    const header = loop.header;
    const latch = loop.back_edges[0].from;
    const preheader = findPreheader(func, loop) orelse return;

const hdr = func.getBlock(header);
if (hdr.instrs.items.len < 2) return;

const hdr_term = &hdr.instrs.items[hdr.instrs.items.len - 1];
if (hdr_term.op != .cond_br) return;

const cond_val = hdr_term.data.cond_branch.cond;
const body_bid = hdr_term.data.cond_branch.then_block;
const exit_bid = hdr_term.data.cond_branch.else_block;

const cmp_idx = findDefIdxInBlock(func, header, cond_val) orelse return;
const cmp_inst = &hdr.instrs.items[cmp_idx];

const is_cmp = switch (cmp_inst.op) {
    .lt, .le, .gt, .ge, .eq, .ne => true,
    else => false,
};
if (!is_cmp) return;
if (cmp_inst.operands.len != 2) return;

var phi_operand_idx: ?usize = null;
for (cmp_inst.operands, 0..) |op, i| {
    if (isPhiInBlock(func, header, op)) {
        phi_operand_idx = i;
        break;
    }
}
if (phi_operand_idx == null) return;

const bound_val = cmp_inst.operands[1 - phi_operand_idx.?];

const phi_val = cmp_inst.operands[phi_operand_idx.?];
const phi_inst_idx = findDefIdxInBlock(func, header, phi_val) orelse return;
const phi_inst = &hdr.instrs.items[phi_inst_idx];
if (phi_inst.op != .phi) return;

var init_val: ?ValueId = null;
var next_val: ?ValueId = null;
for (phi_inst.data.phi_incoming) |inc| {

    if (inc.block == preheader) init_val = inc.value;
    if (inc.block == latch) next_val = inc.value;
}
if (init_val == null or next_val == null) return;

const guard_bid = try module.addBlock(func_id, "loop.guard");

const cond_continues = (body_bid == hdr_term.data.cond_branch.then_block);
const guard_enter = if (cond_continues) header else exit_bid;
const guard_exit = if (cond_continues) exit_bid else header;

const guard_cmp_ops = if (phi_operand_idx.? == 0)
    try module.allocator.dupe(ValueId, &.{ init_val.?, bound_val })
else
    try module.allocator.dupe(ValueId, &.{ bound_val, init_val.? });
const guard_cmp = try module.addInst(func_id, guard_bid, .{
    .op = cmp_inst.op,
    .ty = cmp_inst.ty,
    .result = NO_VALUE,
    .operands = guard_cmp_ops,

    .data = .{ .none = {} },
});
_ = try module.addInst(func_id, guard_bid, .{
    .op = .cond_br,
    .ty = bir.types.INVALID_TYPE,
    .result = NO_VALUE,
    .operands = try module.allocator.dupe(ValueId, &.{guard_cmp}),
    .data = .{ .cond_branch = .{
        .cond = guard_cmp,
        .then_block = guard_enter,

        .else_block = guard_exit,
    } },
});

module.allocator.free(hdr_term.operands);
hdr_term.op = .br;
hdr_term.data = .{ .block_target = body_bid };
hdr_term.operands = &.{};

const latch_block = func.getBlock(latch);

const latch_last: u32 = @as(u32, @intCast(latch_block.instrs.items.len)) - 1;
const latch_last_inst = &latch_block.instrs.items[latch_last];
if (latch_last_inst.op != .br) return;
module.removeInst(func_id, latch, latch_last);

const latch_cmp_ops = if (phi_operand_idx.? == 0)
    try module.allocator.dupe(ValueId, &.{ next_val.?, bound_val })
else
    try module.allocator.dupe(ValueId, &.{ bound_val, next_val.? });
const latch_cmp = try module.addInst(func_id, latch, .{

    .op = cmp_inst.op,
    .ty = cmp_inst.ty,
    .result = NO_VALUE,
    .operands = latch_cmp_ops,
    .data = .{ .none = {} },
});
_ = try module.addInst(func_id, latch, .{
    .op = .cond_br,
    .ty = bir.types.INVALID_TYPE,
    .result = NO_VALUE,

    .operands = try module.allocator.dupe(ValueId, &.{latch_cmp}),
    .data = .{ .cond_branch = .{
        .cond = latch_cmp,
        .then_block = guard_enter,
        .else_block = guard_exit,
    } },
});

updateBranchTarget(func, preheader, header, guard_bid);

for (hdr.instrs.items) |*inst| {
    if (inst.op != .phi) continue;
    for (inst.data.phi_incoming) |*inc| {
        if (inc.block == preheader) {
            inc.block = guard_bid;
        }
    }
}

if (exit_bid < func.blocks.items.len) {

    const exit_block = func.getBlock(exit_bid);
    for (exit_block.instrs.items) |*inst| {
        if (inst.op != .phi) continue;
        for (inst.data.phi_incoming) |*inc| {
            if (inc.block == header) {
                inc.block = guard_bid;
            }
        }
    }
}

    module.rebuildUses();
}

fn findPreheader(func: *const bir.Function, loop: *const bir_loops.Loop) ?BlockId {
    const header = loop.header;
    var result: ?BlockId = null;
    for (func.blocks.items[header].preds.items) |pred| {
        var in_body = false;
        for (loop.body) |b| {

        if (b == pred) {
            in_body = true;
            break;
        }
    }
    if (!in_body) {
        if (result != null) return null;
        result = pred;
    }
}

    return result;
}

fn findDefIdxInBlock(func: *bir.Function, block_id: BlockId, val: ValueId) ?usize {
    if (val == NO_VALUE) return null;
    if (val > func.value_info.items.len) return null;
    const vi = &func.value_info.items[val - 1];
    if (vi.def.block != block_id) return null;
    const block = func.getBlock(block_id);
    if (vi.def.idx >= block.instrs.items.len) return null;

    return @as(usize, @intCast(vi.def.idx));
}

fn isPhiInBlock(func: *bir.Function, block_id: BlockId, val: ValueId) bool {
    const idx = findDefIdxInBlock(func, block_id, val) orelse return false;
    return func.getBlock(block_id).instrs.items[idx].op == .phi;
}

fn updateBranchTarget(func: *bir.Function, block_id: BlockId, old_target: BlockId, new_target: BlockId) void {
    const block = func.getBlock(block_id);

if (block.instrs.items.len == 0) return;
const term = &block.instrs.items[block.instrs.items.len - 1];
switch (term.op) {
    .br => {
        if (term.data.block_target == old_target) {
            term.data.block_target = new_target;
        }
    },
    .cond_br => {
        if (term.data.cond_branch.then_block == old_target) {

                term.data.cond_branch.then_block = new_target;
            }
            if (term.data.cond_branch.else_block == old_target) {
                term.data.cond_branch.else_block = new_target;
            }
        },
        else => {},
    }
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const Module = bir.Module;
const Op = bir.Op;
const Inst = bir.Inst;
const ValueId = bir.ValueId;
const BlockId = bir.BlockId;
const NO_VALUE = bir.NO_VALUE;

const PreservedAnalyses = bir.PreservedAnalyses;
const INVALID_ID = bir.INVALID_ID;

pub const SCCPPass = bir.Pass{
    .name = "sccp",
    .run = runSCCP,
};

// ─── Lattice: Top (undefined) | Const | Bottom (overdefined) ───

const Lattice = union(enum) {
    top: void,
    int_const: i64,
    bool_const: bool,
    bottom: void,

    fn meet(a: Lattice, b: Lattice) Lattice {
        if (a == .bottom or b == .bottom) return .{ .bottom = {} };
        if (a == .top) return b;
        if (b == .top) return a;

    if (a == .int_const and b == .int_const) {
        if (a.int_const == b.int_const) return a;
        return .{ .bottom = {} };
    }
    if (a == .bool_const and b == .bool_const) {
        if (a.bool_const == b.bool_const) return a;
        return .{ .bottom = {} };
    }
    return .{ .bottom = {} };
}

    fn isConstant(self: Lattice) bool {
        return self == .int_const or self == .bool_const;
    }
};

// ─── SCCP Solver ───

const InstOfEntry = struct { block: BlockId, idx: u32 };

const SCCPSolver = struct {
    allocator: Allocator,
    func: *bir.Function,
    cfg: *const bir_cfg.CFG,

    // Value lattice: indexed by ValueId - 1
    lattice: std.ArrayList(Lattice),

    // Block executability
    executable: std.ArrayList(bool),

// Worklists
value_worklist: std.ArrayList(ValueId),
edge_worklist: std.ArrayList(bir_cfg.Edge),
term_worklist: std.ArrayList(BlockId),

// Instructions that need re-evaluation, indexed by ValueId - 1
inst_of: std.ArrayList(InstOfEntry),

fn init(allocator: Allocator, func: *bir.Function, cfg: *const bir_cfg.CFG) !SCCPSolver {

const num_values = func.value_info.items.len;
var lattice = std.ArrayList(Lattice).init(allocator);
var inst_of = std.ArrayList(InstOfEntry).init(allocator);
var executable = std.ArrayList(bool).init(allocator);

try lattice.resize(num_values);
for (lattice.items) |*l| l.* = .{ .top = {} };

try inst_of.resize(num_values);
for (inst_of.items) |*io| io.* = .{ .block = INVALID_ID, .idx = INVALID_ID };

try executable.resize(func.blocks.items.len);
for (executable.items) |*e| e.* = false;

// Map value definitions to instructions
for (func.blocks.items, 0..) |*block, bi| {
    for (block.instrs.items, 0..) |inst, ii| {
        if (inst.result != NO_VALUE and inst.result <= num_values) {
            inst_of.items[inst.result - 1] = .{ .block = @as(BlockId, @intCast(bi)), .idx = @as(u32, @intCast(ii)) };
        }

    }
}

// Mark parameters as bottom (we don't know their values)
for (func.param_values) |pv| {
    if (pv != NO_VALUE and pv <= num_values) {
        lattice.items[pv - 1] = .{ .bottom = {} };
    }
}

    };
}

fn deinit(self: *SCCPSolver) void {
    self.lattice.deinit();
    self.executable.deinit();
    self.value_worklist.deinit();
    self.edge_worklist.deinit();
    self.term_worklist.deinit();
    self.inst_of.deinit();

}

fn run(self: *SCCPSolver) !void {
    self.executable.items[0] = true;
    try self.addBlockInstructions(0);

    while (self.value_worklist.items.len > 0 or self.edge_worklist.items.len > 0 or self.term_worklist.items.len > 0) {
        while (self.edge_worklist.items.len > 0) {
            const edge = self.edge_worklist.pop().?;
            if (!self.executable.items[edge.to]) {

        self.executable.items[edge.to] = true;
        try self.addBlockInstructions(edge.to);
    }
}

while (self.value_worklist.items.len > 0) {
    const vid = self.value_worklist.pop().?;
    if (vid == NO_VALUE or vid == 0) continue;
    if (vid > self.lattice.items.len) continue;

const def = self.inst_of.items[vid - 1];
if (def.block == INVALID_ID) continue;
if (!self.executable.items[def.block]) continue;

const block = &self.func.blocks.items[def.block];
if (def.idx >= block.instrs.items.len) continue;
const inst = &block.instrs.items[def.idx];

const old_lat = self.lattice.items[vid - 1];
const new_lat = self.evaluateInst(inst);

    if (new_lat == .bottom and old_lat != .bottom) {
        self.lattice.items[vid - 1] = .{ .bottom = {} };
        self.notifyUses(vid);
    } else if (new_lat.isConstant() and old_lat == .top) {
        self.lattice.items[vid - 1] = new_lat;
        self.notifyUses(vid);
    }
}

        while (self.term_worklist.items.len > 0) {
            const bid = self.term_worklist.pop().?;
            if (!self.executable.items[bid]) continue;
            const block = &self.func.blocks.items[bid];
            if (block.instrs.items.len == 0) continue;
            const last = block.instrs.items[block.instrs.items.len - 1];
            try self.addTerminatorEdges(bid, last);
        }
    }
}

fn notifyUses(self: *SCCPSolver, vid: ValueId) void {
    const vi = self.func.getValueInfo(vid);
    for (vi.uses.items) |user_val| {
        if (user_val == NO_VALUE or user_val == 0) continue;
        if (user_val > self.inst_of.items.len) continue;
        const def = self.inst_of.items[user_val - 1];
        if (def.block != INVALID_ID and self.executable.items[def.block]) {
            self.value_worklist.append(user_val) catch {};
        }

}
// Also re-evaluate terminators that might use this value
for (self.func.blocks.items, 0..) |*block, bi| {
    if (block.instrs.items.len == 0) continue;
    const last = block.instrs.items[block.instrs.items.len - 1];
    if (last.op == .cond_br) {
        if (last.data.cond_branch.cond == vid) {
            self.term_worklist.append(@as(BlockId, @intCast(bi))) catch {};
        }
    }

    }
}

fn addBlockInstructions(self: *SCCPSolver, bid: BlockId) !void {
    const block = &self.func.blocks.items[bid];
    for (block.instrs.items) |inst| {
        if (inst.result != NO_VALUE and inst.result <= self.lattice.items.len) {
            const old_lat = self.lattice.items[inst.result - 1];
            if (old_lat == .top) {
                self.value_worklist.append(inst.result) catch {};

            }
        }
    }
    // Defer terminator edge addition until terminator is evaluated
    self.term_worklist.append(bid) catch {};
}

fn addTerminatorEdges(self: *SCCPSolver, bid: BlockId, inst: Inst) !void {
    switch (inst.op) {
        .br => {

    const target = inst.data.block_target;
    try self.edge_worklist.append(.{ .from = bid, .to = target });
},
.cond_br => {
    const cb = inst.data.cond_branch;
    const cond_lat = self.getLattice(cb.cond);
    if (cond_lat == .bool_const) {
        if (cond_lat.bool_const) {
            try self.edge_worklist.append(.{ .from = bid, .to = cb.then_block });
        } else {

                    try self.edge_worklist.append(.{ .from = bid, .to = cb.else_block });
                }
            } else {
                try self.edge_worklist.append(.{ .from = bid, .to = cb.then_block });
                try self.edge_worklist.append(.{ .from = bid, .to = cb.else_block });
            }
        },
        else => {},
    }
}

fn evaluateInst(self: *SCCPSolver, inst: *const Inst) Lattice {
    switch (inst.op) {
        .@"const" => {
            return switch (inst.data) {
                .const_data => |cd| switch (cd) {
                    .int => |v| .{ .int_const = v },
                    .bool => |v| .{ .bool_const = v },
                    .float => .{ .bottom = {} },
                    .undefined, .zero => .{ .top = {} },

        },
        else => .{ .top = {} },
    };
},
.add => return self.evalBinaryInt(inst, .add),
.sub => return self.evalBinaryInt(inst, .sub),
.mul => return self.evalBinaryInt(inst, .mul),
.div => return self.evalBinaryInt(inst, .div),
.mod => return self.evalBinaryInt(inst, .mod),
.max => return self.evalBinaryInt(inst, .max),

            const cond = self.getLattice(inst.operands[0]);
            if (cond == .bool_const) {
                return self.getLattice(if (cond.bool_const) inst.operands[1] else inst.operands[2]);
            }
            if (cond == .top) return .{ .top = {} };
            return .{ .bottom = {} };
        },
        else => return .{ .bottom = {} },
    }
}

fn evalBinaryInt(self: *SCCPSolver, inst: *const Inst, comptime op: Op) Lattice {
    if (inst.operands.len < 2) return .{ .bottom = {} };
    const a = self.getLattice(inst.operands[0]);
    const b = self.getLattice(inst.operands[1]);

    if (a == .bottom or b == .bottom) return .{ .bottom = {} };
    if (a == .top or b == .top) return .{ .top = {} };

    if (a != .int_const or b != .int_const) return .{ .bottom = {} };

        .max => if (a.int_const > b.int_const) a.int_const else b.int_const,
        .min => if (a.int_const < b.int_const) a.int_const else b.int_const,
        else => return .{ .bottom = {} },
    };
    return .{ .int_const = result };
}

fn evalUnaryInt(self: *SCCPSolver, inst: *const Inst, comptime op: Op) Lattice {
    if (inst.operands.len < 1) return .{ .bottom = {} };
    const a = self.getLattice(inst.operands[0]);

    if (a == .bottom) return .{ .bottom = {} };
    if (a == .top) return .{ .top = {} };
    if (a != .int_const) return .{ .bottom = {} };

    return switch (op) {
        .neg => .{ .int_const = -%a.int_const },
        .not => .{ .int_const = ~a.int_const },
        else => .{ .bottom = {} },
    };
}

fn evalComparison(self: *SCCPSolver, inst: *const Inst) Lattice {
    if (inst.operands.len < 2) return .{ .bottom = {} };
    const a = self.getLattice(inst.operands[0]);
    const b = self.getLattice(inst.operands[1]);

    if (a == .bottom or b == .bottom) return .{ .bottom = {} };
    if (a == .top or b == .top) return .{ .top = {} };
    if (a != .int_const or b != .int_const) return .{ .bottom = {} };

const result: bool = switch (inst.op) {
    .eq => a.int_const == b.int_const,
    .ne => a.int_const != b.int_const,
    .lt => a.int_const < b.int_const,
    .le => a.int_const <= b.int_const,
    .gt => a.int_const > b.int_const,
    .ge => a.int_const >= b.int_const,
    else => return .{ .bottom = {} },
};
return .{ .bool_const = result };

}

fn evalPhi(self: *SCCPSolver, inst: *const Inst) Lattice {
    if (inst.data != .phi_incoming) return .{ .bottom = {} };
    const incoming = inst.data.phi_incoming;

    var result: Lattice = .{ .top = {} };
    for (incoming) |inc| {
        if (!self.executable.items[inc.block]) continue;
        const inc_lat = self.getLattice(inc.value);

        result = Lattice.meet(result, inc_lat);
        if (result == .bottom) break;
    }
    return result;
}

fn getLattice(self: *const SCCPSolver, vid: ValueId) Lattice {
    if (vid == NO_VALUE or vid == 0) return .{ .top = {} };
    if (vid > self.lattice.items.len) return .{ .bottom = {} };
    return self.lattice.items[vid - 1];

    }
};

// ─── Apply results ───

fn applyResults(func: *bir.Function, solver: *const SCCPSolver) !bool {
    var changed = false;
    var num_folded: u32 = 0;

    for (func.blocks.items) |*block| {

var i: usize = 0;
while (i < block.instrs.items.len) {
    const inst = &block.instrs.items[i];
    if (inst.result == NO_VALUE or inst.result == 0) {
        i += 1;
        continue;
    }
    if (inst.result > solver.lattice.items.len) {
        i += 1;
        continue;

}

const lat = solver.lattice.items[inst.result - 1];

if (lat == .int_const and inst.op != .@"const") {
    // Fold to constant
    inst.deinit(func.allocator);
    const ops = try func.allocator.dupe(ValueId, &.{});
    inst.op = .@"const";
    inst.ty = bir.types.INVALID_TYPE;

    inst.operands = ops;
    inst.data = .{ .const_data = .{ .int = lat.int_const } };
    changed = true;
    num_folded += 1;
} else if (lat == .bool_const and inst.op != .@"const") {
    inst.deinit(func.allocator);
    const ops = try func.allocator.dupe(ValueId, &.{});
    inst.op = .@"const";
    inst.ty = bir.types.INVALID_TYPE;
    inst.operands = ops;

            inst.data = .{ .const_data = .{ .bool = lat.bool_const } };
            changed = true;
            num_folded += 1;
        }

        i += 1;
    }
}

// Remove unreachable blocks and remap all block references

// Step 1: Build remap table (old_index -> new_index, or null for removed)
var remap = std.ArrayList(?usize).init(func.allocator);
defer remap.deinit();
try remap.resize(func.blocks.items.len);

var new_index: usize = 0;
for (0..func.blocks.items.len) |bi| {
    if (bi == 0 or solver.executable.items[bi]) {
        remap.items[bi] = new_index;
        new_index += 1;

    } else {
        remap.items[bi] = null;
    }
}

// Step 2: Fix terminators in executable predecessors (cond_br → br)
for (func.blocks.items) |*block| {
    if (block.instrs.items.len == 0) continue;
    const last = &block.instrs.items[block.instrs.items.len - 1];
    switch (last.op) {

.cond_br => {
    const cb = last.data.cond_branch;
    if (remap.items[cb.then_block] == null and remap.items[cb.else_block] != null) {
        last.op = .br;
        last.data = .{ .block_target = cb.else_block };
        changed = true;
    } else if (remap.items[cb.else_block] == null and remap.items[cb.then_block] != null) {
        last.op = .br;
        last.data = .{ .block_target = cb.then_block };
        changed = true;

            }
        },
        else => {},
    }
}

// Step 3: Clean phi incoming — remove entries that reference dead blocks
for (func.blocks.items) |*block| {
    for (block.instrs.items) |*inst| {
        if (inst.op != .phi) continue;

        var new_incoming = std.ArrayList(bir.PhiIncoming).init(func.allocator);
        for (inst.data.phi_incoming) |inc| {
            if (remap.items[inc.block] != null) {
                try new_incoming.append(.{ .value = inc.value, .block = inc.block });
            }
        }
        func.allocator.free(inst.data.phi_incoming);
        inst.data.phi_incoming = try new_incoming.toOwnedSlice();
    }
}

// Step 4: Remove dead blocks from the list
var wi: usize = func.blocks.items.len;
while (wi > 0) {
    wi -= 1;
    if (wi == 0) continue; // never remove entry
    if (remap.items[wi] == null) {
        func.blocks.items[wi].deinit(func.allocator);
        _ = func.blocks.orderedRemove(wi);
        changed = true;

    }
}

// Step 5: Remap all block references in terminators, phi incoming, and value_info
for (func.blocks.items) |*block| {
    if (block.instrs.items.len == 0) continue;
    const last = &block.instrs.items[block.instrs.items.len - 1];
    switch (last.op) {
        .br => {
            const old_target = last.data.block_target;

    last.data = .{ .block_target = @intCast(remap.items[old_target] orelse 0) };
},
.cond_br => {
    const cb = last.data.cond_branch;
    last.data = .{ .cond_branch = .{
        .cond = cb.cond,
        .then_block = @intCast(remap.items[cb.then_block] orelse 0),
        .else_block = @intCast(remap.items[cb.else_block] orelse 0),
    } };
},

        else => {},
    }
    for (block.instrs.items) |*inst| {
        if (inst.op != .phi) continue;
        for (inst.data.phi_incoming) |*inc| {
            inc.block = @intCast(remap.items[inc.block] orelse 0);
        }
    }
}

// Step 6: Remap value_info def positions — block indices shifted after removal
// Also rebuild def for folded constants since instruction ops changed
for (func.value_info.items) |*vi| {
    const old_block = vi.def.block;
    if (old_block < func.blocks.items.len + remap.items.len) {
        if (old_block < remap.items.len) {
            if (remap.items[old_block]) |new_blk| {
                vi.def.block = @intCast(new_blk);
            } else {
                vi.def.block = 0; // was in dead block, mark as entry (safe)

            }
        }
    }
}

if (num_folded > 0) {
    if (@import("builtin").mode == .Debug) {
        std.debug.print("  SCCP: folded {d} values to constants\n", .{num_folded});
    }
}

    return changed;
}

// ─── Pass entry point ───

fn runSCCP(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    const allocator = ctx.allocator;
    for (module.functions.items, 0..) |*func, fid| {

if (func.blocks.items.len == 0) continue;
const func_id = @as(bir.FunctionId, @intCast(fid));

const cfg = try ctx.analysis.getCFG(func_id);

var solver = try SCCPSolver.init(allocator, func, cfg);
defer solver.deinit();

try solver.run();

        _ = try applyResults(func, &solver);
    }
    return PreservedAnalyses.none();
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const bir_dominators = @import("../../analysis/dominator/dominator.zig");
const bir_loops = @import("../../analysis/loops/loops.zig");
const PreservedAnalyses = bir.PreservedAnalyses;
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;

pub const UnrollPass = bir.Pass{
    .name = "loop-unroll",
    .run = runUnroll,
};

const InductionVar = struct {
    phi_val: bir.ValueId,
    init_val: bir.ValueId,
    step_val: i64,
    bound_val: i64,

    cmp_op: bir.Op,
    count: u64,
};

fn runUnroll(ctx: *bir.PassContext) anyerror!PreservedAnalyses {
    const module = ctx.module;
    for (module.functions.items, 0..) |*func, fid| {
        if (func.blocks.items.len < 3) continue;
        const func_id = @as(bir.FunctionId, @intCast(fid));

    const cfg = try ctx.analysis.getCFG(func_id);
    const dom_tree = try ctx.analysis.getDomTree(func_id);
    const loop_info = try ctx.analysis.getLoopInfo(func_id);
    const loops = loop_info.loops;

    for (loops) |loop| {
        try unrollLoop(module, func_id, func, cfg, dom_tree, &loop);
    }
}
return PreservedAnalyses.none();

}

fn unrollLoop(module: *bir.Module, func_id: bir.FunctionId, func: *bir.Function, _: *const bir_cfg.CFG, _: *const bir_dominators.DominatorTree, loop: *const bir_loops.Loop) !void {
    const preheader = findPreheader(func, loop) orelse return;
    if (loop.back_edges.len != 1) return;
    const latch = loop.back_edges[0].from;

    const iv = detectInductionVar(func, loop, preheader, latch) orelse return;
    if (iv.count < 2 or iv.count > 64) return;

const header = loop.header;

var exit_block: ?bir.BlockId = null;
{
    const header_block = func.getBlock(header);
    const term = &header_block.instrs.items[header_block.instrs.items.len - 1];
    if (term.op != .cond_br) return;
    const cond = term.data.cond_branch;
    const body_bid = if (cond.then_block != exit_block orelse bir.INVALID_ID) cond.then_block else cond.else_block;
    const exit_bid = if (cond.then_block == body_bid) cond.else_block else cond.then_block;

    exit_block = exit_bid;
}

var body_blocks = std.ArrayList(bir.BlockId).init(module.allocator);
defer body_blocks.deinit();
for (loop.body) |bid| {
    if (bid != header) try body_blocks.append(bid);
}
if (body_blocks.items.len == 0) return;

var total_unrolled: u64 = 0;
const count = iv.count;
var last_block_of_prev_iter: bir.BlockId = preheader;

if (count > 0) {
    var phi_replacements = std.AutoHashMap(bir.ValueId, bir.ValueId).init(module.allocator);
    defer phi_replacements.deinit();
    for (func.getBlock(header).instrs.items) |*inst| {
        if (inst.op != .phi) continue;
        for (inst.data.phi_incoming) |inc| {

        if (inc.block == preheader) {
            try phi_replacements.put(inst.result, inc.value);
            break;
        }
    }
}

const header_term_succs = [2]bir.BlockId{
    func.getBlock(header).instrs.items[func.getBlock(header).instrs.items.len - 1].data.cond_branch.then_block,
    func.getBlock(header).instrs.items[func.getBlock(header).instrs.items.len - 1].data.cond_branch.else_block,

};
var exit_bid: bir.BlockId = undefined;
var first_body_bid: bir.BlockId = undefined;
{
    var in_body = false;
    for (body_blocks.items) |b| { if (b == header_term_succs[0]) { in_body = true; break; } }
    if (in_body) {
        first_body_bid = header_term_succs[0];
        exit_bid = header_term_succs[1];
    } else {

        first_body_bid = header_term_succs[1];
        exit_bid = header_term_succs[0];
    }
}

for (body_blocks.items, 0..) |bid, i| {
    if (bid == first_body_bid and i > 0) {
        const tmp = body_blocks.items[0];
        body_blocks.items[0] = bid;
        body_blocks.items[i] = tmp;

        break;
    }
}

var first_unrolled_block: bir.BlockId = INVALID_ID;
var last_old_to_new: ?std.AutoHashMap(bir.ValueId, bir.ValueId) = null;
var iter: u64 = 0;
while (iter < count) : (iter += 1) {
    var old_to_new = std.AutoHashMap(bir.ValueId, bir.ValueId).init(module.allocator);
    var new_blocks = std.ArrayList(bir.BlockId).init(module.allocator);

defer new_blocks.deinit();

for (body_blocks.items) |bid| {
    const src_block = func.getBlock(bid);
    var new_instrs = std.ArrayList(bir.Inst).init(module.allocator);
    defer new_instrs.deinit();

    for (src_block.instrs.items) |*inst| {
        var new_operands = try module.allocator.dupe(bir.ValueId, inst.operands);
        for (new_operands, 0..) |op, j| {

    if (phi_replacements.get(op)) |nv| new_operands[j] = nv;
    if (old_to_new.get(op)) |nv| new_operands[j] = nv;
}

var new_data = cloneData(module.allocator, &inst.data);
switch (new_data) {
    .phi_incoming => |incoming| {
        for (incoming) |*inc| {
            if (phi_replacements.get(inc.value)) |nv| inc.value = nv;
            if (old_to_new.get(inc.value)) |nv| inc.value = nv;

    }
},
.texture_store_info => |*tsi| {
    if (phi_replacements.get(tsi.tex)) |nv| tsi.tex = nv;
    if (old_to_new.get(tsi.tex)) |nv| tsi.tex = nv;
    if (phi_replacements.get(tsi.coord_x)) |nv| tsi.coord_x = nv;
    if (old_to_new.get(tsi.coord_x)) |nv| tsi.coord_x = nv;
    if (phi_replacements.get(tsi.coord_y)) |nv| tsi.coord_y = nv;
    if (old_to_new.get(tsi.coord_y)) |nv| tsi.coord_y = nv;
    if (phi_replacements.get(tsi.val)) |nv| tsi.val = nv;

    if (old_to_new.get(tsi.val)) |nv| tsi.val = nv;
},
.sample_info => |*si| {
    if (phi_replacements.get(si.tex)) |nv| si.tex = nv;
    if (old_to_new.get(si.tex)) |nv| si.tex = nv;
    if (phi_replacements.get(si.sampler)) |nv| si.sampler = nv;
    if (old_to_new.get(si.sampler)) |nv| si.sampler = nv;
    if (phi_replacements.get(si.coord)) |nv| si.coord = nv;
    if (old_to_new.get(si.coord)) |nv| si.coord = nv;
    if (si.lod) |*lod| {

        if (phi_replacements.get(lod.*)) |nv| lod.* = nv;
        if (old_to_new.get(lod.*)) |nv| lod.* = nv;
    }
    if (si.offset) |*off| {
        if (phi_replacements.get(off.*)) |nv| off.* = nv;
        if (old_to_new.get(off.*)) |nv| off.* = nv;
    }
},
.named_call => |*nc| {
    for (nc.args) |*arg| {

        if (phi_replacements.get(arg.*)) |nv| arg.* = nv;
        if (old_to_new.get(arg.*)) |nv| arg.* = nv;
    }
},
.gep_info => |*gi| {
    if (phi_replacements.get(gi.ptr)) |nv| gi.ptr = nv;
    if (old_to_new.get(gi.ptr)) |nv| gi.ptr = nv;
    for (gi.indices) |*idx| {
        if (phi_replacements.get(idx.*)) |nv| idx.* = nv;
        if (old_to_new.get(idx.*)) |nv| idx.* = nv;

    }
},
.cond_branch => |*cb| {
    if (phi_replacements.get(cb.cond)) |nv| cb.cond = nv;
    if (old_to_new.get(cb.cond)) |nv| cb.cond = nv;
},
.atomic_info => |*ai| {
    if (phi_replacements.get(ai.ptr)) |nv| ai.ptr = nv;
    if (old_to_new.get(ai.ptr)) |nv| ai.ptr = nv;
    if (phi_replacements.get(ai.val)) |nv| ai.val = nv;

        if (old_to_new.get(ai.val)) |nv| ai.val = nv;
    },
    else => {},
}

const new_val = try func.createValue();
const new_idx = new_instrs.items.len;
func.getValueInfo(new_val).def = .{ .block = 0, .idx = @as(u32, @intCast(new_idx)) };

if (inst.result != NO_VALUE) {

    try old_to_new.put(inst.result, new_val);
}

try new_instrs.append(.{
    .op = inst.op,
    .ty = inst.ty,
    .result = new_val,
    .operands = new_operands,
    .data = new_data,
});

    }

    const new_label = try std.fmt.allocPrint(module.allocator, "{s}.unroll.{d}", .{ src_block.label, iter });
    const new_bid = try module.addBlockWithInstrs(func_id, new_label, new_instrs.items);
    try new_blocks.append(new_bid);
}

var block_map = std.AutoHashMap(bir.BlockId, bir.BlockId).init(module.allocator);
defer block_map.deinit();
for (body_blocks.items, new_blocks.items) |orig, cloned| {

    try block_map.put(orig, cloned);
}

for (0..new_blocks.items.len) |bi| {
    const new_bid = new_blocks.items[bi];
    const new_block = func.getBlock(new_bid);
    const new_term_idx = new_block.instrs.items.len - 1;
    const new_term = &new_block.instrs.items[new_term_idx];

    for (new_block.instrs.items, 0..) |*inst, ii| {

if (inst.op == .phi) {
    for (inst.data.phi_incoming) |*inc| {
        if (block_map.get(inc.block)) |nb| inc.block = nb;
    }
}
if (ii == new_term_idx) {
    if (inst.op == .br) {
        if (block_map.get(inst.data.block_target)) |nb| inst.data.block_target = nb;
    } else if (inst.op == .cond_br) {
        const cb = &inst.data.cond_branch;

            if (block_map.get(cb.then_block)) |nb| cb.then_block = nb;
            if (block_map.get(cb.else_block)) |nb| cb.else_block = nb;
        }
    }
}

if (iter == count - 1) {
    if (new_term.op == .br and new_term.data.block_target == header) {
        new_term.data.block_target = exit_bid;
    } else if (new_term.op == .cond_br) {

        const cb = &new_term.data.cond_branch;
        if (cb.then_block == header) cb.then_block = exit_bid;
        if (cb.else_block == header) cb.else_block = exit_bid;
    }
}

if (bi == 0 and last_block_of_prev_iter != INVALID_ID) {
    const prev_term = &func.getBlock(last_block_of_prev_iter).instrs.items[func.getBlock(last_block_of_prev_iter).instrs.items.len - 1];
    if (prev_term.op == .br and prev_term.data.block_target == header) {
        prev_term.data.block_target = new_bid;

        } else if (prev_term.op == .cond_br) {
            const cb = &prev_term.data.cond_branch;
            if (cb.then_block == header) cb.then_block = new_bid;
            if (cb.else_block == header) cb.else_block = new_bid;
        }
    }
}

for (func.getBlock(header).instrs.items) |*hdr_inst| {
    if (hdr_inst.op != .phi) continue;

    for (hdr_inst.data.phi_incoming) |inc| {
        if (inc.block == latch) {
            if (old_to_new.get(inc.value)) |nv| {
                try phi_replacements.put(hdr_inst.result, nv);
            }
            break;
        }
    }
}

total_unrolled += 1;
if (iter == count - 1) {
    if (last_old_to_new) |*map| map.deinit();
    last_old_to_new = old_to_new;
} else {
    old_to_new.deinit();
}
if (new_blocks.items.len > 0) {
    if (first_unrolled_block == INVALID_ID) {
        first_unrolled_block = new_blocks.items[0];

}
var latch_block = new_blocks.items[new_blocks.items.len - 1];
for (new_blocks.items) |bid| {
    const blk = func.getBlock(bid);
    const term = blk.instrs.items[blk.instrs.items.len - 1];
    if (term.op == .br and term.data.block_target == header) {
        latch_block = bid;
        break;
    }
    if (term.op == .cond_br) {

                const cb = term.data.cond_branch;
                if (cb.then_block == header or cb.else_block == header) {
                    latch_block = bid;
                    break;
                }
            }
        }
        last_block_of_prev_iter = latch_block;
    }
}

if (first_unrolled_block != INVALID_ID) {
    for (func.getBlock(preheader).instrs.items) |*inst| {
        if (inst.op == .br and inst.data.block_target == header) {
            inst.data.block_target = first_unrolled_block;
        }
    }
}

if (last_old_to_new) |*lotn| {

var phi_to_last = std.AutoHashMap(bir.ValueId, bir.ValueId).init(module.allocator);
defer phi_to_last.deinit();
for (func.getBlock(header).instrs.items) |*phi_inst| {
    if (phi_inst.op != .phi) continue;
    for (phi_inst.data.phi_incoming) |inc| {
        if (inc.block == latch) {
            if (lotn.get(inc.value)) |nv| {
                try phi_to_last.put(phi_inst.result, nv);
            }
            break;

        }
    }
}
if (phi_to_last.count() > 0) {
    for (func.blocks.items, 0..) |*blk, bid| {
        if (bid == header) continue;
        var in_body = false;
        for (body_blocks.items) |bb| { if (bid == bb) { in_body = true; break; } }
        if (in_body) continue;
        for (blk.instrs.items) |*inst| {

for (inst.operands, 0..) |op, i| {
    if (phi_to_last.get(op)) |nv| inst.operands[i] = nv;
}
switch (inst.data) {
    .phi_incoming => |incoming| {
        for (incoming) |*inc| {
            if (phi_to_last.get(inc.value)) |nv| inc.value = nv;
        }
    },
    .cond_branch => |*cb| {

    if (phi_to_last.get(cb.cond)) |nv| cb.cond = nv;
},
.texture_store_info => |*tsi| {
    if (phi_to_last.get(tsi.tex)) |nv| tsi.tex = nv;
    if (phi_to_last.get(tsi.coord_x)) |nv| tsi.coord_x = nv;
    if (phi_to_last.get(tsi.coord_y)) |nv| tsi.coord_y = nv;
    if (phi_to_last.get(tsi.val)) |nv| tsi.val = nv;
},
.sample_info => |*si| {
    if (phi_to_last.get(si.tex)) |nv| si.tex = nv;

    if (phi_to_last.get(si.sampler)) |nv| si.sampler = nv;
    if (phi_to_last.get(si.coord)) |nv| si.coord = nv;
    if (si.lod) |*lod| { if (phi_to_last.get(lod.*)) |nv| lod.* = nv; }
    if (si.offset) |*off| { if (phi_to_last.get(off.*)) |nv| off.* = nv; }
},
.named_call => |*nc| {
    for (nc.args) |*arg| { if (phi_to_last.get(arg.*)) |nv| arg.* = nv; }
},
.gep_info => |*gi| {
    if (phi_to_last.get(gi.ptr)) |nv| gi.ptr = nv;

                for (gi.indices) |*idx| { if (phi_to_last.get(idx.*)) |nv| idx.* = nv; }
            },
            .atomic_info => |*ai| {
                if (phi_to_last.get(ai.ptr)) |nv| ai.ptr = nv;
                if (phi_to_last.get(ai.val)) |nv| ai.val = nv;
            },
            else => {},
        }
    }
}

            }
        }
    }

    module.rebuildUses();
}

fn findPreheader(func: *const bir.Function, loop: *const bir_loops.Loop) ?bir.BlockId {
    const header = loop.header;
    var result: ?bir.BlockId = null;

for (func.blocks.items[header].preds.items) |pred| {
    var in_body = false;
    for (loop.body) |b| {
        if (b == pred) {
            in_body = true;
            break;
        }
    }
    if (!in_body) {
        if (result != null) return null;

            result = pred;
        }
    }
    return result;
}

fn detectInductionVar(func: *bir.Function, loop: *const bir_loops.Loop, preheader: bir.BlockId, latch: bir.BlockId) ?InductionVar {
    const header = loop.header;
    const header_block = func.getBlock(header);
    if (header_block.instrs.items.len < 2) return null;

const term = &header_block.instrs.items[header_block.instrs.items.len - 1];
if (term.op != .cond_br) return null;

const cond_val = term.data.cond_branch.cond;
const cond_def = getDef(func, cond_val) orelse return null;
const cmp_op = cond_def.op;

const is_unsigned = switch (cmp_op) {
    .lt, .le, .gt, .ge, .eq, .ne => false,

    else => return null,
};
_ = is_unsigned;

const cmp_lhs = if (cond_def.operands.len >= 2) cond_def.operands[0] else return null;
var bound_val: ?i64 = null;
for (cond_def.operands) |op| {
    const op_def = getDef(func, op);
    if (op_def != null and op_def.?.op == .@"const") {
        const cd = op_def.?.data.const_data;

        if (cd == .int) {
            bound_val = cd.int;
        }
    }
}

var phi_candidate: ?bir.ValueId = null;
for (header_block.instrs.items) |*inst| {
    if (inst.op != .phi) continue;
    const incoming = inst.data.phi_incoming;

if (incoming.len != 2) continue;

var from_preheader: ?bir.ValueId = null;
var from_latch: ?bir.ValueId = null;
for (incoming) |inc| {
    if (inc.block == preheader) from_preheader = inc.value;
    if (inc.block == latch) from_latch = inc.value;
}
if (from_preheader == null or from_latch == null) continue;

const init_val = from_preheader.?;
const init_def = getDef(func, init_val);
if (init_def == null or init_def.?.op != .@"const") continue;
if (init_def.?.data.const_data != .int) continue;
const init_int = init_def.?.data.const_data.int;

const latch_def = getDef(func, from_latch.?);
if (latch_def == null) continue;

var step_val: i64 = undefined;

const iv_phi_val = inst.result;

if (latch_def.?.op == .add or latch_def.?.op == .sub) {
    const add_ops = latch_def.?.operands;
    var has_iv = false;
    var step_detected = false;
    for (add_ops) |op| {
        if (op == iv_phi_val) { has_iv = true; continue; }
        const op_def = getDef(func, op);
        if (op_def != null and op_def.?.op == .@"const") {

            if (op_def.?.data.const_data == .int) {
                step_val = if (latch_def.?.op == .add) op_def.?.data.const_data.int else -op_def.?.data.const_data.int;
                step_detected = true;
            }
        }
    }
    if (!has_iv or !step_detected) continue;
} else if (latch_def.?.op == .@"const") {
    step_val = 0;
} else {

    continue;
}

if (step_val <= 0) continue;
if (bound_val == null) continue;

if (iv_phi_val == cmp_lhs) {
    phi_candidate = iv_phi_val;
} else {
    const cmp_def = getDef(func, cmp_lhs);

    if (cmp_def != null) {
        for (cmp_def.?.operands) |op| {
            if (op == iv_phi_val) {
                phi_candidate = iv_phi_val;
                break;
            }
        }
    }
}

if (phi_candidate == null) continue;

const bound = bound_val.?;
if (bound == init_int and cmp_op == .lt) return InductionVar{ .phi_val = undefined, .init_val = undefined, .step_val = undefined, .bound_val = undefined, .cmp_op = undefined, .count = 0 };
const count: u64 = if (init_int >= bound) 0 else switch (cmp_op) {
    .lt => @as(u64, @intCast(@divTrunc(bound - init_int + step_val - 1, step_val))),
    .le => @as(u64, @intCast(@divTrunc(bound - init_int + step_val, step_val))),
    .gt => @as(u64, @intCast(@divTrunc(init_int - bound + step_val - 1, step_val))),
    .ge => @as(u64, @intCast(@divTrunc(init_int - bound + step_val, step_val))),
    else => return null,

};

return InductionVar{
    .phi_val = phi_candidate.?,
    .init_val = init_val,
    .step_val = step_val,
    .bound_val = bound,
    .cmp_op = cmp_op,
    .count = count,
};

    }

    return null;
}

fn getDef(func: *bir.Function, val: bir.ValueId) ?*const bir.Inst {
    if (val == NO_VALUE) return null;
    if (val > func.value_info.items.len) return null;
    const vi = &func.value_info.items[val - 1];
    if (vi.def.block == INVALID_ID) return null;

    if (vi.def.block >= func.blocks.items.len) return null;
    const block = &func.blocks.items[vi.def.block];
    if (vi.def.idx >= block.instrs.items.len) return null;
    return &block.instrs.items[vi.def.idx];
}

fn getIntType(func: *bir.Function, val: bir.ValueId) bir.TypeId {
    if (val == NO_VALUE or val > func.value_info.items.len) return 0;
    const vi = &func.value_info.items[val - 1];
    if (vi.def.block == INVALID_ID or vi.def.block >= func.blocks.items.len) return 0;

    const block = &func.blocks.items[vi.def.block];
    if (vi.def.idx >= block.instrs.items.len) return 0;
    return block.instrs.items[vi.def.idx].ty;
}

fn createAddConst(_: *bir.Module, _: bir.FunctionId, _: bir.BlockId, base: bir.ValueId, _: i64) !bir.ValueId {
    return base;
}

fn cloneData(allocator: Allocator, data: *const bir.Inst.Data) bir.Inst.Data {

switch (data.*) {
    .string => |s| return .{ .string = allocator.dupe(u8, s) catch return .{ .none = {} } },
    .phi_incoming => |incoming| {
        const copy = allocator.dupe(bir.PhiIncoming, incoming) catch return .{ .none = {} };
        return .{ .phi_incoming = copy };
    },
    .call_info => |ci| {
        const args_copy = allocator.dupe(bir.ValueId, ci.args) catch return .{ .none = {} };
        return .{ .call_info = .{ .callee = ci.callee, .args = args_copy } };
    },

    .gep_info => |gi| {
        const idx_copy = allocator.dupe(bir.ValueId, gi.indices) catch return .{ .none = {} };
        return .{ .gep_info = .{ .ptr = gi.ptr, .indices = idx_copy, .result_elem_type = gi.result_elem_type } };
    },
    .vector_shuffle => |vs| {
        const mask_copy = allocator.dupe(u32, vs.mask) catch return .{ .none = {} };
        return .{ .vector_shuffle = .{ .a = vs.a, .b = vs.b, .mask = mask_copy } };
    },
    else => return data.*,
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../../bir.zig");
const bir_cfg = @import("../../analysis/cfg/cfg.zig");
const bir_dominators = @import("../../analysis/dominator/dominator.zig");
const INVALID_ID = bir.INVALID_ID;
const NO_VALUE = bir.NO_VALUE;
const ValueId = bir.ValueId;
const BlockId = bir.BlockId;
const Module = bir.Module;

const PreservedAnalyses = bir.PreservedAnalyses;

const VersionLog = struct { alloca: ValueId, old_version: ValueId };

pub const Mem2RegPass = bir.Pass{
    .name = "mem2reg",
    .run = runMem2Reg,
};

fn runMem2Reg(ctx: *bir.PassContext) anyerror!PreservedAnalyses {

const module = ctx.module;
module.rebuildUses();

for (module.functions.items, 0..) |*func, fid| {
    if (func.blocks.items.len < 1) continue;
    const func_id = @as(bir.FunctionId, @intCast(fid));

    const cfg = try ctx.analysis.getCFG(func_id);
    const dom_tree = try ctx.analysis.getDomTree(func_id);
    const df = try ctx.analysis.getDomFrontier(func_id);

var allocas = try collectAllocas(func);
defer {
    for (allocas.items) |*a| a.deinit(func.allocator);
    allocas.deinit();
}

for (allocas.items) |*alloca_info| {
    try promoteAlloca(module, func_id, func, cfg, dom_tree, df, alloca_info);
}

    }
    return PreservedAnalyses.none();
}

const AllocaInfo = struct {
    alloca_val: ValueId,
    ty: bir.TypeId,

    pub fn deinit(_: *AllocaInfo, _: Allocator) void {}
};

fn collectAllocas(func: *bir.Function) !std.ArrayList(AllocaInfo) {
    var result = std.ArrayList(AllocaInfo).init(func.allocator);
    for (func.blocks.items) |*block| {
        for (block.instrs.items) |*inst| {
            if (inst.op != .alloca) continue;
            if (inst.result == NO_VALUE) continue;
            try result.append(.{
                .alloca_val = inst.result,
                .ty = inst.ty,

            });
        }
    }
    return result;
}

fn promoteAlloca(
    module: *Module,
    func_id: bir.FunctionId,
    func: *bir.Function,

    cfg: *const bir_cfg.CFG,
    dom_tree: *const bir_dominators.DominatorTree,
    df: *const bir_dominators.DominanceFrontier,
    alloca_info: *const AllocaInfo,
) !void {
    const alloca_val = alloca_info.alloca_val;

    var store_blocks = std.ArrayList(BlockId).init(module.allocator);
    defer store_blocks.deinit();

for (func.blocks.items, 0..) |*block, bi| {
    for (block.instrs.items) |*inst| {
        if (inst.op == .store and inst.operands.len >= 2 and inst.operands[0] == alloca_val) {
            try store_blocks.append(@as(BlockId, @intCast(bi)));
        }
    }
}

if (store_blocks.items.len == 0) return;

var phi_blocks = std.AutoHashMap(BlockId, void).init(module.allocator);
defer phi_blocks.deinit();

var idf_worklist = std.ArrayList(BlockId).init(module.allocator);
defer idf_worklist.deinit();

for (store_blocks.items) |sb| {
    try idf_worklist.append(sb);
}

while (idf_worklist.items.len > 0) {
    const b = idf_worklist.pop().?;
    for (df.get(b)) |dfb| {
        if (!phi_blocks.contains(dfb)) {
            try phi_blocks.put(dfb, {});
            try idf_worklist.append(dfb);
        }
    }
}

var phi_for_block = std.AutoHashMap(BlockId, ValueId).init(module.allocator);
defer phi_for_block.deinit();

var pit = phi_blocks.keyIterator();
while (pit.next()) |bid_ptr| {
    const bid = bid_ptr.*;
    const phi_val = try module.addPhi(func_id, bid, alloca_info.ty, &.{});
    try phi_for_block.put(bid, phi_val);
}

var version_for = std.AutoHashMap(ValueId, ValueId).init(module.allocator);
defer version_for.deinit();

var push_log = std.ArrayList(VersionLog).init(module.allocator);
defer push_log.deinit();

try renameBlock(module, func, func_id, cfg, dom_tree, &phi_for_block, &version_for, &push_log, cfg.entry, alloca_val);

var i: usize = func.blocks.items.len;
while (i > 0) {

i -= 1;
const bid = @as(BlockId, @intCast(i));
const block = func.getBlock(bid);
var j: usize = block.instrs.items.len;
while (j > 0) {
    j -= 1;
    const inst = &block.instrs.items[j];
    if (inst.op == .alloca and inst.result == alloca_val) {
        module.removeInst(func_id, bid, @as(u32, @intCast(j)));
        break;

        }
    }
}

i = func.blocks.items.len;
while (i > 0) {
    i -= 1;
    const bid = @as(BlockId, @intCast(i));
    const block = func.getBlock(bid);
    var j: usize = block.instrs.items.len;

    while (j > 0) {
        j -= 1;
        const inst = &block.instrs.items[j];
        if (inst.op == .store and inst.operands.len >= 2 and inst.operands[0] == alloca_val) {
            module.removeInst(func_id, bid, @as(u32, @intCast(j)));
        }
    }
}

i = func.blocks.items.len;

while (i > 0) {
    i -= 1;
    const bid = @as(BlockId, @intCast(i));
    const block = func.getBlock(bid);
    var j: usize = block.instrs.items.len;
    while (j > 0) {
        j -= 1;
        const inst = &block.instrs.items[j];
        if (inst.op == .load and inst.operands.len >= 1 and inst.operands[0] == alloca_val) {
            module.removeInst(func_id, bid, @as(u32, @intCast(j)));

            }
        }
    }

    module.rebuildUses();
}

fn renameBlock(
    module: *Module,
    func: *bir.Function,

    func_id: bir.FunctionId,
    cfg: *const bir_cfg.CFG,
    dom_tree: *const bir_dominators.DominatorTree,
    phi_for_block: *const std.AutoHashMap(BlockId, ValueId),
    version_for: *std.AutoHashMap(ValueId, ValueId),
    push_log: *std.ArrayList(VersionLog),
    bid: BlockId,
    alloca_val: ValueId,
) !void {
    if (bid >= func.blocks.items.len) return;

const saved_len = push_log.items.len;

const block = func.getBlock(bid);

for (block.instrs.items) |*inst| {
    if (inst.op == .phi) {
        if (phi_for_block.get(bid)) |phi_val| {
            if (inst.result == phi_val) {
                const old = version_for.get(alloca_val) orelse NO_VALUE;

                try version_for.put(alloca_val, phi_val);
                try push_log.append(.{ .alloca = alloca_val, .old_version = old });
            }
        }
    }
}

for (block.instrs.items) |*inst| {
    if (inst.op == .store and inst.operands.len >= 2 and inst.operands[0] == alloca_val) {
        const stored_val = inst.operands[1];

    const old = version_for.get(alloca_val) orelse NO_VALUE;
    try version_for.put(alloca_val, stored_val);
    try push_log.append(.{ .alloca = alloca_val, .old_version = old });
}
if (inst.op == .load and inst.operands.len >= 1 and inst.operands[0] == alloca_val) {
    const load_val = inst.result;
    const current_version = version_for.get(alloca_val) orelse alloca_val;
    if (load_val != current_version) {
        replaceAllUses(func, load_val, current_version);
    }

    }
}

const current_version = version_for.get(alloca_val) orelse alloca_val;
const succs = func.blocks.items[bid].succs.items;
for (succs) |succ| {
    if (phi_for_block.get(succ)) |phi_val| {
        const succ_block = func.getBlock(succ);
        for (succ_block.instrs.items) |*inst| {
            if (inst.op == .phi and inst.result == phi_val) {

        const old_inc = inst.data.phi_incoming;
        const new_inc = try func.allocator.alloc(bir.PhiIncoming, old_inc.len + 1);
        for (old_inc, 0..) |inc, i| {
            new_inc[i] = inc;
        }
        if (old_inc.len > 0) func.allocator.free(old_inc);
        new_inc[old_inc.len] = .{ .value = current_version, .block = bid };
        inst.data.phi_incoming = new_inc;
    }
}

    }
}

for (dom_tree.children[bid]) |child| {
    try renameBlock(module, func, func_id, cfg, dom_tree, phi_for_block, version_for, push_log, child, alloca_val);
}

while (push_log.items.len > saved_len) {
    const entry = pop(push_log);
    try version_for.put(entry.alloca, entry.old_version);

    }
}

fn pop(list: anytype) @TypeOf(list.items[0]) {
    const idx = list.items.len - 1;
    const val = list.items[idx];
    list.items.len = idx;
    return val;
}

fn replaceAllUses(func: *bir.Function, old_val: ValueId, new_val: ValueId) void {
    if (old_val == new_val) return;
    if (old_val > func.locals_count) return;
    const old_vi = func.getValueInfo(old_val);
    const uses_copy = func.allocator.dupe(ValueId, old_vi.uses.items) catch return;
    defer func.allocator.free(uses_copy);

    for (uses_copy) |user_val| {
        if (user_val == NO_VALUE or user_val > func.locals_count) continue;
        const user_vi = func.getValueInfo(user_val);

if (user_vi.def.block == INVALID_ID) continue;
if (user_vi.def.block >= func.blocks.items.len) continue;
const block = func.getBlock(user_vi.def.block);
if (user_vi.def.idx >= block.instrs.items.len) continue;
const inst = &block.instrs.items[user_vi.def.idx];

for (inst.operands) |*op| {
    if (op.* == old_val) op.* = new_val;
}
switch (inst.data) {

.phi_incoming => |incoming| {
    for (incoming) |*inc| {
        if (inc.value == old_val) inc.value = new_val;
    }
},
.cond_branch => |*cb| {
    if (cb.cond == old_val) cb.cond = new_val;
},
.call_info => |*ci| {
    if (ci.callee == old_val) ci.callee = new_val;

    for (ci.args) |*arg| {
        if (arg.* == old_val) arg.* = new_val;
    }
},
.named_call => |*nc| {
    for (nc.args) |*arg| {
        if (arg.* == old_val) arg.* = new_val;
    }
},
.gep_info => |*gi| {

    if (gi.ptr == old_val) gi.ptr = new_val;
    for (gi.indices) |*idx| {
        if (idx.* == old_val) idx.* = new_val;
    }
},
.texture_store_info => |*tsi| {
    if (tsi.tex == old_val) tsi.tex = new_val;
    if (tsi.coord_x == old_val) tsi.coord_x = new_val;
    if (tsi.coord_y == old_val) tsi.coord_y = new_val;
    if (tsi.val == old_val) tsi.val = new_val;

},
.sample_info => |*si| {
    if (si.tex == old_val) si.tex = new_val;
    if (si.sampler == old_val) si.sampler = new_val;
    if (si.coord == old_val) si.coord = new_val;
    if (si.lod) |*lod| {
        if (lod.* == old_val) lod.* = new_val;
    }
    if (si.offset) |*off| {
        if (off.* == old_val) off.* = new_val;

    }
},
.atomic_info => |*ai| {
    if (ai.ptr == old_val) ai.ptr = new_val;
    if (ai.val == old_val) ai.val = new_val;
},
.vector_shuffle => |*vs| {
    if (vs.a == old_val) vs.a = new_val;
    if (vs.b == old_val) vs.b = new_val;
},

            else => {},
        }

        const new_vi = func.getValueInfo(new_val);
        new_vi.uses.append(user_val) catch {};
    }

    old_vi.uses.clearRetainingCapacity();
}

