pub fn verifyCFG(
    func: *const bir.Function,

    cfg: *const bir_cfg.CFG,
    func_id: FunctionId,
    errs: *DiagnosticList,
) !void {
    const nblocks = func.blocks.items.len;
    if (nblocks == 0) return;

    if (cfg.entry != 0) {
        try errs.push(.{
            .code = .invalid_block_id,

        .func_id = func_id,
        .func_name = func.name,
        .block_id = cfg.entry,
        .message = "CFG entry block is not block 0",
    });
}

if (nblocks > 0) {
    const entry = &func.blocks.items[0];
    if (entry.preds.items.len > 0) {

        try errs.push(.{
            .code = .entry_block_has_predecessor,
            .func_id = func_id,
            .func_name = func.name,
            .block_id = 0,
            .block_name = entry.label,
            .message = "entry block has predecessors",
        });
    }
}

for (func.blocks.items, 0..) |block, bid| {
    const block_id = @as(BlockId, @intCast(bid));
    if (block.instrs.items.len == 0) continue;

    const last_inst = block.instrs.items[block.instrs.items.len - 1];
    switch (last_inst.op) {
        .br => {
            const target = last_inst.data.block_target;
            if (target >= nblocks) {

    try errs.push(.{
        .code = .successor_out_of_range,
        .func_id = func_id,
        .func_name = func.name,
        .block_id = block_id,
        .block_name = block.label,
        .op = .br,
        .message = "branch target block ID out of range",
    });
}

},
.cond_br => {
    const cb = last_inst.data.cond_branch;
    if (cb.then_block >= nblocks or cb.else_block >= nblocks) {
        try errs.push(.{
            .code = .successor_out_of_range,
            .func_id = func_id,
            .func_name = func.name,
            .block_id = block_id,
            .block_name = block.label,

            .op = .cond_br,
            .message = "conditional branch target block ID out of range",
        });
    }
},
.branch_on_bit => {
    const bob = last_inst.data.branch_on_bit;
    if (bob.then_block >= nblocks or bob.else_block >= nblocks) {
        try errs.push(.{
            .code = .successor_out_of_range,

            .func_id = func_id,
            .func_name = func.name,
            .block_id = block_id,
            .block_name = block.label,
            .op = .branch_on_bit,
            .message = "branch_on_bit target block ID out of range",
        });
    }
},
else => {},

    }
}

for (func.blocks.items, 0..) |block, bid| {
    const block_id = @as(BlockId, @intCast(bid));

    for (block.succs.items) |succ| {
        if (succ >= nblocks) {
            try errs.push(.{
                .code = .successor_out_of_range,

        .func_id = func_id,
        .func_name = func.name,
        .block_id = block_id,
        .block_name = block.label,
        .message = "successor block ID out of range in CFG edges",
    });
    continue;
}

var found = false;

for (func.blocks.items[succ].preds.items) |pred| {
    if (pred == block_id) {
        found = true;
        break;
    }
}
if (!found) {
    try errs.push(.{
        .code = .predecessor_symmetry_broken,
        .func_id = func_id,

            .func_name = func.name,
            .block_id = block_id,
            .block_name = block.label,
            .message = "successor does not list this block as predecessor",
        });
    }
}

for (block.preds.items) |pred| {
    if (pred >= nblocks) {

    try errs.push(.{
        .code = .successor_out_of_range,
        .func_id = func_id,
        .func_name = func.name,
        .block_id = block_id,
        .block_name = block.label,
        .message = "predecessor block ID out of range in CFG edges",
    });
    continue;
}

var found = false;
for (func.blocks.items[pred].succs.items) |succ| {
    if (succ == block_id) {
        found = true;
        break;
    }
}
if (!found) {
    try errs.push(.{

                .code = .predecessor_symmetry_broken,
                .func_id = func_id,
                .func_name = func.name,
                .block_id = block_id,
                .block_name = block.label,
                .message = "predecessor does not list this block as successor",
            });
        }
    }
}

const std = @import("std");
const Allocator = std.mem.Allocator;
const bir = @import("../bir.zig");
const FunctionId = bir.FunctionId;
const BlockId = bir.BlockId;
const ValueId = bir.ValueId;
const TypeId = bir.TypeId;
const Op = bir.Op;

pub const ErrorCode = enum {

    use_def_symmetry_broken,
    data_ref_use_def_symmetry_broken,
};

pub const Diagnostic = struct {
    code: ErrorCode,
    func_id: ?FunctionId = null,
    func_name: ?[]const u8 = null,
    block_id: ?BlockId = null,
    block_name: ?[]const u8 = null,

        return .{ .diag = self, .module = module };
    }
};

pub const DiagnosticFormatter = struct {
    diag: Diagnostic,
    module: ?*const bir.Module,

    pub fn format(self: DiagnosticFormatter, comptime fmt: []const u8, options: std.fmt.FormatOptions, writer: anytype) !void {
        _ = fmt;

_ = options;

const w = writer;

try w.writeAll("error: ");
try w.writeAll(@tagName(self.diag.code));

if (self.diag.message) |msg| {
    try w.writeAll(": ");
    try w.writeAll(msg);

}
try w.writeAll("\n");

if (self.diag.func_name) |name| {
    try w.writeAll("  in function: '");
    try w.writeAll(name);
    try w.writeAll("'\n");
}

if (self.diag.block_name) |name| {

    try w.writeAll("  in block: '");
    try w.writeAll(name);
    try w.writeAll("'\n");
} else if (self.diag.block_id) |bid| {
    try w.print("  in block: b{d}\n", .{bid});
}

if (self.diag.inst_idx) |idx| {
    try w.print("  at instruction index: {d}\n", .{idx});
}

if (self.diag.value_id) |vid| {
    try w.print("  for value: %{d}\n", .{vid});
}

if (self.diag.type_id) |tid| {
    try w.print("  type: %{d}\n", .{tid});
}

if (self.diag.expected_type) |et| {

    try w.print("  expected type: %{d}\n", .{et});
}

if (self.diag.other_type_id) |ot| {
    try w.print("  got type: %{d}\n", .{ot});
}

if (self.diag.op) |op| {
    try w.print("  opcode: .{s}\n", .{@tagName(op)});
}

        return;
    }
};

pub const DiagnosticList = struct {
    list: std.ArrayList(Diagnostic),
    allocator: Allocator,

    pub fn init(allocator: Allocator) DiagnosticList {

    return .{
        .list = std.ArrayList(Diagnostic).init(allocator),
        .allocator = allocator,
    };
}

pub fn deinit(self: *DiagnosticList) void {
    self.list.deinit();
}

pub fn push(self: *DiagnosticList, diag: Diagnostic) !void {
    try self.list.append(diag);
}

pub fn len(self: *const DiagnosticList) usize {
    return self.list.items.len;
}

pub fn hasErrors(self: *const DiagnosticList) bool {
    return self.list.items.len > 0;

    }

    pub fn printAll(self: *const DiagnosticList, writer: anytype, module: ?*const bir.Module) !void {
        for (self.list.items) |diag| {
            try diag.format(module).format("", .{}, writer);
        }
    }
};

const std = @import("std");
const bir = @import("../bir.zig");
const FunctionId = bir.FunctionId;
const BlockId = bir.BlockId;
const Op = bir.Op;
const diagnostics = @import("diagnostics.zig");
const DiagnosticList = diagnostics.DiagnosticList;

pub fn verifyFunction(func: *const bir.Function, func_id: FunctionId, errs: *DiagnosticList) !void {
    if (func.blocks.items.len == 0) {

    try errs.push(.{
        .code = .empty_function,
        .func_id = func_id,
        .func_name = func.name,
        .message = "function has no basic blocks",
    });
    return;
}

for (func.blocks.items, 0..) |block, bid| {

const block_id = @as(BlockId, @intCast(bid));

if (block.instrs.items.len == 0) continue;

const last_inst = block.instrs.items[block.instrs.items.len - 1];
const is_terminator = isTerminatorOp(last_inst.op);

if (!is_terminator) {
    try errs.push(.{
        .code = .block_has_no_terminator,

        .func_id = func_id,
        .func_name = func.name,
        .block_id = block_id,
        .block_name = block.label,
        .inst_idx = @intCast(block.instrs.items.len - 1),
        .op = last_inst.op,
        .message = "block does not end with a terminator instruction",
    });
}

var found_terminator = false;
for (block.instrs.items, 0..) |inst, i| {
    if (isTerminatorOp(inst.op)) {
        if (found_terminator) {
            try errs.push(.{
                .code = .instruction_after_terminator,
                .func_id = func_id,
                .func_name = func.name,
                .block_id = block_id,
                .block_name = block.label,

                    .inst_idx = @intCast(i),
                    .op = inst.op,
                    .message = "instruction found after terminator",
                });
                break;
            }
            found_terminator = true;
        }
    }
}

}

pub fn isTerminatorOp(op: Op) bool {
    return switch (op) {
        .br, .cond_br, .ret, .unreachable_op, .branch_on_bit => true,
        else => false,
    };
}

