        .{ .label = "then", .stmts = &.{}, .terminator = .{ .br = BlockId.new(3) } },
        .{ .label = "else", .stmts = &.{}, .terminator = .{ .br = BlockId.new(3) } },
        .{ .label = "merge", .stmts = &.{}, .terminator = .{ .return_ret = .{ .value = null } } },

};
var func = makeFunction(&blocks, BlockId.new(0));

