// ─── IR Stores ───
pub const HirExprStore = std.ArrayList(HirExpr);
pub const HirStmtStore = std.ArrayList(HirStmt);
pub const HirItemStore = std.ArrayList(HirItem);
pub const HirBodyStore = std.ArrayList(HirBody);

pub const HirPatternStore = std.ArrayList(HirPattern);

// ─── Lowering Error ───
pub const LowerError = error{
    OutOfMemory,
    UnsupportedSyntax,
    UnresolvedName,
    MismatchedType,
};

// ─── Loop Context ───
const LoopContext = struct {
    break_block: thir.BlockId,
    continue_block: thir.BlockId,
    next: ?*const LoopContext = null,
};

// ─── Lowering Context ───
pub const LowerContext = struct {
    backing: Allocator,

// Map HIR DefId → THIR ValueId for variables and params
def_to_value: std.AutoHashMap(HirDefId, thir.ValueId),

// Current function being lowered
func: ?*thir.ThirFunction = null,

// Current block being built
current_stmts: std.ArrayList(thir.ThirStmt),
current_terminator: ?thir.BasicBlock.Terminator = null,

    stmts: *const HirStmtStore,
    items: *const HirItemStore,
    hir_bodies: *const HirBodyStore,
) LowerContext {
    const arena_ptr = backing.create(std.heap.ArenaAllocator) catch unreachable;
    arena_ptr.* = std.heap.ArenaAllocator.init(backing);
    const allocator = arena_ptr.allocator();
    return .{
        .backing = backing,
        .arena = arena_ptr,

        .blocks = std.ArrayList(thir.BasicBlock).init(allocator),
        .block_labels = std.ArrayList([]const u8).init(allocator),
        .values = std.ArrayList(thir.ValueDef).init(allocator),
        .value_exprs = std.ArrayList(thir.ThirExpr).init(allocator),
        .places = std.ArrayList(thir.PlaceDesc).init(allocator),
    };
}

pub fn deinit(self: *LowerContext) void {
    self.arena.deinit();

    self.backing.destroy(self.arena);
}


// ─── Value Allocation ───
pub fn allocValue(self: *LowerContext, ty: ids.TypeId, storage: thir.Storage) !thir.ValueId {
    const id = thir.ValueId.new(@intCast(self.values.items.len));
    try self.values.append(.{ .ty = ty, .storage = storage, .expr = ids.ExprId.new(id.index) });
    try self.value_exprs.append(.{ .span = .{}, .ty = ty, .kind = .{ .none = {} } });
    return id;

}

pub fn setExpr(self: *LowerContext, vid: thir.ValueId, expr: thir.ThirExpr) !void {
    self.value_exprs.items[vid.index] = expr;
}

pub fn allocLocal(self: *LowerContext, ty: ids.TypeId, mutable: bool) !thir.ValueId {
    const id = try self.allocValue(ty, .stack);
    try self.places.append(.{ .ty = ty, .storage = .stack, .mutable = mutable, .span = .{} });
    return id;

}

// ─── Block Management ───
pub fn startBlock(self: *LowerContext, label: []const u8) !thir.BlockId {
    const id = thir.BlockId.new(@intCast(self.blocks.items.len));
    try self.block_labels.append(label);
    try self.blocks.append(.{
        .label = label,
        .stmts = &.{},
        .terminator = .{ .diverge = {} },

    });
    self.current_stmts.clearRetainingCapacity();
    self.current_terminator = null;
    return id;
}

pub fn finishBlock(self: *LowerContext, id: thir.BlockId, term: thir.BasicBlock.Terminator) void {
    self.blocks.items[id.index].terminator = term;
    self.blocks.items[id.index].stmts = self.current_stmts.toOwnedSlice() catch unreachable;
}

// ─── Emit Statement ───
pub fn emitStmt(self: *LowerContext, stmt: thir.ThirStmt) !void {
    try self.current_stmts.append(stmt);
}

// ─── Expression Lowering ───
// Returns the ValueId of the result (or NO_VALUE for unit expressions).
pub fn lowerExpr(self: *LowerContext, expr_id: HirExprId) LowerError!thir.ValueId {
    const expr = self.hir_exprs.items[expr_id.index];

// ─── Statement Lowering ───
pub fn lowerStmt(self: *LowerContext, stmt_id: HirStmtId) LowerError!void {
    const stmt = self.stmts.items[stmt_id.index];

    switch (stmt.kind) {
        .local_decl => |ld| try self.lowerLocalDecl(ld, stmt.span),
        .expr => |es| {
            const val = try self.lowerExpr(es.expr);
            if (!val.eql(thir.NO_VALUE)) {
                try self.emitStmt(.{

            .span = stmt.span,
            .kind = .{ .expr_stmt = .{ .expr = val } },
        });
    }
},
.if_stmt => |is| try self.lowerIfStmt(is, stmt.span),
.while_stmt => |ws| try self.lowerWhileStmt(ws, stmt.span),
.for_stmt => |fs| try self.lowerForStmt(fs, stmt.span),
.loop_stmt => |ls| try self.lowerLoopStmt(ls, stmt.span),
.return_stmt => |rs| {

    const val = if (rs.value) |v| try self.lowerExpr(v) else null;
    try self.emitStmt(.{
        .span = stmt.span,
        .kind = .{ .return_stmt = .{ .value = val } },
    });
},
.break_stmt => |bs| {
    const val = if (bs.value) |v| try self.lowerExpr(v) else null;
    const loop_blk = self.loop_ctx.?.break_block;
    try self.emitStmt(.{

        .span = stmt.span,
        .kind = .{ .break_stmt = .{ .value = val, .target_loop = loop_blk } },
    });
},
.continue_stmt => |cs| {
    _ = cs;
    const loop_blk = self.loop_ctx.?.continue_block;
    try self.emitStmt(.{
        .span = stmt.span,
        .kind = .{ .continue_stmt = .{ .target_loop = loop_blk } },

            });
        },
        .block => |bs| {
            for (bs.stmts) |s| try self.lowerStmt(s);
        },
        .defer_stmt => return LowerError.UnsupportedSyntax,
        .errdefer_stmt => return LowerError.UnsupportedSyntax,
        .missing => {},
    }
}

// ─── Specific Lowerers ───

fn lowerLiteral(self: *LowerContext, lit: HirLiteral, ty: ids.TypeId) !thir.ValueId {
    const val = try self.allocValue(ty, .local_reg);
    const thir_lit: thir.Literal = switch (lit) {
        .int => |v| .{ .int = v },
        .float => |v| .{ .float = v },
        .boolean => |v| .{ .bool_val = v },
        .string => |s| .{ .string = try self.allocator.dupe(u8, s) },

    };
    try self.setExpr(val, .{ .span = .{}, .ty = ty, .kind = .{ .literal = thir_lit } });
    return val;
}

fn lowerPath(self: *LowerContext, path: HirExpr.HirExprKind.PathExpr) !thir.ValueId {
    if (self.def_to_value.get(path.def)) |var_vid| {
        const var_ty = self.values.items[var_vid.index].ty;
        const result = try self.allocValue(var_ty, .local_reg);
        try self.setExpr(result, .{ .span = .{}, .ty = var_ty, .kind = .{ .load = .{ .place = .{ .local = var_vid, .projections = &.{} } } } });

        return result;
    }
    // Unknown definition — produce a zero value as placeholder
    const val = try self.allocValue(.{ .index = 0 }, .local_reg);
    try self.setExpr(val, .{ .span = .{}, .ty = .{ .index = 0 }, .kind = .{ .literal = .{ .int = 0 } } });
    return val;
}

fn lowerBinary(self: *LowerContext, b: HirExpr.HirExprKind.BinaryExpr, ty: ids.TypeId) !thir.ValueId {
    const lhs = try self.lowerExpr(b.left);

    const rhs = try self.lowerExpr(b.right);
    const result = try self.allocValue(ty, .local_reg);
    const op = mapBinOp(b.op);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .binary = .{ .op = op, .lhs = lhs, .rhs = rhs } } });
    return result;
}

fn lowerUnary(self: *LowerContext, u: HirExpr.HirExprKind.UnaryExpr, ty: ids.TypeId) !thir.ValueId {
    const operand = try self.lowerExpr(u.operand);
    const result = try self.allocValue(ty, .local_reg);

    const op = mapUnOp(u.op);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .unary = .{ .op = op, .operand = operand } } });
    return result;
}

fn lowerCall(self: *LowerContext, c: HirExpr.HirExprKind.CallExpr, ty: ids.TypeId) !thir.ValueId {
    var args = try self.allocator.alloc(thir.ValueId, c.args.len);
    for (c.args, 0..) |arg, i| {
        args[i] = try self.lowerExpr(arg);
    }

const callee_expr = self.hir_exprs.items[c.callee.index];
const func_def_id = switch (callee_expr.kind) {
    .path => |p| p.def,
    else => HirDefId{ .index = 0 },
};

const resolved_ty = if (ty.isValid()) ty else resolved: {
    var found = ty;
    for (self.items.items) |item| {

switch (item.kind) {
    .fn_decl => |f| {
        if (f.def_id.eql(func_def_id)) {
            found = f.return_type;
            break;
        }
    },
    .extern_fn => |e| {
        if (e.def_id.eql(func_def_id)) {
            found = e.return_type;

                    break;
                }
            },
            else => {},
        }
    }
    break :resolved found;
};

const ret = if (resolved_ty.isValid())

        try self.allocValue(resolved_ty, .local_reg)
    else
        thir.NO_VALUE;

    if (!ret.eql(thir.NO_VALUE)) {
        try self.setExpr(ret, .{ .span = .{}, .ty = resolved_ty, .kind = .{ .call = .{ .func = .{ .function = func_def_id }, .args = args, .ret_ty = resolved_ty } } });
    }

    return ret;
}

fn lowerMethodCall(self: *LowerContext, mc: HirExpr.HirExprKind.MethodCallExpr, ty: ids.TypeId) !thir.ValueId {
    const object = try self.lowerExpr(mc.object);
    const call_args_len = mc.args.len + 1;
    var args = try self.allocator.alloc(thir.ValueId, call_args_len);
    args[0] = object;
    for (mc.args, 1..) |arg, i| {
        args[i] = try self.lowerExpr(arg);
    }

const ret = if (ty.isValid())
    try self.allocValue(ty, .local_reg)
else
    thir.NO_VALUE;

if (!ret.eql(thir.NO_VALUE)) {
    try self.setExpr(ret, .{ .span = .{}, .ty = ty, .kind = .{ .call = .{ .func = .{ .function = mc.method }, .args = args, .ret_ty = ty } } });
}

return ret;

}

fn lowerField(self: *LowerContext, f: HirExpr.HirExprKind.FieldExpr, ty: ids.TypeId) !thir.ValueId {
    const object = try self.lowerExpr(f.object);
    const result = try self.allocValue(ty, .local_reg);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .field_addr = .{ .object = object, .field_index = 0 } } });
    return result;
}

fn lowerIndex(self: *LowerContext, idx: HirExpr.HirExprKind.IndexExpr, ty: ids.TypeId) !thir.ValueId {

    const object = try self.lowerExpr(idx.object);
    const index = try self.lowerExpr(idx.index);
    const result = try self.allocValue(ty, .local_reg);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .index_addr = .{ .object = object, .index = index } } });
    return result;
}

fn lowerAssign(self: *LowerContext, a: HirExpr.HirExprKind.AssignExpr) !thir.ValueId {
    const value = try self.lowerExpr(a.value);
    // target is a place — for now just emit the store

    try self.emitStmt(.{
        .span = .{},
        .kind = .{ .assignment = .{
            .place = value,
            .value = value,
        } },
    });
    return thir.NO_VALUE;
}

fn lowerIf(self: *LowerContext, if_e: HirExpr.HirExprKind.IfExpr, ty: ids.TypeId) !thir.ValueId {
    // if as expression → phi-like merge
    const cond = try self.lowerExpr(if_e.condition);
    const then_blk = try self.startBlock("if.then");
    const else_blk = try self.startBlock("if.else");
    const merge_blk = try self.startBlock("if.merge");

    // terminator for current block
    self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 3)), .{
        .cond_br = .{ .cond = cond, .then = then_blk, .else_ = else_blk },

});

// Lower then branch
const then_val = try self.lowerExpr(if_e.then_branch);
try self.emitStmt(.{
    .span = .{},
    .kind = .{ .break_stmt = .{ .value = if (!then_val.eql(thir.NO_VALUE)) then_val else null, .target_loop = merge_blk } },
});
self.finishBlock(then_blk, .{ .br = merge_blk });

// Lower else branch
const else_val = try self.lowerExpr(if_e.else_branch);
try self.emitStmt(.{
    .span = .{},
    .kind = .{ .break_stmt = .{ .value = if (!else_val.eql(thir.NO_VALUE)) else_val else null, .target_loop = merge_blk } },
});
self.finishBlock(else_blk, .{ .br = merge_blk });

// In merge block, result = phi
const result_val = if (ty.isValid()) try self.allocValue(ty, .local_reg) else thir.NO_VALUE;

    return result_val;
}

fn lowerWhile(self: *LowerContext, w: HirExpr.HirExprKind.WhileExpr, ty: ids.TypeId) !thir.ValueId {
    const cond_blk = try self.startBlock("while.cond");
    const body_blk = try self.startBlock("while.body");
    const exit_blk = try self.startBlock("while.exit");

    try self.emitStmt(.{
        .span = .{},

    .kind = .{ .block = .{ .block = cond_blk } },
});
self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 4)), .{ .br = cond_blk });

// cond check
const cond = try self.lowerExpr(w.condition);
self.finishBlock(cond_blk, .{ .cond_br = .{ .cond = cond, .then = body_blk, .else_ = exit_blk } });

// body
var ctx = LoopContext{ .break_block = exit_blk, .continue_block = cond_blk, .next = self.loop_ctx };

self.loop_ctx = &ctx;
_ = try self.lowerExpr(w.body);
self.loop_ctx = ctx.next;
try self.emitStmt(.{
    .span = .{},
    .kind = .{ .continue_stmt = .{ .target_loop = cond_blk } },
});
self.finishBlock(body_blk, .{ .br = cond_blk });

_ = ty;

    return thir.NO_VALUE;
}

fn lowerFor(self: *LowerContext, f: HirExpr.HirExprKind.ForExpr, ty: ids.TypeId) !thir.ValueId {
    // for = while with iterator
    // Simplified: lower body as a loop
    const body_blk = try self.startBlock("for.body");
    const exit_blk = try self.startBlock("for.exit");
    _ = try self.lowerExpr(f.iterable);

    var ctx = LoopContext{ .break_block = exit_blk, .continue_block = body_blk, .next = self.loop_ctx };
    self.loop_ctx = &ctx;
    _ = try self.lowerExpr(f.body);
    self.loop_ctx = ctx.next;
    self.finishBlock(body_blk, .{ .br = body_blk });

    _ = ty;
    _ = f.iter_var;
    return thir.NO_VALUE;
}

fn lowerLoop(self: *LowerContext, l: HirExpr.HirExprKind.LoopExpr, ty: ids.TypeId) !thir.ValueId {
    const body_blk = try self.startBlock("loop.body");
    const exit_blk = try self.startBlock("loop.exit");

    self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 2)), .{ .br = body_blk });

    var ctx = LoopContext{ .break_block = exit_blk, .continue_block = body_blk, .next = self.loop_ctx };
    self.loop_ctx = &ctx;
    _ = try self.lowerExpr(l.body);

    self.loop_ctx = ctx.next;

    self.finishBlock(body_blk, .{ .br = body_blk });

    _ = ty;
    return thir.NO_VALUE;
}

fn lowerBlock(self: *LowerContext, b: HirExpr.HirExprKind.BlockExpr, ty: ids.TypeId) !thir.ValueId {
    for (b.stmts) |s| try self.lowerStmt(s);

    const result = try self.lowerExpr(b.result);
    _ = ty;
    return result;
}

fn lowerReturn(self: *LowerContext, r: HirExpr.HirExprKind.ReturnExpr) !thir.ValueId {
    const val = if (r.value.index != 0) try self.lowerExpr(r.value) else null;
    try self.emitStmt(.{
        .span = .{},
        .kind = .{ .return_stmt = .{ .value = val } },

    });
    return thir.NO_VALUE;
}

fn lowerBreak(self: *LowerContext, b: HirExpr.HirExprKind.BreakExpr) !thir.ValueId {
    const val = if (b.value.index != 0) try self.lowerExpr(b.value) else null;
    const target = self.loop_ctx.?.break_block;
    try self.emitStmt(.{
        .span = .{},
        .kind = .{ .break_stmt = .{ .value = val, .target_loop = target } },

    });
    return thir.NO_VALUE;
}

fn lowerContinue(self: *LowerContext, c: HirExpr.HirExprKind.ContinueExpr) !thir.ValueId {
    _ = c;
    const target = self.loop_ctx.?.continue_block;
    try self.emitStmt(.{
        .span = .{},
        .kind = .{ .continue_stmt = .{ .target_loop = target } },

    });
    return thir.NO_VALUE;
}

fn lowerCast(self: *LowerContext, tc: HirExpr.HirExprKind.TypeCastExpr, ty: ids.TypeId) !thir.ValueId {
    const operand = try self.lowerExpr(tc.operand);
    const result = try self.allocValue(ty, .local_reg);
    const from_ty = self.getValueType(operand);
    const cast_kind = self.classifyCast(from_ty, tc.target_type);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .cast = .{ .kind = cast_kind, .operand = operand, .from_ty = from_ty, .to_ty = tc.target_type } } });

    return result;
}

fn lowerRef(self: *LowerContext, r: HirExpr.HirExprKind.RefExpr, ty: ids.TypeId) !thir.ValueId {
    const operand = try self.lowerExpr(r.operand);
    const result = try self.allocValue(ty, .local_reg);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .addr_of = .{ .operand = operand, .mut = r.mutable } } });
    return result;
}

fn lowerDeref(self: *LowerContext, d: HirExpr.HirExprKind.DerefExpr, ty: ids.TypeId) !thir.ValueId {
    const operand = try self.lowerExpr(d.operand);
    const result = try self.allocValue(ty, .local_reg);
    try self.setExpr(result, .{ .span = .{}, .ty = ty, .kind = .{ .deref = .{ .operand = operand } } });
    return result;
}

fn lowerMatch(self: *LowerContext, m: HirExpr.HirExprKind.MatchExpr, ty: ids.TypeId) !thir.ValueId {
    // match → switch tree
    const scrutinee = try self.lowerExpr(m.scrutinee);

const exit_blk = try self.startBlock("match.exit");
_ = exit_blk;

// Simplified: lower first arm only for now
for (m.arms) |arm| {
    _ = try self.lowerExpr(arm.body);
    _ = arm.pattern;
    _ = arm.guard;
}

    _ = scrutinee;
    _ = ty;
    return thir.NO_VALUE;
}

fn lowerRange(self: *LowerContext, r: HirExpr.HirExprKind.RangeExpr, ty: ids.TypeId) !thir.ValueId {
    _ = try self.lowerExpr(r.start);
    _ = try self.lowerExpr(r.end);
    _ = ty;
    return thir.NO_VALUE;

}

// ─── Statement Lowerers ───

fn lowerLocalDecl(self: *LowerContext, ld: HirStmt.HirStmtKind.LocalDecl, span: SourceSpan) !void {
    const init_val = if (ld.init) |e| try self.lowerExpr(e) else thir.NO_VALUE;
    const mutable = ld.kind == .@"var" or ld.kind == .let;

    // Allocate the local
    const ty = if (ld.type_annotation) |t| t else ids.TypeId{ .index = 0 };

const place_val = try self.allocLocal(ty, mutable);

if (!init_val.eql(thir.NO_VALUE)) {
    try self.emitStmt(.{
        .span = span,
        .kind = .{ .let = .{
            .place = place_val,
            .init = init_val,
            .storage = .stack,
        } },

        });
    }

    // Map the pattern's DefId to this THIR value
    const pat = self.hir_patterns.items[ld.pattern.index];
    if (pat.kind == .binding) {
        try self.def_to_value.put(pat.kind.binding.def, place_val);
    }
}

fn lowerIfStmt(self: *LowerContext, is: HirStmt.HirStmtKind.IfStmt, span: SourceSpan) !void {
    const cond = try self.lowerExpr(is.condition);
    const then_blk = try self.startBlock("if.then");
    const else_blk = try self.startBlock("if.else");
    const merge_blk = try self.startBlock("if.end");

    self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 4)), .{
        .cond_br = .{ .cond = cond, .then = then_blk, .else_ = else_blk },
    });

// then
try self.lowerStmt(is.then_branch);
try self.emitStmt(.{ .span = span, .kind = .{ .break_stmt = .{ .value = null, .target_loop = merge_blk } } });
self.finishBlock(then_blk, .{ .br = merge_blk });

// else
if (is.else_branch) |else_s| {
    try self.lowerStmt(else_s);
}
try self.emitStmt(.{ .span = span, .kind = .{ .break_stmt = .{ .value = null, .target_loop = merge_blk } } });

    self.finishBlock(else_blk, .{ .br = merge_blk });
}

fn lowerWhileStmt(self: *LowerContext, ws: HirStmt.HirStmtKind.WhileStmt, span: SourceSpan) !void {
    const cond_blk = try self.startBlock("while.cond");
    const body_blk = try self.startBlock("while.body");
    const exit_blk = try self.startBlock("while.exit");

    self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 4)), .{ .br = cond_blk });

    const cond = try self.lowerExpr(ws.condition);
    self.finishBlock(cond_blk, .{ .cond_br = .{ .cond = cond, .then = body_blk, .else_ = exit_blk } });

    var ctx = LoopContext{ .break_block = exit_blk, .continue_block = cond_blk, .next = self.loop_ctx };
    self.loop_ctx = &ctx;
    try self.lowerStmt(ws.body);
    self.loop_ctx = ctx.next;
    try self.emitStmt(.{ .span = span, .kind = .{ .continue_stmt = .{ .target_loop = cond_blk } } });
    self.finishBlock(body_blk, .{ .br = cond_blk });
}

fn lowerForStmt(self: *LowerContext, fs: HirStmt.HirStmtKind.ForStmt, span: SourceSpan) !void {
    const body_blk = try self.startBlock("for.body");
    const exit_blk = try self.startBlock("for.exit");
    _ = try self.lowerExpr(fs.iterable);

    var ctx = LoopContext{ .break_block = exit_blk, .continue_block = body_blk, .next = self.loop_ctx };
    self.loop_ctx = &ctx;
    try self.lowerStmt(fs.body);
    self.loop_ctx = ctx.next;

    try self.emitStmt(.{ .span = span, .kind = .{ .continue_stmt = .{ .target_loop = body_blk } } });
    self.finishBlock(body_blk, .{ .br = body_blk });
    _ = fs.iter_var;
}

fn lowerLoopStmt(self: *LowerContext, ls: HirStmt.HirStmtKind.LoopStmt, span: SourceSpan) !void {
    const body_blk = try self.startBlock("loop.body");
    const exit_blk = try self.startBlock("loop.exit");

    self.finishBlock(thir.BlockId.new(@intCast(self.blocks.items.len - 2)), .{ .br = body_blk });

    var ctx = LoopContext{ .break_block = exit_blk, .continue_block = body_blk, .next = self.loop_ctx };
    self.loop_ctx = &ctx;
    try self.lowerStmt(ls.body);
    self.loop_ctx = ctx.next;
    try self.emitStmt(.{ .span = span, .kind = .{ .continue_stmt = .{ .target_loop = body_blk } } });
    self.finishBlock(body_blk, .{ .br = body_blk });
}

// ─── Item Lowering ───

pub fn lowerItem(self: *LowerContext, item_idx: u32) !void {
    const item = self.items.items[item_idx];
    switch (item.kind) {
        .fn_decl => |f| try self.lowerFnDecl(f, item.span),
        .struct_item => |s| try self.lowerStructItem(s),
        .enum_item => |e| try self.lowerEnumItem(e),
        .const_item => |c| {
            _ = try self.lowerExpr(c.init);
        },

        .state_item, .kernel_item => {}, // Handled by domain-specific passes
        .impl_item => |impl_item| {
            for (impl_item.methods) |method| {
                try self.lowerFnDecl(method, item.span);
            }
        },
        else => {},
    }
}

fn lowerFnDecl(self: *LowerContext, f: HirItemKind.FnItem, span: SourceSpan) !void {
    var params = try self.allocator.alloc(thir.ThirFunction.Param, f.params.len);
    for (f.params, 0..) |p, i| {
        params[i] = .{
            .name = p.name,
            .def_id = p.def_id,
            .ty = p.ty,
            .storage = .stack,
        };
    }

};

self.func = &func;
self.blocks.clearRetainingCapacity();
self.values.clearRetainingCapacity();
self.value_exprs.clearRetainingCapacity();
self.places.clearRetainingCapacity();
self.current_stmts.clearRetainingCapacity();
self.def_to_value.clearRetainingCapacity();

// Create THIR values for parameters (SSA, not stack slots)
for (func.params) |param| {
    const param_val = try self.allocValue(param.ty, .local_reg);
    try self.def_to_value.put(param.def_id, param_val);
}

// Lower body
const entry_blk = try self.startBlock("entry");
const fb = self.hir_bodies.items[f.body.index];
const result_val = try self.lowerExpr(fb.entry);

const return_val: ?thir.ValueId = if (result_val.isValid()) result_val else null;
self.finishBlock(entry_blk, .{ .return_ret = .{ .value = return_val } });

// Build the body
func.body = .{
    .blocks = self.blocks.toOwnedSlice() catch unreachable,
    .entry = entry_blk,
    .values = self.values.toOwnedSlice() catch unreachable,
    .exprs = self.value_exprs.toOwnedSlice() catch unreachable,
    .places = self.places.toOwnedSlice() catch unreachable,

    };

    _ = span;
    _ = try self.module.addFunction(func);
}

fn lowerStructItem(self: *LowerContext, s: HirItemKind.StructItem) !void {
    var fields = try self.allocator.alloc(thir.ThirStruct.Field, s.fields.len);
    for (s.fields, 0..) |f, i| {
        fields[i] = .{ .name = f.name, .ty = f.ty };

    }
    try self.module.structs.append(.{
        .name = s.name,
        .def_id = s.def_id,
        .fields = fields,
    });
}

fn lowerEnumItem(self: *LowerContext, e: HirItemKind.EnumItem) !void {
    var variants = try self.allocator.alloc(thir.ThirEnum.Variant, e.variants.len);

for (e.variants, 0..) |v, i| {
    var fields = try self.allocator.alloc(thir.ThirStruct.Field, v.fields.len);
    for (v.fields, 0..) |f, j| {
        fields[j] = .{ .name = f.name, .ty = f.ty };
    }
    variants[i] = .{ .name = v.name, .fields = fields, .tag = @intCast(i) };
}
try self.module.enums.append(.{
    .name = e.name,
    .def_id = e.def_id,

        .variants = variants,
    });
}

// ─── Op Mapping ───

fn mapBinOp(op: HirBinOp) thir.BinOp {
    return switch (op) {
        .add => .add,
        .sub => .sub,

        .or_ => .or_,
        .bitwise_and => .bitwise_and,
        .bitwise_or => .bitwise_or,
        .bitwise_xor => .bitwise_xor,
        .shl => .shl,
        .shr => .shr,
    };
}

fn mapUnOp(op: HirUnOp) thir.UnOp {

    return switch (op) {
        .negate => .negate,
        .not => .not,
        .bitwise_not => .bitwise_not,
        else => unreachable,
    };
}

fn getValueType(self: *LowerContext, value: thir.ValueId) ids.TypeId {
    if (value.isValid() and value.index < self.values.items.len) {

        return self.values.items[value.index].ty;
    }
    return .{ .index = 0 };
}

fn classifyCast(self: *LowerContext, from: ids.TypeId, to: ids.TypeId) thir.CastKind {
    const from_resolved = self.type_engine.resolve(from);
    const to_resolved = self.type_engine.resolve(to);
    const from_data = self.type_engine.get(from_resolved);
    const to_data = self.type_engine.get(to_resolved);

if (from_data == null or to_data == null) return .bitcast;
const fd = from_data.?;
const td = to_data.?;

return switch (fd) {
    .builtin => |fb| switch (td) {
        .builtin => |tb| classifyBuiltinCast(fb, tb),
        .pointer => .pointer_cast,
        else => .bitcast,

},
.pointer => switch (td) {
    .pointer => .pointer_cast,
    .builtin => .pointer_to_int,
    else => .bitcast,
},
.slice => switch (td) {
    .pointer => .pointer_cast,
    else => .bitcast,
},

.array => switch (td) {
    .pointer => .pointer_cast,
    .slice => .unsize,
    else => .bitcast,
},
.reference => switch (td) {
    .pointer => .pointer_cast,
    else => .bitcast,
},
else => .bitcast,

    };
}

fn classifyBuiltinCast(from: type_sys.BuiltinKind, to: type_sys.BuiltinKind) thir.CastKind {
    if (from == to) return .bitcast;

    const from_is_int = builtinIsSignedInt(from) or builtinIsUnsignedInt(from);
    const to_is_int = builtinIsSignedInt(to) or builtinIsUnsignedInt(to);
    const from_is_float = builtinIsFloat(from);
    const to_is_float = builtinIsFloat(to);

if (from_is_int and to_is_int) {
    const fb = builtinBitWidth(from);
    const tb = builtinBitWidth(to);
    if (tb > fb) {
        if (builtinIsSignedInt(from) and builtinIsSignedInt(to)) return .int_extend_signed;
        if (builtinIsUnsignedInt(from) and builtinIsUnsignedInt(to)) return .int_extend_unsigned;
        return .int_extend_unsigned;
    }
    if (tb < fb) return .int_truncate;

    return .bitcast;
}

if (from_is_int and to_is_float) {
    return if (builtinIsUnsignedInt(from)) .uint_to_float else .int_to_float;
}

if (from_is_float and to_is_int) {
    return if (builtinIsUnsignedInt(to)) .float_to_uint else .float_to_int;
}

if (from_is_float and to_is_float) {
    const fb = builtinBitWidth(from);
    const tb = builtinBitWidth(to);
    if (tb > fb) return .float_extend;
    if (tb < fb) return .float_truncate;
    return .bitcast;
}

if (from == .bool_type and to_is_int) return .bool_to_int;

    if (from_is_int and to == .bool_type) return .int_to_bool;

    return .bitcast;
}

fn builtinIsSignedInt(k: type_sys.BuiltinKind) bool {
    return switch (k) {
        .i8_type, .i16_type, .i32_type, .i64_type => true,
        else => false,
    };

}

fn builtinIsUnsignedInt(k: type_sys.BuiltinKind) bool {
    return switch (k) {
        .u8_type, .u16_type, .u32_type, .u64_type => true,
        else => false,
    };
}

fn builtinIsFloat(k: type_sys.BuiltinKind) bool {

    return switch (k) {
        .f32_type, .f64_type => true,
        else => false,
    };
}

fn builtinBitWidth(k: type_sys.BuiltinKind) u32 {
    return switch (k) {
        .bool_type => 1,
        .i8_type, .u8_type, .char_type => 8,

            .i16_type, .u16_type => 16,
            .i32_type, .u32_type, .f32_type => 32,
            .i64_type, .u64_type, .f64_type => 64,
            .void_type, .never_type, .str_type => 0,
        };
    }
};

const std = @import("std");
const thir = @import("../thir.zig");
const ThirModule = thir.ThirModule;
const ThirFunction = thir.ThirFunction;
const ThirStmt = thir.ThirStmt;
const ThirExpr = thir.ThirExpr;
const BasicBlock = thir.BasicBlock;
const ThirValueId = thir.ValueId;
const ThirBlockId = thir.BlockId;
const ThirPlace = thir.Place;

const ThirCase = thir.ThirCase;
const ValueDef = thir.ValueDef;
const PlaceDesc = thir.PlaceDesc;
const Storage = thir.Storage;
const Literal = thir.Literal;
const BinOp = thir.BinOp;
const UnOp = thir.UnOp;
const CastKind = thir.CastKind;
const DefId = thir.DefId;
const SymbolId = thir.SymbolId;

const bir = @import("../../bir/bir.zig");
const bir_types = bir.types;
const Mem2RegPass = @import("../../bir/passes/ssa/mem2reg.zig").Mem2RegPass;
const BIRTypeId = bir_types.TypeId;
const ScalarKind = bir_types.ScalarKind;
const BIRValueId = bir.ValueId;
const BIRBlockId = bir.BlockId;
const Inst = bir.Inst;
const Op = bir.Op;
const PhiIncoming = bir.PhiIncoming;

const BIR_NO_VALUE = bir.NO_VALUE;
const hir_ty_mod = @import("../../../frontend/hir/ty.zig");
const HirTy = hir_ty_mod.HirTy;
const hir_item_mod = @import("../../../frontend/hir/item.zig");
const HirItem = hir_item_mod.HirItem;
const type_sys = @import("../../../frontend/type_system/type_system.zig");
const ids = @import("../../../frontend/foundation/ids/ids.zig");

pub const LowerError = error{ TypeError, OutOfMemory };

pub const ThirToBir = struct {
    allocator: std.mem.Allocator,
    thir_mod: *ThirModule,
    hir_types: *const std.ArrayList(HirTy),
    hir_items: *const std.ArrayList(HirItem),
    module: bir.Module,

    pub fn init(allocator: std.mem.Allocator, thir_mod: *ThirModule, hir_types: *const std.ArrayList(HirTy), hir_items: *const std.ArrayList(HirItem)) ThirToBir {
        return .{
            .allocator = allocator,

        .thir_mod = thir_mod,
        .hir_types = hir_types,
        .hir_items = hir_items,
        .module = bir.Module.init(allocator),
    };
}

pub fn deinit(self: *ThirToBir) void {
    self.module.deinit();
}

pub fn lower(self: *ThirToBir) anyerror!bir.Module {
    try self.ensureBuiltinTypes();
    for (self.thir_mod.functions.items) |*func| {
        try self.lowerFunction(func);
    }

    try self.runMem2Reg();

    const m = self.module;

    self.module = bir.Module.init(self.allocator);
    return m;
}

fn runMem2Reg(self: *ThirToBir) !void {
    var pm = bir.PassManager.init(self.allocator);
    defer pm.deinit();
    try pm.addPass(Mem2RegPass);

    var am = bir.AnalysisManager.init(self.allocator, &self.module);

    defer am.deinit();

    var ctx = bir.PassContext{
        .module = &self.module,
        .analysis = &am,
        .allocator = self.allocator,
    };
    try pm.run(&ctx);
}

fn ensureBuiltinTypes(self: *ThirToBir) !void {
    _ = try self.module.types.voidType();
    _ = try self.module.types.scalarType(.i1);
    _ = try self.module.types.scalarType(.i8);
    _ = try self.module.types.scalarType(.i16);
    _ = try self.module.types.scalarType(.i32);
    _ = try self.module.types.scalarType(.i64);
    _ = try self.module.types.scalarType(.u8);
    _ = try self.module.types.scalarType(.u16);
    _ = try self.module.types.scalarType(.u32);

    _ = try self.module.types.scalarType(.u64);
    _ = try self.module.types.scalarType(.f32);
    _ = try self.module.types.scalarType(.f64);
    _ = try self.module.types.pointerType(0, .generic);
}

fn builtinToBir(self: *ThirToBir, kind: HirTy.BuiltinKind) BIRTypeId {
    return switch (kind) {
        .bool => self.module.types.scalarType(.i1) catch 0,
        .i8 => self.module.types.scalarType(.i8) catch 0,

        .never => self.module.types.voidType() catch 0,
        .str => self.module.types.pointerType(0, .generic) catch 0,
        .char_type => self.module.types.scalarType(.u8) catch 0,
    };
}

fn typeToBir(self: *ThirToBir, ty: ids.TypeId) BIRTypeId {
    if (!ty.isValid()) return self.module.types.voidType() catch 0;
    if (ty.index >= self.hir_types.items.len) return self.module.types.voidType() catch 0;
    const hir_ty = self.hir_types.items[ty.index];

return switch (hir_ty) {
    .builtin => |b| self.builtinToBir(b.kind),
    .named => self.module.types.pointerType(0, .generic) catch 0,
    .pointer => self.module.types.pointerType(0, .generic) catch 0,
    .slice => self.module.types.pointerType(0, .generic) catch 0,
    .array => |a| {
        const elem = self.typeToBir(a.element);
        return self.module.types.arrayType(elem, @intCast(a.length)) catch 0;
    },
    .fn_type => self.module.types.pointerType(0, .generic) catch 0,

        .tuple => self.module.types.pointerType(0, .generic) catch 0,
        .inference_var => self.module.types.voidType() catch 0,
        .generic => self.module.types.pointerType(0, .generic) catch 0,
        .error_union => self.module.types.pointerType(0, .generic) catch 0,
        .optional => self.module.types.pointerType(0, .generic) catch 0,
        .missing => self.module.types.voidType() catch 0,
    };
}

fn lowerFunction(self: *ThirToBir, func: *ThirFunction) LowerError!void {

const ret_ty = self.typeToBir(func.return_type);
const owned_name = if (func.name_str.len > 0)
    try self.allocator.dupe(u8, func.name_str)
else
    try std.fmt.allocPrint(self.allocator, "fn_{d}", .{func.def_id.index});
defer self.allocator.free(owned_name);

const cc: bir.CallingConvention = switch (func.linkage) {
    .@"export" => .entry,
    .entry => .entry,

    .internal => .internal,
};

const func_id = try self.module.addFunction(owned_name, ret_ty, cc);

{
    const fn_mut = self.module.getFunctionMut(func_id);
    const owned_params = try self.allocator.alloc(bir.FuncParam, func.params.len);
    const owned_values = try self.allocator.alloc(BIRValueId, func.params.len);
    for (func.params, 0..) |param, i| {

        const param_ty = self.typeToBir(param.ty);
        owned_params[i] = .{
            .name = try std.fmt.allocPrint(self.allocator, "param_{d}", .{param.def_id.index}),
            .ty = param_ty,
        };
        owned_values[i] = try fn_mut.createValue();
    }
    fn_mut.params = owned_params;
    fn_mut.param_values = owned_values;
}

const body = func.body orelse return;

var block_map = std.AutoHashMap(ThirBlockId, BIRBlockId).init(self.allocator);
defer block_map.deinit();

var value_map = std.AutoHashMap(ThirValueId, Builder.ValueBinding).init(self.allocator);
defer value_map.deinit();

var value_ty_map = std.AutoHashMap(ThirValueId, BIRTypeId).init(self.allocator);

defer value_ty_map.deinit();

for (body.blocks, 0..) |_, i| {
    const label = try std.fmt.allocPrint(self.allocator, "bb{d}", .{i});
    defer self.allocator.free(label);
    const bir_blk = try self.module.addBlock(func_id, label);
    try block_map.put(ThirBlockId.new(@intCast(i)), bir_blk);
}

var param_map = std.AutoHashMap(DefId, Builder.ValueBinding).init(self.allocator);

defer param_map.deinit();

for (func.params, 0..) |param, i| {
    try param_map.put(param.def_id, .{ .value = self.module.getFunction(func_id).param_values[i], .kind = .ssa });
}

const entry_bir = block_map.get(body.entry) orelse 0;

for (body.values, 0..) |val_def, i| {
    const thir_vid = ThirValueId.new(@intCast(i));

if (val_def.storage == .stack) {
    const slot_ty = self.typeToBir(val_def.ty);
    const ptr_ty = try self.module.types.pointerType(slot_ty, .generic);
    const slot = try self.module.addInst(func_id, entry_bir, try makeInst(self.allocator, .alloca, ptr_ty, &.{}, .{ .none = {} }));
    try value_map.put(thir_vid, .{ .value = slot, .kind = .stack_slot });
    try value_ty_map.put(thir_vid, slot_ty);
} else {
    const slot_ty = self.typeToBir(val_def.ty);
    try value_ty_map.put(thir_vid, slot_ty);
}

}

// Map param THIR values to BIR param values (SSA, no allocas)
for (0..func.params.len) |i| {
    const thir_vid = ThirValueId.new(@intCast(i));
    const bir_val = self.module.getFunction(func_id).param_values[i];
    try value_map.put(thir_vid, .{ .value = bir_val, .kind = .ssa });
}

var builder = Builder{

    .ret_type = ret_ty,
};

for (body.blocks, 0..) |*blk, i| {
    const bir_blk_id = block_map.get(ThirBlockId.new(@intCast(i))) orelse continue;
    builder.blk = bir_blk_id;

    for (blk.stmts) |stmt| {
        try builder.lowerStmt(stmt);
        if (builder.terminated()) break;

            }

            if (!builder.terminated()) {
                try builder.lowerTerminator(blk.terminator);
            }
        }
    }
};

fn makeInst(allocator: std.mem.Allocator, op: Op, ty: BIRTypeId, ops: []const BIRValueId, data: Inst.Data) !Inst {

    var owned_ops: []BIRValueId = &.{};
    if (ops.len > 0) {
        owned_ops = try allocator.dupe(BIRValueId, ops);
    }
    return .{ .op = op, .ty = ty, .result = BIR_NO_VALUE, .operands = owned_ops, .data = data };
}

const Builder = struct {
    alloc: std.mem.Allocator,
    mod: *bir.Module,

pub const ValueBinding = struct {
    value: BIRValueId,
    kind: Kind,

    pub const Kind = enum {
        ssa,
        address,
        stack_slot,
    };
};

fn isTerminator(op: Op) bool {
    return switch (op) {
        .ret, .br, .cond_br, .unreachable_op => true,
        else => false,
    };
}

fn terminated(self: *Builder) bool {
    const bl = self.mod.getFunctionMut(self.fid).getBlock(self.blk);

    if (bl.instrs.items.len == 0) return false;
    return isTerminator(bl.instrs.items[bl.instrs.items.len - 1].op);
}

fn blockTerminated(self: *Builder, bir_blk: BIRBlockId) bool {
    const bl = self.mod.getFunctionMut(self.fid).getBlock(bir_blk);
    if (bl.instrs.items.len == 0) return false;
    return isTerminator(bl.instrs.items[bl.instrs.items.len - 1].op);
}

fn emitOp(self: *Builder, op: Op, ty: BIRTypeId, ops: []const BIRValueId, data: Inst.Data) !BIRValueId {
    return self.mod.addInst(self.fid, self.blk, try makeInst(self.alloc, op, ty, ops, data));
}

fn emitPhi(self: *Builder, ty: BIRTypeId, incoming: []const PhiIncoming) !BIRValueId {
    const owned = try self.alloc.dupe(PhiIncoming, incoming);
    const val = try self.mod.addPhi(self.fid, self.blk, ty, owned);
    return val;
}

fn emitAlloca(self: *Builder, func_id: bir.FunctionId, ty: BIRTypeId) !BIRValueId {
    return self.mod.addInst(func_id, self.blk, try makeInst(self.alloc, .alloca, ty, &.{}, .{ .none = {} }));
}

fn emitRet(self: *Builder, val: BIRValueId, ty: BIRTypeId) !void {
    const void_ty = self.mod.types.voidType() catch 0;
    if (val == BIR_NO_VALUE or ty == void_ty) {
        try self.retVoid();
    } else {
        _ = try self.emitOp(.ret, ty, &.{val}, .{ .none = {} });

    }
}

fn retVoid(self: *Builder) !void {
    const void_ty = self.mod.types.voidType() catch 0;
    _ = try self.emitOp(.ret, void_ty, &.{}, .{ .none = {} });
}

fn emitBr(self: *Builder, target: ThirBlockId) !void {
    const bir_target = self.block_map.get(target) orelse return;

    const void_ty = self.mod.types.voidType() catch 0;
    _ = try self.emitOp(.br, void_ty, &.{}, .{ .block_target = bir_target });
}

fn emitBrBir(self: *Builder, target: BIRBlockId) !void {
    const void_ty = self.mod.types.voidType() catch 0;
    _ = try self.emitOp(.br, void_ty, &.{}, .{ .block_target = target });
}

fn emitCondBr(self: *Builder, cond: BIRValueId, then_bir: BIRBlockId, else_bir: BIRBlockId) !void {

    const void_ty = self.mod.types.voidType() catch 0;
    _ = try self.emitOp(.cond_br, void_ty, &.{cond}, .{ .cond_branch = .{ .cond = cond, .then_block = then_bir, .else_block = else_bir } });
}

fn lookup(self: *Builder, vid: ThirValueId) ValueBinding {
    return self.value_map.get(vid) orelse .{ .value = BIR_NO_VALUE, .kind = .ssa };
}

fn lookupDef(self: *Builder, did: DefId) ValueBinding {
    return self.param_map.get(did) orelse .{ .value = BIR_NO_VALUE, .kind = .ssa };

}

fn storeSlot(self: *Builder, slot: BIRValueId, val: BIRValueId, ty: BIRTypeId) !void {
    _ = try self.emitOp(.store, ty, &.{ slot, val }, .{ .none = {} });
}

fn loadFromSlot(self: *Builder, slot: BIRValueId, ty: BIRTypeId) !BIRValueId {
    return self.emitOp(.load, ty, &.{slot}, .{ .none = {} });
}

fn lowerStmt(self: *Builder, stmt: ThirStmt) LowerError!void {
    if (self.terminated()) return;

    switch (stmt.kind) {
        .let => |let_stmt| {
            const binding = self.lookup(let_stmt.place);
            if (binding.value == BIR_NO_VALUE) return;
            const slot_ty = self.value_ty_map.get(let_stmt.place) orelse (self.mod.types.voidType() catch 0);
            if (let_stmt.init.isValid()) {
                const init_val = try self.lowerValueExpr(let_stmt.init);

        if (init_val != BIR_NO_VALUE) {
            try self.storeSlot(binding.value, init_val, slot_ty);
        }
    }
},
.assignment => |assign_stmt| {
    const binding = self.lookup(assign_stmt.place);
    if (binding.value == BIR_NO_VALUE) return;
    const slot_ty = self.value_ty_map.get(assign_stmt.place) orelse (self.mod.types.voidType() catch 0);
    const val = try self.lowerValueExpr(assign_stmt.value);

    if (val != BIR_NO_VALUE) {
        try self.storeSlot(binding.value, val, slot_ty);
    }
},
.expr_stmt => |es| {
    _ = try self.lowerValueExpr(es.expr);
},
.if_stmt => |ifs| {
    const cond_val = try self.lowerValueExpr(ifs.cond);
    const then_bir = self.block_map.get(ifs.then_block) orelse return;

    if (ifs.else_block) |else_blk| {
        const else_bir = self.block_map.get(else_blk) orelse return;
        try self.emitCondBr(cond_val, then_bir, else_bir);
    } else {
        const merge = try self.newBlock("if_merge");
        try self.emitCondBr(cond_val, then_bir, merge);
    }
},
.while_stmt => |ws| {
    try self.emitBr(ws.cond_block);

},
.return_stmt => |rs| {
    if (rs.value) |val| {
        const ret_val = try self.lowerValueExpr(val);
        try self.emitRet(ret_val, self.ret_type);
    } else {
        try self.retVoid();
    }
},
.break_stmt => |bs| {

            try self.emitBr(bs.target_loop);
        },
        .continue_stmt => |cs| {
            try self.emitBr(cs.target_loop);
        },
        .block => |blk_stmt| {
            try self.emitBr(blk_stmt.block);
        },
    }
}

fn lowerTerminator(self: *Builder, term: BasicBlock.Terminator) LowerError!void {
    switch (term) {
        .br => |target| {
            try self.emitBr(target);
        },
        .cond_br => |cb| {
            const cond_val = try self.lowerValueExpr(cb.cond);
            const then_bir = self.block_map.get(cb.then) orelse return;
            const else_bir = self.block_map.get(cb.else_) orelse return;

    try self.emitCondBr(cond_val, then_bir, else_bir);
},
.switch_br => |sb| {
    _ = sb;
    try self.retVoid();
},
.return_ret => |rr| {
    if (rr.value) |val| {
        const ret_val = try self.lowerValueExpr(val);
        try self.emitRet(ret_val, self.ret_type);

    } else {
        try self.retVoid();
    }
},
.unreachable_term => {
    const void_ty = self.mod.types.voidType() catch 0;
    _ = try self.emitOp(.unreachable_op, void_ty, &.{}, .{ .none = {} });
},
.diverge => {
    const void_ty = self.mod.types.voidType() catch 0;

            _ = try self.emitOp(.unreachable_op, void_ty, &.{}, .{ .none = {} });
        },
    }
}

fn lowerValueExpr(self: *Builder, vid: ThirValueId) LowerError!BIRValueId {
    if (!vid.isValid() or vid.index >= self.body.values.len) return BIR_NO_VALUE;
    const value_def = self.body.values[vid.index];

    if (!value_def.expr.isValid() or value_def.expr.index >= self.body.exprs.len) {

    const binding = self.lookup(vid);
    if (binding.value == BIR_NO_VALUE) return BIR_NO_VALUE;
    if (binding.kind == .ssa) return binding.value;
    const slot_ty = self.value_ty_map.get(vid) orelse (self.mod.types.voidType() catch 0);
    return self.loadFromSlot(binding.value, slot_ty);
}

const expr = self.body.exprs[value_def.expr.index];
switch (expr.kind) {
    .literal => |lit| return self.lowerLiteral(lit, expr.ty),

        .none => {},
        else => {},
    }

    const binding = self.lookup(vid);
    if (binding.value == BIR_NO_VALUE) return BIR_NO_VALUE;
    if (binding.kind == .ssa) return binding.value;
    const slot_ty = self.value_ty_map.get(vid) orelse (self.mod.types.voidType() catch 0);
    return self.loadFromSlot(binding.value, slot_ty);
}

fn lowerLiteral(self: *Builder, lit: Literal, ty: type_sys.TypeId) LowerError!BIRValueId {
    const bir_ty = self.lowerer.typeToBir(ty);
    const void_ty = self.lowerer.module.types.voidType() catch 0;
    const use_ty = if (!ty.isValid() or bir_ty == void_ty)
        switch (lit) {
            .int => self.lowerer.module.types.scalarType(.i64) catch 0,
            .float => self.lowerer.module.types.scalarType(.f64) catch 0,
            .bool_val => self.lowerer.module.types.scalarType(.i1) catch 0,
            .string => self.lowerer.module.types.pointerType(0, .generic) catch 0,

        .unit => void_ty,
    }
else
    bir_ty;
return switch (lit) {
    .int => |v| self.emitOp(.@"const", use_ty, &.{}, .{ .const_data = .{ .int = v } }),
    .float => |v| self.emitOp(.@"const", use_ty, &.{}, .{ .const_data = .{ .float = v } }),
    .bool_val => |v| self.emitOp(.@"const", use_ty, &.{}, .{ .const_data = .{ .bool = v } }),
    .string => |s| self.emitOp(.@"const", use_ty, &.{}, .{ .string = try self.alloc.dupe(u8, s) }),
    .unit => BIR_NO_VALUE,

    };
}

fn resolveBirType(self: *Builder, ty: type_sys.TypeId, fallback_vid: ThirValueId) BIRTypeId {
    if (ty.isValid()) return self.lowerer.typeToBir(ty);
    return self.value_ty_map.get(fallback_vid) orelse (self.mod.types.voidType() catch 0);
}

fn lowerBinary(self: *Builder, bin: ThirExpr.BinaryExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const lhs = try self.lowerValueExpr(bin.lhs);

const rhs = try self.lowerValueExpr(bin.rhs);
if (lhs == BIR_NO_VALUE or rhs == BIR_NO_VALUE) return BIR_NO_VALUE;

const bir_ty = self.resolveBirType(ty, bin.lhs);
const bir_op = switch (bin.op) {
    .add => Op.add,
    .sub => Op.sub,
    .mul => Op.mul,
    .div => Op.div,
    .mod => Op.mod,

        .bitwise_xor => Op.xor_op,
        .shl => Op.shl,
        .shr => Op.shr,
    };
    return self.emitOp(bir_op, bir_ty, &.{ lhs, rhs }, .{ .none = {} });
}

fn lowerUnary(self: *Builder, un: ThirExpr.UnaryExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const operand = try self.lowerValueExpr(un.operand);
    if (operand == BIR_NO_VALUE) return BIR_NO_VALUE;

    const bir_ty = self.resolveBirType(ty, un.operand);
    const bir_op = switch (un.op) {
        .negate => Op.neg,
        .not => Op.not,
        .bitwise_not => Op.not,
    };
    return self.emitOp(bir_op, bir_ty, &.{operand}, .{ .none = {} });
}

fn lowerCall(self: *Builder, call: ThirExpr.CallExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    var args = std.ArrayList(BIRValueId).init(self.alloc);
    defer args.deinit();

    for (call.args) |arg| {
        const val = try self.lowerValueExpr(arg);
        if (val != BIR_NO_VALUE) {
            try args.append(val);
        }
    }

const void_ty = self.mod.types.voidType() catch 0;
const result_ty = if (ty.isValid()) self.lowerer.typeToBir(ty) else void_ty;

const callee_name = switch (call.func) {
    .function => |def_id| blk: {
        var found_name: ?[]const u8 = null;
        for (self.lowerer.thir_mod.functions.items) |*func| {
            if (func.def_id.index == def_id.index) {
                found_name = func.name_str;

        break;
    }
}
if (found_name == null) {
    for (self.lowerer.hir_items.items) |*item| {
        switch (item.kind) {
            .extern_fn => |e| {
                if (e.def_id.index == def_id.index) {
                    found_name = e.name_bytes;
                    break;

                }
            },
            else => {},
        }
    }
}
if (found_name) |name| {
    if (std.mem.eql(u8, name, "print")) {
        const callee = if (call.args.len > 0) blk2: {
            const arg_vid = call.args[0];

if (arg_vid.isValid() and arg_vid.index < self.body.values.len) {
    const vd = self.body.values[arg_vid.index];
    if (vd.expr.isValid() and vd.expr.index < self.body.exprs.len) {
        const arg_expr = self.body.exprs[vd.expr.index];
        const is_str = switch (arg_expr.kind) {
            .literal => |lit| switch (lit) {
                .string => true,
                else => false,
            },
            else => false,

                    };
                    break :blk2 if (is_str) "print_str" else "print_i64";
                }
            }
            break :blk2 "print_i64";
        } else "print_i64";
        break :blk try self.alloc.dupe(u8, callee);
    }
    break :blk try self.alloc.dupe(u8, name);
} else {

                break :blk try std.fmt.allocPrint(self.alloc, "fn_{d}", .{def_id.index});
            }
        },
        .value => try std.fmt.allocPrint(self.alloc, "closure_{d}", .{call.func.value.index}),
    };

    const owned_args = try self.alloc.dupe(BIRValueId, args.items);
    const result = try self.emitOp(.call, result_ty, &.{}, .{ .named_call = .{ .name = callee_name, .args = owned_args } });
    return result;
}

fn lowerCast(self: *Builder, cast: ThirExpr.CastExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const operand = try self.lowerValueExpr(cast.operand);
    if (operand == BIR_NO_VALUE) return BIR_NO_VALUE;

    const resolved_ty = if (ty.isValid()) ty else cast.from_ty;
    const bir_ty = self.lowerer.typeToBir(resolved_ty);
    const from_bir_ty = self.lowerer.typeToBir(cast.from_ty);

    switch (cast.kind) {

        .int_to_bool => return self.emitOp(.trunc, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .trunc, .from = from_bir_ty, .to = bir_ty } }),
        .bitcast => return self.emitOp(.bitcast, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .bitcast, .from = from_bir_ty, .to = bir_ty } }),
        .pointer_cast => return self.emitOp(.bitcast, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .bitcast, .from = from_bir_ty, .to = bir_ty } }),
        .pointer_to_int => return self.emitOp(.ptr_to_int, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .ptr2int, .from = from_bir_ty, .to = bir_ty } }),
        .int_to_pointer => return self.emitOp(.int_to_ptr, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .int2ptr, .from = from_bir_ty, .to = bir_ty } }),
        .unsize => return self.emitOp(.bitcast, bir_ty, &.{operand}, .{ .cast_info = .{ .kind = .bitcast, .from = from_bir_ty, .to = bir_ty } }),
    }
}

fn lowerLoad(self: *Builder, ld: ThirExpr.LoadExpr, ty: type_sys.TypeId) LowerError!BIRValueId {

if (ld.place.projections.len == 0) {
    const binding = self.lookup(ld.place.local);
    if (binding.value != BIR_NO_VALUE and binding.kind == .ssa) {
        return binding.value;
    }
}
const ptr = try self.lowerPlace(ld.place);
if (ptr == BIR_NO_VALUE) return BIR_NO_VALUE;
const bir_ty = self.lowerer.typeToBir(ty);
return self.emitOp(.load, bir_ty, &.{ptr}, .{ .none = {} });

}

fn lowerPlace(self: *Builder, place: ThirPlace) LowerError!BIRValueId {
    if (!place.local.isValid()) return BIR_NO_VALUE;

    const binding = self.lookup(place.local);
    var ptr = binding.value;
    if (ptr == BIR_NO_VALUE) return BIR_NO_VALUE;
    const current_ty = self.value_ty_map.get(place.local) orelse (self.mod.types.voidType() catch 0);

for (place.projections) |proj| {
    switch (proj) {
        .field => |field_idx| {
            const idx_ty = try self.mod.types.scalarType(.i32);
            const idx = try self.emitOp(.@"const", idx_ty, &.{}, .{ .const_data = .{ .int = @intCast(field_idx) } });
            ptr = try self.emitOp(.getelementptr, current_ty, &.{ ptr, idx }, .{ .none = {} });
        },
        .index => |index_vid| {
            const idx = try self.lowerValueExpr(index_vid);
            if (idx == BIR_NO_VALUE) return BIR_NO_VALUE;

            ptr = try self.emitOp(.getelementptr, current_ty, &.{ ptr, idx }, .{ .none = {} });
        },
        .deref => {
            // ptr already holds the address — no-op for Place semantics
        },
        .downcast => |_| {},
    }
}

return ptr;

}

fn lowerAddrOf(self: *Builder, ao: ThirExpr.AddrOfExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const operand = try self.lowerValueExpr(ao.operand);
    if (operand == BIR_NO_VALUE) return BIR_NO_VALUE;
    const bir_ty = self.lowerer.typeToBir(ty);
    return self.emitOp(.getelementptr, bir_ty, &.{operand}, .{ .none = {} });
}

fn lowerDeref(self: *Builder, dr: ThirExpr.DerefExpr, ty: type_sys.TypeId) LowerError!BIRValueId {

    const operand = try self.lowerValueExpr(dr.operand);
    if (operand == BIR_NO_VALUE) return BIR_NO_VALUE;
    const bir_ty = self.lowerer.typeToBir(ty);
    return self.emitOp(.load, bir_ty, &.{operand}, .{ .none = {} });
}

fn lowerFieldAddr(self: *Builder, fa: ThirExpr.FieldAddrExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const object = try self.lowerValueExpr(fa.object);
    if (object == BIR_NO_VALUE) return BIR_NO_VALUE;
    const bir_ty = self.lowerer.typeToBir(ty);

    const idx_val = try self.emitOp(.@"const", (self.lowerer.module.types.scalarType(.i32) catch 0), &.{}, .{ .const_data = .{ .int = @intCast(fa.field_index) } });
    return self.emitOp(.getelementptr, bir_ty, &.{ object, idx_val }, .{ .none = {} });
}

fn lowerIndexAddr(self: *Builder, ia: ThirExpr.IndexAddrExpr, ty: type_sys.TypeId) LowerError!BIRValueId {
    const object = try self.lowerValueExpr(ia.object);
    const index = try self.lowerValueExpr(ia.index);
    if (object == BIR_NO_VALUE or index == BIR_NO_VALUE) return BIR_NO_VALUE;
    const bir_ty = self.lowerer.typeToBir(ty);
    return self.emitOp(.getelementptr, bir_ty, &.{ object, index }, .{ .none = {} });

    }

    fn newBlock(self: *Builder, prefix: []const u8) !BIRBlockId {
        const label = try std.fmt.allocPrint(self.alloc, "{s}_{d}", .{ prefix, @as(u32, @intCast(self.mod.getFunctionMut(self.fid).blocks.items.len)) });
        defer self.alloc.free(label);
        return try self.mod.addBlock(self.fid, label);
    }
