    const entry_block = try bir_module.addBlock(main_id, "entry");

    const callee_name = try bir_module.allocator.dupe(u8, "__plan_entry");
    _ = try bir_module.addInst(main_id, entry_block, .{

    .op = .call,
    .ty = void_ty,
    .result = 0,
    .operands = &.{},
    .data = .{ .named_call = .{ .name = callee_name, .args = &.{} } },
});

_ = try bir_module.addInst(main_id, entry_block, .{
    .op = .ret,
    .ty = void_ty,

        .result = 0,
        .operands = &.{},
        .data = .none,
    });
}

