pub const FrameGraphGPUExecutor = struct {
    ctx: *dx12.ComputeContext,
    pool: *resource_system.ResourcePool,
    allocator: std.mem.Allocator,
    rs_bld: rs_builder.RSRootSignatureBuilder,

// Shader cache: source_hash -> bytecode
shader_cache: std.AutoHashMap(u64, []const u8),

// PSO cache: (shader_source_hash, root_sig_ptr) -> pso_ptr
pso_cache: std.AutoHashMap(u64, ?*anyopaque),

// Descriptor heap linear allocator (per resolve)
descriptor_capacity: u32 = 1024,
descriptor_next_free: u32 = 0,

pub fn init(
    allocator: std.mem.Allocator,
    ctx: *dx12.ComputeContext,
    pool: *resource_system.ResourcePool,
) FrameGraphGPUExecutor {
    return FrameGraphGPUExecutor{
        .ctx = ctx,
        .pool = pool,
        .allocator = allocator,
        .rs_bld = rs_builder.RSRootSignatureBuilder.init(allocator, ctx),

        .shader_cache = std.AutoHashMap(u64, []const u8).init(allocator),
        .pso_cache = std.AutoHashMap(u64, ?*anyopaque).init(allocator),
    };
}

pub fn deinit(self: *FrameGraphGPUExecutor) void {
    self.shader_cache.deinit();
    self.rs_bld.deinit();

    var pc_it = self.pso_cache.valueIterator();

    while (pc_it.next()) |pso| {
        if (pso.*) |p| d3d.release(p);
    }
    self.pso_cache.deinit();
}

fn hashSource(source: []const u8) u64 {
    return std.hash.Wyhash.hash(0, source);
}

fn hashShaderAndSig(shader_hash: u64, root_sig: ?*anyopaque) u64 {
    var h = std.hash.Wyhash.init(0);
    h.update(std.mem.asBytes(&shader_hash));
    const ptr_val = @intFromPtr(root_sig);
    h.update(std.mem.asBytes(&ptr_val));
    return h.final();
}

fn getOrCompileShader(self: *FrameGraphGPUExecutor, shader_key: gpu_types.ShaderKey) ![]const u8 {
    const h = hashSource(shader_key.source);

    if (self.shader_cache.get(h)) |bytecode| return bytecode;

    // Compile via DXIL backend (DXC) — produces DXIL bytecode container
    const result = try dxil_backend.compileHlsl(self.allocator, shader_key.source);
    try self.shader_cache.put(h, result.bytecode);
    // Don't call deinit — bytecode is now owned by shader_cache
    return result.bytecode;
}

fn createPSO(self: *FrameGraphGPUExecutor, root_sig: ?*anyopaque, bytecode: []const u8) !?*anyopaque {

var pso: ?*anyopaque = null;
const desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = root_sig,
    .CS = .{ .pShaderBytecode = bytecode.ptr, .BytecodeLength = bytecode.len },
};
const hr_ = d3d.getDeviceVtbl(self.ctx.device.?).CreateComputePipelineState(
    self.ctx.device.?,
    &desc,
    &d3d.IID_ID3D12PipelineState,
    &pso,

    );
    std.debug.print("CreatePSO: hr=0x{x} rs=0x{x} bc_len={}\n", .{ @as(u32, @bitCast(hr_)), @intFromPtr(root_sig), bytecode.len });
    if (hr_ < 0) return error.PSOFailed;
    return pso;
}

fn getOrCreatePSO(self: *FrameGraphGPUExecutor, root_sig: ?*anyopaque, bytecode: []const u8) !?*anyopaque {
    const shader_hash = hashSource(bytecode);
    const cache_key = hashShaderAndSig(shader_hash, root_sig);

    if (self.pso_cache.get(cache_key)) |pso| return pso;
    const pso = try self.createPSO(root_sig, bytecode);
    try self.pso_cache.put(cache_key, pso);
    return pso;
}

fn allocateDescriptorSlots(self: *FrameGraphGPUExecutor, count: u32) !u32 {
    const base = self.descriptor_next_free;
    if (base + count > self.descriptor_capacity) return error.OutOfDescriptorSpace;
    self.descriptor_next_free = base + count;

    return base;
}

fn resetDescriptorAllocator(self: *FrameGraphGPUExecutor) void {
    self.descriptor_next_free = 0;
}

pub fn execute(
    self: *FrameGraphGPUExecutor,
    plan: *const frame_graph.ExecutionPlan,

    gpu_passes: []const frame_graph.GPUPassDesc,
) !void {
    for (plan.nodes) |node| {
        const pass_id = switch (node.kind) {
            .gpu => |g| g.pass_id,
            .render => |r| r.pass_id,
            else => continue,
        };

        // Find matching GPU pass descriptor

const gpu_pass = for (gpu_passes) |gp| {
    if (gp.pass_id == pass_id) break &gp;
} else continue;

// Per-pass root signature compiled from BindLayout
const compiled_rs = try self.rs_bld.getOrBuild(gpu_pass.pipeline.layout);

// Compile shader
const bytecode = try self.getOrCompileShader(gpu_pass.pipeline.shader);

// Create or get PSO (per-pass RS, per-pass PSO)
const pso = try self.getOrCreatePSO(compiled_rs.root_signature, bytecode);

// Reset command list
_ = d3d.getAllocatorVtbl(self.ctx.cmd_allocator.?).Reset(self.ctx.cmd_allocator.?);
_ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Reset(self.ctx.cmd_list.?, self.ctx.cmd_allocator, null);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetPipelineState(self.ctx.cmd_list.?, pso);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootSignature(self.ctx.cmd_list.?, compiled_rs.root_signature);
var heaps = [_]?*anyopaque{ self.ctx.uav_heap, self.ctx.sampler_heap };
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetDescriptorHeaps(self.ctx.cmd_list.?, 2, &heaps);

// Apply barriers before
self.pool.applyBarriers(self.ctx.cmd_list.?, gpu_pass.barriers_before);

// Set up descriptors: RS-driven allocation with validation
self.pool.setupDescriptorHeap(gpu_pass.bindings.entries, compiled_rs, 0);

// Set root descriptor table (all ranges start at heap offset 0)
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootDescriptorTable(
    self.ctx.cmd_list.?,

    0,
    self.ctx.getUAVGPUHandle(0),
);

// Dispatch
d3d.getCmdListVtbl(self.ctx.cmd_list.?).Dispatch(
    self.ctx.cmd_list.?,
    gpu_pass.grid.x,
    gpu_pass.grid.y,
    gpu_pass.grid.z,

);

// Apply barriers after
self.pool.applyBarriers(self.ctx.cmd_list.?, gpu_pass.barriers_after);

// Close and submit
_ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Close(self.ctx.cmd_list.?);
var lists = [_]?*anyopaque{self.ctx.cmd_list};
d3d.getQueueVtbl(self.ctx.queue.?).ExecuteCommandLists(self.ctx.queue.?, 1, &lists);

        std.debug.print("GPU pass {}: '{s}' dispatched ({},{},{}) RS={d} descriptors\n", .{
            gpu_pass.pass_id, gpu_pass.pipeline.shader.entry,
            gpu_pass.grid.x,  gpu_pass.grid.y,
            gpu_pass.grid.z,  compiled_rs.total_descriptors,
        });
    }

    // Wait for all GPU work
    _ = try self.ctx.submitAndWait();
}

pub fn executeRenderPlan(
    self: *FrameGraphGPUExecutor,
    plan: *const render_graph.RenderPlan,
) !void {
    for (plan.nodes, 0..) |node, ni| {
        const pass_id = switch (node.kind) {
            .gpu => |g| g.pass_id,
            .render => |r| r.pass_id,
            else => continue,

};

const gpu_pass = for (plan.gpu_passes) |gp| {
    if (gp.pass_id == pass_id) break &gp;
} else continue;

const compiled_rs = try self.rs_bld.getOrBuild(gpu_pass.pipeline.layout);
const bytecode = try self.getOrCompileShader(gpu_pass.pipeline.shader);
const pso = try self.getOrCreatePSO(compiled_rs.root_signature, bytecode);

_ = d3d.getAllocatorVtbl(self.ctx.cmd_allocator.?).Reset(self.ctx.cmd_allocator.?);
_ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Reset(self.ctx.cmd_list.?, self.ctx.cmd_allocator, null);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetPipelineState(self.ctx.cmd_list.?, pso);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootSignature(self.ctx.cmd_list.?, compiled_rs.root_signature);
var heaps = [_]?*anyopaque{ self.ctx.uav_heap, self.ctx.sampler_heap };
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetDescriptorHeaps(self.ctx.cmd_list.?, 2, &heaps);

// Auto-barriers for this pass
for (plan.auto_barriers) |b| {
    if (b.pass_index == ni) {

        self.pool.transitionBarrier(self.ctx.cmd_list, b.barrier.resource_id, b.barrier.state_after);
    }
}

// User barriers (if any)
self.pool.applyBarriers(self.ctx.cmd_list.?, gpu_pass.barriers_before);

self.pool.setupDescriptorHeap(gpu_pass.bindings.entries, compiled_rs, 0);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootDescriptorTable(
    self.ctx.cmd_list.?,

    0,
    self.ctx.getUAVGPUHandle(0),
);

d3d.getCmdListVtbl(self.ctx.cmd_list.?).Dispatch(
    self.ctx.cmd_list.?,
    gpu_pass.grid.x,
    gpu_pass.grid.y,
    gpu_pass.grid.z,
);

self.pool.applyBarriers(self.ctx.cmd_list.?, gpu_pass.barriers_after);

_ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Close(self.ctx.cmd_list.?);
var lists = [_]?*anyopaque{self.ctx.cmd_list};
d3d.getQueueVtbl(self.ctx.queue.?).ExecuteCommandLists(self.ctx.queue.?, 1, &lists);

std.debug.print("Render pass {}: '{s}' ({},{},{}) RS={d} descriptors\n", .{
    gpu_pass.pass_id, gpu_pass.pipeline.shader.entry,
    gpu_pass.grid.x,  gpu_pass.grid.y,

            gpu_pass.grid.z,  compiled_rs.total_descriptors,
        });
    }

    _ = try self.ctx.submitAndWait();
}

pub fn executeRenderPlanInSlot(
    self: *FrameGraphGPUExecutor,
    plan: *const render_graph.RenderPlan,

    slot: *frame_runtime.FrameSlot,
) !void {
    for (plan.nodes, 0..) |node, ni| {
        const pass_id = switch (node.kind) {
            .gpu => |g| g.pass_id,
            .render => |r| r.pass_id,
            else => continue,
        };

        const gpu_pass = for (plan.gpu_passes) |gp| {

    if (gp.pass_id == pass_id) break &gp;
} else continue;

const cmd_list = switch (gpu_pass.queue) {
    .compute => slot.compute.list,
    .graphics => slot.graphics.list,
};

const compiled_rs = try self.rs_bld.getOrBuild(gpu_pass.pipeline.layout);
const bytecode = try self.getOrCompileShader(gpu_pass.pipeline.shader);

const pso = try self.getOrCreatePSO(compiled_rs.root_signature, bytecode);

d3d.getCmdListVtbl(cmd_list.?).SetPipelineState(cmd_list.?, pso);
d3d.getCmdListVtbl(cmd_list.?).SetComputeRootSignature(cmd_list.?, compiled_rs.root_signature);
var heaps = [_]?*anyopaque{ self.ctx.uav_heap, self.ctx.sampler_heap };
d3d.getCmdListVtbl(cmd_list.?).SetDescriptorHeaps(cmd_list.?, 2, &heaps);

for (plan.auto_barriers) |b| {
    if (b.pass_index == ni) {
        self.pool.transitionBarrier(cmd_list, b.barrier.resource_id, b.barrier.state_after);

    }
}
self.pool.applyBarriers(cmd_list.?, gpu_pass.barriers_before);

self.pool.setupDescriptorHeap(gpu_pass.bindings.entries, compiled_rs, 0);
d3d.getCmdListVtbl(cmd_list.?).SetComputeRootDescriptorTable(
    cmd_list.?,
    0,
    self.ctx.getUAVGPUHandle(0),
);

d3d.getCmdListVtbl(cmd_list.?).Dispatch(
    cmd_list.?,
    gpu_pass.grid.x,
    gpu_pass.grid.y,
    gpu_pass.grid.z,
);
self.pool.applyBarriers(cmd_list.?, gpu_pass.barriers_after);

std.debug.print("pass {}: '{s}' ({},{},{}) RS={d} descriptors\n", .{
    gpu_pass.pass_id, gpu_pass.pipeline.shader.entry,

            gpu_pass.grid.x,  gpu_pass.grid.y,
            gpu_pass.grid.z,  compiled_rs.total_descriptors,
        });
    }
}

pub fn executeRenderPlanWithHistory(
    self: *FrameGraphGPUExecutor,
    plan: *const render_graph.RenderPlan,
    history: *history_manager.HistoryManager,

) !void {
    history.beginFrame();
    try self.executeRenderPlan(plan);
    history.flip();
}

/// Phase 3 (resolve): compile shaders, bake PSO/RS, allocate descriptor
/// heap region, write all views.  After resolve the batch is fully baked.
fn resolveBatch(
    self: *FrameGraphGPUExecutor,

    plan: *const render_graph.RenderPlan,
    batch: *gpu_scheduler.GPUBatch,
) !void {
    const count = batch.pass_indices.len;
    var resolved = try self.allocator.alloc(gpu_scheduler.ResolvedPass, count);
    errdefer self.allocator.free(resolved);

    for (batch.pass_indices, 0..) |pass_idx, i| {
        const gp = &plan.gpu_passes[pass_idx];
        const compiled_rs = try self.rs_bld.getOrBuild(gp.pipeline.layout);

const bytecode = try self.getOrCompileShader(gp.pipeline.shader);
const pso = try self.getOrCreatePSO(compiled_rs.root_signature, bytecode);

// Allocate contiguous descriptor region for this pass
const num_slots = compiled_rs.total_descriptors;
const base_slot = try self.allocateDescriptorSlots(num_slots);

// Write all descriptor views into heap at absolute offset
self.pool.setupDescriptorHeap(gp.bindings.entries, compiled_rs, base_slot);

resolved[i] = gpu_scheduler.ResolvedPass{
    .pso = pso,
    .root_signature = compiled_rs.root_signature,
    .root_table_gpu_handle = self.ctx.getUAVGPUHandle(base_slot).ptr,
    .descriptor_base_index = base_slot,
    .descriptor_count = num_slots,
    .grid = .{ gp.grid.x, gp.grid.y, gp.grid.z },
};

std.debug.print("resolve pass {} (pass_idx={}): '{s}' RS={d}desc @slot{}\n", .{

            gp.pass_id, pass_idx, gp.pipeline.shader.entry,
            num_slots, base_slot,
        });
    }

    if (batch.resolved_passes.len > 0) self.allocator.free(batch.resolved_passes);
    batch.resolved_passes = resolved;
}

/// Phase 4 (replay): pure command emission from pre-baked ResolvedPass.

/// Zero hashmap lookups, zero shader compilation, zero descriptor writes.
fn executeBatchResolved(
    self: *FrameGraphGPUExecutor,
    batch: *const gpu_scheduler.GPUBatch,
    cmd_list: ?*anyopaque,
) void {
    for (batch.resolved_passes, batch.pass_indices) |*rp, pass_idx| {
        const handle = d3d.D3D12_GPU_DESCRIPTOR_HANDLE{ .ptr = rp.root_table_gpu_handle };

        d3d.getCmdListVtbl(cmd_list.?).SetPipelineState(cmd_list.?, rp.pso);

d3d.getCmdListVtbl(cmd_list.?).SetComputeRootSignature(cmd_list.?, rp.root_signature);
var heaps = [_]?*anyopaque{self.ctx.uav_heap};
d3d.getCmdListVtbl(cmd_list.?).SetDescriptorHeaps(cmd_list.?, 1, &heaps);

// Pre-compressed barriers for this specific pass
for (batch.barriers) |ab| {
    if (ab.pass_index == pass_idx) {
        self.pool.transitionBarrier(cmd_list, ab.barrier.resource_id, ab.barrier.state_after);
    }
}

        d3d.getCmdListVtbl(cmd_list.?).SetComputeRootDescriptorTable(cmd_list.?, 0, handle);
        d3d.getCmdListVtbl(cmd_list.?).Dispatch(cmd_list.?, rp.grid[0], rp.grid[1], rp.grid[2]);

        std.debug.print("exec pass {} @slot{}\n", .{ pass_idx, rp.descriptor_base_index });
    }
}

pub fn executeScheduledFrame(
    self: *FrameGraphGPUExecutor,

    plan: *const render_graph.RenderPlan,
    schedule: *gpu_scheduler.ScheduledFrame,
    history: *history_manager.HistoryManager,
    runtime: *frame_runtime.FrameRuntime,
) !void {
    history.beginFrame();
    const slot = try runtime.beginFrame();

    self.resetDescriptorAllocator();

// Phase 3 (resolve): compile + bake PSO/RS + write descriptors to heap
for (schedule.compute.batches) |*batch| {
    try self.resolveBatch(plan, batch);
}
for (schedule.graphics.batches) |*batch| {
    try self.resolveBatch(plan, batch);
}

// Phase 4 (replay): pure command emission, no hashing, no descriptor writes
for (schedule.compute.batches) |*batch| {

    self.executeBatchResolved(batch, slot.compute.list);
}
for (schedule.graphics.batches) |*batch| {
    self.executeBatchResolved(batch, slot.graphics.list);
}

try runtime.endFrame(slot);
history.flip();

std.debug.print("Schedule: {} pass ({}C+{}G) {}→{} barrier {}B+{}B batch\n", .{

        schedule.stats.total_passes,
        schedule.stats.compute_passes,
        schedule.stats.graphics_passes,
        schedule.stats.barriers_in,
        schedule.stats.barriers_out,
        schedule.stats.compute_batches,
        schedule.stats.graphics_batches,
    });
}

/// Build resource slot table from bindings.
/// Maps each unique resource_id to a slot index in FrameInputs.
fn buildResourceSlots(
    allocator: std.mem.Allocator,
    gpu_passes: []const frame_graph.GPUPassDesc,
) !struct { slots: std.AutoHashMap(u64, u32), count: u32 } {
    var map = std.AutoHashMap(u64, u32).init(allocator);
    var next: u32 = 0;
    for (gpu_passes) |gp| {
        for (gp.bindings.entries) |entry| {

            if (!map.contains(entry.resource_id)) {
                try map.put(entry.resource_id, next);
                next += 1;
            }
        }
    }
    return .{ .slots = map, .count = next };
}

/// compileGraph — resolves all PSOs, RSs, pre-filters barriers,

/// pre-maps bind_slots, plans descriptor layout.
/// Returns an immutable CompiledGraph with zero runtime references to RenderPlan.
pub fn compileGraph(
    self: *FrameGraphGPUExecutor,
    plan: *const render_graph.RenderPlan,
    schedule: *const gpu_scheduler.ScheduledFrame,
) !compiled_graph.CompiledGraph {
    const allocator = self.allocator;

    var comp_batches = try std.ArrayList(compiled_graph.CompiledBatch).initCapacity(allocator, schedule.compute.batches.len);

defer comp_batches.deinit();
var gfx_batches = try std.ArrayList(compiled_graph.CompiledBatch).initCapacity(allocator, schedule.graphics.batches.len);
defer gfx_batches.deinit();

// Build resource slot table from full plan
var slot_info = try buildResourceSlots(allocator, plan.gpu_passes);
defer slot_info.slots.deinit();

var total_desc: u32 = 0;

const CompileBatchFn = struct {
    fn compile(
        plan2: *const render_graph.RenderPlan,
        exec: *FrameGraphGPUExecutor,
        batch: *const gpu_scheduler.GPUBatch,
        desc_offset: *u32,
        alloc: std.mem.Allocator,
        resource_slots: *const std.AutoHashMap(u64, u32),
    ) !compiled_graph.CompiledBatch {
        const count = batch.pass_indices.len;

var passes = try alloc.alloc(compiled_graph.CompiledPass, count);

for (batch.pass_indices, 0..) |pass_idx, i| {
    const gp = &plan2.gpu_passes[pass_idx];
    const compiled_rs = try exec.rs_bld.getOrBuild(gp.pipeline.layout);
    const bytecode = try exec.getOrCompileShader(gp.pipeline.shader);
    const pso = try exec.getOrCreatePSO(compiled_rs.root_signature, bytecode);

    const num_slots = compiled_rs.total_descriptors;
    const base_slot = desc_offset.*;

desc_offset.* += num_slots;

// Pre-filter barriers for this pass only (zero conditionals in execute)
var pass_barriers = std.ArrayList(gpu_types.BarrierDesc).init(alloc);
for (batch.barriers) |ab| {
    if (ab.pass_index == pass_idx) {
        try pass_barriers.append(ab.barrier);
    }
}

// Pre-map bind_slots: (BindingKey → input_slot, heap_offset)
var bs_list = try std.ArrayList(compiled_graph.BindSlot).initCapacity(alloc, gp.bindings.entries.len);
for (gp.bindings.entries) |entry| {
    const input_slot = resource_slots.get(entry.resource_id).?;
    const heap_offset = rs_builder.RSRootSignatureBuilder.getHeapOffset(compiled_rs, entry.key) orelse {
        std.debug.print("WARN: binding (reg={},space={},{s}) not in RS ranges\n", .{
            entry.key.reg, entry.key.space, @tagName(entry.key.kind),
        });
        continue;
    };

    bs_list.appendAssumeCapacity(.{
        .key = entry.key,
        .input_slot = input_slot,
        .heap_offset = heap_offset,
    });
}
const bind_slots = try bs_list.toOwnedSlice();

passes[i] = compiled_graph.CompiledPass{
    .pso = pso,

        .root_signature = compiled_rs.root_signature,
        .descriptor_base_within_frame = base_slot,
        .descriptor_count = num_slots,
        .grid = .{ gp.grid.x, gp.grid.y, gp.grid.z },
        .queue = gp.queue,
        .barriers = try pass_barriers.toOwnedSlice(),
        .bind_slots = bind_slots,
    };
}
return compiled_graph.CompiledBatch{

            .passes = passes,
            .queue = batch.queue,
        };
    }
};

for (schedule.compute.batches) |*batch| {
    const cb = try CompileBatchFn.compile(plan, self, batch, &total_desc, allocator, &slot_info.slots);
    comp_batches.appendAssumeCapacity(cb);
}

for (schedule.graphics.batches) |*batch| {
    const cb = try CompileBatchFn.compile(plan, self, batch, &total_desc, allocator, &slot_info.slots);
    gfx_batches.appendAssumeCapacity(cb);
}

return compiled_graph.CompiledGraph{
    .compute_batches = try comp_batches.toOwnedSlice(),
    .graphics_batches = try gfx_batches.toOwnedSlice(),
    .frame_descriptor_count = total_desc,
    .num_resource_slots = slot_info.count,

        .allocator = allocator,
    };
}

/// writeFrameDescriptors — per-frame CPU work.
/// Writes descriptor views for the current frame slot using FrameInputs.
/// Zero references to RenderPlan — uses pre-baked bind_slots.
pub fn writeFrameDescriptors(
    self: *FrameGraphGPUExecutor,
    cg: *const compiled_graph.CompiledGraph,

    inputs: *const compiled_graph.FrameInputs,
    slot_index: u32,
) void {
    const frame_stride = cg.frame_descriptor_count;

    for (cg.compute_batches) |*batch| {
        for (batch.passes) |*cp| {
            const pass_base = slot_index * frame_stride + cp.descriptor_base_within_frame;
            for (cp.bind_slots) |bs| {
                const resource_id = inputs.resources[bs.input_slot];

            const cpu_handle = self.ctx.getUAVCPUHandle(pass_base + bs.heap_offset);
            self.pool.writeView(resource_id, bs.key.kind, cpu_handle);
        }
    }
}
for (cg.graphics_batches) |*batch| {
    for (batch.passes) |*cp| {
        const pass_base = slot_index * frame_stride + cp.descriptor_base_within_frame;
        for (cp.bind_slots) |bs| {
            const resource_id = inputs.resources[bs.input_slot];

                const cpu_handle = self.ctx.getUAVCPUHandle(pass_base + bs.heap_offset);
                self.pool.writeView(resource_id, bs.key.kind, cpu_handle);
            }
        }
    }
}

/// executeCompiledGraph — pure GPU command replay.
/// Zero descriptor heap writes, zero hash lookups, zero shader compilation,
/// zero conditionals (barriers pre-filtered per pass).

pub fn executeCompiledGraph(
    self: *FrameGraphGPUExecutor,
    cg: *const compiled_graph.CompiledGraph,
    slot_index: u32,
    cmd_list: ?*anyopaque,
) void {
    var arena = compiled_graph.DescriptorArena.init(self.ctx);
    const frame_stride = cg.frame_descriptor_count;
    var heaps = [_]?*anyopaque{ self.ctx.uav_heap, self.ctx.sampler_heap };
    d3d.getCmdListVtbl(cmd_list.?).SetDescriptorHeaps(cmd_list.?, 2, &heaps);

for (cg.compute_batches) |*batch| {
    for (batch.passes) |*cp| {
        d3d.getCmdListVtbl(cmd_list.?).SetPipelineState(cmd_list.?, cp.pso);
        d3d.getCmdListVtbl(cmd_list.?).SetComputeRootSignature(cmd_list.?, cp.root_signature);

        for (cp.barriers) |b| {
            self.pool.transitionBarrier(cmd_list, b.resource_id, b.state_after);
        }

        const handle = arena.passGPUHandle(slot_index, frame_stride, cp.descriptor_base_within_frame);
        d3d.getCmdListVtbl(cmd_list.?).SetComputeRootDescriptorTable(cmd_list.?, 0, handle);
        d3d.getCmdListVtbl(cmd_list.?).Dispatch(cmd_list.?, cp.grid[0], cp.grid[1], cp.grid[2]);
    }
}
for (cg.graphics_batches) |*batch| {
    for (batch.passes) |*cp| {
        d3d.getCmdListVtbl(cmd_list.?).SetPipelineState(cmd_list.?, cp.pso);
        d3d.getCmdListVtbl(cmd_list.?).SetComputeRootSignature(cmd_list.?, cp.root_signature);

            for (cp.barriers) |b| {
                self.pool.transitionBarrier(cmd_list, b.resource_id, b.state_after);
            }

            const handle = arena.passGPUHandle(slot_index, frame_stride, cp.descriptor_base_within_frame);
            d3d.getCmdListVtbl(cmd_list.?).SetComputeRootDescriptorTable(cmd_list.?, 0, handle);
            d3d.getCmdListVtbl(cmd_list.?).Dispatch(cmd_list.?, cp.grid[0], cp.grid[1], cp.grid[2]);
        }
    }
}

/// Full frame pipeline: write descriptors + execute, frame-slot safe.
/// No RenderPlan, no DAG, no graph topology — only FrameInputs + CompiledGraph.
pub fn executeCompiledFrame(
    self: *FrameGraphGPUExecutor,
    cg: *const compiled_graph.CompiledGraph,
    inputs: *const compiled_graph.FrameInputs,
    runtime: *frame_runtime.FrameRuntime,
) !void {
    const slot = try runtime.beginFrame();

    const slot_index = @as(u32, @intCast(runtime.frame_index % frame_runtime.MAX_FRAMES_IN_FLIGHT));

    self.writeFrameDescriptors(cg, inputs, slot_index);
    self.executeCompiledGraph(cg, slot_index, slot.compute.list);

    try runtime.endFrame(slot);
}

pub fn executeFramePipeline(
    self: *FrameGraphGPUExecutor,

    plan: *const render_graph.RenderPlan,
    history: *history_manager.HistoryManager,
    runtime: *frame_runtime.FrameRuntime,
) !void {
    history.beginFrame();
    const slot = try runtime.beginFrame();
    try self.executeRenderPlanInSlot(plan, slot);
    try runtime.endFrame(slot);
    history.flip();
}

const std = @import("std");
const windows = std.os.windows;
const d3d = @import("d3d12_bindings.zig");
const dx12 = @import("dx12_compute.zig");
const sched = @import("../runtime/scheduler.zig");

pub const MAX_FRAMES_IN_FLIGHT = 3;

pub const QueueCmdLists = struct {
    allocator: ?*anyopaque = null,

    list: ?*anyopaque = null,
};

pub const FrameSlot = struct {
    compute: QueueCmdLists = .{},
    graphics: QueueCmdLists = .{},
    fence_value: u64 = 0,
};

pub const FrameRuntime = struct {

    .uav_heap = ctx.uav_heap,
    .uav_heap_increment = ctx.uav_heap_increment,
    .sampler_heap = ctx.sampler_heap,
    .sampler_heap_increment = ctx.sampler_heap_increment,
    .allocator = allocator,
};

for (&rt.slots) |*slot| {
    inline for (.{ .COMPUTE, .DIRECT }) |qtype| {
        var allocator_: ?*anyopaque = null;

var hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateCommandAllocator(
    ctx.device.?,
    qtype,
    &d3d.IID_ID3D12CommandAllocator,
    &allocator_,
);
if (hr_ < 0) return error.CommandAllocatorFailed;

var cmd_list: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateCommandList(

    ctx.device.?,
    0,
    qtype,
    allocator_,
    null,
    &d3d.IID_ID3D12GraphicsCommandList,
    &cmd_list,
);
if (hr_ < 0) return error.CommandListFailed;

        _ = d3d.getCmdListVtbl(cmd_list.?).Close(cmd_list.?);

        if (qtype == .COMPUTE) {
            slot.compute = .{ .allocator = allocator_, .list = cmd_list };
        } else {
            slot.graphics = .{ .allocator = allocator_, .list = cmd_list };
        }
    }
}

    return rt;
}

pub fn deinit(self: *FrameRuntime) void {
    for (&self.slots) |*slot| {
        if (slot.compute.list) |cl| d3d.release(cl);
        if (slot.compute.allocator) |ca| d3d.release(ca);
        if (slot.graphics.list) |cl| d3d.release(cl);
        if (slot.graphics.allocator) |ca| d3d.release(ca);
    }

}

pub fn beginFrame(self: *FrameRuntime) !*FrameSlot {
    const slot_index = self.frame_index % MAX_FRAMES_IN_FLIGHT;
    const slot = &self.slots[slot_index];

    if (slot.fence_value > 0) {
        const completed = d3d.getFenceVtbl(self.fence.?).GetCompletedValue(self.fence.?);
        if (completed < slot.fence_value) {
            _ = d3d.getFenceVtbl(self.fence.?).SetEventOnCompletion(

            self.fence.?,
            slot.fence_value,
            @ptrFromInt(self.event),
        );
        _ = windows.WaitForSingleObject(@as(windows.HANDLE, @ptrFromInt(self.event)), windows.INFINITE) catch {};
    }
}

_ = d3d.getAllocatorVtbl(slot.compute.allocator.?).Reset(slot.compute.allocator.?);
_ = d3d.getCmdListVtbl(slot.compute.list.?).Reset(slot.compute.list.?, slot.compute.allocator, null);

    _ = d3d.getAllocatorVtbl(slot.graphics.allocator.?).Reset(slot.graphics.allocator.?);
    _ = d3d.getCmdListVtbl(slot.graphics.list.?).Reset(slot.graphics.list.?, slot.graphics.allocator, null);

    return slot;
}

pub fn endFrame(self: *FrameRuntime, slot: *FrameSlot) !void {
    _ = d3d.getCmdListVtbl(slot.compute.list.?).Close(slot.compute.list.?);
    _ = d3d.getCmdListVtbl(slot.graphics.list.?).Close(slot.graphics.list.?);

var compute_lists = [_]?*anyopaque{slot.compute.list};
d3d.getQueueVtbl(self.queue.?).ExecuteCommandLists(self.queue.?, 1, &compute_lists);

var graphics_lists = [_]?*anyopaque{slot.graphics.list};
d3d.getQueueVtbl(self.gfx_queue.?).ExecuteCommandLists(self.gfx_queue.?, 1, &graphics_lists);

self.frame_index += 1;
slot.fence_value = self.frame_index;
_ = d3d.getQueueVtbl(self.queue.?).Signal(self.queue.?, self.fence, slot.fence_value);

    _ = d3d.getQueueVtbl(self.gfx_queue.?).Signal(self.gfx_queue.?, self.fence, slot.fence_value);
}

pub fn drain(self: *FrameRuntime) void {
    for (0..MAX_FRAMES_IN_FLIGHT) |i| {
        const fv = self.slots[i].fence_value;
        if (fv > 0) {
            const completed = d3d.getFenceVtbl(self.fence.?).GetCompletedValue(self.fence.?);
            if (completed < fv) {
                _ = d3d.getFenceVtbl(self.fence.?).SetEventOnCompletion(

                    self.fence.?,
                    fv,
                    @ptrFromInt(self.event),
                );
                _ = windows.WaitForSingleObject(@as(windows.HANDLE, @ptrFromInt(self.event)), windows.INFINITE) catch {};
            }
        }
    }
}

    pub fn currentFrameIndex(self: *const FrameRuntime) u64 {
        return self.frame_index;
    }
};

pub const FrameResources = struct {
    input: []f32,
    output: []f32,
    history: []f32,
    motion_x: []f32,

    motion_y: []f32,
    reactive: []f32,
    depth: []f32,
};

pub const FrameCtx = struct {
    id: u64,
    width: u32,
    height: u32,
    scale: f32,

    resources: *FrameResources,
    jitter_x: f32,
    jitter_y: f32,
};

const FrameStageCtx = struct {
    ctx: *FrameCtx,
    stage: Stage,
    tile_x: u32,
    tile_y: u32,

    tile_w: u32,
    tile_h: u32,
    allocator: std.mem.Allocator,
};

pub const Stage = enum { upsample, sharpen, temporal };

const TileStream = struct {
    jobs: []sched.Job,

    pub fn deinit(ts: *TileStream, allocator: std.mem.Allocator) void {
        allocator.free(ts.jobs);
    }
};

pub const FrameBatch = struct {
    upsample: TileStream,
    sharpen: TileStream,
    temporal: TileStream,

    pub fn deinit(fb: *FrameBatch, allocator: std.mem.Allocator) void {
        fb.upsample.deinit(allocator);
        fb.sharpen.deinit(allocator);
        fb.temporal.deinit(allocator);
    }
};

fn buildStage(allocator: std.mem.Allocator, ctx: *FrameCtx, stage: Stage) !TileStream {
    _ = ctx;
    _ = stage;

    return TileStream{ .jobs = try allocator.alloc(sched.Job, 0) };
}

fn submitStage(pool: *sched.WorkerPool, allocator: std.mem.Allocator, ctx: *FrameCtx, stage: Stage) !TileStream {
    const ts = try buildStage(allocator, ctx, stage);
    for (ts.jobs) |*j| pool.submit(j);
    return ts;
}

pub fn submitFrame(s: *sched.Scheduler, allocator: std.mem.Allocator, ctx: *FrameCtx) !FrameBatch {

const pool = &s.pool.?;
var batch = FrameBatch{
    .upsample = try submitStage(pool, allocator, ctx, .upsample),
    .sharpen = TileStream{ .jobs = &.{} },
    .temporal = TileStream{ .jobs = &.{} },
};
s.waitAll();

batch.sharpen = try submitStage(pool, allocator, ctx, .sharpen);
s.waitAll();

    if (ctx.resources.history.len > 0) {
        batch.temporal = try submitStage(pool, allocator, ctx, .temporal);
        s.waitAll();
    }

    return batch;
}

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const frame_graph = @import("frame_graph.zig");
const render_graph = @import("render_graph.zig");
const resource_system = @import("resource_system.zig");
const history_manager = @import("history_manager.zig");
const temporal_pipeline = @import("temporal_pipeline.zig");
const gpu_execution = @import("gpu_execution.zig");

/// FSR 3.1 quality mode.
pub const QualityMode = enum {
    performance, // 2x
    balanced,    // 2x
    quality,     // 2x
    ultra_quality, // 2x
};

/// Frame generation mode: how many frames to interpolate.

pub const GenMode = enum {
    /// Generate 1 frame between each real frame (2x frame rate).
    x2,
    /// Generate 2 frames (3x frame rate).
    x3,
    /// Generate 3 frames (4x frame rate).
    x4,
};

/// Configuration for FSR 3.1 pipeline.

    depth_threshold: f32 = 0.05,
};

/// FSR 3.1 pipeline pass IDs.
pub const FSR3Pass = enum(u32) {
    optical_flow = 100,
    disocclusion = 101,
    generate = 102,
    post_process = 103,
};

/// Static dependency arrays for FSR3 pass graph.
/// Module-level const ensures static lifetime (no dangling references).
const empty_deps: []const u32 = &.{};
const disocclusion_deps: []const u32 = &.{@intFromEnum(FSR3Pass.optical_flow)};
const generate_deps: []const u32 = &.{@intFromEnum(FSR3Pass.disocclusion)};
const post_process_deps: []const u32 = &.{@intFromEnum(FSR3Pass.generate)};

/// FSR 3.1 resource IDs (beyond those managed by history).
pub const FSR3Resources = struct {

    optical_flow: gpu_types.ResourceId = 0,
    disocclusion: gpu_types.ResourceId = 0,
    confidence: gpu_types.ResourceId = 0,
    generated_frame: gpu_types.ResourceId = 0,
    debug_output: gpu_types.ResourceId = 0,
};

/// Frame classification determined by policy engine.
/// Canonical definition in gpu_execution.zig.
pub const FrameMode = gpu_execution.FrameMode;

/// Configuration for the frame policy engine.
pub const FramePolicyConfig = struct {
    /// Max consecutive generated frames before forcing a real frame.
    max_generated_frames: u32 = 2,
    /// Min real frames required between generated sequences.
    min_real_frames: u32 = 1,
    /// Motion intensity above this always forces real frame.
    high_motion_threshold: f32 = 0.7,
    /// Motion below this allows generated frames.

    low_motion_threshold: f32 = 0.3,
    /// Max frame budget in microseconds.
    latency_budget_us: u32 = 2000,
    /// Budget for full render when in real mode.
    render_budget_us: u32 = 16000,
};

/// Input context for policy evaluation.
pub const PolicyContext = struct {
    /// Measured frame latency in microseconds.

    frame_latency_us: u32,
    /// Motion intensity estimate (0 = static, 1 = max motion).
    motion_intensity: f32,
    /// Whether history buffers are valid for generation.
    history_valid: bool,
    /// Current frame index.
    frame_index: u64,
};

/// Frame policy engine — state machine that decides real vs generated vs pass_through.

/// Deterministic: same config + context → same decision.
pub const FramePolicy = struct {
    config: FramePolicyConfig,
    generated_count: u32 = 0,
    real_count: u32 = 0,
    last_mode: FrameMode = .real,

    pub fn init(config: FramePolicyConfig) FramePolicy {
        return .{ .config = config };
    }

/// Evaluate frame policy for current context.
/// Returns frame mode and updates internal state.
pub fn evaluate(self: *FramePolicy, ctx: PolicyContext) FrameMode {
    // 1. Budget overflow → skip frame entirely
    if (ctx.frame_latency_us > self.config.latency_budget_us) {
        self.transition(.pass_through);
        return .pass_through;
    }

// 2. High motion → must render real frame
if (ctx.motion_intensity >= self.config.high_motion_threshold) {
    self.transition(.real);
    return .real;
}

// 3. If currently in real mode: must accumulate min_real_frames before gen
if (self.last_mode == .real and self.real_count < self.config.min_real_frames) {
    self.transition(.real);
    return .real;

}

// 4. Too many generated frames → need real frame
if (self.generated_count >= self.config.max_generated_frames) {
    self.transition(.real);
    return .real;
}

// 5. History invalid → cannot generate
if (!ctx.history_valid) {

    self.transition(.real);
    return .real;
}

// 6. History valid + not high motion → generate
if (ctx.motion_intensity < self.config.high_motion_threshold) {
    self.transition(.generated);
    return .generated;
}

    // 7. Default: real frame (high motion or edge case)
    self.transition(.real);
    return .real;
}

fn transition(self: *FramePolicy, mode: FrameMode) void {
    if (mode == self.last_mode) {
        switch (mode) {
            .real => self.real_count += 1,
            .generated => self.generated_count += 1,

        .pass_through => {},
    }
    return;
}
// Mode switch: reset counters for new mode
switch (mode) {
    .real => {
        self.real_count = 1;
        self.generated_count = 0;
    },

        .generated => {
            self.generated_count = 1;
            self.real_count = 0;
        },
        .pass_through => {},
    }
    self.last_mode = mode;
}

/// Reset policy state (e.g., on config change or resolution switch).

    pub fn reset(self: *FramePolicy) void {
        self.generated_count = 0;
        self.real_count = 0;
        self.last_mode = .real;
    }
};

/// FSR 3.1 runtime — manages frame generation pipeline.
pub const FSR3Runtime = struct {
    config: FSR3Config,

        .config = config,
        .temporal = temporal_pipeline.TemporalPipeline.init(config.render_width, config.render_height),
        .policy = FramePolicy.init(.{}),
    };
}

pub fn initResources(
    self: *FSR3Runtime,
    pool: *resource_system.ResourcePool,
) !void {

const w = self.config.render_width;
const h = self.config.render_height;

// History resources
try self.history.initColor(pool, w, h, .r16g16b16a16_float);
try self.history.initDepth(pool, w, h, .r32_float);
try self.history.initMotion(pool, w, h, .r16g16_float);
try self.history.initExposure(pool, w, h, .r16_float);
try self.history.initReactive(pool, w, h, .r8_unorm);

// Optical flow resources
self.resources.optical_flow = try pool.createTexture2D(.{
    .width = w / 2,
    .height = h / 2,
    .format = .r16g16_float,
});

// Confidence buffer
self.resources.confidence = try pool.createTexture2D(.{
    .width = w / 2,

    .height = h / 2,
    .format = .r16_float,
});

// Disocclusion mask
self.resources.disocclusion = try pool.createTexture2D(.{
    .width = w,
    .height = h,
    .format = .r8_unorm,
});

// Generated frame output
self.resources.generated_frame = try pool.createTexture2D(.{
    .width = w,
    .height = h,
    .format = .r16g16b16a16_float,
});

if (self.config.enable_debug) {
    self.resources.debug_output = try pool.createTexture2D(.{

            .width = w,
            .height = h,
            .format = .r16g16b16a16_float,
        });
    }
}

/// Build GPU pass descriptors from a frame graph, using this runtime's resources.
pub fn buildGPUPasses(
    _: *const FSR3Runtime,

    allocator: std.mem.Allocator,
    fg: *const frame_graph.FrameGraph,
) ![]frame_graph.GPUPassDesc {
    var gpu_count: usize = 0;
    for (fg.passes) |p| {
        if (p.gpu) gpu_count += 1;
    }
    var passes = try allocator.alloc(frame_graph.GPUPassDesc, gpu_count);
    var idx: usize = 0;
    for (fg.passes) |p| {

    if (!p.gpu) continue;
    passes[idx] = .{
        .pass_id = p.id,
        .queue = .compute,
        .pipeline = .{ .shader = .{ .source = "", .entry = "main" } },
        .grid = .{ .x = 8, .y = 8, .z = 1 },
        .bindings = gpu_types.BindGroup{ .entries = &.{} },
    };
    idx += 1;
}

    return passes;
}

/// Owned compile result: bundles the RenderPlan with heap-allocated passes
/// so both are freed together, preventing use-after-free.
pub const FrameCompileResult = struct {
    plan: render_graph.RenderPlan,
    owned_passes: []const frame_graph.Pass,
    owned_gpu_passes: []const frame_graph.GPUPassDesc,

    pub fn deinit(self: *FrameCompileResult, allocator: std.mem.Allocator) void {
        self.plan.deinit(allocator);
        allocator.free(self.owned_passes);
        allocator.free(self.owned_gpu_passes);
    }
};

/// End-to-end compile: evaluate policy → build graph → schedule → execution plan.
/// Connects FramePolicy → ExecutionContext → CostScheduler → GpuExecutionPlan.
/// Returns a FrameCompileResult that owns all allocations (free with .deinit()).

pub fn compileFrame(
    self: *FSR3Runtime,
    allocator: std.mem.Allocator,
    rg: *render_graph.RenderGraph,
    ctx: PolicyContext,
    budget_us: u32,
) !FrameCompileResult {
    const mode = self.evaluateFramePolicy(ctx);
    const fg = try self.buildFrameGraph(allocator);
    const gpu_passes = try self.buildGPUPasses(allocator, &fg);

    const plan = try rg.compileWithMode(fg.passes, gpu_passes, budget_us, mode);
    return .{
        .plan = plan,
        .owned_passes = fg.passes,
        .owned_gpu_passes = gpu_passes,
    };
}

pub fn buildFrameGraph(self: *FSR3Runtime, allocator: std.mem.Allocator) !frame_graph.FrameGraph {
    const interp_t = self.getInterpolationT();

    .history_reads = .{ .color = true, .depth = true },
    .history_writes = .{},
    .fsr3_pass = 0,
    .interp_t = interp_t,
};
passes[1] = .{
    .id = @intFromEnum(FSR3Pass.disocclusion),
    .name = "fsr3_disocclusion",
    .deps = disocclusion_deps,
    .gpu = true,

    .gpu_wait_for = empty_deps,
    .gpu_signal = empty_deps,
    .cost_us = 200,
    .critical = true,
    .history_reads = .{ .color = true, .depth = true, .motion = true },
    .history_writes = .{},
    .fsr3_pass = 1,
    .interp_t = interp_t,
};
passes[2] = .{

    .fsr3_pass = 2,
    .interp_t = interp_t,
};
passes[3] = .{
    .id = @intFromEnum(FSR3Pass.post_process),
    .name = "fsr3_post",
    .deps = post_process_deps,
    .gpu = true,
    .gpu_wait_for = empty_deps,
    .gpu_signal = empty_deps,

        .cost_us = 300,
        .critical = true,
        .history_reads = .{ .color = true },
        .history_writes = .{},
        .fsr3_pass = 3,
        .interp_t = interp_t,
    };
    return frame_graph.FrameGraph{ .passes = passes };
}

pub fn beginFrame(self: *FSR3Runtime) void {
    self.temporal.beginFrame();
    self.history.beginFrame();
}

pub fn endFrame(self: *FSR3Runtime) void {
    self.temporal.endFrame();
}

pub fn evaluateFramePolicy(self: *FSR3Runtime, ctx: PolicyContext) FrameMode {

    const mode = self.policy.evaluate(ctx);
    if (mode == .generated) {
        self.generated_frame_count += 1;
    }
    return mode;
}

pub fn shouldGenerateFrame(self: *FSR3Runtime) bool {
    return self.history.canGenerateFrame();
}

pub fn getInterpolationT(self: *const FSR3Runtime) f32 {
    return switch (self.config.gen_mode) {
        .x2 => 0.5,
        .x3 => 0.333,
        .x4 => 0.25,
    };
}

pub fn deinit(self: *FSR3Runtime, pool: *resource_system.ResourcePool) void {

self.history.deinit(pool);
if (self.resources.optical_flow != 0) {
    if (pool.getResource(self.resources.optical_flow)) |_| {
        _ = pool.resources.remove(self.resources.optical_flow);
    }
}
if (self.resources.confidence != 0) {
    if (pool.getResource(self.resources.confidence)) |_| {
        _ = pool.resources.remove(self.resources.confidence);
    }

}
if (self.resources.disocclusion != 0) {
    if (pool.getResource(self.resources.disocclusion)) |_| {
        _ = pool.resources.remove(self.resources.disocclusion);
    }
}
if (self.resources.generated_frame != 0) {
    if (pool.getResource(self.resources.generated_frame)) |_| {
        _ = pool.resources.remove(self.resources.generated_frame);
    }

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const frame_graph = @import("frame_graph.zig");
const lifetime_graph = @import("lifetime_graph.zig");
const barrier_optimizer = @import("barrier_optimizer.zig");
const cost_scheduler = @import("../runtime/cost_scheduler.zig");

/// Frame classification: what kind of frame the GPU should produce.
/// This is the canonical definition; fsr3_runtime re-exports it.
pub const FrameMode = enum(u32) {

    /// Render a real frame (full pipeline).
    real = 0,
    /// Generate an interpolated frame (FSR3 gen only).
    generated = 1,
    /// Skip frame entirely (budget exhausted).
    pass_through = 2,
};

/// Type of GPU dispatch: compute, graphics render pass, or async compute.
pub const DispatchType = enum(u32) {

    compute,
    graphics,
    async_compute,
};

/// A single dispatch unit derived from a GPU pass.
/// Maps one-to-one with GPUPassDesc in the sorted execution order.
pub const DispatchDesc = struct {
    pass_id: u32,
    dispatch_type: DispatchType,

    group_count_x: u32,
    group_count_y: u32,
    group_count_z: u32,
    estimated_cost_us: u32,
    barrier_index: u32,
    num_bindings: u32,
    binding_start: u32,
};

/// Resource binding slot classification for shader register mapping.

pub const ResourceSlotType = enum(u32) {
    texture,
    buffer,
    rw_buffer,
    sampler,
};

/// Describes how a resource is bound to a GPU pass.
/// Captures slot assignment + access mode for future DXIL lowering.
pub const BindingDesc = struct {

    pass_id: u32,
    resource_id: gpu_types.ResourceId,
    slot: u32,
    slot_type: ResourceSlotType,
    stage_flags: u32,
    read_write: bool,
};

/// Per-frame execution context fed into the GPU execution compiler.
/// Bridges FramePolicy decisions and temporal history state.

pub const ExecutionContext = struct {
    frame_index: u32,
    budget_us: u32,
    motion_intensity: f32,
    history_valid: bool,
    /// Scheduling mode: real / generated / pass_through.
    frame_mode: FrameMode = .real,
};

/// Compiled GPU execution plan — a flat, deterministic schedule of dispatches

/// with explicit binding information.
///
/// The plan has no references back to the source FrameGraph; it is a
/// self-contained executable description of what to issue on the GPU.
pub const GpuExecutionPlan = struct {
    allocator: std.mem.Allocator,
    dispatches: []DispatchDesc,
    bindings: []BindingDesc,
    frame_budget_us: u32,

    pub fn deinit(self: *GpuExecutionPlan) void {
        self.allocator.free(self.dispatches);
        self.allocator.free(self.bindings);
    }
};

/// Compile GPU execution plan from passes + lifetimes + barriers + context.
/// Produces a self-contained GpuExecutionPlan with deterministic ordering.
pub fn compileGpuExecutionPlan(
    allocator: std.mem.Allocator,

    gpu_passes: []const frame_graph.GPUPassDesc,
    lifetimes: *const lifetime_graph.LifetimeGraph,
    barriers: []const barrier_optimizer.BarrierSlot,
    ctx: ExecutionContext,
) !GpuExecutionPlan {
    _ = lifetimes;

    // Phase 1: Schedule — filter and prioritize passes by budget + frame mode
    const schedule = try cost_scheduler.scheduleGpuPasses(allocator, gpu_passes, ctx);
    defer allocator.free(schedule.order);

var dispatches = std.ArrayList(DispatchDesc).init(allocator);
errdefer dispatches.deinit();

var bindings = std.ArrayList(BindingDesc).init(allocator);
errdefer bindings.deinit();

// Phase 2: Build dispatches only for scheduled (non-skipped) passes
for (schedule.order) |idx| {
    const gp = &gpu_passes[idx];

// Map barrier index: find the barrier slot matching this gpu_passes index
var barrier_idx: u32 = 0;
for (barriers, 0..) |slot, bi| {
    if (slot.pass_index == idx) {
        barrier_idx = @intCast(bi);
        break;
    }
}

const binding_start = @as(u32, @intCast(bindings.items.len));

for (gp.bindings.entries, 0..) |entry, bi| {
    const slot_type: ResourceSlotType = switch (entry.key.kind) {
        .srv => .texture,
        .uav => .rw_buffer,
        .cbv => .buffer,
        .sampler => .sampler,
    };
    try bindings.append(.{

        .pass_id = gp.pass_id,
        .resource_id = entry.resource_id,
        .slot = @intCast(bi),
        .slot_type = slot_type,
        .stage_flags = 1,
        .read_write = entry.key.kind == .uav,
    });
}

const cost = cost_scheduler.PassCost.estimateFromGrid(gp.*);

try dispatches.append(.{
    .pass_id = gp.pass_id,
    .dispatch_type = switch (gp.queue) {
        .compute => DispatchType.compute,
        .graphics => DispatchType.graphics,
    },
    .group_count_x = gp.grid.x,
    .group_count_y = gp.grid.y,
    .group_count_z = gp.grid.z,
    .estimated_cost_us = cost.gpu_us,

        .barrier_index = barrier_idx,
        .num_bindings = @intCast(bindings.items.len - binding_start),
        .binding_start = binding_start,
    });
}

return GpuExecutionPlan{
    .allocator = allocator,
    .dispatches = try dispatches.toOwnedSlice(),
    .bindings = try bindings.toOwnedSlice(),

        .frame_budget_us = ctx.budget_us,
    };
}

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const gpu_execution = @import("gpu_execution.zig");
const frame_graph = @import("frame_graph.zig");
const resource_system = @import("resource_system.zig");
const dx12 = @import("dx12_compute.zig");
const d3d = @import("d3d12_bindings.zig");
const rs_builder = @import("root_signature_builder.zig");
const dxil_backend = @import("../compiler/gpu/dxil_backend.zig");
const barrier_opt = @import("barrier_optimizer.zig");

/// Bridges GpuExecutionPlan → D3D12.
/// Compiles shaders, creates PSOs, records command lists, submits.
pub const GpuExecutor = struct {
    ctx: *dx12.ComputeContext,
    pool: *resource_system.ResourcePool,
    allocator: std.mem.Allocator,
    rs_bld: rs_builder.RSRootSignatureBuilder,

    shader_cache: std.AutoHashMap(u64, []const u8),

pso_cache: std.AutoHashMap(u64, ?*anyopaque),
descriptor_next_free: u32 = 0,

pub fn init(
    allocator: std.mem.Allocator,
    ctx: *dx12.ComputeContext,
    pool: *resource_system.ResourcePool,
) GpuExecutor {
    return GpuExecutor{
        .ctx = ctx,

        .pool = pool,
        .allocator = allocator,
        .rs_bld = rs_builder.RSRootSignatureBuilder.init(allocator, ctx),
        .shader_cache = std.AutoHashMap(u64, []const u8).init(allocator),
        .pso_cache = std.AutoHashMap(u64, ?*anyopaque).init(allocator),
    };
}

pub fn deinit(self: *GpuExecutor) void {
    self.shader_cache.deinit();

    self.rs_bld.deinit();
    var it = self.pso_cache.valueIterator();
    while (it.next()) |pso| {
        if (pso.*) |p| d3d.release(p);
    }
    self.pso_cache.deinit();
}

fn hashSource(source: []const u8) u64 {
    return std.hash.Wyhash.hash(0, source);

}

fn hashShaderAndSig(shader_hash: u64, root_sig: ?*anyopaque) u64 {
    var h = std.hash.Wyhash.init(0);
    h.update(std.mem.asBytes(&shader_hash));
    const ptr_val = @intFromPtr(root_sig);
    h.update(std.mem.asBytes(&ptr_val));
    return h.final();
}

fn getOrCompileShader(self: *GpuExecutor, shader_key: gpu_types.ShaderKey) ![]const u8 {
    const h = hashSource(shader_key.source);
    if (self.shader_cache.get(h)) |bytecode| return bytecode;
    const result = try dxil_backend.compileHlsl(self.allocator, shader_key.source);
    try self.shader_cache.put(h, result.bytecode);
    return result.bytecode;
}

fn createPSO(self: *GpuExecutor, root_sig: ?*anyopaque, bytecode: []const u8) !?*anyopaque {
    var pso: ?*anyopaque = null;

const desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = root_sig,
    .CS = .{ .pShaderBytecode = bytecode.ptr, .BytecodeLength = bytecode.len },
};
const hr_ = d3d.getDeviceVtbl(self.ctx.device.?).CreateComputePipelineState(
    self.ctx.device.?,
    &desc,
    &d3d.IID_ID3D12PipelineState,
    &pso,
);

    if (hr_ < 0) return error.PSOFailed;
    return pso;
}

fn getOrCreatePSO(self: *GpuExecutor, root_sig: ?*anyopaque, bytecode: []const u8) !?*anyopaque {
    const shader_hash = hashSource(bytecode);
    const cache_key = hashShaderAndSig(shader_hash, root_sig);
    if (self.pso_cache.get(cache_key)) |pso| return pso;
    const pso = try self.createPSO(root_sig, bytecode);
    try self.pso_cache.put(cache_key, pso);

    return pso;
}

/// Execute a GpuExecutionPlan on the GPU.
/// Iterates dispatches in scheduled order, compiles shaders/PSOs on demand,
/// records all commands into one command list, submits, and waits.
pub fn execute(
    self: *GpuExecutor,
    plan: *const gpu_execution.GpuExecutionPlan,
    gpu_passes: []const frame_graph.GPUPassDesc,

    barriers: []const barrier_opt.BarrierSlot,
) !void {
    _ = d3d.getAllocatorVtbl(self.ctx.cmd_allocator.?).Reset(self.ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Reset(self.ctx.cmd_list.?, self.ctx.cmd_allocator, null);

    var heaps = [_]?*anyopaque{ self.ctx.uav_heap, self.ctx.sampler_heap };
    d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetDescriptorHeaps(self.ctx.cmd_list.?, 2, &heaps);

    for (plan.dispatches) |*disp| {
        const gp = for (gpu_passes) |*gp| {

    if (gp.pass_id == disp.pass_id) break gp;
} else continue;

const compiled_rs = try self.rs_bld.getOrBuild(gp.pipeline.layout);
const bytecode = try self.getOrCompileShader(gp.pipeline.shader);
const pso = try self.getOrCreatePSO(compiled_rs.root_signature, bytecode);

d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetPipelineState(self.ctx.cmd_list.?, pso);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootSignature(self.ctx.cmd_list.?, compiled_rs.root_signature);

for (barriers) |b| {
    if (b.pass_index == disp.pass_id) {
        self.pool.transitionBarrier(self.ctx.cmd_list, b.barrier.resource_id, b.barrier.state_after);
    }
}
self.pool.applyBarriers(self.ctx.cmd_list.?, gp.barriers_before);

self.pool.setupDescriptorHeap(gp.bindings.entries, compiled_rs, 0);
d3d.getCmdListVtbl(self.ctx.cmd_list.?).SetComputeRootDescriptorTable(
    self.ctx.cmd_list.?,

    0,
    self.ctx.getUAVGPUHandle(0),
);

d3d.getCmdListVtbl(self.ctx.cmd_list.?).Dispatch(
    self.ctx.cmd_list.?,
    disp.group_count_x,
    disp.group_count_y,
    disp.group_count_z,
);

            self.pool.applyBarriers(self.ctx.cmd_list.?, gp.barriers_after);
        }

        _ = d3d.getCmdListVtbl(self.ctx.cmd_list.?).Close(self.ctx.cmd_list.?);
        var lists = [_]?*anyopaque{self.ctx.cmd_list};
        d3d.getQueueVtbl(self.ctx.queue.?).ExecuteCommandLists(self.ctx.queue.?, 1, &lists);
        _ = try self.ctx.submitAndWait();
    }
};

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const resource_system = @import("resource_system.zig");

/// Ring-buffer depth for frame generation.
/// FSR 3.1 needs N-1 and N-2 for interpolation; N-3 for optical flow confidence.
pub const HISTORY_DEPTH = 4;

/// A single history slot — wraps a texture resource.
pub const HistorySlot = struct {

    resource_id: gpu_types.ResourceId = 0,

    pub fn bind(self: *const HistorySlot, reg: u32, space: u32, kind: gpu_types.BindingKind) gpu_types.BindEntry {
        return .{
            .key = .{ .reg = reg, .space = space, .kind = kind },
            .resource_id = self.resource_id,
        };
    }
};

/// Ring buffer of history textures with generation tracking.
pub const HistoryRing = struct {
    slots: [HISTORY_DEPTH]gpu_types.ResourceId = [_]gpu_types.ResourceId{0} ** HISTORY_DEPTH,
    write_idx: u32 = 0,
    count: u32 = 0,

    pub fn getCurrent(self: *const HistoryRing) HistorySlot {
        if (self.count == 0) return .{};
        return .{ .resource_id = self.slots[self.write_idx] };
    }

pub fn getPrevious(self: *const HistoryRing, offset: u32) HistorySlot {
    if (offset >= self.count) return .{};
    const read_idx = (self.write_idx + HISTORY_DEPTH - offset) % HISTORY_DEPTH;
    return .{ .resource_id = self.slots[read_idx] };
}

pub fn getAll(self: *const HistoryRing, comptime count: u32) [count]HistorySlot {
    var result: [count]HistorySlot = undefined;
    for (0..@min(count, self.count)) |i| {

        result[i] = self.getPrevious(i);
    }
    return result;
}

pub fn push(self: *HistoryRing, resource_id: gpu_types.ResourceId) void {
    self.write_idx = (self.write_idx + 1) % HISTORY_DEPTH;
    self.slots[self.write_idx] = resource_id;
    if (self.count < HISTORY_DEPTH) self.count += 1;
}

pub fn flip(_: *HistoryRing) void {
    // write_idx stays — next frame overwrites oldest slot
}

pub fn hasHistory(self: *const HistoryRing) bool {
    // Need at least 2 frames (prev + current) for temporal reprojection.
    return self.count >= 2;
}

    pub fn hasFullHistory(self: *const HistoryRing) bool {
        return self.count >= HISTORY_DEPTH;
    }
};

/// Full history manager for FSR 3.1 temporal resources.
pub const HistoryManager = struct {
    color: HistoryRing = .{},
    depth: HistoryRing = .{},
    motion: HistoryRing = .{},

exposure: HistoryRing = .{},
reactive: HistoryRing = .{},
compositing: HistoryRing = .{},
frame_index: u64 = 0,
valid: bool = false,

pub fn deinit(self: *HistoryManager, pool: *resource_system.ResourcePool) void {
    inline for (.{ "color", "depth", "motion", "exposure", "reactive", "compositing" }) |field_name| {
        const ring = &@field(self, field_name);
        for (&ring.slots) |*id| {

            if (id.* != 0) {
                if (pool.getResource(id.*)) |_| {
                    _ = pool.resources.remove(id.*);
                }
                id.* = 0;
            }
        }
    }
}

fn initRing(
    ring: *HistoryRing,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,
    format: gpu_types.ResourceFormat,
) !void {
    const desc = gpu_types.TextureDesc{ .width = width, .height = height, .format = format };
    for (&ring.slots) |*id| {
        id.* = try pool.createTexture2D(desc);

    }
    ring.write_idx = 0;
    ring.count = 0;
}

pub fn initColor(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.color, pool, width, height, format);
}

pub fn initDepth(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.depth, pool, width, height, format);
}

pub fn initMotion(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.motion, pool, width, height, format);
}

pub fn initExposure(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.exposure, pool, width, height, format);
}

pub fn initReactive(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.reactive, pool, width, height, format);
}

pub fn initCompositing(
    self: *HistoryManager,
    pool: *resource_system.ResourcePool,
    width: u32,
    height: u32,

    format: gpu_types.ResourceFormat,
) !void {
    try initRing(&self.compositing, pool, width, height, format);
}

pub fn beginFrame(self: *HistoryManager) void {
    self.frame_index += 1;
}

pub fn flip(self: *HistoryManager) void {

    self.color.flip();
    self.depth.flip();
    self.motion.flip();
    self.exposure.flip();
    self.reactive.flip();
    self.compositing.flip();
    self.valid = true;
}

pub fn pushFrame(

    self: *HistoryManager,
    color_id: gpu_types.ResourceId,
    depth_id: gpu_types.ResourceId,
    motion_id: gpu_types.ResourceId,
) void {
    self.color.push(color_id);
    self.depth.push(depth_id);
    self.motion.push(motion_id);
    self.valid = true;
}

pub fn reset(self: *HistoryManager) void {
    self.valid = false;
    self.frame_index = 0;
    self.color = .{};
    self.depth = .{};
    self.motion = .{};
    self.exposure = .{};
    self.reactive = .{};
    self.compositing = .{};

}

pub fn hasHistory(self: *const HistoryManager) bool {
    return self.valid and self.color.hasHistory();
}

pub fn hasFullHistory(self: *const HistoryManager) bool {
    return self.valid and self.color.hasFullHistory();
}

    pub fn canGenerateFrame(self: *const HistoryManager) bool {
        // Need at least 2 previous frames for interpolation
        return self.hasHistory() and self.color.count >= 2;
    }
};

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const frame_graph = @import("frame_graph.zig");
const resource_system = @import("resource_system.zig");

/// A single resource's lifetime interval [first_pass, last_pass].
pub const LifetimeEntry = struct {
    resource_id: gpu_types.ResourceId,
    first_pass: u32,
    last_pass: u32,

    transient: bool,
};

/// A group of resources with non-overlapping lifetimes that can share memory.
pub const AliasGroup = struct {
    group_id: u32,
    /// Memory requirement: max of all resource sizes in group.
    max_size: u64,
    max_alignment: u64,
    /// Resources assigned to this group (sorted by first_pass).

    resources: []gpu_types.ResourceId,
};

/// Complete lifetime analysis: per-resource intervals + alias groups.
pub const LifetimeGraph = struct {
    entries: []LifetimeEntry,
    groups: []AliasGroup,
    /// resource_id → alias_group_id (only for resources assigned to a group).
    alias_map: std.AutoHashMap(gpu_types.ResourceId, u32),

pub fn build(
    allocator: std.mem.Allocator,
    gpu_passes: []const frame_graph.GPUPassDesc,
    pool: *resource_system.ResourcePool,
) !LifetimeGraph {
    const entries = try computeLifetimes(allocator, gpu_passes, pool);
    errdefer allocator.free(entries);

    var map = std.AutoHashMap(gpu_types.ResourceId, u32).init(allocator);
    errdefer map.deinit();

const groups = try findAliasGroups(allocator, entries, &map);
errdefer allocator.free(groups);

for (groups) |*g| {
    for (g.resources) |rid| {
        if (pool.getResource(rid)) |handle| {
            const size = resourceSize(handle.desc);
            g.max_size = @max(g.max_size, size);
            const group_align: u64 = switch (handle.desc) {

                .texture2d => 256,
                .buffer => 16,
                .sampler => 0,
            };
            g.max_alignment = @max(g.max_alignment, group_align);
        }
    }
}

return .{

        .entries = entries,
        .groups = groups,
        .alias_map = map,
    };
}

pub fn deinit(self: *LifetimeGraph, allocator: std.mem.Allocator) void {
    const groups = @as([]AliasGroup, self.groups);
    for (groups) |*g| allocator.free(g.resources);
    allocator.free(groups);

    allocator.free(self.entries);
    self.alias_map.deinit();
}

/// Check if two lifetime intervals can share memory.
pub fn canAlias(a: LifetimeEntry, b: LifetimeEntry) bool {
    if (!a.transient or !b.transient) return false;
    const a_first = a.first_pass;
    const a_last = a.last_pass;
    const b_first = b.first_pass;

    const b_last = b.last_pass;
    return (a_last < b_first) or (b_last < a_first);
}

/// Return the alias group id for a resource, or null if ungrouped.
pub fn aliasGroup(self: *const LifetimeGraph, resource_id: gpu_types.ResourceId) ?u32 {
    return self.alias_map.get(resource_id);
}

/// Estimate resource memory size in bytes.

fn resourceSize(desc: gpu_types.ResourceDesc) u64 {
    return switch (desc) {
        .buffer => |b| @max(b.size, b.stride * b.elements),
        .texture2d => |t| {
            const bpp: u64 = switch (t.format) {
                .r32g32b32a32_float => 16,
                .r32g32b32a32_uint => 16,
                .r32g32b32a32_sint => 16,
                .r16g16b16a16_float => 8,
                .r16g16b16a16_unorm => 8,

                else => 4,
            };
            return t.width * t.height * bpp * t.array_size;
        },
        .sampler => 0,
    };
}

/// Compute lifetime intervals for all resources referenced in gpu passes.
fn computeLifetimes(

    allocator: std.mem.Allocator,
    gpu_passes: []const frame_graph.GPUPassDesc,
    pool: *resource_system.ResourcePool,
) ![]LifetimeEntry {
    var interval_map = std.AutoHashMap(gpu_types.ResourceId, struct { first: u32, last: u32, transient: bool }).init(allocator);
    defer interval_map.deinit();

    for (gpu_passes, 0..) |gp, pi| {
        const pass_idx = @as(u32, @intCast(pi));
        for (gp.bindings.entries) |entry| {

    const gop = try interval_map.getOrPut(entry.resource_id);
    if (!gop.found_existing) {
        const handle = pool.getResource(entry.resource_id);
        const is_transient = if (handle) |h| h.desc != .sampler else false;
        gop.value_ptr.* = .{ .first = pass_idx, .last = pass_idx, .transient = is_transient };
    } else {
        if (pass_idx < gop.value_ptr.first) gop.value_ptr.first = pass_idx;
        if (pass_idx > gop.value_ptr.last) gop.value_ptr.last = pass_idx;
    }
}

}

var list = try std.ArrayList(LifetimeEntry).initCapacity(allocator, interval_map.count());
var it = interval_map.iterator();
while (it.next()) |entry| {
    list.appendAssumeCapacity(.{
        .resource_id = entry.key_ptr.*,
        .first_pass = entry.value_ptr.first,
        .last_pass = entry.value_ptr.last,
        .transient = entry.value_ptr.transient,

        });
    }
    return list.toOwnedSlice();
}

/// Find alias groups: resources with non-overlapping lifetimes share a group.
/// Greedy interval packing: sort by first_pass, assign to earliest compatible group.
fn findAliasGroups(
    allocator: std.mem.Allocator,
    entries: []LifetimeEntry,

    alias_map: *std.AutoHashMap(gpu_types.ResourceId, u32),
) ![]AliasGroup {
    // Only consider transient resources
    var candidates = std.ArrayList(LifetimeEntry).init(allocator);
    defer candidates.deinit();
    for (entries) |e| {
        if (e.transient) try candidates.append(e);
    }

    if (candidates.items.len == 0) {

    return allocator.alloc(AliasGroup, 0);
}

// Sort by first_pass
std.mem.sort(LifetimeEntry, candidates.items, {}, struct {
    fn less(_: void, a: LifetimeEntry, b: LifetimeEntry) bool {
        if (a.first_pass != b.first_pass) return a.first_pass < b.first_pass;
        return a.resource_id < b.resource_id;
    }
}.less);

// Greedy group assignment
var groups = std.ArrayList(struct {
    last_pass: u32,
    resources: std.ArrayList(gpu_types.ResourceId),
}).init(allocator);
defer {
    for (groups.items) |*g| g.resources.deinit();
    groups.deinit();
}

for (candidates.items) |candidate| {
    var assigned = false;
    for (groups.items, 0..) |*g, gi| {
        if (g.last_pass < candidate.first_pass) {
            try g.resources.append(candidate.resource_id);
            if (candidate.last_pass > g.last_pass) g.last_pass = candidate.last_pass;
            try alias_map.put(candidate.resource_id, @intCast(gi));
            assigned = true;
            break;

    }
}
if (!assigned) {
    var new_resources = std.ArrayList(gpu_types.ResourceId).init(allocator);
    try new_resources.append(candidate.resource_id);
    try groups.append(.{
        .last_pass = candidate.last_pass,
        .resources = new_resources,
    });
    try alias_map.put(candidate.resource_id, @intCast(groups.items.len - 1));

    }
}

// Convert groups to output format
var result = try std.ArrayList(AliasGroup).initCapacity(allocator, groups.items.len);
for (groups.items, 0..) |g, gi| {
    const res_slice = try g.resources.toOwnedSlice();
    result.appendAssumeCapacity(.{
        .group_id = @intCast(gi),
        .max_size = 0,

                .max_alignment = 0,
                .resources = res_slice,
            });
        }
        return result.toOwnedSlice();
    }
};

﻿const std = @import("std");
const frame_graph = @import("frame_graph.zig");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const resource_system = @import("resource_system.zig");
const lifetime_graph = @import("lifetime_graph.zig");
const barrier_optimizer = @import("barrier_optimizer.zig");
const gpu_execution = @import("gpu_execution.zig");

pub const ResourceAccess = enum(u8) {
    read,

    write,
    read_write,
};

pub const ResourceNode = struct {
    id: u32,
    resource_id: gpu_types.ResourceId,
    passes: []const u32,
    state: gpu_types.ResourceState = .common,
    access: ResourceAccess = .read,

    transient: bool = false,
};

pub const BarrierSlot = barrier_optimizer.BarrierSlot;

pub const RenderPlan = struct {
    nodes: []frame_graph.ExecutionNode,
    edges: []frame_graph.DependencyEdge,
    budget_us: u32,
    gpu_passes: []const frame_graph.GPUPassDesc,

    lifetimes: lifetime_graph.LifetimeGraph,
    auto_barriers: []const BarrierSlot,
    execution_plan: gpu_execution.GpuExecutionPlan,
};

pub const RenderGraph = struct {
    allocator: std.mem.Allocator,
    pool: *resource_system.ResourcePool,

    pub fn init(allocator: std.mem.Allocator, pool: *resource_system.ResourcePool) RenderGraph {

    return .{ .allocator = allocator, .pool = pool };
}

pub fn compile(
    self: *RenderGraph,
    frames: []const frame_graph.Pass,
    gpu_passes: []const frame_graph.GPUPassDesc,
    budget_us: u32,
) !RenderPlan {
    return self.compileWithMode(frames, gpu_passes, budget_us, .real);

}

pub fn compileWithMode(
    self: *RenderGraph,
    frames: []const frame_graph.Pass,
    gpu_passes: []const frame_graph.GPUPassDesc,
    budget_us: u32,
    frame_mode: gpu_execution.FrameMode,
) !RenderPlan {
    const fg = frame_graph.FrameGraph.init(frames);

var plan = try fg.compile(self.allocator, budget_us);
errdefer frame_graph.FrameGraph.deinitPlan(self.allocator, &plan);

const lifetimes = try lifetime_graph.LifetimeGraph.build(self.allocator, gpu_passes, self.pool);
errdefer lifetimes.deinit(self.allocator);

var opt = barrier_optimizer.BarrierOptimizer.init(self.allocator);
const barrier_result = try opt.optimize(gpu_passes, &lifetimes);
errdefer self.allocator.free(barrier_result.barriers);

const exec_ctx = gpu_execution.ExecutionContext{
    .frame_index = 0,
    .budget_us = budget_us,
    .motion_intensity = 0.0,
    .history_valid = false,
    .frame_mode = frame_mode,
};
const execution_plan = try gpu_execution.compileGpuExecutionPlan(
    self.allocator,
    gpu_passes,

    &lifetimes,
    barrier_result.barriers,
    exec_ctx,
);
errdefer execution_plan.deinit();

return RenderPlan{
    .nodes = plan.nodes,
    .edges = plan.edges,
    .budget_us = plan.budget_us,

        .gpu_passes = gpu_passes,
        .lifetimes = lifetimes,
        .auto_barriers = barrier_result.barriers,
        .execution_plan = execution_plan,
    };
}

pub fn allocateTransients(self: *RenderGraph, plan: *RenderPlan) !void {
    for (plan.lifetimes.entries) |e| {
        if (!e.transient) continue;

const handle = self.pool.getResource(e.resource_id) orelse continue;
if (handle.d3d_resource != null) continue;
switch (handle.desc) {
    .texture2d => |td| {
        _ = try self.pool.createTexture2D(td);
    },
    .buffer => |bd| {
        _ = try self.pool.createBuffer(bd);
    },
    .sampler => {},

        }
    }
}

pub fn releaseTransients(self: *RenderGraph, plan: *RenderPlan) void {
    for (plan.lifetimes.entries) |e| {
        if (!e.transient) continue;
        if (self.pool.getResource(e.resource_id)) |handle| {
            if (handle.d3d_resource != null) {
                _ = self.pool.resources.remove(e.resource_id);

            }
        }
    }
}

pub fn deinitPlan(allocator: std.mem.Allocator, plan: *RenderPlan) void {
    frame_graph.FrameGraph.deinitPlan(allocator, &.{
        .nodes = plan.nodes,
        .edges = plan.edges,
        .budget_us = plan.budget_us,

    });
    var lifetimes = plan.lifetimes;
    lifetimes.deinit(allocator);
    allocator.free(plan.auto_barriers);
    plan.execution_plan.deinit();
}

/// Build FSR 3.1 resource barrier descriptions for a frame generation pipeline.
/// Returns barriers for optical flow, confidence, disocclusion, and output resources.
pub fn buildFSR3Barriers(

    pool: *resource_system.ResourcePool,
    optical_flow: gpu_types.ResourceId,
    confidence: gpu_types.ResourceId,
    disocclusion: gpu_types.ResourceId,
    output: gpu_types.ResourceId,
) ![4]gpu_types.BarrierDesc {
    var result: [4]gpu_types.BarrierDesc = undefined;
    var i: u32 = 0;

    const entries = [_]struct { id: gpu_types.ResourceId, target: gpu_types.ResourceState }{

    .{ .id = optical_flow, .target = .unordered_access },
    .{ .id = confidence, .target = .unordered_access },
    .{ .id = disocclusion, .target = .unordered_access },
    .{ .id = output, .target = .unordered_access },
};

for (entries) |e| {
    if (e.id != 0) {
        const handle = pool.getResource(e.id) orelse continue;
        result[i] = .{

                    .resource_id = e.id,
                    .state_before = @intFromEnum(handle.current_state),
                    .state_after = @intFromEnum(e.target),
                };
                i += 1;
            }
        }
        return result;
    }
};

