        .StructureByteStride = 0,

                .CounterOffsetInBytes = 0,
                .Flags = 0,
            } };
            self.ctx.createUAVView(handle.d3d_resource.?, &desc, cpu_handle);
        },
        .sampler => {},
    }
},
.srv => {
    switch (handle.desc) {

.texture2d => |td| {
    const dxgi_format: d3d.DXGI_FORMAT = @enumFromInt(td.format.toDXGI());
    var desc: d3d.D3D12_SHADER_RESOURCE_VIEW_DESC = undefined;
    desc.Format = dxgi_format;
    desc.ViewDimension = .TEXTURE2D;
    desc.Shader4ComponentMapping = 0x1608;
    desc._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } };
    self.ctx.createSRV(handle.d3d_resource.?, &desc, cpu_handle);
},
.buffer => |bd| {

var desc: d3d.D3D12_SHADER_RESOURCE_VIEW_DESC = undefined;
desc.Format = .R32_FLOAT;
desc.ViewDimension = .BUFFER;
desc.Shader4ComponentMapping = 0x1608;
desc._u = .{ .Buffer = .{
    .FirstElement = 0,
    .NumElements = if (bd.elements > 0) bd.elements else @as(u32, @intCast(bd.size / 4)),
    .StructureByteStride = 0,
    .Flags = 0,
} };

                        self.ctx.createSRV(handle.d3d_resource.?, &desc, cpu_handle);
                    },
                    .sampler => {},
                }
            },
            .cbv => {},
            .sampler => {},
        }
    }
}

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const d3d = @import("d3d12_bindings.zig");
const dx12 = @import("dx12_compute.zig");

/// A single range in the compiled root signature.
pub const RSRange = struct {
    kind: gpu_types.BindType,
    base_register: u32,
    space: u32,

    count: u32,
    /// Descriptor heap offset for the start of this range.
    heap_offset: u32,
};

/// Per-pass compiled root signature artifact.
pub const CompiledRS = struct {
    root_signature: ?*anyopaque,
    ranges: []const RSRange,
    total_descriptors: u32,

    allocator: std.mem.Allocator,

    pub fn deinit(self: *CompiledRS) void {
        d3d.release(self.root_signature);
        self.allocator.free(self.ranges);
    }
};

/// RS cache entry.
const RSCacheEntry = struct {

    compiled: CompiledRS,
};

pub const RSRootSignatureBuilder = struct {
    allocator: std.mem.Allocator,
    ctx: *dx12.ComputeContext,
    /// Cache: hash of BindLayout → CompiledRS
    cache: std.AutoHashMap(u64, RSCacheEntry),

    pub fn init(allocator: std.mem.Allocator, ctx: *dx12.ComputeContext) RSRootSignatureBuilder {

    return .{
        .allocator = allocator,
        .ctx = ctx,
        .cache = std.AutoHashMap(u64, RSCacheEntry).init(allocator),
    };
}

pub fn deinit(self: *RSRootSignatureBuilder) void {
    var it = self.cache.valueIterator();
    while (it.next()) |entry| {

        entry.compiled.deinit();
    }
    self.cache.deinit();
}

fn hashLayout(layout: gpu_types.BindLayout) u64 {
    var h = std.hash.Wyhash.init(0);
    for (layout.slots) |slot| {
        h.update(std.mem.asBytes(&slot.register));
        h.update(std.mem.asBytes(&slot.space));

        h.update(std.mem.asBytes(&slot.bind_type));
        h.update(std.mem.asBytes(&slot.num_descriptors));
    }
    return h.final();
}

/// Build per-pass root signature from BindLayout.
pub fn getOrBuild(self: *RSRootSignatureBuilder, layout: gpu_types.BindLayout) !*const CompiledRS {
    const hash = hashLayout(layout);
    if (self.cache.getPtr(hash)) |entry| return &entry.compiled;

// Analyze layout: find max register per (type, space)
var max_srv: [8]u32 = [_]u32{0} ** 8;
var max_uav: [8]u32 = [_]u32{0} ** 8;
var max_cbv: [8]u32 = [_]u32{0} ** 8;
var has_srv: [8]bool = [_]bool{false} ** 8;
var has_uav: [8]bool = [_]bool{false} ** 8;
var has_cbv: [8]bool = [_]bool{false} ** 8;

for (layout.slots) |slot| {

const s = slot.space;
if (s >= 8) continue;
const end_reg = slot.register + slot.num_descriptors;
switch (slot.bind_type) {
    .srv => {
        if (end_reg > max_srv[s]) max_srv[s] = end_reg;
        has_srv[s] = true;
    },
    .uav => {
        if (end_reg > max_uav[s]) max_uav[s] = end_reg;

            has_uav[s] = true;
        },
        .cbv => {
            if (end_reg > max_cbv[s]) max_cbv[s] = end_reg;
            has_cbv[s] = true;
        },
        .sampler => {},
    }
}

// Count non-empty spaces (CBV not in descriptor table — root descriptor)
var range_count: u32 = 0;
var ti: u32 = 0;
while (ti < 8) : (ti += 1) {
    if (has_srv[ti]) range_count += 1;
    if (has_uav[ti]) range_count += 1;
}

// Build ranges array and descriptor table ranges
var total_descriptors: u32 = 0;

var ranges = try self.allocator.alloc(RSRange, range_count);
errdefer self.allocator.free(ranges);

var d3d_ranges_list = try std.ArrayList(d3d.D3D12_DESCRIPTOR_RANGE).initCapacity(self.allocator, range_count);
defer d3d_ranges_list.deinit();

var ri: u32 = 0;
ti = 0;
while (ti < 8) : (ti += 1) {
    if (has_srv[ti]) {

const count = max_srv[ti];
ranges[ri] = .{
    .kind = .srv,
    .base_register = 0,
    .space = ti,
    .count = count,
    .heap_offset = total_descriptors,
};
d3d_ranges_list.appendAssumeCapacity(.{
    .RangeType = .SRV,

        .NumDescriptors = count,
        .BaseShaderRegister = 0,
        .RegisterSpace = ti,
        .OffsetInDescriptorsFromTableStart = total_descriptors,
    });
    total_descriptors += count;
    ri += 1;
}
if (has_uav[ti]) {
    const count = max_uav[ti];

ranges[ri] = .{
    .kind = .uav,
    .base_register = 0,
    .space = ti,
    .count = count,
    .heap_offset = total_descriptors,
};
d3d_ranges_list.appendAssumeCapacity(.{
    .RangeType = .UAV,
    .NumDescriptors = count,

            .BaseShaderRegister = 0,
            .RegisterSpace = ti,
            .OffsetInDescriptorsFromTableStart = total_descriptors,
        });
        total_descriptors += count;
        ri += 1;
    }
}

// Create the root signature

const rs = try self.createRootSignature(d3d_ranges_list.items);

const compiled = CompiledRS{
    .root_signature = rs,
    .ranges = ranges,
    .total_descriptors = total_descriptors,
    .allocator = self.allocator,
};

try self.cache.put(hash, .{ .compiled = compiled });

    const entry = self.cache.getPtr(hash).?;
    return &entry.compiled;
}

fn createRootSignature(
    self: *RSRootSignatureBuilder,
    d3d_ranges: []const d3d.D3D12_DESCRIPTOR_RANGE,
) !?*anyopaque {
    var params = [1]d3d.D3D12_ROOT_PARAMETER{
        .{

        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{
            .NumDescriptorRanges = @as(u32, @intCast(d3d_ranges.len)),
            .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(d3d_ranges.ptr)),
        } },
        .ShaderVisibility = .ALL,
    },
};

var static_samplers = [1]d3d.D3D12_STATIC_SAMPLER_DESC{

        .MaxLOD = 3.40282347e+38,
        .ShaderRegister = 0,
        .RegisterSpace = 0,
        .ShaderVisibility = .ALL,
    },
};

var root_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{
    .NumParameters = 1,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&params)),

    .NumStaticSamplers = 1,
    .pStaticSamplers = @as(?*const d3d.D3D12_STATIC_SAMPLER_DESC, @ptrCast(&static_samplers)),
    .Flags = 0,
};

var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = self.ctx.D3D12SerializeRootSignature.?(
    &root_desc,
    1,

    &blob,
    &err_blob,
);
if (hr_ < 0) {
    if (err_blob) |eb| {
        const v = d3d.getBlobVtbl(eb);
        const ptr = v.GetBufferPointer(eb);
        if (@intFromPtr(ptr) != 0)
            std.debug.print("RS serialize error: {s}\n", .{@as([*:0]u8, @ptrCast(@alignCast(ptr)))});
    }

    return error.RootSignatureFailed;
}
defer d3d.release(blob);

var root_sig: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(self.ctx.device.?).CreateRootSignature(
    self.ctx.device.?,
    0,
    d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?),
    d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?),

        &d3d.IID_ID3D12RootSignature,
        &root_sig,
    );
    if (hr_ < 0) return error.RootSignatureFailed;
    return root_sig;
}

/// Validate that a BindingKey is covered by the compiled RSRanges.
pub fn validateBinding(compiled: *const CompiledRS, key: gpu_types.BindingKey) bool {
    for (compiled.ranges) |r| {

        if (r.kind == key.kind and r.space == key.space) {
            if (key.reg < r.count) return true;
        }
    }
    return false;
}

/// Get the descriptor heap offset for a BindingKey within this RS.
pub fn getHeapOffset(compiled: *const CompiledRS, key: gpu_types.BindingKey) ?u32 {
    for (compiled.ranges) |r| {

            if (r.kind == key.kind and r.space == key.space) {
                if (key.reg < r.count) {
                    return r.heap_offset + key.reg;
                }
            }
        }
        return null;
    }
};

const std = @import("std");
const history_manager = @import("history_manager.zig");

/// Per-frame confidence score (0.0 = useless, 1.0 = perfect).
pub const FrameConfidence = struct {
    overall: f32 = 1.0,
    reprojection: f32 = 1.0,
    motion_coherence: f32 = 1.0,
    depth_stability: f32 = 1.0,
    exposure_match: f32 = 1.0,

};

/// Per-slot metadata for history ring tracking.
pub const HistorySlotMeta = struct {
    frame_index: u64 = 0,
    confidence: FrameConfidence = .{},
    rejected: bool = false,
};

/// Validation configuration.

pub const ValidationConfig = struct {
    /// Minimum overall confidence to use a frame for temporal accumulation.
    confidence_threshold: f32 = 0.3,
    /// Per-frame confidence decay for old frames (0-1).
    decay_rate: f32 = 0.95,
    /// Max reprojection error before rejection (pixels).
    reprojection_error_max: f32 = 4.0,
    /// Motion magnitude above this triggers rejection.
    motion_discontinuity_threshold: f32 = 0.5,
    /// Depth change ratio above this triggers disocclusion rejection.

    depth_disocclusion_threshold: f32 = 0.2,
};

/// Temporal history validation engine.
/// Tracks per-slot confidence, rejection state, and computes blend weights.
pub const TemporalHistory = struct {
    config: ValidationConfig = .{},
    slot_meta: [history_manager.HISTORY_DEPTH]HistorySlotMeta = [_]HistorySlotMeta{.{}} ** history_manager.HISTORY_DEPTH,
    write_idx: u32 = 0,
    count: u32 = 0,

/// Call after HistoryRing.push with the current frame index.
pub fn pushFrame(self: *TemporalHistory, frame_index: u64) void {
    self.write_idx = (self.write_idx + 1) % history_manager.HISTORY_DEPTH;
    if (self.count < history_manager.HISTORY_DEPTH) self.count += 1;

    const slot = &self.slot_meta[self.write_idx];
    slot.frame_index = frame_index;
    slot.confidence = .{}; // starts at 1.0
    slot.rejected = false;

}

/// Get metadata slot at offset (0 = current, 1 = previous, etc).
fn getSlot(self: *const TemporalHistory, offset: u32) HistorySlotMeta {
    if (offset >= self.count) {
        return .{
            .frame_index = 0,
            .confidence = .{ .overall = 0 },
            .rejected = true,
        };

    }
    const read_idx = (self.write_idx + history_manager.HISTORY_DEPTH - offset) % history_manager.HISTORY_DEPTH;
    return self.slot_meta[read_idx];
}

/// Get overall confidence for a frame at offset. Applies decay for older frames.
pub fn getConfidence(self: *const TemporalHistory, offset: u32) f32 {
    const slot = self.getSlot(offset);
    if (slot.rejected) return 0.0;
    const decay = std.math.pow(f32, self.config.decay_rate, @as(f32, @floatFromInt(offset)));

    return slot.confidence.overall * decay;
}

/// Whether the frame at offset is usable for temporal accumulation.
pub fn isFrameValid(self: *const TemporalHistory, offset: u32) bool {
    return self.getConfidence(offset) >= self.config.confidence_threshold;
}

/// Compute blend weight for a frame at offset, given a base factor.
/// Higher confidence → higher weight. Older frames get decayed.

pub fn getBlendWeight(self: *const TemporalHistory, offset: u32, base_weight: f32) f32 {
    return base_weight * self.getConfidence(offset);
}

/// Reject a frame at offset (e.g., due to ghosting, disocclusion).
pub fn rejectFrame(self: *TemporalHistory, offset: u32) void {
    if (offset >= self.count) return;
    const read_idx = @as(usize, (self.write_idx + history_manager.HISTORY_DEPTH - offset) % history_manager.HISTORY_DEPTH);
    self.slot_meta[read_idx].rejected = true;
    self.slot_meta[read_idx].confidence.overall = 0;

}

/// Update reprojection confidence for current frame.
pub fn setReprojectionConfidence(self: *TemporalHistory, error_pixels: f32) void {
    const slot = &self.slot_meta[self.write_idx];
    const ratio = 1.0 - (error_pixels / self.config.reprojection_error_max);
    slot.confidence.reprojection = @max(@as(f32, 0), @min(@as(f32, 1), ratio));
    slot.confidence.overall = self.computeOverall(slot.confidence);
}

/// Update motion coherence confidence for current frame.
pub fn setMotionCoherence(self: *TemporalHistory, motion_magnitude: f32) void {
    const slot = &self.slot_meta[self.write_idx];
    if (motion_magnitude > self.config.motion_discontinuity_threshold) {
        slot.confidence.motion_coherence = 0;
        slot.rejected = true;
    } else {
        slot.confidence.motion_coherence = 1.0 - (motion_magnitude / self.config.motion_discontinuity_threshold);
    }
    slot.confidence.overall = self.computeOverall(slot.confidence);

}

/// Update depth stability confidence for current frame.
pub fn setDepthStability(self: *TemporalHistory, depth_change_ratio: f32) void {
    const slot = &self.slot_meta[self.write_idx];
    if (depth_change_ratio > self.config.depth_disocclusion_threshold) {
        slot.confidence.depth_stability = 0;
        slot.rejected = true;
    } else {
        slot.confidence.depth_stability = 1.0 - (depth_change_ratio / self.config.depth_disocclusion_threshold);

    }
    slot.confidence.overall = self.computeOverall(slot.confidence);
}

/// Reject current frame entirely (e.g., on camera cut, full-screen disocclusion).
pub fn rejectCurrentFrame(self: *TemporalHistory) void {
    const slot = &self.slot_meta[self.write_idx];
    slot.rejected = true;
    slot.confidence.overall = 0;
}

/// Mark current frame as valid (after validation passes).
pub fn validateCurrentFrame(self: *TemporalHistory) void {
    const slot = &self.slot_meta[self.write_idx];
    slot.rejected = false;
    slot.confidence.overall = self.computeOverall(slot.confidence);
}

fn computeOverall(_: *const TemporalHistory, c: FrameConfidence) f32 {
    // Weighted combination: reprojection is most important for temporal stability

    return c.reprojection * 0.4 +
        c.motion_coherence * 0.3 +
        c.depth_stability * 0.2 +
        c.exposure_match * 0.1;
}

/// Reset all metadata (on history reset or camera cut).
pub fn reset(self: *TemporalHistory) void {
    self.write_idx = 0;
    self.count = 0;

    for (&self.slot_meta) |*slot| {
        slot.* = .{};
    }
}

/// Number of valid (non-rejected, confident) frames in the ring.
pub fn validFrameCount(self: *const TemporalHistory) u32 {
    var n: u32 = 0;
    for (0..self.count) |i| {
        if (self.isFrameValid(@intCast(i))) n += 1;

    }
    return n;
}

/// Whether we have enough valid history for frame generation.
pub fn canGenerate(self: *const TemporalHistory) bool {
    // FSR 3.1 needs at least 2 valid frames (N-1 and N) for interpolation
    var valid_count: u32 = 0;
    for (0..self.count) |i| {
        if (self.isFrameValid(@intCast(i))) {

                valid_count += 1;
                if (valid_count >= 2) return true;
            }
        }
        return false;
    }
};

﻿const std = @import("std");
const gpu_types = @import("../compiler/gpu/gpu_types.zig");
const history_manager = @import("history_manager.zig");
const camera_jitter = @import("camera_jitter.zig");

/// Camera matrices for reprojection.
pub const CameraMatrices = struct {
    view: [16]f32 = undefined,
    projection: [16]f32 = undefined,
    view_projection: [16]f32 = undefined,

inverse_view: [16]f32 = undefined,
inverse_projection: [16]f32 = undefined,
inverse_view_projection: [16]f32 = undefined,
prev_view_projection: [16]f32 = undefined,

pub fn update(self: *CameraMatrices, view: *const [16]f32, proj: *const [16]f32) void {
    self.view = view.*;
    self.projection = proj.*;
    matMul(view, proj, &self.view_projection);
    matInverse(view, &self.inverse_view);

        matInverse(proj, &self.inverse_projection);
        matInverse(&self.view_projection, &self.inverse_view_projection);
    }

    pub fn advanceFrame(self: *CameraMatrices) void {
        self.prev_view_projection = self.view_projection;
    }
};

/// Per-frame constants for temporal reprojection shader.

    far_plane: f32,
    frame_index: u32,
    reset_history: u32,
    pad: [2]u32 = undefined,
};

/// Motion vector generation constants.
pub const MotionVectorConstants = struct {
    viewport_width: f32,
    viewport_height: f32,

    inv_viewport_width: f32,
    inv_viewport_height: f32,
    near_plane: f32,
    far_plane: f32,
    reprojection_matrix: [16]f32, // prev_view_proj * inv_current_view_proj
};

/// Temporal accumulation constants.
pub const AccumulationConstants = struct {
    jitter_x: f32,

    frame_index: u32,
    reset_history: u32,
};

/// Disocclusion detection constants.
pub const DisocclusionConstants = struct {
    depth_threshold: f32 = 0.05,
    motion_amplitude: f32 = 0.02,
    normal_threshold: f32 = 0.3,
    neighbourhood: u32 = 2,

};

/// Temporal pipeline — manages reprojection, motion vectors, and accumulation.
pub const TemporalPipeline = struct {
    width: u32,
    height: u32,
    camera: CameraMatrices = .{},
    jitter: camera_jitter.JitteredProjection = undefined,
    prev_jitter: camera_jitter.JitteredProjection = undefined,
    history: history_manager.HistoryManager = .{},

    };
}

pub fn beginFrame(self: *TemporalPipeline) void {
    self.frame_index += 1;
    self.jitter = camera_jitter.JitteredProjection.init(self.width, self.height, self.frame_index);
    self.history.beginFrame();
}

pub fn endFrame(self: *TemporalPipeline) void {

    self.camera.advanceFrame();
    self.prev_jitter = self.jitter;
    self.reset_history = false;
}

pub fn getTemporalConstants(self: *const TemporalPipeline) TemporalConstants {
    return .{
        .jitter_x = self.jitter.jitter_x,
        .jitter_y = self.jitter.jitter_y,
        .prev_jitter_x = self.prev_jitter.jitter_x,

}

pub fn getMotionConstants(self: *const TemporalPipeline) MotionVectorConstants {
    var reproj_mat: [16]f32 = undefined;
    matMul(&self.camera.prev_view_projection, &self.camera.inverse_view_projection, &reproj_mat);
    return .{
        .viewport_width = @as(f32, @floatFromInt(self.width)),
        .viewport_height = @as(f32, @floatFromInt(self.height)),
        .inv_viewport_width = 1.0 / @as(f32, @floatFromInt(self.width)),
        .inv_viewport_height = 1.0 / @as(f32, @floatFromInt(self.height)),

        .near_plane = 0.1,
        .far_plane = 1000.0,
        .reprojection_matrix = reproj_mat,
    };
}

pub fn getAccumulationConstants(self: *const TemporalPipeline) AccumulationConstants {
    return .{
        .jitter_x = self.jitter.jitter_x,
        .jitter_y = self.jitter.jitter_y,

            .reset_history = @intFromBool(self.reset_history),
        };
    }
};

// ── Matrix math helpers ──

fn matMul(a: *const [16]f32, b: *const [16]f32, out: *[16]f32) void {
    for (0..4) |row| {
        for (0..4) |col| {

            var sum: f32 = 0;
            for (0..4) |k| {
                sum += a[row * 4 + k] * b[k * 4 + col];
            }
            out[row * 4 + col] = sum;
        }
    }
}

fn matInverse(m: *const [16]f32, out: *[16]f32) void {

const a = m[0];
const b = m[1];
const c = m[2];
const d = m[3];
const e = m[4];
const f = m[5];
const g = m[6];
const h = m[7];
const i = m[8];
const j = m[9];

const k = m[10];
const l = m[11];
const m0 = m[12];
const m1 = m[13];
const m2 = m[14];
const m3 = m[15];

const s0 = a * f - b * e;
const s1 = a * g - c * e;
const s2 = a * h - d * e;

const s3 = b * g - c * f;
const s4 = b * h - d * f;
const s5 = c * h - d * g;
const s6 = i * m1 - j * m0;
const s7 = i * m2 - k * m0;
const s8 = i * m3 - l * m0;
const s9 = j * m2 - k * m1;
const s10 = j * m3 - l * m1;
const s11 = k * m3 - l * m2;

const det = s0 * s11 - s1 * s10 + s2 * s9 + s3 * s8 - s4 * s7 + s5 * s6;
if (det == 0) {
    @memcpy(out, m);
    return;
}
const inv_det = 1.0 / det;

out[0] = (f * s11 - g * s10 + h * s9) * inv_det;
out[1] = (-b * s11 + c * s10 - d * s9) * inv_det;
out[2] = (m1 * s5 - m2 * s4 + m3 * s3) * inv_det;

out[3] = (-j * s5 + k * s4 - l * s3) * inv_det;
out[4] = (-e * s11 + g * s8 - h * s7) * inv_det;
out[5] = (a * s11 - c * s8 + d * s7) * inv_det;
out[6] = (-m0 * s5 + m2 * s2 - m3 * s1) * inv_det;
out[7] = (i * s5 - k * s2 + l * s1) * inv_det;
out[8] = (e * s10 - f * s8 + h * s6) * inv_det;
out[9] = (-a * s10 + b * s8 - d * s6) * inv_det;
out[10] = (m0 * s4 - m1 * s2 + m3 * s0) * inv_det;
out[11] = (-i * s4 + j * s2 - l * s0) * inv_det;
out[12] = (-e * s9 + f * s7 - g * s6) * inv_det;

    out[13] = (a * s9 - b * s7 + c * s6) * inv_det;
    out[14] = (-m0 * s3 + m1 * s1 - m2 * s0) * inv_det;
    out[15] = (i * s3 - j * s1 + k * s0) * inv_det;
}

const std = @import("std");
const sched = @import("scheduler.zig");
const cpu = @import("cpu.zig");
const latency = @import("latency.zig");
const sched_config = @import("scheduler_config.zig");
const sched_state = @import("scheduler_state.zig");
const frame_graph = @import("../render/frame_graph.zig");
const gpu_job = @import("gpu_job.zig");
const gpu_scheduler = @import("gpu_scheduler.zig");

const NUM_WORKERS: u32 = 4;
const ALLOC_SIZE = 64 * 1024 * 1024;

const TimingCtx = struct {
    submitted_at: u64,
    started_at: u64,
    completed_at: u64,
    work_iters: u32,
    enqueue_depth: u32,
    completed_before_start: u64 = 0,

};

fn timingJobFn(ctx: *anyopaque) void {
    const tc = @as(*TimingCtx, @ptrCast(@alignCast(ctx)));
    tc.started_at = @intCast(std.time.nanoTimestamp());
    var x: u64 = 1;
    for (0..tc.work_iters) |_| x = x *| 7 +| 3;
    std.mem.doNotOptimizeAway(&x);
    tc.completed_at = @intCast(std.time.nanoTimestamp());
}

};

fn makeJob(jobs: []sched.Job, idx: usize, ctxs: []TimingCtx, iters: u32, sticky_core: ?u32, stickiness: u8) void {
    ctxs[idx] = TimingCtx{ .submitted_at = 0, .started_at = 0, .completed_at = 0, .work_iters = iters, .enqueue_depth = 0 };
    jobs[idx] = sched.Job{
        .func = timingJobFn,
        .ctx = @as(*anyopaque, @ptrCast(&ctxs[idx])),
        .priority = .Normal,
        .next = null,
        .sticky_core = sticky_core,

        .stickiness = stickiness,
    };
}

fn compute(label: []const u8, ctxs: []TimingCtx, scheduler: *sched.Scheduler, first_submit: u64, last_completion: u64) RunResult {
    const N = ctxs.len;
    var latencies = std.heap.page_allocator.alloc(u64, N) catch unreachable;
    defer std.heap.page_allocator.free(latencies);
    for (ctxs, 0..) |ctx, i| latencies[i] = ctx.completed_at - ctx.submitted_at;
    std.sort.block(u64, latencies, {}, std.sort.asc(u64));

const wall_ns = last_completion - first_submit;
const throughput = if (wall_ns > 0)
    @as(f64, @floatFromInt(N)) / (@as(f64, @floatFromInt(wall_ns)) / 1_000_000_000.0)
else
    0;

const median = latencies[N * 50 / 100];
var stalls: u64 = 0;
for (latencies) |l| {

    if (l > median * 2) stalls += 1;
}

const ww_max = if (scheduler.pool) |*p| p.metrics.wave_wait_max_ns.load(.acquire) else 0;
const ww_sum = if (scheduler.pool) |*p| p.metrics.wave_wait_sum_ns.load(.acquire) else 0;
const ww_cnt = if (scheduler.pool) |*p| p.metrics.wave_count.load(.acquire) else 0;
const qw_max = if (scheduler.pool) |*p| p.metrics.queue_wait_max_ns.load(.acquire) else 0;

var queue_waits = std.heap.page_allocator.alloc(u64, N) catch unreachable;
defer std.heap.page_allocator.free(queue_waits);

for (ctxs, 0..) |ctx, i| queue_waits[i] = if (ctx.started_at > 0) ctx.started_at -| ctx.submitted_at else 0;
std.sort.block(u64, queue_waits, {}, std.sort.asc(u64));

var depths = std.heap.page_allocator.alloc(u32, N) catch unreachable;
defer std.heap.page_allocator.free(depths);
for (ctxs, 0..) |ctx, i| depths[i] = ctx.enqueue_depth;
std.sort.block(u32, depths, {}, std.sort.asc(u32));

var exec_times = std.heap.page_allocator.alloc(u64, N) catch unreachable;
defer std.heap.page_allocator.free(exec_times);

for (ctxs, 0..) |ctx, i| exec_times[i] = if (ctx.started_at > 0) ctx.completed_at -| ctx.started_at else 0;
std.sort.block(u64, exec_times, {}, std.sort.asc(u64));

var completed_before = std.heap.page_allocator.alloc(u64, N) catch unreachable;
defer std.heap.page_allocator.free(completed_before);
for (ctxs, 0..) |ctx, i| completed_before[i] = ctx.completed_before_start;
std.sort.block(u64, completed_before, {}, std.sort.asc(u64));

return RunResult{
    .label = label,

        .queue_depth_max = depths[N - 1],
        .exec_time_p50_ns = exec_times[N * 50 / 100],
        .exec_time_p95_ns = exec_times[N * 95 / 100],
        .exec_time_p99_ns = exec_times[N * 99 / 100],
        .completed_before_p50 = completed_before[N * 50 / 100],
        .completed_before_p95 = completed_before[N * 95 / 100],
        .completed_before_p99 = completed_before[N * 99 / 100],
    };
}

// ── Pattern A: Hot core skew (70% to core 0) ──
fn runHotCoreSkew(allocator: std.mem.Allocator, smart: bool) !RunResult {
    const N = 2000;
    const mem = try allocator.alloc(u8, ALLOC_SIZE);
    defer allocator.free(mem);

    var topo: cpu.CpuTopology = undefined;
    var lp: latency.LatencyProfile = undefined;
    var scheduler: sched.Scheduler = undefined;

if (smart) {
    topo = try cpu.CpuTopology.detect(allocator);
    lp = try latency.LatencyProfile.init(allocator, &topo);
    try sched.Scheduler.initThreadedWithTopo(&scheduler, allocator, NUM_WORKERS, 0, 0, &lp);
} else {
    try sched.Scheduler.initThreaded(&scheduler, allocator, NUM_WORKERS, 0, 0);
}
try scheduler.start();

var jobs = try allocator.alloc(sched.Job, N);

defer allocator.free(jobs);
var ctxs = try allocator.alloc(TimingCtx, N);
defer allocator.free(ctxs);

const first_submit = @as(u64, @intCast(std.time.nanoTimestamp()));
for (0..N) |i| {
    const is_hot = smart and i < N * 70 / 100;
    makeJob(jobs, i, ctxs, 50, if (is_hot) @as(?u32, @intCast(0)) else null, if (is_hot) 1 else 0);
    ctxs[i].submitted_at = @as(u64, @intCast(std.time.nanoTimestamp()));
    if (is_hot)

        scheduler.submitAffine(&jobs[i], 0)
    else
        scheduler.submit(&jobs[i]);
    ctxs[i].enqueue_depth = jobs[i].enqueue_depth;
}
scheduler.waitAll();
for (0..N) |i| ctxs[i].completed_before_start = jobs[i].completed_before_start;
const end = @as(u64, @intCast(std.time.nanoTimestamp()));
const result = compute("hot-core-skew", ctxs, &scheduler, first_submit, end);

    scheduler.deinit();
    if (smart) lp.deinit();
    if (smart) topo.deinit();
    return result;
}

// ── Pattern B: Burst load ──
fn runBurstLoad(allocator: std.mem.Allocator, smart: bool) !RunResult {
    const N = 10000;
    const mem = try allocator.alloc(u8, ALLOC_SIZE);

defer allocator.free(mem);

var topo: cpu.CpuTopology = undefined;
var lp: latency.LatencyProfile = undefined;
var scheduler: sched.Scheduler = undefined;

if (smart) {
    topo = try cpu.CpuTopology.detect(allocator);
    lp = try latency.LatencyProfile.init(allocator, &topo);
    try sched.Scheduler.initThreadedWithTopo(&scheduler, allocator, NUM_WORKERS, 0, 0, &lp);

} else {
    try sched.Scheduler.initThreaded(&scheduler, allocator, NUM_WORKERS, 0, 0);
}
try scheduler.start();

var jobs = try allocator.alloc(sched.Job, N);
defer allocator.free(jobs);
var ctxs = try allocator.alloc(TimingCtx, N);
defer allocator.free(ctxs);

const first_submit = @as(u64, @intCast(std.time.nanoTimestamp()));
for (0..N) |i| {
    const st = if (smart) @as(?u32, @intCast(@as(u32, @truncate(i % 4)))) else null;
    makeJob(jobs, i, ctxs, 10, st, if (st != null) 1 else 0);
    ctxs[i].submitted_at = @as(u64, @intCast(std.time.nanoTimestamp()));
    scheduler.submit(&jobs[i]);
    ctxs[i].enqueue_depth = jobs[i].enqueue_depth;
}
scheduler.waitAll();
for (0..N) |i| ctxs[i].completed_before_start = jobs[i].completed_before_start;

    const end = @as(u64, @intCast(std.time.nanoTimestamp()));
    const result = compute("burst-load", ctxs, &scheduler, first_submit, end);

    scheduler.deinit();
    if (smart) lp.deinit();
    if (smart) topo.deinit();
    return result;
}

// ── Pattern C: Mixed size jobs ──

fn runMixedSize(allocator: std.mem.Allocator, smart: bool) !RunResult {
    const N = 2000;
    const mem = try allocator.alloc(u8, ALLOC_SIZE);
    defer allocator.free(mem);

    var topo: cpu.CpuTopology = undefined;
    var lp: latency.LatencyProfile = undefined;
