const std = @import("std");
const windows = std.os.windows;

const kernel32 = windows.kernel32;

pub export fn print_i64(val: i64) void {
    var buf: [32]u8 = undefined;
    const s = std.fmt.bufPrint(&buf, "{d}\n", .{val}) catch "error";
    const handle = kernel32.GetStdHandle(windows.STD_OUTPUT_HANDLE) orelse return;
    var written: windows.DWORD = 0;

    _ = kernel32.WriteFile(handle, s.ptr, @intCast(s.len), &written, null);
}

pub export fn read_i64() i64 {
    var buf: [32]u8 = undefined;
    const handle = kernel32.GetStdHandle(windows.STD_INPUT_HANDLE) orelse return 0;
    var count: windows.DWORD = 0;
    if (kernel32.ReadFile(handle, &buf, @intCast(buf.len), &count, null) == 0) return 0;
    if (count > 0 and buf[count - 1] == '\n') count -= 1;
    if (count > 0 and buf[count - 1] == '\r') count -= 1;

    const trimmed = std.mem.trimRight(u8, buf[0..count], " \r\n");
    return std.fmt.parseInt(i64, trimmed, 10) catch 0;
}

pub export fn bplus_exit(code: i64) void {
    kernel32.ExitProcess(@intCast(code));
}

pub export fn bplus_malloc(size: i64) i64 {
    const heap = kernel32.GetProcessHeap() orelse return 0;

    const ptr = kernel32.HeapAlloc(heap, 0, @intCast(@as(usize, @intCast(size)))) orelse return 0;
    return @intCast(@intFromPtr(ptr));
}

pub export fn bplus_free(ptr: i64) void {
    const heap = kernel32.GetProcessHeap() orelse return;
    _ = kernel32.HeapFree(heap, 0, @ptrFromInt(@as(usize, @intCast(ptr))));
}

pub export fn bpc_read_line(buf_ptr: i64, buf_size: i64) i64 {

    const buf = @as([*]u8, @ptrFromInt(@as(usize, @intCast(buf_ptr))));
    const handle = kernel32.GetStdHandle(windows.STD_INPUT_HANDLE) orelse return 0;
    var count: windows.DWORD = 0;
    const max_read: u32 = @intCast(@min(@as(u64, @intCast(buf_size)), 256));
    if (kernel32.ReadFile(handle, buf, max_read, &count, null) == 0) return 0;
    if (count > 0 and buf[count - 1] == '\n') count -= 1;
    if (count > 0 and buf[count - 1] == '\r') count -= 1;
    buf[count] = 0;
    return @intCast(count);
}

pub export fn bpc_str_equal(a_ptr: i64, b_ptr: i64) i64 {
    const a = @as([*:0]const u8, @ptrFromInt(@as(usize, @intCast(a_ptr))));
    const b = @as([*:0]const u8, @ptrFromInt(@as(usize, @intCast(b_ptr))));
    var i: usize = 0;
    while (a[i] != 0 and b[i] != 0) : (i += 1) {
        if (a[i] != b[i]) return 0;
    }
    return if (a[i] == 0 and b[i] == 0) 1 else 0;
}

pub export fn print_str(ptr: i64) void {
    const s = @as([*:0]const u8, @ptrFromInt(@as(usize, @intCast(ptr))));
    var len: usize = 0;
    while (s[len] != 0) : (len += 1) {}
    const handle = kernel32.GetStdHandle(windows.STD_OUTPUT_HANDLE) orelse return;
    var written: windows.DWORD = 0;
    _ = kernel32.WriteFile(handle, s, @intCast(len), &written, null);
}

const std = @import("std");
const frame_graph = @import("../render/frame_graph.zig");
const gpu_execution = @import("../render/gpu_execution.zig");

/// Cost classification of a single GPU pass.
pub const CostClass = enum(u32) {
    lightweight,
    medium,
    heavy,
    critical,

};

/// Cost estimate breakdown for a single GPU pass.
pub const PassCost = struct {
    gpu_us: u32,
    bandwidth_mb: u32,
    wave_occupancy: f32,
    class: CostClass,

    /// Estimate pass cost from dispatch dimensions and intrinsic cost.

pub fn estimateFromGrid(grid: frame_graph.GPUPassDesc) PassCost {
    const total_groups = @as(u64, grid.grid.x) * grid.grid.y * grid.grid.z;
    const gpu_us: u32 = @intCast(@max(@as(u64, 1), total_groups * 2));
    const class: CostClass = if (total_groups >= 64 * 64)
        .heavy
    else if (total_groups >= 16 * 16)
        .medium
    else
        .lightweight;
    return .{

            .gpu_us = gpu_us,
            .bandwidth_mb = @intCast(total_groups * 4 / 1024),
            .wave_occupancy = 1.0,
            .class = class,
        };
    }
};

/// Whether a pass should execute or be skipped.
pub const SchedulingDecision = enum(u32) {

    execute,
    skip,
};

/// Result of scheduling: an ordered list of pass indices to execute.
pub const ScheduleResult = struct {
    order: []usize,
    total_cost_us: u32,
    total_skipped: u32,
    budget_us: u32,

};

/// Priority helper struct for sorting.
const PassPriority = struct {
    idx: usize,
    priority: u32,
    cost_us: u32,
    critical: bool,
    fsr3_pass: bool,
};

/// Schedule GPU passes by budget + frame mode.
///
/// Real mode:     full set, sorted by criticality, non-critical skipped when over budget.
/// Generated mode: FSR3 passes prioritized, render passes deprioritized.
/// Pass_through:  only critical passes execute.
pub fn scheduleGpuPasses(
    allocator: std.mem.Allocator,
    gpu_passes: []const frame_graph.GPUPassDesc,
    ctx: gpu_execution.ExecutionContext,

) !ScheduleResult {
    const n = gpu_passes.len;
    if (n == 0) {
        return .{
            .order = try allocator.alloc(usize, 0),
            .total_cost_us = 0,
            .total_skipped = 0,
            .budget_us = ctx.budget_us,
        };
    }

const budget_us = ctx.budget_us;
const mode = ctx.frame_mode;

// Phase 1: classify and compute priority
var priorities = try allocator.alloc(PassPriority, n);
defer allocator.free(priorities);

for (gpu_passes, 0..) |gp, i| {
    const cost = PassCost.estimateFromGrid(gp);

// FSR3 pass IDs: 100-103 (matches FSR3Pass enum in fsr3_runtime)
const is_fsr3 = gp.pass_id >= 100 and gp.pass_id <= 103;
const is_critical = switch (mode) {
    .real => cost.class == .critical,
    .generated => is_fsr3,
    .pass_through => false,
};

// Compute priority: lower = earlier execution
const priority: u32 = blk: {

switch (mode) {
    .real => {
        // Critical passes always first, then by cost (cheaper first)
        if (is_critical) break :blk 0;
        if (cost.class == .heavy) break :blk 40;
        if (cost.class == .medium) break :blk 30;
        break :blk 20;
    },
    .generated => {
        // FSR3 passes first (optical flow → disocclusion → gen → post)

    if (is_fsr3) {
        const base: u32 = @intCast(gp.pass_id - 100);
        break :blk base;
    }
    // Non-FSR3 render passes get deprioritized
    break :blk 60 + cost.gpu_us / 100;
},
.pass_through => {
    // All passes get max priority → skipped
    break :blk std.math.maxInt(u32);

        },
    }
};

priorities[i] = .{
    .idx = i,
    .priority = priority,
    .cost_us = cost.gpu_us,
    .critical = is_critical,
    .fsr3_pass = is_fsr3,

    };
}

// Phase 2: sort by priority (stable for equal priorities)
std.mem.sort(PassPriority, priorities, {}, struct {
    fn less(_: void, a: PassPriority, b: PassPriority) bool {
        if (a.priority != b.priority) return a.priority < b.priority;
        return a.idx < b.idx;
    }
}.less);

// Phase 3: single-pass accumulation — build ordered list in one pass
var order = std.ArrayList(usize).init(allocator);
var total_used: u32 = 0;
var skipped: u32 = 0;

for (priorities) |pp| {
    if (pp.priority == std.math.maxInt(u32)) {
        skipped += 1;
        continue;

    }
    const fits = pp.critical or (total_used + pp.cost_us <= budget_us);
    if (fits) {
        try order.append(pp.idx);
        if (!pp.critical) total_used += pp.cost_us;
    } else {
        skipped += 1;
    }
}

    return ScheduleResult{
        .order = try order.toOwnedSlice(),
        .total_cost_us = total_used,
        .total_skipped = skipped,
        .budget_us = budget_us,
    };
}

const std = @import("std");
const windows = std.os.windows;

const WINAPI = windows.WINAPI;
const BOOL = windows.BOOL;
const DWORD = windows.DWORD;
const LPVOID = windows.LPVOID;

extern "kernel32" fn GetSystemInfo(lpSystemInfo: *SYSTEM_INFO) callconv(WINAPI) void;
extern "kernel32" fn GetLogicalProcessorInformation(

    Buffer: ?*SYSTEM_LOGICAL_PROCESSOR_INFORMATION,
    ReturnedLength: *DWORD,
) callconv(WINAPI) BOOL;
extern "kernel32" fn GetLogicalProcessorInformationEx(
    RelationshipType: LOGICAL_PROCESSOR_RELATIONSHIP,
    Buffer: ?*anyopaque,
    ReturnedLength: *DWORD,
) callconv(WINAPI) BOOL;

const ERROR_INSUFFICIENT_BUFFER: windows.Win32Error = .INSUFFICIENT_BUFFER;

    RelationAll = 0xFFFF,
};

const SYSTEM_INFO = extern struct {
    wProcessorArchitecture: u16,
    wReserved: u16,
    dwPageSize: DWORD,
    lpMinimumApplicationAddress: LPVOID,
    lpMaximumApplicationAddress: LPVOID,
    dwActiveProcessorMask: ?*anyopaque,

    dwNumberOfProcessors: DWORD,
    dwProcessorType: DWORD,
    dwAllocationGranularity: DWORD,
    wProcessorLevel: u16,
    wProcessorRevision: u16,
};

const CACHE_DESCRIPTOR = extern struct {
    Level: u8,
    Associativity: u8,

    LineSize: u16,
    Size: DWORD,
    Type: enum(u32) {
        CacheUnified = 0,
        CacheInstruction = 1,
        CacheData = 2,
        CacheTrace = 3,
    },
};

const SYSTEM_LOGICAL_PROCESSOR_INFORMATION = extern struct {
    ProcessorMask: ?*anyopaque,
    Relationship: LOGICAL_PROCESSOR_RELATIONSHIP,
    Anonymous: extern union {
        ProcessorCore: extern struct {
            Flags: u8,
        },
        NumaNode: extern struct {
            NodeNumber: DWORD,
        },

        Cache: CACHE_DESCRIPTOR,
        Reserved: [2]u64,
    },
};

pub const CacheInfo = struct {
    level: u8,
    size_bytes: u64,
    line_size: u16,
    associativity: u8,

};

pub const NumaNode = struct {
    node_number: u32,
    processor_count: u32,
    processor_mask: usize,
};

pub const CpuClass = enum(u8) {
    tiny,

    pc,
    workstation,
    manycore,
};

pub const CpuTopology = struct {
    logical_cores: u32,
    physical_cores: u32,
    has_hyperthreading: bool,
    class: CpuClass,

numa_nodes: []const NumaNode,
caches: []const CacheInfo,
logical_to_physical: []u32,
allocator: std.mem.Allocator,

pub fn detect(allocator: std.mem.Allocator) !CpuTopology {
    var sys_info: SYSTEM_INFO = undefined;
    GetSystemInfo(&sys_info);
    const logical_cores = sys_info.dwNumberOfProcessors;

var nodes = std.ArrayList(NumaNode).init(allocator);
var caches = std.ArrayList(CacheInfo).init(allocator);
var phys_count: u32 = 0;
const logical_to_physical = try allocator.alloc(u32, logical_cores);
@memset(logical_to_physical, 0);

// Try GetLogicalProcessorInformationEx first (richer data)
const ex_used = try detectEx(allocator, logical_cores, &nodes, &caches, &phys_count, logical_to_physical);

if (!ex_used) {

    // Fallback to the older API
    _ = try detectLegacy(allocator, &nodes, &caches, &phys_count, logical_to_physical);
}
if (phys_count == 0) phys_count = logical_cores;

// Fill missing NUMA: single node if none detected
if (nodes.items.len == 0) {
    try nodes.append(.{
        .node_number = 0,
        .processor_count = logical_cores,

        .processor_mask = 0,
    });
}

// Deduplicate caches (the Ex API returns one entry per cache per core)
{
    var deduped = std.ArrayList(CacheInfo).init(allocator);
    for (caches.items) |c| {
        var found = false;
        for (deduped.items) |d| {

            if (d.level == c.level and d.size_bytes == c.size_bytes and d.line_size == c.line_size and d.associativity == c.associativity) {
                found = true;
                break;
            }
        }
        if (!found) try deduped.append(c);
    }
    caches.deinit();
    caches = deduped;
}

// Determine CPU class
const class = classify(logical_cores, phys_count);

return CpuTopology{
    .logical_cores = logical_cores,
    .physical_cores = phys_count,
    .has_hyperthreading = logical_cores > phys_count,
    .class = class,
    .numa_nodes = try nodes.toOwnedSlice(),

        .caches = try caches.toOwnedSlice(),
        .logical_to_physical = logical_to_physical,
        .allocator = allocator,
    };
}

pub fn deinit(topo: *const CpuTopology) void {
    topo.allocator.free(topo.numa_nodes);
    topo.allocator.free(topo.caches);
    topo.allocator.free(topo.logical_to_physical);

    }
};

fn detectEx(
    allocator: std.mem.Allocator,
    logical_cores: u32,
    nodes: *std.ArrayList(NumaNode),
    caches: *std.ArrayList(CacheInfo),
    phys_count: *u32,
    logical_to_physical: []u32,

) !bool {
    _ = logical_cores;
    // Try to call GetLogicalProcessorInformationEx
    var buf_size: DWORD = 0;
    const rs = GetLogicalProcessorInformationEx(.RelationAll, null, &buf_size);
    if (rs == 0 and buf_size == 0) return false;
    if (windows.kernel32.GetLastError() != ERROR_INSUFFICIENT_BUFFER) return false;

    const buf = try allocator.alloc(u8, buf_size);
    defer allocator.free(buf);

if (GetLogicalProcessorInformationEx(.RelationAll, @ptrCast(buf.ptr), &buf_size) == 0) return false;

// Parse the buffer
var offset: usize = 0;
while (offset < buf_size) {
    const header = @as(*align(1) const SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX, @ptrCast(buf.ptr + offset));
    switch (header.Relationship) {
        .RelationProcessorCore => {
            // Count physical cores

const core = @as(*align(1) const PROCESSOR_RELATIONSHIP, @ptrCast(&header.Anonymous));
phys_count.* += 1;
// Map logical cores to this physical core
var group: u32 = 0;
while (group < core.GroupCount) : (group += 1) {
    const ga = &core.GroupMasks[@intCast(group)];
    var bit: u32 = 0;
    while (bit < 64) : (bit += 1) {
        if ((ga.Mask >> @as(u6, @intCast(bit))) & 1 != 0) {
            // Find which logical core this corresponds to

                const logical_idx = group * 64 + bit;
                if (logical_idx < logical_to_physical.len and phys_count.* > 0) {
                    logical_to_physical[logical_idx] = phys_count.* - 1;
                }
            }
        }
    }
},
.RelationCache => {
    const cache = @as(*align(1) const CACHE_RELATIONSHIP, @ptrCast(&header.Anonymous));

    try caches.append(.{
        .level = cache.Level,
        .size_bytes = cache.CacheSize,
        .line_size = @intCast(cache.LineSize),
        .associativity = cache.Associativity,
    });
},
.RelationNumaNode => {
    const numa = @as(*align(1) const NUMA_NODE_RELATIONSHIP, @ptrCast(&header.Anonymous));
    // Count processors in this NUMA node

var proc_count: u32 = 0;
var group: u32 = 0;
while (group < numa.GroupCount) : (group += 1) {
    const ga = &numa.GroupMasks[@intCast(group)];
    var bit: u32 = 0;
    while (bit < 64) : (bit += 1) {
        if ((ga.Mask >> @as(u6, @intCast(bit))) & 1 != 0) proc_count += 1;
    }
}
try nodes.append(.{

                .node_number = numa.NodeNumber,
                .processor_count = proc_count,
                .processor_mask = 0,
            });
        },
        else => {},
    }
    if (header.Size == 0) break;
    offset += header.Size;
}

    return true;
}

fn detectLegacy(
    allocator: std.mem.Allocator,
    nodes: *std.ArrayList(NumaNode),
    caches: *std.ArrayList(CacheInfo),
    phys_count: *u32,
    logical_to_physical: []u32,

) !bool {
    var buf_size: DWORD = 0;
    if (GetLogicalProcessorInformation(null, &buf_size) == 0) {
        if (windows.kernel32.GetLastError() != ERROR_INSUFFICIENT_BUFFER) return false;
    }

    const buf = try allocator.alloc(u8, buf_size);
    defer allocator.free(buf);

    if (GetLogicalProcessorInformation(@ptrCast(@alignCast(buf.ptr)), &buf_size) == 0) return false;

const entries = @as([*]SYSTEM_LOGICAL_PROCESSOR_INFORMATION, @ptrCast(@alignCast(buf.ptr)));
const count = buf_size / @sizeOf(SYSTEM_LOGICAL_PROCESSOR_INFORMATION);

var i: usize = 0;
while (i < count) : (i += 1) {
    const entry = &entries[i];
    switch (entry.Relationship) {
        .RelationProcessorCore => {
            const idx = phys_count.*;

phys_count.* += 1;
// Map logical bits to physical core index
const mask = @intFromPtr(entry.ProcessorMask);
var bit: u32 = 0;
while (bit < 64) : (bit += 1) {
    if ((mask >> @as(u6, @intCast(bit))) & 1 != 0) {
        if (bit < logical_to_physical.len) {
            logical_to_physical[bit] = idx;
        }
    }

    }
},
.RelationCache => {
    const cache = &entry.Anonymous.Cache;
    try caches.append(.{
        .level = cache.Level,
        .size_bytes = cache.Size,
        .line_size = cache.LineSize,
        .associativity = cache.Associativity,
    });

    },
    .RelationNumaNode => {
        try nodes.append(.{
            .node_number = entry.Anonymous.NumaNode.NodeNumber,
            .processor_count = 0,
            .processor_mask = @intFromPtr(entry.ProcessorMask),
        });
    },
    else => {},
}

    }

    return true;
}

fn classify(logical: u32, physical: u32) CpuClass {
    _ = logical;
    if (physical <= 2) return .tiny;
    if (physical <= 16) return .pc;
    if (physical <= 24) return .workstation;

    return .manycore;
}

test "CPU topology detection" {
    const topo = try CpuTopology.detect(std.testing.allocator);
    defer topo.deinit();

    try std.testing.expect(topo.logical_cores > 0);
    try std.testing.expect(topo.physical_cores > 0);
    try std.testing.expect(topo.physical_cores <= topo.logical_cores);

try std.testing.expect(topo.numa_nodes.len > 0);

std.debug.print("\n  logical={d} physical={d} ht={} class={s} numa={d}", .{
    topo.logical_cores, topo.physical_cores, topo.has_hyperthreading,
    @tagName(topo.class), topo.numa_nodes.len,
});
std.debug.print("\n  caches:", .{});
for (topo.caches) |c| {
    std.debug.print(" L{d}={}KB", .{ c.level, c.size_bytes / 1024 });
}

    std.debug.print("\n", .{});
}

