};

pub const GPUBatch = struct {
    pass_indices: []const u32,
    resolved_passes: []ResolvedPass = &.{},
    queue: gpu_types.QueueType,
    barriers: []const render_graph.BarrierSlot,
};

pub const QueueBatches = struct {
    batches: []GPUBatch,
};

pub const ScheduleStats = struct {
    total_passes: u32,
