const std = @import("std");
const latency = @import("latency.zig");

pub const DecisionOverride = enum(u8) {
    none = 0,
    force_steal = 1,
    force_migrate = 2,
    prefer_affinity = 3,
    balanced = 4,
};

pub const GlobalSchedulerState = struct {
    last_system_load: latency.SystemLoad = latency.SystemLoad{
        .avg_queue = 0,
        .max_queue = 0,
        .min_queue = 0,
        .imbalance_ratio = 0,
    },
    tick_counter: u64 = 0,

pub fn computeAndStore(state: *GlobalSchedulerState, cores: []latency.CoreStats) void {
    state.last_system_load = latency.computeSystemLoad(cores);
    state.tick_counter += 1;
}

pub fn adjustDecision(
    state: *const GlobalSchedulerState,
    ctx: anytype,
    d: DecisionOverride,
) DecisionOverride {

_ = ctx;
const load = state.last_system_load;

if (load.imbalance_ratio > 3.0) {
    return .force_steal;
}

if (load.imbalance_ratio > 2.0) {
    if (d == .prefer_affinity) {
        return .balanced;

            }
        }

        return d;
    }
};

const std = @import("std");

pub const StateId = u32;
pub const EventId = u32;

pub const Transition = struct {
    from: StateId,
    event: EventId,
    to: StateId,
    guard: ?*const fn () bool = null,

};

pub const StateMachine = struct {
    current_state: StateId,
    transitions: []const Transition,
    entry_fns: []const ?*const fn () void,
    exit_fns: []const ?*const fn () void,
    state_count: u32,

    pub fn init(config: Config) StateMachine {

    return .{
        .current_state = config.initial_state,
        .transitions = config.transitions,
        .entry_fns = config.entry_fns,
        .exit_fns = config.exit_fns,
        .state_count = config.state_count,
    };
}

pub fn fire(self: *StateMachine, event: EventId) void {

for (self.transitions) |*t| {
    if (t.from != self.current_state) continue;
    if (t.event != event) continue;
    if (t.guard) |g| {
        if (!g()) continue;
    }
    self.exitState(t.from);
    self.current_state = t.to;
    self.entryState(t.to);
    return;

    }
}

fn entryState(self: *StateMachine, state: StateId) void {
    if (state < self.entry_fns.len) {
        if (self.entry_fns[state]) |f| f();
    }
}

fn exitState(self: *StateMachine, state: StateId) void {

    if (state < self.exit_fns.len) {
        if (self.exit_fns[state]) |f| f();
    }
}

pub const Config = struct {
    initial_state: StateId = 0,
    transitions: []const Transition = &.{},
    entry_fns: []const ?*const fn () void = &.{},
    exit_fns: []const ?*const fn () void = &.{},

        state_count: u32 = 0,
    };
};

var global_machine: ?StateMachine = null;

pub fn initGlobalMachine(config: StateMachine.Config) void {
    global_machine = StateMachine.init(config);
}

pub fn bpc_fire(event_id: u32) void {
    if (global_machine) |*m| {
        m.fire(event_id);
    }
}

