            return Expect{ .float_val = @as(f32, @floatCast(val)) };
        }
        return error.UnknownExpectType;
    }
    return error.UnknownExpectKeyword;
}

// --- v2: Frame expect parser ---

fn parseFrameExpect(src: []const u8, pos: *usize) !ExpectEntry {
    const kw = parseIdentifier(src, pos);
    if (std.mem.eql(u8, kw, "state")) {
        if (!expectChar(src, pos, '.')) return error.ExpectedDotAfterState;
        const field_name = parseIdentifier(src, pos);
        if (!expectChar(src, pos, '=')) return error.ExpectedEqInStateExpect;
        if (expectChar(src, pos, '=')) {} // allow ==
        // Determine if value is int or float by looking ahead for '.'
        const val_pos = pos.*;
        skipSpaces(src, pos);

var is_float = false;
const scan = pos.*;
var si = scan;
if (si < src.len and src[si] == '-') si += 1;
while (si < src.len and std.ascii.isDigit(src[si])) si += 1;
if (si < src.len and src[si] == '.') is_float = true;
pos.* = val_pos;
if (is_float) {
    const val = try parseFloatValue(src, pos);
    return ExpectEntry{ .state_float = .{ .name = field_name, .value = val } };

    } else {
        const val = try parseIntValue(src, pos);
        return ExpectEntry{ .state_int = .{ .name = field_name, .value = val } };
    }
} else if (std.mem.eql(u8, kw, "image")) {
    if (!expectChar(src, pos, '[')) return error.ExpectedOpenBracketAfterImage;
    const img_name = try parseQuotedString(src, pos);
    if (!expectChar(src, pos, ']')) return error.ExpectedCloseBracket;
    if (!expectChar(src, pos, '[')) return error.ExpectedOpenBracket;
    const x_str = parseIdentifier(src, pos);

if (!expectChar(src, pos, ',')) return error.ExpectedComma;
const y_str = parseIdentifier(src, pos);
if (!expectChar(src, pos, ']')) return error.ExpectedCloseBracket;
const x = try std.fmt.parseInt(u32, x_str, 10);
const y = try std.fmt.parseInt(u32, y_str, 10);
// Check for == or тЙИ
skipSpaces(src, pos);
if (pos.* < src.len and src[pos.*] == '=') {
    pos.* += 1;
    if (pos.* < src.len and src[pos.*] == '=') pos.* += 1;

    const val = @as(f32, @floatCast(try parseFloatValue(src, pos)));
    return ExpectEntry{ .image_pixel = .{ .name = img_name, .x = x, .y = y, .value = val } };
} else if (pos.* < src.len and src[pos.*] == 0x2248) { // тЙИ
    pos.* += 1;
    const val = @as(f32, @floatCast(try parseFloatValue(src, pos)));
    const eps: f32 = 0.0001;
    return ExpectEntry{ .image_approx = .{ .name = img_name, .x = x, .y = y, .value = val, .eps = eps } };
} else {
    return error.ExpectedEqOrApprox;
}

    } else {
        return error.UnknownFrameExpectKeyword;
    }
}

fn parseU32Value(src: []const u8, pos: *usize) !u32 {
    skipSpaces(src, pos);
    const start = pos.*;
    while (pos.* < src.len and std.ascii.isDigit(src[pos.*])) pos.* += 1;
    if (pos.* == start) return error.ExpectedInt;

    return try std.fmt.parseInt(u32, src[start..pos.*], 10);
}

fn parseFrameDecl(src: []const u8, pos: *usize) !u32 {
    const kw = parseIdentifier(src, pos);
    if (!std.mem.eql(u8, kw, "frame")) return error.ExpectedFrameKeyword;
    const idx = try parseU32Value(src, pos);
    if (!expectChar(src, pos, ':')) return error.ExpectedColonAfterFrame;
    return idx;
}

// --- Main parser ---

pub fn parseTestDesc(allocator: std.mem.Allocator, text: []const u8) !TestDesc {
    var lines = std.mem.splitScalar(u8, text, '\n');
    var test_name: ?[]const u8 = null;
    var source: ?[]const u8 = null;
    var build_type_str: ?[]const u8 = null;
    var reset_str: ?[]const u8 = null;
    var export_list: ?[][]const u8 = null;

var cases = std.ArrayList(CaseDesc).init(allocator);
var frames = std.ArrayList(FrameDesc).init(allocator);
var parse_frames = false;

var case_name: ?[]const u8 = null;
var case_calls = std.ArrayList([]const u8).init(allocator);
var case_expect: ?Expect = null;

var frame_idx: ?u32 = null;
var frame_calls = std.ArrayList([]const u8).init(allocator);

var frame_expects = std.ArrayList(ExpectEntry).init(allocator);

while (lines.next()) |raw_line| {
    const line = std.mem.trimRight(u8, raw_line, " \t\r");
    if (line.len == 0 or line[0] == '#') continue;
    const indent = countIndent(line);
    const content = std.mem.trimLeft(u8, line, " \t");

    if (indent == 0) {
        // Flush pending case/frame

if (case_name) |cn| {
    try cases.append(CaseDesc{
        .name = cn,
        .calls = try case_calls.toOwnedSlice(),
        .expect = case_expect orelse Expect{ .null_val = {} },
    });
    case_calls = std.ArrayList([]const u8).init(allocator);
}
case_name = null;
case_expect = null;

if (frame_idx) |fi| {
    try frames.append(FrameDesc{
        .index = fi,
        .calls = try frame_calls.toOwnedSlice(),
        .expects = try frame_expects.toOwnedSlice(),
    });
    frame_calls = std.ArrayList([]const u8).init(allocator);
    frame_expects = std.ArrayList(ExpectEntry).init(allocator);
}
frame_idx = null;

    var pos: usize = 0;
    const kw = parseIdentifier(content, &pos);
    if (!std.mem.eql(u8, kw, "test")) return error.ExpectedTestKeyword;
    test_name = try parseQuotedString(content, &pos);
    if (!expectChar(content, &pos, ':')) return error.ExpectedColonAfterTest;
} else if (indent == 4) {
    // Check for frame keyword
    var pos: usize = 0;
    const kw = parseIdentifier(content, &pos);

if (std.mem.eql(u8, kw, "frame")) {
    parse_frames = true;
    // Flush pending case
    if (case_name) |cn| {
        try cases.append(CaseDesc{
            .name = cn,
            .calls = try case_calls.toOwnedSlice(),
            .expect = case_expect orelse Expect{ .null_val = {} },
        });
        case_calls = std.ArrayList([]const u8).init(allocator);

}
case_name = null;
case_expect = null;
// Flush pending frame
if (frame_idx) |fi| {
    try frames.append(FrameDesc{
        .index = fi,
        .calls = try frame_calls.toOwnedSlice(),
        .expects = try frame_expects.toOwnedSlice(),
    });

        frame_calls = std.ArrayList([]const u8).init(allocator);
        frame_expects = std.ArrayList(ExpectEntry).init(allocator);
    }
    frame_idx = null;

    pos = 0;
    frame_idx = try parseFrameDecl(content, &pos);
} else if (std.mem.eql(u8, kw, "source")) {
    source = try parseQuotedString(content, &pos);
} else if (std.mem.eql(u8, kw, "build")) {

    build_type_str = parseIdentifier(content, &pos);
} else if (std.mem.eql(u8, kw, "reset")) {
    reset_str = parseIdentifier(content, &pos);
} else if (std.mem.eql(u8, kw, "exports")) {
    export_list = try parseCommaList(allocator, content, &pos);
} else if (std.mem.eql(u8, kw, "case")) {
    if (case_name) |cn| {
        try cases.append(CaseDesc{
            .name = cn,
            .calls = try case_calls.toOwnedSlice(),

            .expect = case_expect orelse Expect{ .null_val = {} },
        });
        case_calls = std.ArrayList([]const u8).init(allocator);
    }
    case_name = null;
    case_expect = null;

    case_name = try parseQuotedString(content, &pos);
    if (!expectChar(content, &pos, ':')) return error.ExpectedColonAfterCase;
} else {

        return error.UnknownTestKeyword;
    }
} else if (indent == 8) {
    var pos: usize = 0;
    const kw = parseIdentifier(content, &pos);
    if (std.mem.eql(u8, kw, "call")) {
        const name = parseIdentifier(content, &pos);
        if (name.len > 0) {
            if (frame_idx != null) {
                try frame_calls.append(name);

        } else {
            try case_calls.append(name);
        }
    }
} else if (std.mem.eql(u8, kw, "expect")) {
    if (frame_idx != null) {
        const ee = try parseFrameExpect(content, &pos);
        try frame_expects.append(ee);
    } else {
        case_expect = try parseExpect(content, &pos);

            }
        }
    } else {
        return error.UnexpectedIndent;
    }
}

// Flush final case/frame
if (case_name) |cn| {
    try cases.append(CaseDesc{

        .name = cn,
        .calls = try case_calls.toOwnedSlice(),
        .expect = case_expect orelse Expect{ .null_val = {} },
    });
} else {
    case_calls.deinit();
}
if (frame_idx) |fi| {
    try frames.append(FrameDesc{
        .index = fi,

        .calls = try frame_calls.toOwnedSlice(),
        .expects = try frame_expects.toOwnedSlice(),
    });
} else {
    frame_calls.deinit();
    frame_expects.deinit();
}

const bt: BuildType = if (build_type_str) |b| blk: {
    if (std.mem.eql(u8, b, "dll")) break :blk .dll;

    return error.UnsupportedBuildType;
} else .dll;
const rm: ResetMode = if (std.mem.eql(u8, reset_str orelse "per_case", "per_case")) .per_case else .per_test;

return TestDesc{
    .name = test_name orelse return error.MissingTestName,
    .source = source orelse return error.MissingSource,
    .build_type = bt,
    .reset_mode = rm,
    .exports = export_list orelse return error.MissingExports,

        .cases = try cases.toOwnedSlice(),
        .frames = try frames.toOwnedSlice(),
    };
}

// --- Compilation ---

fn compileDll(allocator: std.mem.Allocator, source_path: []const u8, dll_path: []const u8) !void {
    return compileDllEx(allocator, source_path, dll_path, .off);
}

fn compileDllEx(allocator: std.mem.Allocator, source_path: []const u8, dll_path: []const u8, trace_mode: x64gen.TraceMode) !void {
    var src = try std.fs.cwd().readFileAlloc(allocator, source_path, std.math.maxInt(u32));
    defer allocator.free(src);

    if (std.mem.startsWith(u8, src, "\xEF\xBB\xBF")) {
        const stripped = try allocator.dupe(u8, src[3..]);
        allocator.free(src);
        src = stripped;
    }

var p = parser.Parser.init(allocator, src, "test.bpt");
var program = try p.parse();
defer program.deinit();

var output = try x64gen.generateEx(allocator, program, true, trace_mode);
defer allocator.free(output.code);
defer output.symbols.deinit();

var resolved = std.ArrayList(pe.ResolvedExport).init(allocator);

defer resolved.deinit();
for (output.symbols.symbols.items) |s| {
    if (s.kind == .exp) {
        try resolved.append(.{
            .name = s.name,
            .rva = if (s.forward_to == null) pe.section_rva + s.rva else 0,
            .forward_to = s.forward_to,
        });
    }
}

    const pe_bytes = try pe.writeDll(allocator, output.code, output.import_dir_rva, output.idat_size, resolved.items);
    defer allocator.free(pe_bytes);

    try std.fs.cwd().writeFile(.{ .sub_path = dll_path, .data = pe_bytes });
}

// --- v1: per-case return expectation helpers ---

fn formatExpect(e: Expect, allocator: std.mem.Allocator) ![]const u8 {

    return switch (e) {
        .null_val => try allocator.dupe(u8, "null"),
        .int_val => |v| try std.fmt.allocPrint(allocator, "{}", .{v}),
        .float_val => |v| try std.fmt.allocPrint(allocator, "{d}", .{v}),
    };
}

fn formatActual(val: i64, expect: Expect, allocator: std.mem.Allocator) ![]const u8 {
    return switch (expect) {
        .null_val => try allocator.dupe(u8, "<non-null>"),

        .int_val => try std.fmt.allocPrint(allocator, "{}", .{val}),
        .float_val => blk: {
            const f = @as(f32, @bitCast(@as(u32, @truncate(@as(u64, @intCast(val))))));
            break :blk try std.fmt.allocPrint(allocator, "{d}", .{f});
        },
    };
}

fn matchesExpect(val: i64, expect: Expect) bool {
    return switch (expect) {

        .null_val => false,
        .int_val => |ev| val == ev,
        .float_val => |ev| blk: {
            const f = @as(f32, @bitCast(@as(u32, @truncate(@as(u64, @intCast(val))))));
            break :blk f == ev;
        },
    };
}

// --- v2: Snapshot capture ---

const FIELD_RECORD_SIZE = 48;

fn readFieldTable(base: [*]u8, allocator: std.mem.Allocator) ![]FieldEntry {
    var list = std.ArrayList(FieldEntry).init(allocator);
    var i: usize = 0;
    while (true) {
        const off = i * FIELD_RECORD_SIZE;
        const name_ptr: [*]u8 = base + off;
        var name_len: usize = 0;

while (name_len < 32 and name_ptr[name_len] != 0) name_len += 1;
if (name_len == 0) break;
const name = try allocator.dupe(u8, name_ptr[0..name_len]);
const type_tag = @as(*align(1) u32, @ptrCast(base + off + 32)).*;
const layout_off = @as(*align(1) u64, @ptrCast(base + off + 40)).*;
try list.append(FieldEntry{
    .name = name,
    .type = @as(FieldType, @enumFromInt(type_tag)),
    .offset = @as(u32, @intCast(layout_off)),
});

        i += 1;
    }
    return list.toOwnedSlice();
}

fn captureState(state_base: [*]u8, fields: []const FieldEntry, allocator: std.mem.Allocator) !Snapshot {
    var map = std.StringHashMap(SnapshotValue).init(allocator);
    const sv = StateView{ .base = state_base };
    for (fields) |f| {
        const val: SnapshotValue = switch (f.type) {

.INT => .{ .int = sv.getInt(f.offset) },
.FLOAT => .{ .float = sv.getFloat(f.offset) },
.IMAGE_F32 => blk: {
    const ptr = sv.getPtr(f.offset);
    if (ptr == 0) {
        break :blk .{ .image = ImageView{ .data = undefined, .stride = 0, .width = 0, .height = 0 } };
    }
    const hdr = @as(*align(1) ImageHeader, @ptrCast(@as(*anyopaque, @ptrFromInt(ptr))));
    const data: [*]f32 = @ptrCast(@as([*]align(4) u8, @ptrFromInt(ptr + 16)));
    break :blk .{ .image = ImageView{ .data = data, .stride = hdr.stride, .width = hdr.width, .height = hdr.height } };

            },
        };
        // Dup name so HashMap owns keys independently from fields[] lifetime
        const key = try allocator.dupe(u8, f.name);
        try map.put(key, val);
    }
    return Snapshot{ .fields = map };
}

fn formatSnapshotValue(val: SnapshotValue, allocator: std.mem.Allocator) ![]const u8 {

    return switch (val) {
        .int => |v| try std.fmt.allocPrint(allocator, "{}", .{v}),
        .float => |v| try std.fmt.allocPrint(allocator, "{d:.6}", .{v}),
        .image => |v| try std.fmt.allocPrint(allocator, "image<{}x{} stride={}>", .{ v.width, v.height, v.stride }),
    };
}

fn getSnapshotValue(snap: *const Snapshot, name: []const u8) ?SnapshotValue {
    return snap.fields.get(name);
}

// --- v2: Diff engine ---

fn diffExpect(expect: ExpectEntry, snap: *const Snapshot, allocator: std.mem.Allocator) !ExpectResult {
    const desc = switch (expect) {
        .state_int => |e| try std.fmt.allocPrint(allocator, "state.{s} == {}", .{ e.name, e.value }),
        .state_float => |e| try std.fmt.allocPrint(allocator, "state.{s} тЙИ {d:.6}", .{ e.name, e.value }),
        .image_pixel => |e| try std.fmt.allocPrint(allocator, "image[\"{s}\"][{},{}] == {d}", .{ e.name, e.x, e.y, e.value }),
        .image_approx => |e| try std.fmt.allocPrint(allocator, "image[\"{s}\"][{},{}] тЙИ {d}", .{ e.name, e.x, e.y, e.value }),
    };

const matched: bool = switch (expect) {
    .state_int => |e| blk: {
        const actual = getSnapshotValue(snap, e.name);
        break :blk if (actual) |v| switch (v) {
            .int => |iv| iv == e.value,
            else => false,
        } else false;
    },
    .state_float => |e| blk: {

    const actual = getSnapshotValue(snap, e.name);
    break :blk if (actual) |v| switch (v) {
        .float => |fv| @abs(fv - e.value) < 0.000001,
        else => false,
    } else false;
},
.image_pixel => |e| blk: {
    const actual = getSnapshotValue(snap, e.name);
    break :blk if (actual) |v| switch (v) {
        .image => |img| img.get(e.x, e.y) == e.value,

        else => false,
    } else false;
},
.image_approx => |e| blk: {
    const actual = getSnapshotValue(snap, e.name);
    break :blk if (actual) |v| switch (v) {
        .image => |img| @abs(img.get(e.x, e.y) - e.value) <= e.eps,
        else => false,
    } else false;
},

};

const expected_str = switch (expect) {
    .state_int => |e| try std.fmt.allocPrint(allocator, "== {}", .{e.value}),
    .state_float => |e| try std.fmt.allocPrint(allocator, "тЙИ {d:.6}", .{e.value}),
    .image_pixel => |e| try std.fmt.allocPrint(allocator, "== {d}", .{e.value}),
    .image_approx => |e| try std.fmt.allocPrint(allocator, "тЙИ {d}", .{e.value}),
};

const actual_str = if (!matched) blk: {

const name = switch (expect) {
    .state_int => |e| e.name,
    .state_float => |e| e.name,
    .image_pixel => |e| e.name,
    .image_approx => |e| e.name,
};
const actual = getSnapshotValue(snap, name);
if (actual) |v| {
    switch (v) {
        .int => |iv| break :blk try std.fmt.allocPrint(allocator, "{}", .{iv}),

        .float => |fv| break :blk try std.fmt.allocPrint(allocator, "{d:.6}", .{fv}),
        .image => |img| {
            switch (expect) {
                .image_pixel => |e| break :blk try std.fmt.allocPrint(allocator, "{d}", .{img.get(e.x, e.y)}),
                .image_approx => |e| break :blk try std.fmt.allocPrint(allocator, "{d}", .{img.get(e.x, e.y)}),
                else => break :blk try std.fmt.allocPrint(allocator, "image<{}x{} stride={}>", .{ img.width, img.height, img.stride }),
            }
        },
    }
} else break :blk try allocator.dupe(u8, "<missing>");

    } else try allocator.dupe(u8, "<ok>");

    return ExpectResult{
        .desc = desc,
        .status = if (matched) .pass else .fail,
        .expected = expected_str,
        .actual = actual_str,
    };
}

// --- v2: State diff engine ---

const StateDiff = struct {
    field: []const u8,
    before: SnapshotValue,
    after: SnapshotValue,
};

fn snapshotValueEql(a: SnapshotValue, b: SnapshotValue) bool {
    return switch (a) {

        .int => |av| switch (b) { .int => |bv| av == bv, else => false },
        .float => |av| switch (b) { .float => |bv| @abs(av - bv) < 0.000001, else => false },
        .image => |av| switch (b) { .image => |bv| @intFromPtr(av.data) == @intFromPtr(bv.data), else => false },
    };
}

fn diffSnapshots(before: *const Snapshot, after: *const Snapshot, allocator: std.mem.Allocator) ![]StateDiff {
    var list = std.ArrayList(StateDiff).init(allocator);
    // Fields in after that differ from before
    var it = after.fields.iterator();

while (it.next()) |entry| {
    const name = entry.key_ptr.*;
    const after_val = entry.value_ptr.*;
    const before_val = before.fields.get(name);
    if (before_val) |bv| {
        if (!snapshotValueEql(bv, after_val)) {
            try list.append(StateDiff{ .field = name, .before = bv, .after = after_val });
        }
    } else {
        // New field

        try list.append(StateDiff{ .field = name, .before = .{ .int = 0 }, .after = after_val });
    }
}
// Fields in before that disappeared from after
var it2 = before.fields.iterator();
while (it2.next()) |entry| {
    const name = entry.key_ptr.*;
    if (after.fields.get(name) == null) {
        try list.append(StateDiff{ .field = name, .before = entry.value_ptr.*, .after = .{ .int = 0 } });
    }

    }
    return list.toOwnedSlice();
}

fn formatDiffValue(val: SnapshotValue, allocator: std.mem.Allocator) ![]const u8 {
    return switch (val) {
        .int => |v| try std.fmt.allocPrint(allocator, "{}", .{v}),
        .float => |v| try std.fmt.allocPrint(allocator, "{d:.6}", .{v}),
        .image => |v| if (@intFromPtr(v.data) == 0) try allocator.dupe(u8, "<null>")
        else try std.fmt.allocPrint(allocator, "image<{}x{} stride={}>", .{ v.width, v.height, v.stride }),

    };
}

// --- v2: Timeline / Call Transition Model ---

const CallSnapshot = struct {
    frame_index: u32,
    call_index: u32,
    export_name: []const u8,
    after: Snapshot,

    diffs: []StateDiff,
};

fn freeCallSnapshot(cs: *CallSnapshot, allocator: std.mem.Allocator) void {
    // Free diffs array (field strings owned by snapshot, not freed here)
    allocator.free(cs.diffs);
    // Free snapshot keys and HashMap
    var it = cs.after.fields.iterator();
    while (it.next()) |entry| allocator.free(entry.key_ptr.*);
    cs.after.fields.deinit();

}

const CausalEdge = struct {
    frame_index: u32,
    export_name: []const u8,
    field: []const u8,
    before: SnapshotValue,
    after: SnapshotValue,
};

fn printFrameDiffs(diffs: []const StateDiff, writer: anytype, allocator: std.mem.Allocator) !void {
    for (diffs) |d| {
        const before_str = try formatDiffValue(d.before, allocator);
        defer allocator.free(before_str);
        const after_str = try formatDiffValue(d.after, allocator);
        defer allocator.free(after_str);
        try writer.print("    {s}: {s} тЖТ {s}\n", .{ d.field, before_str, after_str });
    }
}

fn printCausalGraph(edges: []const CausalEdge, writer: anytype, allocator: std.mem.Allocator) !void {
    try writer.print("\nCAUSAL GRAPH:\n", .{});
    var i: usize = 0;
    while (i < edges.len) {
        const exp = edges[i].export_name;
        try writer.print("  {s}\n", .{exp});
        while (i < edges.len and std.mem.eql(u8, edges[i].export_name, exp)) {
            const e = edges[i];
            const before_str = try formatDiffValue(e.before, allocator);
            defer allocator.free(before_str);

        const after_str = try formatDiffValue(e.after, allocator);
        defer allocator.free(after_str);
        if (e.frame_index > 0) {
            try writer.print("    {s}: {s} тЖТ {s}  (frame {})\n", .{ e.field, before_str, after_str, e.frame_index });
        } else {
            try writer.print("    {s}: {s} тЖТ {s}\n", .{ e.field, before_str, after_str });
        }
        i += 1;
    }
}

}

fn runFrames(allocator: std.mem.Allocator, lib: *DynLib, frames: []const FrameDesc, writer: anytype) ![]FrameResult {
    var frame_results = std.ArrayList(FrameResult).init(allocator);
    var call_snapshots = std.ArrayList(CallSnapshot).init(allocator);
    var causal_edges = std.ArrayList(CausalEdge).init(allocator);

    // Look up introspection exports
    const get_state_fn = (try lib.lookup("bpc_get_state")) orelse return error.MissingBpcGetState;
    const enum_fields_fn = (try lib.lookup("bpc_enum_fields")) orelse return error.MissingBpcEnumFields;

// Read field table once (it's constant after DLL load)
const table_ptr_raw = enum_fields_fn();
const table_ptr: [*]u8 = @ptrFromInt(@as(usize, @intCast(table_ptr_raw)));
const fields = try readFieldTable(table_ptr, allocator);
defer {
    for (fields) |f| allocator.free(f.name);
    allocator.free(fields);
}

// Capture initial state before any frames
const initial_ptr_raw = get_state_fn();
const initial_base: [*]u8 = @ptrFromInt(@as(usize, @intCast(initial_ptr_raw)));
var prev_snap = try captureState(initial_base, fields, allocator);
var own_prev = true; // we own prev_snap (it's the initial snapshot)

for (frames) |frame| {
    try writer.print("  FRAME {}:\n", .{frame.index});

    var call_err = false;

var expect_results = std.ArrayList(ExpectResult).init(allocator);
var frame_ok = true;

for (frame.calls, 0..) |call_name, call_i| {
    const func = (try lib.lookup(call_name)) orelse {
        try writer.print("    CALL {s}: ERROR (not found)\n", .{call_name});
        call_err = true;
        break;
    };

_ = func();

// Capture state after this call
const state_ptr_raw = get_state_fn();
const state_base: [*]u8 = @ptrFromInt(@as(usize, @intCast(state_ptr_raw)));
var after_call = try captureState(state_base, fields, allocator);

// Diffs attributed to THIS export
const diffs = try diffSnapshots(&prev_snap, &after_call, allocator);

// Store as atomic CallSnapshot
try call_snapshots.append(CallSnapshot{
    .frame_index = frame.index,
    .call_index = @as(u32, @intCast(call_i)),
    .export_name = call_name,
    .after = after_call,
    .diffs = diffs,
});

// Print per-call timeline with its diffs

try writer.print("    CALL {s}\n", .{call_name});
if (diffs.len > 0) {
    try printFrameDiffs(diffs, writer, allocator);
}

// Advance: free prev_snap only if we own it (initial or orphaned)
if (own_prev) {
    var it = prev_snap.fields.iterator();
    while (it.next()) |entry| allocator.free(entry.key_ptr.*);
    prev_snap.fields.deinit();

    }
    prev_snap = after_call; // now owned by call_snapshots (last entry)
    own_prev = false;
}

if (call_err) {
    try frame_results.append(FrameResult{
        .index = frame.index,
        .calls = frame.calls,
        .expects = try expect_results.toOwnedSlice(),

    });
    break;
}

// Diff expects against final frame state (prev_snap = last call's after)
for (frame.expects) |exp| {
    const er = try diffExpect(exp, &prev_snap, allocator);
    try expect_results.append(er);
    if (er.status == .pass) {
        try writer.print("    expect {s}: PASS\n", .{er.desc});

    } else {
        try writer.print("    expect {s}: FAIL\n", .{er.desc});
        try writer.print("      expected: {s}\n", .{er.expected});
        try writer.print("      actual:   {s}\n", .{er.actual});
        frame_ok = false;
    }
}
if (frame_ok and frame.expects.len > 0) {
    try writer.print("    -> OK\n", .{});
}

    try frame_results.append(FrameResult{
        .index = frame.index,
        .calls = frame.calls,
        .expects = try expect_results.toOwnedSlice(),
    });
}

// Build causal graph from CallSnapshot diffs
for (call_snapshots.items) |cs| {

    for (cs.diffs) |diff| {
        try causal_edges.append(CausalEdge{
            .frame_index = cs.frame_index,
            .export_name = cs.export_name,
            .field = try allocator.dupe(u8, diff.field),
            .before = diff.before,
            .after = diff.after,
        });
    }
}

// Print causal graph after all frames
if (causal_edges.items.len > 0) {
    try printCausalGraph(causal_edges.items, writer, allocator);
}

// Cleanup: free call_snapshots (diffs first, then snapshots)
for (call_snapshots.items) |*cs| freeCallSnapshot(cs, allocator);
call_snapshots.deinit();
// Free causal edges

for (causal_edges.items) |ce| allocator.free(ce.field);
causal_edges.deinit();

// Free prev_snap if we still own it (should only happen with 0 frames)
if (own_prev) {
    var it = prev_snap.fields.iterator();
    while (it.next()) |entry| allocator.free(entry.key_ptr.*);
    prev_snap.fields.deinit();
}

    return frame_results.toOwnedSlice();
}

// --- Main test entry point ---

pub fn runTest(allocator: std.mem.Allocator, source_full: []const u8, desc: TestDesc, writer: anytype) !TestResult {
    const dll_path = try std.fmt.allocPrint(allocator, "{s}.dll", .{source_full});
    defer allocator.free(dll_path);

    const has_frames = desc.frames.len > 0;

// Step 1: compile
try writer.print("  COMPILE: ", .{});
const trace_mode: x64gen.TraceMode = if (has_frames) .full else .off;
compileDllEx(allocator, source_full, dll_path, trace_mode) catch |err| {
    try writer.print("FAIL ({any})\n", .{err});
    return TestResult{ .name = desc.name, .status = .@"error", .compile_ok = false, .load_ok = false, .cases = &.{}, .frames = &.{} };
};
try writer.print("OK\n", .{});

// Step 2: load
try writer.print("  LOAD: ", .{});
var lib = DynLib.open(dll_path) catch |err| {
    try writer.print("FAIL ({any})\n", .{err});
    return TestResult{ .name = desc.name, .status = .@"error", .compile_ok = true, .load_ok = false, .cases = &.{}, .frames = &.{} };
};
try writer.print("OK\n", .{});

if (has_frames) {
    // --- v2: Frame-based test ---

// Set up trace buffer if trace export exists
var trace_buf: ?[]u8 = null;
const trace_slot: ?*align(1) u64 = if (try lib.lookup("bpc_get_trace_buf_slot")) |get_slot| blk: {
    const addr = get_slot();
    try writer.print("    trace slot addr={any}\n", .{@as(u64, @bitCast(addr))});
    const ptr: usize = @as(usize, @intCast(addr));
    break :blk @ptrFromInt(ptr);
} else blk: {
    try writer.print("    trace slot not found\n", .{});
    break :blk null;

};

{
    const get_state_fn = (try lib.lookup("bpc_get_state")) orelse return error.MissingGetState;
    const state_ptr_raw = get_state_fn();
    try writer.print("    state_ptr_raw={any}\n", .{@as(u64, @bitCast(state_ptr_raw))});
}

if (trace_slot) |slot| {
    const buf_size = 65536;

    const buf = try std.heap.page_allocator.alloc(u8, buf_size);
    @memset(buf, 0);
    trace_buf = buf;
    slot.* = @intFromPtr(buf.ptr);
    try writer.print("    trace buf ptr={any}\n", .{@intFromPtr(buf.ptr)});
}

// Print trace slot info (buffer is zeroed and ready for frame events)

const frame_results = runFrames(allocator, &lib, desc.frames, writer) catch {

    if (trace_buf) |b| std.heap.page_allocator.free(b);
    lib.close();
    return TestResult{ .name = desc.name, .status = .@"error", .compile_ok = true, .load_ok = true, .cases = &.{}, .frames = &.{} };
};

// Print trace event count if tracing was active
if (trace_buf) |buf| {
    if (trace_slot) |slot| {
        const bytes_written = slot.* - @intFromPtr(buf.ptr);
        const event_count = bytes_written / 16;

        if (event_count > 0) {
            try writer.print("  TRACE: {} events ({} bytes)\n", .{ event_count, bytes_written });
        }
    }
    std.heap.page_allocator.free(buf);
}

lib.close();
// Determine overall status from frame results
var any_fail = false;

for (frame_results) |fr| {
    for (fr.expects) |er| {
        if (er.status != .pass) any_fail = true;
    }
}
return TestResult{
    .name = desc.name,
    .status = if (any_fail) .fail else .pass,
    .compile_ok = true,
    .load_ok = true,

        .cases = &.{},
        .frames = frame_results,
    };
} else {
    // --- v1: Case-based test ---
    var case_results = std.ArrayList(CaseResult).init(allocator);
    var any_fail = false;

    for (desc.cases) |case| {
        if (desc.reset_mode == .per_case) {

lib.close();
lib = DynLib.open(dll_path) catch |err| {
    try writer.print("  CASE {s}: ERROR (reload: {any})\n", .{ case.name, err });
    try case_results.append(CaseResult{
        .name = case.name,
        .calls = case.calls,
        .status = .@"error",
        .expected = "N/A",
        .actual = try std.fmt.allocPrint(allocator, "reload failed: {any}", .{err}),
    });

        any_fail = true;
        continue;
    };
}

var call_err = false;
var return_val: i64 = 0;

for (case.calls) |call_name| {
    const func = (try lib.lookup(call_name)) orelse {

try writer.print("  CASE {s}: ERROR (symbol {s} not found)\n", .{ case.name, call_name });
try case_results.append(CaseResult{
    .name = case.name,
    .calls = case.calls,
    .status = .@"error",
    .expected = try formatExpect(case.expect, allocator),
    .actual = try std.fmt.allocPrint(allocator, "symbol {s} not found", .{call_name}),
});
call_err = true;
any_fail = true;

        break;
    };
    return_val = func();
}

if (call_err) continue;

const expected_str = try formatExpect(case.expect, allocator);
const actual_str = try formatActual(return_val, case.expect, allocator);
const matched = matchesExpect(return_val, case.expect);

if (matched) {
    try writer.print("  CASE {s}: PASS\n", .{case.name});
} else {
    try writer.print("  CASE {s}: FAIL\n", .{case.name});
    try writer.print("    expected: {s}\n", .{expected_str});
    try writer.print("    actual:   {s}\n", .{actual_str});
    any_fail = true;
}

    try case_results.append(CaseResult{
        .name = case.name,
        .calls = case.calls,
        .status = if (matched) .pass else .fail,
        .expected = expected_str,
        .actual = actual_str,
    });
}

lib.close();

    return TestResult{
        .name = desc.name,
        .status = if (any_fail) .fail else .pass,
        .compile_ok = true,
        .load_ok = true,
        .cases = try case_results.toOwnedSlice(),
        .frames = &.{},
    };
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

fn makePSO(device: ?*anyopaque, rs: ?*anyopaque, code: []const u8) !?*anyopaque {
    var pso: ?*anyopaque = null;
    var desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs, .CS = .{ .pShaderBytecode = code.ptr, .BytecodeLength = code.len } };
    const h = d3d.getDeviceVtbl(device.?).CreateComputePipelineState(device.?, &desc, &d3d.IID_ID3D12PipelineState, &pso);
    if (h < 0) return error.PSOFailed;
    return pso;

}

fn execUAVFill(c: *dx12.ComputeContext, cmd_list: ?*anyopaque, rs: ?*anyopaque, pso: ?*anyopaque, gpu_handle: d3d.D3D12_GPU_DESCRIPTOR_HANDLE, gx: u32, gy: u32) !void {
    _ = d3d.getAllocatorVtbl(c.cmd_allocator.?).Reset(c.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd_list.?).Reset(cmd_list.?, c.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd_list.?).SetPipelineState(cmd_list.?, pso);
    d3d.getCmdListVtbl(cmd_list.?).SetComputeRootSignature(cmd_list.?, rs);
    var heaps = [_]?*anyopaque{c.uav_heap};
    d3d.getCmdListVtbl(cmd_list.?).SetDescriptorHeaps(cmd_list.?, 1, &heaps);
    d3d.getCmdListVtbl(cmd_list.?).SetComputeRootDescriptorTable(cmd_list.?, 0, gpu_handle);

    d3d.getCmdListVtbl(cmd_list.?).Dispatch(cmd_list.?, gx, gy, 1);
    const h = d3d.getCmdListVtbl(cmd_list.?).Close(cmd_list.?);
    if (h < 0) return error.Close;
    var lists = [_]?*anyopaque{cmd_list};
    d3d.getQueueVtbl(c.queue.?).ExecuteCommandLists(c.queue.?, 1, &lists);
    c.fence_value += 1;
    _ = d3d.getQueueVtbl(c.queue.?).Signal(c.queue.?, c.fence, c.fence_value);
    _ = d3d.getFenceVtbl(c.fence.?).SetEventOnCompletion(c.fence.?, c.fence_value, @as(*anyopaque, @ptrFromInt(c.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(c.event)), 5000);
}

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    const W_LOW: u32 = 8;
    const H_LOW: u32 = 8;
    const W_HIGH: u32 = 16;
    const H_HIGH: u32 = 16;

// --- Root sig 1: UAV only (fill) ---
var rs1_ranges = [1]d3d.D3D12_DESCRIPTOR_RANGE{.{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 }};
var rs1_params = [1]d3d.D3D12_ROOT_PARAMETER{.{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs1_ranges)) } }, .ShaderVisibility = .ALL }};
var rs1_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs1_params)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };
var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&rs1_desc, 1, &blob, &err_blob);
if (hr_ < 0) return error.RS1Failed;
var rs1: ?*anyopaque = null;

hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs1);
if (hr_ < 0) return error.RS1Failed;
d3d.release(blob);

// --- Root sig 2: SRV×5 + UAV (t0..t4, u0) ---
var rs2_ranges = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SRV, .NumDescriptors = 5, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 5 },
};
var rs2_params = [1]d3d.D3D12_ROOT_PARAMETER{.{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_ranges)) } }, .ShaderVisibility = .ALL }};

var rs2_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs2_params)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };
hr_ = ctx.D3D12SerializeRootSignature.?(&rs2_desc, 1, &blob, &err_blob);
if (hr_ < 0) { if (err_blob) |eb| d3d.release(eb); return error.RS2Failed; }
var rs2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs2);
if (hr_ < 0) return error.RS2Failed;
d3d.release(blob);

// --- Fill shaders ---
const fill_lr_shader = \\RWTexture2D<float> tex : register(u0); [numthreads(8,8,1)] void main(uint3 t : SV_DispatchThreadID) { tex[t.xy] = float(t.x + t.y * 8); }

;
const fill_mv_shader = \\RWTexture2D<float2> tex : register(u0); [numthreads(8,8,1)] void main(uint3 t : SV_DispatchThreadID) { tex[t.xy] = float2(2.0, 0.0); }
;
const fill_prev_shader = \\RWTexture2D<float> tex : register(u0); [numthreads(8,8,1)] void main(uint3 t : SV_DispatchThreadID) { tex[t.xy] = 999.0; }
;
const fill_depth_shader = \\RWTexture2D<float> tex : register(u0); [numthreads(8,8,1)] void main(uint3 t : SV_DispatchThreadID) { tex[t.xy] = 1.0; }
;
const fill_pdepth_shader = \\RWTexture2D<float> tex : register(u0); [numthreads(8,8,1)] void main(uint3 t : SV_DispatchThreadID) { tex[t.xy] = t.x < 8 ? 1.0 : 10.0; }
;

const code_lr = try dx12.compileShaderSource(fill_lr_shader);
const code_mv = try dx12.compileShaderSource(fill_mv_shader);
const code_prev = try dx12.compileShaderSource(fill_prev_shader);
const code_depth = try dx12.compileShaderSource(fill_depth_shader);
const code_pdepth = try dx12.compileShaderSource(fill_pdepth_shader);

const pso_lr = try makePSO(ctx.device.?, rs1, code_lr);
const pso_mv = try makePSO(ctx.device.?, rs1, code_mv);
const pso_prev = try makePSO(ctx.device.?, rs1, code_prev);
const pso_depth = try makePSO(ctx.device.?, rs1, code_depth);

const pso_pdepth = try makePSO(ctx.device.?, rs1, code_pdepth);
defer d3d.release(pso_lr);
defer d3d.release(pso_mv);
defer d3d.release(pso_prev);
defer d3d.release(pso_depth);
defer d3d.release(pso_pdepth);

// --- Temporal + depth rejection PSO ---
const temporal_shader =
    \\Texture2D<float> lowResColor : register(t0);

\\Texture2D<float2> motionVectors : register(t1);
\\Texture2D<float> prevOutput : register(t2);
\\Texture2D<float> depth : register(t3);
\\Texture2D<float> prevDepth : register(t4);
\\RWTexture2D<float> output : register(u0);
\\[numthreads(8, 8, 1)]
\\void main(uint3 tid : SV_DispatchThreadID) {
\\    uint2 outSize; output.GetDimensions(outSize.x, outSize.y);
\\    uint2 inSize; lowResColor.GetDimensions(inSize.x, inSize.y);
\\    float2 scale = float2(inSize) / float2(outSize);

\\    float2 uv = (float2(tid.xy) + 0.5) * scale;
\\    int2 inPos = int2(uv);
\\    float currentColor = lowResColor.Load(int3(inPos, 0));
\\    float2 mv = motionVectors.Load(int3(inPos, 0));
\\    float currentDepth = depth.Load(int3(inPos, 0));
\\    float2 prevUV = float2(tid.xy) + 0.5 - mv;
\\    int2 prevPos = int2(prevUV);
\\    float prevColor = 0;
\\    float blend = 0.0;
\\    if (prevPos.x >= 0 && prevPos.x < int(outSize.x) && prevPos.y >= 0 && prevPos.y < int(outSize.y)) {

    \\        prevColor = prevOutput.Load(int3(prevPos, 0));
    \\        float prevDepthVal = prevDepth.Load(int3(prevPos, 0));
    \\        if (abs(currentDepth - prevDepthVal) < 0.01) blend = 0.5;
    \\    }
    \\    output[tid.xy] = lerp(currentColor, prevColor, blend);
    \\}
;
const temporal_code = try dx12.compileShaderSource(temporal_shader);
var pso_temporal_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs2, .CS = .{ .pShaderBytecode = temporal_code.ptr, .BytecodeLength = temporal_code.len } };
var pso_temporal: ?*anyopaque = null;

hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso_temporal_desc, &d3d.IID_ID3D12PipelineState, &pso_temporal);
if (hr_ < 0) return error.PSOTemporalFailed;
defer d3d.release(pso_temporal);

// --- Textures ---
const tex_lr = try ctx.createTexture2D(W_LOW, H_LOW, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_lr);
const tex_mv = try ctx.createTexture2D(W_LOW, H_LOW, .R32G32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_mv);
const tex_prev = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);

defer d3d.release(tex_prev);
const tex_depth = try ctx.createTexture2D(W_LOW, H_LOW, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_depth);
const tex_pdepth = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_pdepth);
const tex_out = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_out);

const readback = try ctx.createBuffer(try ctx.getTextureFootprint(W_HIGH, H_HIGH, .R32_FLOAT), .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
defer d3d.release(readback);

const cmd = ctx.cmd_list;

// --- SRVs t0..t4 at slots 0..4 ---
const srv_r32 = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } } };
const srv_rg32 = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } } };
ctx.createSRV(tex_lr, &srv_r32, ctx.getUAVCPUHandle(0));
ctx.createSRV(tex_mv, &srv_rg32, ctx.getUAVCPUHandle(1));
ctx.createSRV(tex_prev, &srv_r32, ctx.getUAVCPUHandle(2));
ctx.createSRV(tex_depth, &srv_r32, ctx.getUAVCPUHandle(3));

ctx.createSRV(tex_pdepth, &srv_r32, ctx.getUAVCPUHandle(4));

// --- UAV u0 at slot 5 ---
const uav_r32 = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(tex_out, &uav_r32, ctx.getUAVCPUHandle(5));

// --- Fill UAVs at slots 6..11 ---
ctx.createUAVViewTexture(tex_lr, &uav_r32, ctx.getUAVCPUHandle(6));
const uav_rg32 = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(tex_mv, &uav_rg32, ctx.getUAVCPUHandle(7));

ctx.createUAVViewTexture(tex_prev, &uav_r32, ctx.getUAVCPUHandle(8));
ctx.createUAVViewTexture(tex_depth, &uav_r32, ctx.getUAVCPUHandle(9));
ctx.createUAVViewTexture(tex_pdepth, &uav_r32, ctx.getUAVCPUHandle(10));

// Helper to execute a fill pass
try execUAVFill(&ctx, cmd.?, rs1, pso_lr, ctx.getUAVGPUHandle(6), 1, 1);
std.debug.print("Pass 1a: low-res\n", .{});
try execUAVFill(&ctx, cmd.?, rs1, pso_prev, ctx.getUAVGPUHandle(8), 2, 2);
std.debug.print("Pass 1b: prev output\n", .{});
try execUAVFill(&ctx, cmd.?, rs1, pso_mv, ctx.getUAVGPUHandle(7), 1, 1);

std.debug.print("Pass 1c: mv\n", .{});
try execUAVFill(&ctx, cmd.?, rs1, pso_depth, ctx.getUAVGPUHandle(9), 1, 1);
std.debug.print("Pass 1d: depth\n", .{});
try execUAVFill(&ctx, cmd.?, rs1, pso_pdepth, ctx.getUAVGPUHandle(10), 2, 2);
std.debug.print("Pass 1e: prev depth\n", .{});

// Barriers: all to NON_PIXEL_SHADER_RESOURCE
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

dx12.ComputeContext.bufferBarrier(cmd.?, tex_lr, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_mv, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_prev, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_depth, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_pdepth, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseBarrier;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;

    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Barriers done\n", .{});
}

// ===== Temporal upscale with depth rejection =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso_temporal);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs2);
var heaps = [_]?*anyopaque{ctx.uav_heap};
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 2, 2, 1);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_out, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseTemporal;
var lists = [_]?*anyopaque{cmd};

    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 2: temporal + depth rejection\n", .{});
}

// Copy to readback
var row_pitch: u32 = undefined;

{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    row_pitch = ctx.copyTextureToBuffer(readback, tex_out, W_HIGH, H_HIGH, .R32_FLOAT);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
    if (hr_ < 0) return error.CloseCopy;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);

    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 3: copy (RowPitch={})\n", .{row_pitch});
}

// Verify
const ptr = try dx12.ComputeContext.mapBuffer(readback);
defer dx12.ComputeContext.unmapBuffer(readback);
const data: [*]f32 = @ptrCast(@alignCast(ptr));
const rf = row_pitch / 4;

std.debug.print("\nRow 1 output: ", .{});
for (0..W_HIGH) |x| std.debug.print("{d:7.1} ", .{data[1 * rf + x]});
std.debug.print("\n", .{});

// Expected:
// MV=(2,0). For output (ox, oy):
//   inPos = int2((ox+0.5)*0.5, (oy+0.5)*0.5)
//   prevPos = int2(ox+0.5-2, oy+0.5-0) = (ox-2, oy) when truncating
//

// prevDepth: x<8 → 1.0, x>=8 → 10.0. depth: all 1.0.
// If prevDepth == 1.0 (within threshold): blend=0.5, else blend=0
//
// (0,1): inPos=(0,0), cur=0, prevPos=(-2,1) OOB → blend=0, output=0
// (2,1): inPos=(1,0), cur=1, prevPos=(0,1)→prevDepth=1.0, diff=0→blend=0.5,
//         prev=prevOutput[0,1]=999, output=lerp(1,999,0.5)=500
// (15,1): inPos=(7,0), cur=7, prevPos=(13,1)→prevDepth=10.0, diff=9→blend=0,
//          output=7

var pass: bool = true;

const checks = [_]struct { ox: u32, oy: u32, expected: f32, tol: f32 }{
    .{ .ox = 0, .oy = 1, .expected = 0, .tol = 0.1 },     // OOB → no history
    .{ .ox = 2, .oy = 1, .expected = 500, .tol = 0.1 },   // depth matches → history used
    .{ .ox = 15, .oy = 1, .expected = 7, .tol = 0.1 },    // depth mismatch → history rejected
    .{ .ox = 9, .oy = 1, .expected = 501.5, .tol = 0.1 }, // prevPos=(7,1), prevDepth=1.0 → history used, lerp(4,999,0.5)=501.5
};
for (checks) |c| {
    const actual = data[c.oy * rf + c.ox];
    const diff = @abs(actual - c.expected);
    if (diff > c.tol) {

        std.debug.print("FAIL[{}x{}]: got {d:.1} expected {d:.1} (diff={d:.1})\n", .{ c.ox, c.oy, actual, c.expected, diff });
        pass = false;
    } else {
        std.debug.print("OK[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
    }
}

if (pass) std.debug.print("\nPASS: Depth-based disocclusion rejection verified\n", .{});

d3d.release(rs1);

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

pub fn main() !void {
    // Minimal test: DIRECT queue + DIRECT command list, same compute shader
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

var queue_desc: d3d.D3D12_COMMAND_QUEUE_DESC = undefined;
_ = d3d.getQueueVtbl(ctx.queue.?).GetDesc(ctx.queue.?, &queue_desc);
std.debug.print("queue type = {d} ({s})\n", .{
    @intFromEnum(queue_desc.Type), @tagName(queue_desc.Type),
});
const cmd_type = d3d.getCmdListVtbl(ctx.cmd_list.?).GetType(ctx.cmd_list.?);
std.debug.print("cmdlist type = {d} ({s})\n", .{
    @intFromEnum(cmd_type), @tagName(cmd_type),
});

const num_elements: u32 = 64;
const buf_size: u64 = num_elements * 4;

const uav_buf = try ctx.createBuffer(buf_size, .DEFAULT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
errdefer d3d.release(uav_buf);

const readback = try ctx.createBuffer(buf_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
errdefer d3d.release(readback);

const uav_desc = dx12.ComputeContext.createUAVDesc(null, num_elements);

const cpu_handle = ctx.getUAVCPUHandle(0);
ctx.createUAVView(uav_buf, &uav_desc, cpu_handle);

// Try DIRECT command allocator + command list
var direct_alloc: ?*anyopaque = null;
var hr = d3d.getDeviceVtbl(ctx.device.?).CreateCommandAllocator(ctx.device.?, .DIRECT, &d3d.IID_ID3D12CommandAllocator, &direct_alloc);
std.debug.print("CreateDirectAllocator: hr=0x{x}\n", .{@as(u32, @bitCast(hr))});
if (hr < 0) return error.AllocFailed;

var direct_list: ?*anyopaque = null;

hr = d3d.getDeviceVtbl(ctx.device.?).CreateCommandList(ctx.device.?, 0, .DIRECT, direct_alloc, null, &d3d.IID_ID3D12GraphicsCommandList, &direct_list);
std.debug.print("CreateDirectCmdList: hr=0x{x}\n", .{@as(u32, @bitCast(hr))});
if (hr < 0) return error.ListFailed;

const list_type = d3d.getCmdListVtbl(direct_list.?).GetType(direct_list.?);
std.debug.print("direct list type = {d} ({s})\n", .{
    @intFromEnum(list_type), @tagName(list_type),
});

hr = d3d.getCmdListVtbl(direct_list.?).Close(direct_list.?);

std.debug.print("Initial close: hr=0x{x}\n", .{@as(u32, @bitCast(hr))});

// Now record compute commands on the DIRECT command list
hr = d3d.getCmdListVtbl(direct_list.?).Reset(direct_list.?, direct_alloc, null);
std.debug.print("Reset: hr=0x{x}\n", .{@as(u32, @bitCast(hr))});
if (hr < 0) return error.ResetFailed;

d3d.getCmdListVtbl(direct_list.?).SetPipelineState(direct_list.?, ctx.pso);
d3d.getCmdListVtbl(direct_list.?).SetComputeRootSignature(direct_list.?, ctx.root_sig);

var heaps = [_]?*anyopaque{ctx.uav_heap};
d3d.getCmdListVtbl(direct_list.?).SetDescriptorHeaps(direct_list.?, 1, &heaps);

const gpu_handle = ctx.getUAVGPUHandle(0);
d3d.getCmdListVtbl(direct_list.?).SetComputeRootDescriptorTable(direct_list.?, 0, gpu_handle);
d3d.getCmdListVtbl(direct_list.?).Dispatch(direct_list.?, 1, 1, 1);

dx12.ComputeContext.bufferBarrier(direct_list.?, uav_buf, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
d3d.getCmdListVtbl(direct_list.?).CopyResource(direct_list.?, readback, uav_buf);

hr = d3d.getCmdListVtbl(direct_list.?).Close(direct_list.?);
std.debug.print("Close after recording: hr=0x{x}\n", .{@as(u32, @bitCast(hr))});
if (hr < 0) return error.CloseFailed;

// Execute on DIRECT queue
var lists = [_]?*anyopaque{direct_list};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
hr = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
if (hr < 0) return error.SignalFailed;

hr = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
if (hr < 0) return error.FenceFailed;
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);

// Map and verify
const ptr = dx12.ComputeContext.mapBuffer(readback) catch |err| {
    const reason = d3d.getDeviceVtbl(ctx.device.?).GetDeviceRemovedReason(ctx.device.?);
    std.debug.print("Map failed with {}. DeviceRemovedReason = 0x{x}\n", .{ err, @as(u32, @bitCast(reason)) });
    return err;
};

defer dx12.ComputeContext.unmapBuffer(readback);

const data: [*]f32 = @ptrCast(@alignCast(ptr));
var pass: bool = true;
for (0..num_elements) |i| {
    const expected: f32 = @floatFromInt(@as(u32, @intCast(i)) * 2);
    if (data[i] != expected) {
        std.debug.print("FAIL[{}]: got {} expected {}\n", .{ i, data[i], expected });
        pass = false;
        break;

        }
    }
    if (pass) {
        std.debug.print("PASS: All {} elements verified\n", .{num_elements});
    }

    d3d.release(direct_alloc);
    d3d.release(direct_list);
}

