const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

const W_LOW = 8;
const H_LOW = 8;
const W_HIGH = 16;
const H_HIGH = 16;

fn makePSO(d: ?*anyopaque, rs: ?*anyopaque, code: []const u8) !?*anyopaque {

    var pso: ?*anyopaque = null;
    var desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs, .CS = .{ .pShaderBytecode = code.ptr, .BytecodeLength = code.len } };
    if (d3d.getDeviceVtbl(d.?).CreateComputePipelineState(d.?, &desc, &d3d.IID_ID3D12PipelineState, &pso) < 0) return error.PSO;
    return pso;
}

fn fill(c: *dx12.ComputeContext, cl: ?*anyopaque, rs: ?*anyopaque, pso: ?*anyopaque, gh: d3d.D3D12_GPU_DESCRIPTOR_HANDLE, gx: u32, gy: u32) !void {
    _ = d3d.getAllocatorVtbl(c.cmd_allocator.?).Reset(c.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cl.?).Reset(cl.?, c.cmd_allocator, null);
    d3d.getCmdListVtbl(cl.?).SetPipelineState(cl.?, pso);

d3d.getCmdListVtbl(cl.?).SetComputeRootSignature(cl.?, rs);
var heaps = [_]?*anyopaque{c.uav_heap};
d3d.getCmdListVtbl(cl.?).SetDescriptorHeaps(cl.?, 1, &heaps);
d3d.getCmdListVtbl(cl.?).SetComputeRootDescriptorTable(cl.?, 0, gh);
d3d.getCmdListVtbl(cl.?).Dispatch(cl.?, gx, gy, 1);
if (d3d.getCmdListVtbl(cl.?).Close(cl.?) < 0) return error.Close;
var lists = [_]?*anyopaque{cl};
d3d.getQueueVtbl(c.queue.?).ExecuteCommandLists(c.queue.?, 1, &lists);
c.fence_value += 1;
_ = d3d.getQueueVtbl(c.queue.?).Signal(c.queue.?, c.fence, c.fence_value);

    _ = d3d.getFenceVtbl(c.fence.?).SetEventOnCompletion(c.fence.?, c.fence_value, @as(*anyopaque, @ptrFromInt(c.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(c.event)), 5000);
}

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    // RS1: UAV only

var r1r = [1]d3d.D3D12_DESCRIPTOR_RANGE{.{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 }};
var r1p = [1]d3d.D3D12_ROOT_PARAMETER{.{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&r1r)) } }, .ShaderVisibility = .ALL }};
var r1d = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&r1p)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };
var blob: ?*anyopaque = null; var eblob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&r1d, 1, &blob, &eblob);
if (hr_ < 0) return error.RS1;
var rs1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs1);
if (hr_ < 0) return error.RS1;
d3d.release(blob);

// RS2: SRV×6 + UAV×2 (t0..t5, u0..u1)
var r2r = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SRV, .NumDescriptors = 6, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 2, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 6 },
};
var r2p = [1]d3d.D3D12_ROOT_PARAMETER{.{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&r2r)) } }, .ShaderVisibility = .ALL }};
var r2d = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&r2p)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };
hr_ = ctx.D3D12SerializeRootSignature.?(&r2d, 1, &blob, &eblob);
if (hr_ < 0) return error.RS2;

var rs2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs2);
if (hr_ < 0) return error.RS2;
d3d.release(blob);

// --- Fill shaders ---
const S_lr = \\RWTexture2D<float> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = float(d.x + d.y * 8); }
;
const S_po = \\RWTexture2D<float> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = d.x < 8 ? 1000.0 : float(int(d.x/2) + int(d.y/2) * 8); }
;

const S_mv = \\RWTexture2D<float2> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = float2(0,0); }
;
const S_dp = \\RWTexture2D<float> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = 1.0; }
;
const S_pd = \\RWTexture2D<float> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = 1.0; }
;
const S_lk = \\RWTexture2D<float> t : register(u0); [numthreads(8,8,1)] void main(uint3 d : SV_DispatchThreadID) { t[d.xy] = 5.0; }
;

const C1 = try dx12.compileShaderSource(S_lr);

const C2 = try dx12.compileShaderSource(S_po);
const C3 = try dx12.compileShaderSource(S_mv);
const C4 = try dx12.compileShaderSource(S_dp);
const C5 = try dx12.compileShaderSource(S_pd);
const C6 = try dx12.compileShaderSource(S_lk);

const P1 = try makePSO(ctx.device.?, rs1, C1);
const P2 = try makePSO(ctx.device.?, rs1, C2);
const P3 = try makePSO(ctx.device.?, rs1, C3);
const P4 = try makePSO(ctx.device.?, rs1, C4);

const P5 = try makePSO(ctx.device.?, rs1, C5);
const P6 = try makePSO(ctx.device.?, rs1, C6);
defer d3d.release(P1); defer d3d.release(P2); defer d3d.release(P3);
defer d3d.release(P4); defer d3d.release(P5); defer d3d.release(P6);

// --- Temporal + lock PSO ---
const lock_shader =
    \\Texture2D<float> lowResColor : register(t0);
    \\Texture2D<float2> motionVectors : register(t1);
    \\Texture2D<float> prevOutput : register(t2);

\\Texture2D<float> depth : register(t3);
\\Texture2D<float> prevDepth : register(t4);
\\Texture2D<float> lockPrev : register(t5);
\\RWTexture2D<float> output : register(u0);
\\RWTexture2D<float> lockCurr : register(u1);
\\[numthreads(8, 8, 1)]
\\void main(uint3 tid : SV_DispatchThreadID) {
\\    uint2 os; output.GetDimensions(os.x, os.y);
\\    uint2 is; lowResColor.GetDimensions(is.x, is.y);
\\    int2 ip = int2((float2(tid.xy) + 0.5) * float2(is) / float2(os));

\\    float cc = lowResColor.Load(int3(ip, 0));
\\    float2 mv = motionVectors.Load(int3(ip, 0));
\\    float cd = depth.Load(int3(ip, 0));
\\    int2 pp = int2(float2(tid.xy) + 0.5 - mv);
\\    float pc = 0; float blend = 0; float nl = 0;
\\    if (pp.x >= 0 && pp.x < int(os.x) && pp.y >= 0 && pp.y < int(os.y)) {
\\        pc = prevOutput.Load(int3(pp, 0));
\\        float pd = prevDepth.Load(int3(pp, 0));
\\        if (abs(cd - pd) < 0.01) {
\\            float lumaDiff = abs(cc - pc);

\\            float gf = exp(-(lumaDiff * lumaDiff) / 86900.0);
\\            float pl = lockPrev.Load(int3(pp, 0));
\\            if (gf > 0.5) {
\\                nl = min(pl + 1.0, 10.0);
\\                blend = 0.5 * (nl / 10.0);
\\            }
\\        }
\\    }
\\    lockCurr[tid.xy] = nl;
\\    output[tid.xy] = lerp(cc, pc, blend);

    \\}
;
const lock_code = try dx12.compileShaderSource(lock_shader);
var pso_lock_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs2, .CS = .{ .pShaderBytecode = lock_code.ptr, .BytecodeLength = lock_code.len } };
var pso_lock: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso_lock_desc, &d3d.IID_ID3D12PipelineState, &pso_lock);
if (hr_ < 0) return error.PSOLock;
defer d3d.release(pso_lock);

// --- Textures ---

const tex_lr = try ctx.createTexture2D(W_LOW, H_LOW, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_lr);
const tex_mv = try ctx.createTexture2D(W_LOW, H_LOW, .R32G32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_mv);
const tex_po = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_po);
const tex_dp = try ctx.createTexture2D(W_LOW, H_LOW, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_dp);
const tex_pd = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_pd);

const tex_lp = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS); // lock prev
defer d3d.release(tex_lp);
const tex_lc = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS); // lock curr
defer d3d.release(tex_lc);
const tex_out = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_out);

const rb_size = try ctx.getTextureFootprint(W_HIGH, H_HIGH, .R32_FLOAT);
const rb_out = try ctx.createBuffer(rb_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
defer d3d.release(rb_out);

const rb_lock = try ctx.createBuffer(rb_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
defer d3d.release(rb_lock);

const cmd = ctx.cmd_list;

// --- SRVs: 0-5 ---
const srv_r32 = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1 } } };
const srv_rg32 = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1 } } };
ctx.createSRV(tex_lr, &srv_r32, ctx.getUAVCPUHandle(0));
ctx.createSRV(tex_mv, &srv_rg32, ctx.getUAVCPUHandle(1));

ctx.createSRV(tex_po, &srv_r32, ctx.getUAVCPUHandle(2));
ctx.createSRV(tex_dp, &srv_r32, ctx.getUAVCPUHandle(3));
ctx.createSRV(tex_pd, &srv_r32, ctx.getUAVCPUHandle(4));
ctx.createSRV(tex_lp, &srv_r32, ctx.getUAVCPUHandle(5));

// --- UAVs: 6-7 ---
const uav_r32 = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0 } } };
ctx.createUAVViewTexture(tex_out, &uav_r32, ctx.getUAVCPUHandle(6));
ctx.createUAVViewTexture(tex_lc, &uav_r32, ctx.getUAVCPUHandle(7));

// --- Fill UAVs: 8-13 ---
const uav_rg32 = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0 } } };
ctx.createUAVViewTexture(tex_lr, &uav_r32, ctx.getUAVCPUHandle(8));
ctx.createUAVViewTexture(tex_mv, &uav_rg32, ctx.getUAVCPUHandle(9));
ctx.createUAVViewTexture(tex_po, &uav_r32, ctx.getUAVCPUHandle(10));
ctx.createUAVViewTexture(tex_dp, &uav_r32, ctx.getUAVCPUHandle(11));
ctx.createUAVViewTexture(tex_pd, &uav_r32, ctx.getUAVCPUHandle(12));
ctx.createUAVViewTexture(tex_lp, &uav_r32, ctx.getUAVCPUHandle(13));

// Fill passes

try fill(&ctx, cmd, rs1, P1, ctx.getUAVGPUHandle(8), 1, 1);
std.debug.print("Fill: low-res pattern\n", .{});
try fill(&ctx, cmd, rs1, P2, ctx.getUAVGPUHandle(10), 2, 2);
std.debug.print("Fill: prev output (left=1000, right=match)\n", .{});
try fill(&ctx, cmd, rs1, P3, ctx.getUAVGPUHandle(9), 1, 1);
std.debug.print("Fill: mv (0,0)\n", .{});
try fill(&ctx, cmd, rs1, P4, ctx.getUAVGPUHandle(11), 1, 1);
std.debug.print("Fill: depth\n", .{});
try fill(&ctx, cmd, rs1, P5, ctx.getUAVGPUHandle(12), 2, 2);
std.debug.print("Fill: prev depth\n", .{});

try fill(&ctx, cmd, rs1, P6, ctx.getUAVGPUHandle(13), 2, 2);
std.debug.print("Fill: lock prev (5.0)\n", .{});

// Barriers
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    dx12.ComputeContext.bufferBarrier(cmd.?, tex_lr, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    dx12.ComputeContext.bufferBarrier(cmd.?, tex_mv, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    dx12.ComputeContext.bufferBarrier(cmd.?, tex_po, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);

dx12.ComputeContext.bufferBarrier(cmd.?, tex_dp, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_pd, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_lp, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
if (d3d.getCmdListVtbl(cmd.?).Close(cmd.?) < 0) return error.Barrier;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);

    std.debug.print("Barriers done\n", .{});
}

// Temporal + lock pass
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso_lock);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs2);
    var heaps = [_]?*anyopaque{ctx.uav_heap};

d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 2, 2, 1);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_out, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
dx12.ComputeContext.bufferBarrier(cmd.?, tex_lc, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
if (d3d.getCmdListVtbl(cmd.?).Close(cmd.?) < 0) return error.Close;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);

    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass: temporal + lock\n", .{});
}

// Copy output → rb_out
var rp_out: u32 = undefined;
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

    rp_out = ctx.copyTextureToBuffer(rb_out, tex_out, W_HIGH, H_HIGH, .R32_FLOAT);
    if (d3d.getCmdListVtbl(cmd.?).Close(cmd.?) < 0) return error.Close;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
}
// Copy lock → rb_lock

var rp_lock: u32 = undefined;
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    rp_lock = ctx.copyTextureToBuffer(rb_lock, tex_lc, W_HIGH, H_HIGH, .R32_FLOAT);
    if (d3d.getCmdListVtbl(cmd.?).Close(cmd.?) < 0) return error.Close;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);

    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Copies done\n", .{});
}

// Verify
const ptr_out = try dx12.ComputeContext.mapBuffer(rb_out);
defer dx12.ComputeContext.unmapBuffer(rb_out);
const out: [*]f32 = @ptrCast(@alignCast(ptr_out));

const ptr_lock = try dx12.ComputeContext.mapBuffer(rb_lock);
defer dx12.ComputeContext.unmapBuffer(rb_lock);
const lck: [*]f32 = @ptrCast(@alignCast(ptr_lock));

const rfo = rp_out / 4;
const rfl = rp_lock / 4;

std.debug.print("\nOutput row 2: ", .{});
for (0..W_HIGH) |x| std.debug.print("{d:6.1} ", .{out[2 * rfo + x]});
std.debug.print("\nLock row 2:   ", .{});

for (0..W_HIGH) |x| std.debug.print("{d:6.1} ", .{lck[2 * rfl + x]});
std.debug.print("\n", .{});

// Expected lock:
// Left (x<8): luma mismatch (1000 vs pattern) → lock reset to 0
// Right (x>=8): luma match → lock increment from 5→6
// Output:
// Left: ghosting rejected → output ≈ current (pattern value)
// Right: lock=6 → blend=0.5*6/10=0.3, prev matches current → output ≈ current

var pass: bool = true;

// Lock checks
const lock_checks = [_]struct { ox: u32, oy: u32, expected: f32, tol: f32 }{
    .{ .ox = 0, .oy = 0, .expected = 0, .tol = 0.1 },  // left: reset
    .{ .ox = 4, .oy = 2, .expected = 0, .tol = 0.1 },  // left: reset
    .{ .ox = 8, .oy = 0, .expected = 6, .tol = 0.1 },  // right: increment 5→6
    .{ .ox = 12, .oy = 4, .expected = 6, .tol = 0.1 }, // right: increment 5→6
};
std.debug.print("\nLock verification:\n", .{});

for (lock_checks) |c| {
    const actual = lck[c.oy * rfl + c.ox];
    const diff = @abs(actual - c.expected);
    if (diff > c.tol) {
        std.debug.print("  FAIL lock[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
        pass = false;
    } else {
        std.debug.print("  OK lock[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
    }
}

// Output checks
const out_checks = [_]struct { ox: u32, oy: u32, expected: f32, tol: f32 }{
    .{ .ox = 0, .oy = 0, .expected = 0, .tol = 2 },   // ghosting rejected → current
    .{ .ox = 4, .oy = 2, .expected = 10, .tol = 2 },  // ghosting rejected → current
    .{ .ox = 8, .oy = 4, .expected = 20, .tol = 2 },  // lock blend → current≈prev
    .{ .ox = 14, .oy = 6, .expected = 31, .tol = 2 }, // lock blend → current≈prev
};
std.debug.print("\nOutput verification:\n", .{});
for (out_checks) |c| {

    const actual = out[c.oy * rfo + c.ox];
    const diff = @abs(actual - c.expected);
    if (diff > c.tol) {
        std.debug.print("  FAIL out[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
        pass = false;
    } else {
        std.debug.print("  OK out[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
    }
}

    if (pass) std.debug.print("\nPASS: Lock mechanism verified\n", .{});
    d3d.release(rs1);
    d3d.release(rs2);
}

﻿const std = @import("std");
const frame_graph = @import("../../src/render/frame_graph.zig");
const gpu_types = @import("../../src/compiler/gpu/gpu_types.zig");
const resource_system = @import("../../src/render/resource_system.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const rs_builder = @import("../../src/render/root_signature_builder.zig");
const fg_executor = @import("../../src/render/frame_graph_executor.zig");
const render_graph = @import("../../src/render/render_graph.zig");
const history_manager = @import("../../src/render/history_manager.zig");

const camera_jitter = @import("../../src/render/camera_jitter.zig");
const render_helpers = @import("../../src/render/render_helpers.zig");
const frame_runtime = @import("../../src/render/frame_runtime.zig");
const gpu_scheduler = @import("../../src/runtime/gpu_scheduler.zig");
const compiled_graph = @import("../../src/render/compiled_graph.zig");

pub fn main() !void {
    const W: u32 = 64;
    const H: u32 = 64;

var gpa = std.heap.GeneralPurposeAllocator(.{}){};
const allocator = gpa.allocator();

var ctx = dx12.ComputeContext{
    .device = null, .queue = null, .cmd_allocator = null, .cmd_list = null,
    .fence = null, .fence_value = 0, .event = 0,
    .uav_heap = null, .uav_heap_increment = 0,
    .sampler_heap = null, .sampler_heap_increment = 0,
    .root_sig = null, .pso = null, .d3d12_module = null,
    .D3D12CreateDevice = null, .D3D12SerializeRootSignature = null,

    .D3D12SerializeVersionedRootSignature = null, .D3D12GetDebugInterface = null,
};
try ctx.init();
defer ctx.deinit();

var runtime = try frame_runtime.FrameRuntime.init(allocator, &ctx);
defer { runtime.drain(); runtime.deinit(); }

var pool = resource_system.ResourcePool.init(allocator, &ctx);
defer pool.deinit();

var history = history_manager.HistoryManager{};
try history.initColor(&pool, W, H, .r32g32b32a32_float);
defer history.deinit(&pool);
history.valid = false;

const scene_color_id = try pool.createTexture2D(.{ .width = W, .height = H, .format = .r32g32b32a32_float });
const final_color_id = try pool.createTexture2D(.{ .width = W, .height = H, .format = .r32g32b32a32_float });
const motion_velocity_id = try pool.createTexture2D(.{ .width = W, .height = H, .format = .r32g32b32a32_float });

var executor = fg_executor.FrameGraphGPUExecutor.init(allocator, &ctx, &pool);
defer executor.deinit();

const num_frames: u32 = 4;
const grid = render_helpers.dispatch2D(W, H);

const scene_shader =
    \\RWTexture2D<float4> ColorOut : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {

    \\    float2 uv = (float2(tid.xy) + 0.5) / float2(64, 64);
    \\    ColorOut[tid.xy] = float4(uv, 0, 1);
    \\}
;

const motion_shader =
    \\RWTexture2D<float4> MotionOut : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    MotionOut[tid.xy] = float4(0, 0, 0, 0);

    \\}
;

const taa_shader =
    \\RWTexture2D<float4> Result : register(u0);
    \\Texture2D<float4> Current : register(t0);
    \\Texture2D<float4> History : register(t1);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    float4 cur = Current[tid.xy];

    \\    float4 hist = History[tid.xy];
    \\    float blend = 0.2;
    \\    Result[tid.xy] = lerp(cur, hist, blend);
    \\}
;

const sharpen_shader =
    \\RWTexture2D<float4> Result : register(u0);
    \\Texture2D<float4> Input : register(t0);
    \\[numthreads(8, 8, 1)]

    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    float4 c = Input[tid.xy];
    \\    float4 sum = Input[int2(tid.x-1,tid.y-1)] + Input[int2(tid.x,tid.y-1)] + Input[int2(tid.x+1,tid.y-1)]
    \\               + Input[int2(tid.x-1,tid.y)]   + Input[int2(tid.x+1,tid.y)]
    \\               + Input[int2(tid.x-1,tid.y+1)] + Input[int2(tid.x,tid.y+1)] + Input[int2(tid.x+1,tid.y+1)];
    \\    float4 blurred = sum / 8.0;
    \\    Result[tid.xy] = saturate(c + (c - blurred) * 0.5);
    \\}
;

const scene_layout = gpu_types.BindLayout{ .slots = &.{
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .uav },
} };
const motion_layout = gpu_types.BindLayout{ .slots = &.{
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .uav },
} };
const taa_layout = gpu_types.BindLayout{ .slots = &.{
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .uav },
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .srv },
    gpu_types.BindSlot{ .register = 1, .space = 0, .bind_type = .srv },

} };
const sharpen_layout = gpu_types.BindLayout{ .slots = &.{
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .uav },
    gpu_types.BindSlot{ .register = 0, .space = 0, .bind_type = .srv },
} };

// Build graph topology once (static for all frames)
const gpu_passes = [_]frame_graph.GPUPassDesc{
    .{
        .pass_id = 0,

    .queue = .compute,
    .pipeline = .{ .shader = .{ .source = scene_shader, .entry = "main", .target = "cs_5_1" }, .layout = scene_layout },
    .grid = grid,
    .bindings = render_helpers.makeBindGroup(&.{
        .{ .key = .{ .reg = 0, .space = 0, .kind = .uav }, .resource_id = scene_color_id },
    }),
},
.{
    .pass_id = 1,
    .queue = .compute,

    .pipeline = .{ .shader = .{ .source = motion_shader, .entry = "main", .target = "cs_5_1" }, .layout = motion_layout },
    .grid = grid,
    .bindings = render_helpers.makeBindGroup(&.{
        .{ .key = .{ .reg = 0, .space = 0, .kind = .uav }, .resource_id = motion_velocity_id },
    }),
},
.{
    .pass_id = 2,
    .queue = .compute,
    .pipeline = .{ .shader = .{ .source = taa_shader, .entry = "main", .target = "cs_5_1" }, .layout = taa_layout },

    .grid = grid,
    .bindings = render_helpers.makeBindGroup(&.{
        .{ .key = .{ .reg = 0, .space = 0, .kind = .uav }, .resource_id = scene_color_id },
        .{ .key = .{ .reg = 0, .space = 0, .kind = .srv }, .resource_id = history.color.textures[0] },
        .{ .key = .{ .reg = 1, .space = 0, .kind = .srv }, .resource_id = history.color.textures[1] },
    }),
},
.{
    .pass_id = 3,
    .queue = .compute,

        .pipeline = .{ .shader = .{ .source = sharpen_shader, .entry = "main", .target = "cs_5_1" }, .layout = sharpen_layout },
        .grid = grid,
        .bindings = render_helpers.makeBindGroup(&.{
            .{ .key = .{ .reg = 0, .space = 0, .kind = .uav }, .resource_id = final_color_id },
            .{ .key = .{ .reg = 0, .space = 0, .kind = .srv }, .resource_id = scene_color_id },
        }),
    },
};

const frames = [_]frame_graph.Pass{

    .{ .id = 0, .name = "scene",   .deps = &.{},       .gpu = true, .gpu_wait_for = &.{}, .gpu_signal = &.{}, .cost_us = 100, .critical = true },
    .{ .id = 1, .name = "motion",  .deps = &.{},       .gpu = true, .gpu_wait_for = &.{}, .gpu_signal = &.{}, .cost_us = 100, .critical = true },
    .{ .id = 2, .name = "taa",     .deps = &.{ 0, 1 }, .gpu = true, .gpu_wait_for = &.{}, .gpu_signal = &.{}, .cost_us = 100, .critical = true },
    .{ .id = 3, .name = "sharpen", .deps = &.{ 2 },    .gpu = true, .gpu_wait_for = &.{}, .gpu_signal = &.{}, .cost_us = 100, .critical = true },
};

// Compile graph once (topology + PSO/RS + descriptor layout + bind slot map)
var rg = render_graph.RenderGraph.init(allocator, &pool);
var plan = try rg.compile(&frames, &gpu_passes, 10000);
defer render_graph.RenderGraph.deinitPlan(allocator, &plan);

try rg.allocateTransients(&plan);
defer rg.releaseTransients(&plan);

var scheduler = gpu_scheduler.GPUScheduler.init(allocator);
var schedule = try scheduler.build(&plan);
defer gpu_scheduler.GPUScheduler.deinitScheduledFrame(allocator, &schedule);

var cg = try executor.compileGraph(&plan, &schedule);
defer cg.deinit();

// Per-frame loop: no graph, no plan, no DAG — only FrameInputs
for (0..num_frames) |frame| {
    history.beginFrame();

    const inputs = compiled_graph.FrameInputs{
        .resources = &[_]gpu_types.ResourceId{
            scene_color_id,                            // slot 0
            motion_velocity_id,                        // slot 1
            history.color.textures[0],                 // slot 2

        history.color.textures[1],                 // slot 3
        final_color_id,                            // slot 4
    },
};

try executor.executeCompiledFrame(&cg, &inputs, &runtime);

history.flip();

std.debug.print("Frame {}: history={}\n", .{ frame, history.hasHistory() });

    }

    runtime.drain();
    std.debug.print("All {} frames passed: compileGraph+FrameInputs, no RenderPlan in runtime\n", .{num_frames});
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    const num_elements: u32 = 64;

const tex_width: u32 = 64;
const tex_height: u32 = 1;

// --- Root Signature 1: write pass (UAV only) ---
var rs1_ranges = [1]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
};
var rs1_params = [1]d3d.D3D12_ROOT_PARAMETER{
    .{
        .ParameterType = .DESCRIPTOR_TABLE,

        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs1_ranges)) } },
        .ShaderVisibility = .ALL,
    },
};
var rs1_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{
    .NumParameters = 1,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs1_params)),
    .NumStaticSamplers = 0,
    .pStaticSamplers = null,
    .Flags = 0,

};

var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&rs1_desc, 1, &blob, &err_blob);
if (hr_ < 0) { if (err_blob) |eb| { if (@intFromPtr(d3d.getBlobVtbl(eb).GetBufferPointer(eb)) != 0) std.debug.print("RS1 err: {s}\n", .{@as([*:0]u8, @ptrCast(d3d.getBlobVtbl(eb).GetBufferPointer(eb)))}); } return error.RS1Failed; }

var rs1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs1);
if (hr_ < 0) return error.RS1Failed;

d3d.release(blob);

// --- Root Signature 2: sample pass (SRV t0 + sampler s0 + UAV u0) ---
var rs2_ranges = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SRV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 1 },
};
var rs2_samp_range = [1]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SAMPLER, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
};

var rs2_params = [2]d3d.D3D12_ROOT_PARAMETER{
    .{
        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_ranges)) } },
        .ShaderVisibility = .ALL,
    },
    .{
        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_samp_range)) } },
        .ShaderVisibility = .ALL,

    },
};
var rs2_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{
    .NumParameters = 2,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs2_params)),
    .NumStaticSamplers = 0,
    .pStaticSamplers = null,
    .Flags = 0,
};
hr_ = ctx.D3D12SerializeRootSignature.?(&rs2_desc, 1, &blob, &err_blob);

if (hr_ < 0) { if (err_blob) |eb| { if (@intFromPtr(d3d.getBlobVtbl(eb).GetBufferPointer(eb)) != 0) std.debug.print("RS2 err: {s}\n", .{@as([*:0]u8, @ptrCast(d3d.getBlobVtbl(eb).GetBufferPointer(eb)))}); } return error.RS2Failed; }

var rs2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs2);
if (hr_ < 0) return error.RS2Failed;
d3d.release(blob);

// --- PSO 1: Write constant value to RWTexture2D ---
const write_shader =
    \\RWTexture2D<float> tex : register(u0);

    \\[numthreads(64, 1, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    tex[uint2(tid.x, 0)] = float(tid.x * 2 + 100);
    \\}
;
const write_code = try dx12.compileShaderSource(write_shader);
var pso1_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = rs1,
    .CS = .{ .pShaderBytecode = write_code.ptr, .BytecodeLength = write_code.len },
};

var pso1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso1_desc, &d3d.IID_ID3D12PipelineState, &pso1);
if (hr_ < 0) return error.PSO1Failed;
errdefer d3d.release(pso1);

// --- PSO 2: Sample SRV texture, write to buffer ---
const sample_shader =
    \\Texture2D<float> tex : register(t0);
    \\SamplerState samp : register(s0);
    \\RWBuffer<float> buf : register(u0);

    \\[numthreads(64, 1, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    float v = tex.SampleLevel(samp, float2((float(tid.x) + 0.5) / 64.0, 0.5), 0);
    \\    buf[tid.x] = v;
    \\}
;
const sample_code = try dx12.compileShaderSource(sample_shader);
var pso2_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = rs2,
    .CS = .{ .pShaderBytecode = sample_code.ptr, .BytecodeLength = sample_code.len },

};
var pso2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso2_desc, &d3d.IID_ID3D12PipelineState, &pso2);
if (hr_ < 0) return error.PSO2Failed;
errdefer d3d.release(pso2);

// --- Resources ---
// Texture as UAV (for writing), then SRV (for sampling)
const texture = try ctx.createTexture2D(tex_width, tex_height, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
errdefer d3d.release(texture);

// Output buffer (UAV + readback)
const buf_size: u64 = num_elements * 4;
const uav_buf = try ctx.createBuffer(buf_size, .DEFAULT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
errdefer d3d.release(uav_buf);

const readback = try ctx.createBuffer(buf_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
errdefer d3d.release(readback);

// --- Descriptors ---

const cmd = ctx.cmd_list;

// Write Pass: UAV at heap index 0 (texture UAV)
const tex_uav_desc = ctx.createUAVTexture2DDesc(0);
ctx.createUAVViewTexture(texture, &tex_uav_desc, ctx.getUAVCPUHandle(0));

// Sample Pass: SRV at heap index 0, UAV at heap index 1
const srv_desc = ctx.createSRVTexture2DDesc(1);
ctx.createSRV(texture, &srv_desc, ctx.getUAVCPUHandle(0));

const buf_uav_desc = dx12.ComputeContext.createUAVDesc(null, num_elements);
ctx.createUAVView(uav_buf, &buf_uav_desc, ctx.getUAVCPUHandle(1));

// Sampler at sampler heap index 0
const samp_desc = ctx.createSamplerDesc();
ctx.createSampler(&samp_desc, ctx.getSamplerCPUHandle(0));

// ===== PASS 1: Write to texture =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);

_ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso1);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs1);

var heaps = [_]?*anyopaque{ctx.uav_heap};
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);

    if (hr_ < 0) return error.CloseFailed1;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 1 done (texture write)\n", .{});
}

// Barrier: texture UNORDERED_ACCESS -> NON_PIXEL_SHADER_RESOURCE (for SRV in compute)
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    dx12.ComputeContext.bufferBarrier(cmd.?, texture, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
    if (hr_ < 0) return error.CloseBarrier;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;

    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Barrier done\n", .{});
}

// ===== PASS 2: Sample texture, write to buffer =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso2);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs2);

var heaps = [_]?*anyopaque{ ctx.uav_heap, ctx.sampler_heap };
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 2, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 1, ctx.getSamplerGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);

// Barrier buffer: UNORDERED_ACCESS -> COPY_SOURCE

dx12.ComputeContext.bufferBarrier(cmd.?, uav_buf, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
ctx.copyResource(readback, uav_buf);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseFailed2;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));

    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 2 done (sample)\n", .{});
}

// Verify: texture was written with [tid.x * 2 + 100], sampling should read same values
const ptr = try dx12.ComputeContext.mapBuffer(readback);
defer dx12.ComputeContext.unmapBuffer(readback);
const data: [*]f32 = @ptrCast(@alignCast(ptr));

var pass: bool = true;

for (0..num_elements) |i| {
    const expected: f32 = @floatFromInt(@as(u32, @intCast(i)) * 2 + 100);
    const tolerance: f32 = if (expected == 0) @as(f32, 0.001) else @abs(expected) * 0.001;
    const diff = @abs(data[i] - expected);
    if (diff > tolerance) {
        std.debug.print("FAIL[{}]: got {} expected {} (diff={})\n", .{ i, data[i], expected, diff });
        pass = false;
        break;
    }
}

    if (pass) {
        std.debug.print("PASS: All {} sampled values verified\n", .{num_elements});
    }

    d3d.release(rs1);
    d3d.release(rs2);
    d3d.release(pso1);
    d3d.release(pso2);
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    const W: u32 = 8;

const H: u32 = 8;

// --- Root sig 1: UAV only (fill) ---
var rs1_ranges = [1]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
};
var rs1_params = [1]d3d.D3D12_ROOT_PARAMETER{
    .{
        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs1_ranges)) } },

        .ShaderVisibility = .ALL,
    },
};
var rs1_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{
    .NumParameters = 1,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs1_params)),
    .NumStaticSamplers = 0,
    .pStaticSamplers = null,
    .Flags = 0,
};

var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&rs1_desc, 1, &blob, &err_blob);
if (hr_ < 0) return error.RS1Failed;
var rs1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs1);
if (hr_ < 0) return error.RS1Failed;
d3d.release(blob);

// --- Root sig 2: SRV + UAV + SAMPLER (sharpen) ---

var rs2_ranges = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SRV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 1 },
};
var rs2_samp = [1]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SAMPLER, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
};
var rs2_params = [2]d3d.D3D12_ROOT_PARAMETER{
    .{
        .ParameterType = .DESCRIPTOR_TABLE,

        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_ranges)) } },
        .ShaderVisibility = .ALL,
    },
    .{
        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_samp)) } },
        .ShaderVisibility = .ALL,
    },
};
var rs2_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{

    .NumParameters = 2,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs2_params)),
    .NumStaticSamplers = 0,
    .pStaticSamplers = null,
    .Flags = 0,
};
hr_ = ctx.D3D12SerializeRootSignature.?(&rs2_desc, 1, &blob, &err_blob);
if (hr_ < 0) { if (err_blob) |eb| d3d.release(eb); return error.RS2Failed; }
var rs2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs2);

if (hr_ < 0) return error.RS2Failed;
d3d.release(blob);

// --- PSO 1: Fill with step pattern ---
const fill_shader =
    \\RWTexture2D<float> tex : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    tex[tid.xy] = tid.x < 4 ? 0.0 : 100.0;
    \\}

;
const fill_code = try dx12.compileShaderSource(fill_shader);
var pso1_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = rs1,
    .CS = .{ .pShaderBytecode = fill_code.ptr, .BytecodeLength = fill_code.len },
};
var pso1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso1_desc, &d3d.IID_ID3D12PipelineState, &pso1);
if (hr_ < 0) return error.PSO1Failed;
defer d3d.release(pso1);

// --- PSO 2: 3x3 unsharp mask sharpen ---
const sharpen_shader =
    \\Texture2D<float> inputTex : register(t0);
    \\SamplerState samp : register(s0);
    \\RWTexture2D<float> outputTex : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    uint w, h;
    \\    outputTex.GetDimensions(w, h);

\\    int2 uv = int2(tid.xy);
\\    float c = inputTex.Load(int3(uv, 0));
\\    float sum = 0;
\\    for (int dy = -1; dy <= 1; dy++) {
\\        for (int dx = -1; dx <= 1; dx++) {
\\            sum += inputTex.Load(int3(uv + int2(dx, dy), 0));
\\        }
\\    }
\\    float blur = sum / 9.0;
\\    float diff = c - blur;

    \\    outputTex[tid.xy] = c + diff * 2.0;
    \\}
;
const sharpen_code = try dx12.compileShaderSource(sharpen_shader);
var pso2_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = rs2,
    .CS = .{ .pShaderBytecode = sharpen_code.ptr, .BytecodeLength = sharpen_code.len },
};
var pso2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso2_desc, &d3d.IID_ID3D12PipelineState, &pso2);

if (hr_ < 0) return error.PSO2Failed;
defer d3d.release(pso2);

// --- Sampler (point filter for Load) ---
var samp_desc = ctx.createSamplerDesc();
samp_desc.Filter = .MIN_MAG_MIP_POINT;
ctx.createSampler(&samp_desc, ctx.getSamplerCPUHandle(0));

// --- Resources ---
const texture = try ctx.createTexture2D(W, H, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);

defer d3d.release(texture);

const readback = try ctx.createBuffer(try ctx.getTextureFootprint(W, H, .R32_FLOAT), .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
defer d3d.release(readback);

const cmd = ctx.cmd_list;

// --- Descriptors ---
// heap[0] = texture UAV (fill), then texture SRV (sharpen)
// heap[1] = output UAV for sharpen (we reuse as sharpen output for same texture, but need separate)

// Actually for in-place sharpen, we SRV read + UAV write to same texture? That's illegal.
// We need separate textures for input and output.

// Let's create output texture
const tex_out = try ctx.createTexture2D(W, H, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(tex_out);

// Fill pass: texture UAV at heap[0]
const tex_uav = ctx.createUAVTexture2DDesc(0);
ctx.createUAVViewTexture(texture, &tex_uav, ctx.getUAVCPUHandle(0));

// Sharpen pass: texture SRV at heap[0], tex_out UAV at heap[1]
const srv_desc = ctx.createSRVTexture2DDesc(1);
ctx.createSRV(texture, &srv_desc, ctx.getUAVCPUHandle(0));

const out_uav = ctx.createUAVTexture2DDesc(0);
ctx.createUAVViewTexture(tex_out, &out_uav, ctx.getUAVCPUHandle(1));

// ===== PASS 1: Fill texture with step pattern =====
{

_ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
_ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso1);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs1);
var heaps = [_]?*anyopaque{ctx.uav_heap};
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);

    if (hr_ < 0) return error.CloseFailed1;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 1: fill step pattern complete\n", .{});
}

// Barrier: texture UNORDERED_ACCESS -> NON_PIXEL_SHADER_RESOURCE (for SRV)
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    dx12.ComputeContext.bufferBarrier(cmd.?, texture, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
    if (hr_ < 0) return error.CloseBarrier1;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;

    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Barrier done\n", .{});
}

// ===== PASS 2: Apply sharpen =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso2);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs2);
var heaps = [_]?*anyopaque{ ctx.uav_heap, ctx.sampler_heap };
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 2, &heaps);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 1, ctx.getSamplerGPUHandle(0));
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);

// Barrier: tex_out UNORDERED_ACCESS -> COPY_SOURCE
dx12.ComputeContext.bufferBarrier(cmd.?, tex_out, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseFailed2;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
std.debug.print("Pass 2: sharpen complete\n", .{});

}

// Barrier: tex_out COPY_SOURCE -> COPY_DEST? No, tex_out is DEFAULT heap, need COPY_SOURCE for CopyTextureRegion
// Actually tex_out is in DEFAULT heap with UNORDERED_ACCESS initial state. After DRAW we transition to COPY_SOURCE.
// But the barrier was inside the previous command list. Let's do CopyTextureRegion in a new command list.

// ===== PASS 3: CopyTextureRegion tex_out -> readback =====
var row_pitch: u32 = undefined;
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);

_ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);

row_pitch = ctx.copyTextureToBuffer(readback, tex_out, W, H, .R32_FLOAT);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseCopy;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);

    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 3: CopyTextureRegion complete (RowPitch={})\n", .{row_pitch});
}

// Verify
const ptr = try dx12.ComputeContext.mapBuffer(readback);
defer dx12.ComputeContext.unmapBuffer(readback);
const data: [*]f32 = @ptrCast(@alignCast(ptr));

const row_floats = row_pitch / 4;

std.debug.print("\nVerification:\n", .{});
for (0..H) |y| {
    std.debug.print("  row {}: ", .{y});
    for (0..W) |x| {
        std.debug.print("{d:6.1} ", .{data[y * row_floats + x]});
    }
    std.debug.print("\n", .{});
}

var pass: bool = true;
// Check: at edge (x=3, y=3), sharpened should have overshoot
// Position (3,3): originally 0.0, should go negative (undershoot)
// Position (4,3): originally 100.0, should go >100 (overshoot)
const v3 = data[3 * row_floats + 3];
const v4 = data[3 * row_floats + 4];
std.debug.print("\nEdge check: [3,3]={d:.1} (expect <0), [4,3]={d:.1} (expect >100)\n", .{ v3, v4 });
if (v3 >= 0) { std.debug.print("FAIL: no undershoot at edge\n", .{}); pass = false; }
if (v4 <= 100) { std.debug.print("FAIL: no overshoot at edge\n", .{}); pass = false; }

// Check: flat area before edge should be near 0
const v0 = data[3 * row_floats + 0];
const v1 = data[3 * row_floats + 1];
const v2 = data[3 * row_floats + 2];
std.debug.print("Flat left: [3,0]={d:.1} [3,1]={d:.1} [3,2]={d:.1} (expect ~0)\n", .{ v0, v1, v2 });
if (@abs(v0) > 5 or @abs(v1) > 5 or @abs(v2) > 5) {
    std.debug.print("FAIL: flat area disturbed\n", .{});
    pass = false;
}

// Check: flat area after edge should be near 100 (exclude boundary pixel x=7 where 3x3 reads OOB)
const v5 = data[3 * row_floats + 5];
const v6 = data[3 * row_floats + 6];
std.debug.print("Flat right: [3,5]={d:.1} [3,6]={d:.1} (expect ~100)\n", .{ v5, v6 });
if (@abs(v5 - 100) > 5 or @abs(v6 - 100) > 5) {
    std.debug.print("FAIL: flat area disturbed\n", .{});
    pass = false;
}

    if (pass) {
        std.debug.print("\nPASS: Adaptive sharpening verified\n", .{});
    }

    d3d.release(rs1);
    d3d.release(rs2);
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    const W_LOW: u32 = 8;

const H_LOW: u32 = 8;
const W_HIGH: u32 = 16;
const H_HIGH: u32 = 16;

// --- Root sig 1: UAV only (fill) ---
var rs1_ranges = [1]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
};
var rs1_params = [1]d3d.D3D12_ROOT_PARAMETER{.{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 1, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs1_ranges)) } }, .ShaderVisibility = .ALL }};
var rs1_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs1_params)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };

var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&rs1_desc, 1, &blob, &err_blob);
if (hr_ < 0) return error.RS1Failed;
var rs1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs1);
if (hr_ < 0) return error.RS1Failed;
d3d.release(blob);

// --- Root sig 2: SRV×3 + UAV (no sampler, using Load) ---

var rs2_ranges = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .SRV, .NumDescriptors = 3, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 3 },
};
var rs2_params = [1]d3d.D3D12_ROOT_PARAMETER{
    .{ .ParameterType = .DESCRIPTOR_TABLE, ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&rs2_ranges)) } }, .ShaderVisibility = .ALL },
};
var rs2_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{ .NumParameters = 1, .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&rs2_params)), .NumStaticSamplers = 0, .pStaticSamplers = null, .Flags = 0 };
hr_ = ctx.D3D12SerializeRootSignature.?(&rs2_desc, 1, &blob, &err_blob);
if (hr_ < 0) { if (err_blob) |eb| d3d.release(eb); return error.RS2Failed; }

var rs2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &rs2);
if (hr_ < 0) return error.RS2Failed;
d3d.release(blob);

// --- PSO 1a: Fill low-res ---
const fill_shader =
    \\RWTexture2D<float> tex : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {

    \\    tex[tid.xy] = float(tid.x + tid.y * 8);
    \\}
;
const fill_code = try dx12.compileShaderSource(fill_shader);
var pso1_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs1, .CS = .{ .pShaderBytecode = fill_code.ptr, .BytecodeLength = fill_code.len } };
var pso1: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso1_desc, &d3d.IID_ID3D12PipelineState, &pso1);
if (hr_ < 0) return error.PSO1Failed;
defer d3d.release(pso1);

// --- PSO 1b: Fill prev output ---
const fill_prev_shader =
    \\RWTexture2D<float> tex : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    tex[tid.xy] = float((tid.x + tid.y * 16) * 2);
    \\}
;
const fill_prev_code = try dx12.compileShaderSource(fill_prev_shader);
var pso1b_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs1, .CS = .{ .pShaderBytecode = fill_prev_code.ptr, .BytecodeLength = fill_prev_code.len } };

var pso1b: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso1b_desc, &d3d.IID_ID3D12PipelineState, &pso1b);
if (hr_ < 0) return error.PSO1bFailed;
defer d3d.release(pso1b);

// --- PSO 1c: Fill motion vectors ---
const fill_mv_shader =
    \\RWTexture2D<float2> tex : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {

    \\    tex[tid.xy] = float2(2.0, 2.0);
    \\}
;
const fill_mv_code = try dx12.compileShaderSource(fill_mv_shader);
var pso1c_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs1, .CS = .{ .pShaderBytecode = fill_mv_code.ptr, .BytecodeLength = fill_mv_code.len } };
var pso1c: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso1c_desc, &d3d.IID_ID3D12PipelineState, &pso1c);
if (hr_ < 0) return error.PSO1cFailed;
defer d3d.release(pso1c);

// --- PSO 2: Temporal reprojection + blend ---
const temporal_shader =
    \\Texture2D<float> lowResColor : register(t0);
    \\Texture2D<float2> motionVectors : register(t1);
    \\Texture2D<float> prevOutput : register(t2);
    \\RWTexture2D<float> output : register(u0);
    \\[numthreads(8, 8, 1)]
    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    uint2 outSize; output.GetDimensions(outSize.x, outSize.y);
    \\    uint2 inSize; lowResColor.GetDimensions(inSize.x, inSize.y);

\\    float2 scale = float2(inSize) / float2(outSize);
\\    float2 uv = (float2(tid.xy) + 0.5) * scale;
\\    int2 inPos = int2(uv);
\\    float currentColor = lowResColor.Load(int3(inPos, 0));
\\    float2 mv = motionVectors.Load(int3(inPos, 0));
\\    float2 prevUV = float2(tid.xy) + 0.5 - mv;
\\    int2 prevPos = int2(prevUV);
\\    float prevColor = 0;
\\    if (prevPos.x >= 0 && prevPos.x < int(outSize.x) && prevPos.y >= 0 && prevPos.y < int(outSize.y))
\\        prevColor = prevOutput.Load(int3(prevPos, 0));

    \\    output[tid.xy] = lerp(currentColor, prevColor, 0.5);
    \\}
;
const temporal_code = try dx12.compileShaderSource(temporal_shader);
var pso2_desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs2, .CS = .{ .pShaderBytecode = temporal_code.ptr, .BytecodeLength = temporal_code.len } };
var pso2: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &pso2_desc, &d3d.IID_ID3D12PipelineState, &pso2);
if (hr_ < 0) return error.PSO2Failed;
defer d3d.release(pso2);

// --- Textures ---
const low_res_tex = try ctx.createTexture2D(W_LOW, H_LOW, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(low_res_tex);

const mv_tex = try ctx.createTexture2D(W_LOW, H_LOW, .R32G32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(mv_tex);

const prev_tex = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(prev_tex);

const out_tex = try ctx.createTexture2D(W_HIGH, H_HIGH, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
defer d3d.release(out_tex);

const readback = try ctx.createBuffer(try ctx.getTextureFootprint(W_HIGH, H_HIGH, .R32_FLOAT), .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
defer d3d.release(readback);

const cmd = ctx.cmd_list;

// --- Descriptors ---
// SRVs at slots 0,1,2 (for temporal pass)

const srv_lr = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } } };
ctx.createSRV(low_res_tex, &srv_lr, ctx.getUAVCPUHandle(0));
const srv_mv = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } } };
ctx.createSRV(mv_tex, &srv_mv, ctx.getUAVCPUHandle(1));
const srv_prev = d3d.D3D12_SHADER_RESOURCE_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, .Shader4ComponentMapping = 0x1608, ._u = .{ .Texture2D = .{ .MostDetailedMip = 0, .MipLevels = 1, .PlaneSlice = 0, .ResourceMinLODClamp = 0 } } };
ctx.createSRV(prev_tex, &srv_prev, ctx.getUAVCPUHandle(2));

// UAV at slot 3 (temporal output)
const out_uav = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(out_tex, &out_uav, ctx.getUAVCPUHandle(3));

// Fill-pass UAVs at slots 4,5,6
const fill_lr = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(low_res_tex, &fill_lr, ctx.getUAVCPUHandle(4));
const fill_mv = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32G32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(mv_tex, &fill_mv, ctx.getUAVCPUHandle(5));
const fill_prev = d3d.D3D12_UNORDERED_ACCESS_VIEW_DESC{ .Format = .R32_FLOAT, .ViewDimension = .TEXTURE2D, ._u = .{ .Texture2D = .{ .MipSlice = 0, .PlaneSlice = 0 } } };
ctx.createUAVViewTexture(prev_tex, &fill_prev, ctx.getUAVCPUHandle(6));

// ===== PASS 1a: Fill low-res =====

{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso1);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs1);
    var heaps = [_]?*anyopaque{ctx.uav_heap};
    d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(4));
    d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);

    if (hr_ < 0) return error.Close1;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 1a: low-res fill\n", .{});
}

// ===== PASS 1b: Fill prev output =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso1b);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs1);
    var heaps = [_]?*anyopaque{ctx.uav_heap};
    d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(6));
    d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 2, 2, 1);

    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
    if (hr_ < 0) return error.Close1;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 1b: prev output fill\n", .{});
}

// ===== PASS 1c: Fill motion vectors =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso1c);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs1);
    var heaps = [_]?*anyopaque{ctx.uav_heap};
    d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(5));

d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);
hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.Close1;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
std.debug.print("Pass 1c: mv fill\n", .{});

}

// Barriers: all NON_PIXEL_SHADER_RESOURCE for SRV reads
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    dx12.ComputeContext.bufferBarrier(cmd.?, low_res_tex, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    dx12.ComputeContext.bufferBarrier(cmd.?, mv_tex, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    dx12.ComputeContext.bufferBarrier(cmd.?, prev_tex, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);

    if (hr_ < 0) return error.CloseBarrier;
    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Barriers done\n", .{});
}

// ===== PASS 2: Temporal reprojection + blend =====
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, pso2);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, rs2);
    var heaps = [_]?*anyopaque{ctx.uav_heap};
    d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 1, &heaps);
    d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, ctx.getUAVGPUHandle(0));
    d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 2, 2, 1);

dx12.ComputeContext.bufferBarrier(cmd.?, out_tex, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.Close2;
var lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
std.debug.print("Pass 2: temporal upscale\n", .{});

}

// ===== PASS 3: CopyTextureRegion =====
var row_pitch: u32 = undefined;
{
    _ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
    row_pitch = ctx.copyTextureToBuffer(readback, out_tex, W_HIGH, H_HIGH, .R32_FLOAT);
    hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
    if (hr_ < 0) return error.Close3;

    var lists = [_]?*anyopaque{cmd};
    d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
    ctx.fence_value += 1;
    _ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
    _ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);
    std.debug.print("Pass 3: copy (RowPitch={})\n", .{row_pitch});
}

// Verify

const ptr = try dx12.ComputeContext.mapBuffer(readback);
defer dx12.ComputeContext.unmapBuffer(readback);
const data: [*]f32 = @ptrCast(@alignCast(ptr));
const row_floats = row_pitch / 4;

std.debug.print("\nRow 2 output: ", .{});
for (0..W_HIGH) |x| {
    std.debug.print("{d:6.1} ", .{data[2 * row_floats + x]});
}
std.debug.print("\n", .{});

// Expected values using Load (integer texel access, no bilinear):
// lowResColor[tid] = x + y*8
// prevOutput[tid] = (x + y*16)*2
// MV = (2,2)
// For output pixel (ox, oy):
//   inPos = int2((ox+0.5)*8/16, (oy+0.5)*8/16) = nearest low-res pixel
//   current = lowRes[inPos]
//   mv = MV[inPos] = (2,2)
//   prevPos = int2((ox+0.5-2), (oy+0.5-2))

//   prev = prevOutput[prevPos] if in bounds
//   output = lerp(current, prev, 0.5)

// (4,2): inPos=int2(2.25, 1.25)=(2,1), current=10
//        prevPos=int2(2.5, 0.5)=(2,0), prev=(2+0)*2=4
//        output=lerp(10,4,0.5)=7

// (8,4): inPos=int2(4.25, 2.25)=(4,2), current=20
//        prevPos=int2(6.5, 2.5)=(6,2), prev=(6+32)*2=76
//        output=lerp(20,76,0.5)=48

// (0,0): inPos=int2(0.25, 0.25)=(0,0), current=0
//        prevPos=int2(-1.5, -1.5)=(-2,-2) OOB → prev=0
//        output=lerp(0,0,0.5)=0

// (2,2): inPos=int2(1.25, 1.25)=(1,1), current=9
//        prevPos=int2(0.5, 0.5)=(0,0), prev=0
//        output=lerp(9,0,0.5)=4.5

var pass: bool = true;

const checks = [_]struct { ox: u32, oy: u32, expected: f32, tol: f32 }{
    .{ .ox = 0, .oy = 0, .expected = 0, .tol = 0.1 },
    .{ .ox = 4, .oy = 2, .expected = 7, .tol = 0.1 },
    .{ .ox = 8, .oy = 4, .expected = 48, .tol = 0.1 },
    .{ .ox = 2, .oy = 2, .expected = 4.5, .tol = 0.1 },
};
for (checks) |c| {
    const actual = data[c.oy * row_floats + c.ox];
    const diff = @abs(actual - c.expected);
    if (diff > c.tol) {

        std.debug.print("FAIL[{}x{}]: got {d:.1} expected {d:.1} (diff={d:.1})\n", .{ c.ox, c.oy, actual, c.expected, diff });
        pass = false;
    } else {
        std.debug.print("OK[{}x{}]: got {d:.1} expected {d:.1}\n", .{ c.ox, c.oy, actual, c.expected });
    }
}

if (pass) {
    std.debug.print("\nPASS: Temporal reprojection + blend works\n", .{});
}

    d3d.release(rs1);
    d3d.release(rs2);
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

pub fn main() !void {
    var ctx: dx12.ComputeContext = undefined;
    try ctx.init();
    defer ctx.deinit();

    const num_elements: u32 = 64;

const tex_width: u32 = 64;
const tex_height: u32 = 1;
const buf_size: u64 = num_elements * 4; // 256 bytes

// Override root sig + PSO for dual-UAV test (texture UAV + buffer UAV)
// Root signature: one descriptor table with two UAV ranges (u0, u1)
var ranges = [2]d3d.D3D12_DESCRIPTOR_RANGE{
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 0, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 0 },
    .{ .RangeType = .UAV, .NumDescriptors = 1, .BaseShaderRegister = 1, .RegisterSpace = 0, .OffsetInDescriptorsFromTableStart = 1 },
};

var params = [1]d3d.D3D12_ROOT_PARAMETER{
    .{
        .ParameterType = .DESCRIPTOR_TABLE,
        ._u = .{ .DescriptorTable = .{ .NumDescriptorRanges = 2, .pDescriptorRanges = @as(*const d3d.D3D12_DESCRIPTOR_RANGE, @ptrCast(&ranges)) } },
        .ShaderVisibility = .ALL,
    },
};
var root_desc = d3d.D3D12_ROOT_SIGNATURE_DESC{
    .NumParameters = 1,
    .pParameters = @as(?*const d3d.D3D12_ROOT_PARAMETER, @ptrCast(&params)),

    .NumStaticSamplers = 0,
    .pStaticSamplers = null,
    .Flags = 0,
};

var blob: ?*anyopaque = null;
var err_blob: ?*anyopaque = null;
var hr_ = ctx.D3D12SerializeRootSignature.?(&root_desc, 1, &blob, &err_blob);
if (hr_ < 0) { if (err_blob) |eb| { if (@intFromPtr(d3d.getBlobVtbl(eb).GetBufferPointer(eb)) != 0) std.debug.print("RS err: {s}\n", .{@as([*:0]u8, @ptrCast(d3d.getBlobVtbl(eb).GetBufferPointer(eb)))}); } return error.RootSigFailed; }

var tex_root_sig: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateRootSignature(ctx.device.?, 0, d3d.getBlobVtbl(blob.?).GetBufferPointer(blob.?), d3d.getBlobVtbl(blob.?).GetBufferSize(blob.?), &d3d.IID_ID3D12RootSignature, &tex_root_sig);
if (hr_ < 0) return error.RootSigFailed;
d3d.release(blob);

// PSO: write to RWTexture2D<float> at u0 AND buffer at u1
const tex_pso_shader =
    \\RWTexture2D<float> tex : register(u0);
    \\RWBuffer<float> buf : register(u1);
    \\[numthreads(64, 1, 1)]

    \\void main(uint3 tid : SV_DispatchThreadID) {
    \\    tex[uint2(tid.x, 0)] = float(tid.x * 2);
    \\    buf[tid.x] = float(tid.x * 3);
    \\}
;
const shader_code = try dx12.compileShaderSource(tex_pso_shader);
const desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{
    .pRootSignature = tex_root_sig,
    .CS = .{ .pShaderBytecode = shader_code.ptr, .BytecodeLength = shader_code.len },
};

var tex_pso: ?*anyopaque = null;
hr_ = d3d.getDeviceVtbl(ctx.device.?).CreateComputePipelineState(ctx.device.?, &desc, &d3d.IID_ID3D12PipelineState, &tex_pso);
if (hr_ < 0) return error.PSOFailed;

// Create texture for UAV (64x1 R32_FLOAT, ALLOW_UNORDERED_ACCESS)
const texture = try ctx.createTexture2D(tex_width, tex_height, .R32_FLOAT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
errdefer d3d.release(texture);

// Create buffer UAV for output
const uav_buf = try ctx.createBuffer(buf_size, .DEFAULT, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);

errdefer d3d.release(uav_buf);

// Create readback buffer
const footprint_size = try ctx.getTextureFootprint(tex_width, tex_height, .R32_FLOAT);
std.debug.print("texture footprint size={}\n", .{footprint_size});
const readback = try ctx.createBuffer(footprint_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);
errdefer d3d.release(readback);

// Create UAV views
// Index 0: Texture2D UAV

const tex_uav_desc = ctx.createUAVTexture2DDesc(0);
const tex_cpu = ctx.getUAVCPUHandle(0);
ctx.createUAVViewTexture(texture, &tex_uav_desc, tex_cpu);
// Index 1: Buffer UAV
const buf_uav_desc = dx12.ComputeContext.createUAVDesc(null, num_elements);
const buf_cpu = ctx.getUAVCPUHandle(1);
ctx.createUAVView(uav_buf, &buf_uav_desc, buf_cpu);

// Record and execute
const cmd = ctx.cmd_list;

_ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
_ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
d3d.getCmdListVtbl(cmd.?).SetPipelineState(cmd.?, tex_pso);
d3d.getCmdListVtbl(cmd.?).SetComputeRootSignature(cmd.?, tex_root_sig);
var heaps = [_]?*anyopaque{ ctx.uav_heap, ctx.sampler_heap };
d3d.getCmdListVtbl(cmd.?).SetDescriptorHeaps(cmd.?, 2, &heaps);

const gpu_handle = ctx.getUAVGPUHandle(0);
d3d.getCmdListVtbl(cmd.?).SetComputeRootDescriptorTable(cmd.?, 0, gpu_handle);
d3d.getCmdListVtbl(cmd.?).Dispatch(cmd.?, 1, 1, 1);

// Readback texture: UNORDERED_ACCESS -> COPY_SOURCE
dx12.ComputeContext.bufferBarrier(cmd.?, texture, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
ctx.copyTextureToBuffer(readback, texture, tex_width, tex_height, .R32_FLOAT);
dx12.ComputeContext.bufferBarrier(cmd.?, texture, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseFailed;

var lists = [_]?*anyopaque{cmd};

d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);

// Map readback and verify texture data
const ptr = dx12.ComputeContext.mapBuffer(readback) catch |err| {
    const reason = d3d.getDeviceVtbl(ctx.device.?).GetDeviceRemovedReason(ctx.device.?);
    std.debug.print("Map failed with {}. DeviceRemovedReason = 0x{x}\n", .{ err, @as(u32, @bitCast(reason)) });

    return err;
};
defer dx12.ComputeContext.unmapBuffer(readback);

const data: [*]f32 = @ptrCast(@alignCast(ptr));
var pass: bool = true;
for (0..num_elements) |i| {
    const expected: f32 = @floatFromInt(@as(u32, @intCast(i)) * 2);
    if (data[i] != expected) {
        std.debug.print("TEX FAIL[{}]: got {} expected {}\n", .{ i, data[i], expected });

        pass = false;
        break;
    }
}
if (pass) {
    std.debug.print("PASS: Texture UAV write verified ({} elements)\n", .{num_elements});
}

// Also verify buffer UAV data
const readback_buf = try ctx.createBuffer(buf_size, .READBACK, d3d.D3D12_RESOURCE_STATE_COPY_DEST, d3d.D3D12_RESOURCE_FLAG_NONE);

defer d3d.release(readback_buf);

// Barrier + copy for buffer
// Re-record command list for buffer copy
_ = d3d.getAllocatorVtbl(ctx.cmd_allocator.?).Reset(ctx.cmd_allocator.?);
_ = d3d.getCmdListVtbl(cmd.?).Reset(cmd.?, ctx.cmd_allocator, null);
dx12.ComputeContext.bufferBarrier(cmd.?, uav_buf, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, d3d.D3D12_RESOURCE_STATE_COPY_SOURCE);
ctx.copyResource(readback_buf, uav_buf);
hr_ = d3d.getCmdListVtbl(cmd.?).Close(cmd.?);
if (hr_ < 0) return error.CloseFailed;

lists = [_]?*anyopaque{cmd};
d3d.getQueueVtbl(ctx.queue.?).ExecuteCommandLists(ctx.queue.?, 1, &lists);
ctx.fence_value += 1;
_ = d3d.getQueueVtbl(ctx.queue.?).Signal(ctx.queue.?, ctx.fence, ctx.fence_value);
_ = d3d.getFenceVtbl(ctx.fence.?).SetEventOnCompletion(ctx.fence.?, ctx.fence_value, @as(*anyopaque, @ptrFromInt(ctx.event)));
_ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(ctx.event)), 5000);

const ptr2 = try dx12.ComputeContext.mapBuffer(readback_buf);
defer dx12.ComputeContext.unmapBuffer(readback_buf);

const buf_data: [*]f32 = @ptrCast(@alignCast(ptr2));
var buf_pass: bool = true;
for (0..num_elements) |i| {
    const expected: f32 = @floatFromInt(@as(u32, @intCast(i)) * 3);
    if (buf_data[i] != expected) {
        std.debug.print("BUF FAIL[{}]: got {} expected {}\n", .{ i, buf_data[i], expected });
        buf_pass = false;
        break;
    }
}

    if (buf_pass) {
        std.debug.print("PASS: Buffer UAV write verified ({} elements)\n", .{num_elements});
    }

    d3d.release(tex_root_sig);
    d3d.release(tex_pso);
}

const std = @import("std");
const d3d = @import("../../src/render/d3d12_bindings.zig");
const dx12 = @import("../../src/render/dx12_compute.zig");

const W_LOW = 8;
const H_LOW = 8;
const W_HIGH = 16;
const H_HIGH = 16;

fn makePSO(d: ?*anyopaque, rs: ?*anyopaque, code: []const u8) !?*anyopaque {

    var pso: ?*anyopaque = null;
    var desc = d3d.D3D12_COMPUTE_PIPELINE_STATE_DESC{ .pRootSignature = rs, .CS = .{ .pShaderBytecode = code.ptr, .BytecodeLength = code.len } };
    if (d3d.getDeviceVtbl(d.?).CreateComputePipelineState(d.?, &desc, &d3d.IID_ID3D12PipelineState, &pso) < 0) return error.PSO;
    return pso;
}

fn dispatch(c: *dx12.ComputeContext, cl: ?*anyopaque, rs: ?*anyopaque, pso: ?*anyopaque, gh: d3d.D3D12_GPU_DESCRIPTOR_HANDLE, gx: u32, gy: u32, barriers: []const struct { t: ?*anyopaque, after: u32 }) !void {
    _ = d3d.getAllocatorVtbl(c.cmd_allocator.?).Reset(c.cmd_allocator.?);
    _ = d3d.getCmdListVtbl(cl.?).Reset(cl.?, c.cmd_allocator, null);
    d3d.getCmdListVtbl(cl.?).SetPipelineState(cl.?, pso);

d3d.getCmdListVtbl(cl.?).SetComputeRootSignature(cl.?, rs);
var heaps = [_]?*anyopaque{c.uav_heap};
d3d.getCmdListVtbl(cl.?).SetDescriptorHeaps(cl.?, 1, &heaps);
d3d.getCmdListVtbl(cl.?).SetComputeRootDescriptorTable(cl.?, 0, gh);
d3d.getCmdListVtbl(cl.?).Dispatch(cl.?, gx, gy, 1);
for (barriers) |b| {
    dx12.ComputeContext.bufferBarrier(cl.?, b.t, d3d.D3D12_RESOURCE_STATE_UNORDERED_ACCESS, b.after);
}
if (d3d.getCmdListVtbl(cl.?).Close(cl.?) < 0) return error.Close;
var lists = [_]?*anyopaque{cl};

    d3d.getQueueVtbl(c.queue.?).ExecuteCommandLists(c.queue.?, 1, &lists);
    c.fence_value += 1;
    _ = d3d.getQueueVtbl(c.queue.?).Signal(c.queue.?, c.fence, c.fence_value);
    _ = d3d.getFenceVtbl(c.fence.?).SetEventOnCompletion(c.fence.?, c.fence_value, @as(*anyopaque, @ptrFromInt(c.event)));
    _ = try std.os.windows.WaitForSingleObject(@as(std.os.windows.HANDLE, @ptrFromInt(c.event)), 5000);
}

pub fn main() !void {
