const CAP = 8;
const CHUNK_CAP = 32;

var runtime_test_free_list: [CHUNK_CAP]u32 = undefined;

fn makeMetaStore(
    cids: *[CAP]u32,

    offs: *[CAP]u32,
    gens: *[CAP]u32,
    sizes: *[CAP]u32,
    states: *[CAP]rt.SlotState,
    free_next: *[CAP]u32,
    heats: *[CAP]u32,
    total_heats: *[CAP]u32,
) rt.MetaStore {
    return rt.MetaStore.init(cids, offs, gens, sizes, states, free_next, heats, total_heats);
